# Depth-map attachments (Alchemy depth_anything_v2 annotation form)
DEPTH_FORM = "annotation"
DEPTH_CONTROL_TYPE = "depth_anything_v2"
DEPTH_POSTFIX = "_depth"


def depth_path_for(path: str) -> str:
    """Companion depth-map path of an image (same folder, same name + _depth)."""
    return os.path.splitext(path)[0] + DEPTH_POSTFIX + ".png"


def has_depth_map(path: str) -> bool:
    return bool(path) and os.path.isfile(depth_path_for(path))


def is_depth_image_path(path: str) -> bool:
    """True when the path itself IS a depth attachment (never listed in galleries)."""
    return os.path.basename(path or "").lower().endswith(DEPTH_POSTFIX + ".png")

