# =============================================================================
#  2. In-Memory Structured Diagnostic Logger (No Log Files Written to Disk)
# =============================================================================
@dataclass(frozen=True)
class LogRecord:
    ts: float
    channel: str
    level: str
    message: str

    def format_line(self) -> str:
        t = time.strftime("%H:%M:%S", time.localtime(self.ts))
        return f"[{t}] [{self.channel:<6s}] [{self.level:<5s}] {self.message}"

    def format_html(self, level_colors: Dict[str, str], dim: str) -> str:
        t = time.strftime("%H:%M:%S", time.localtime(self.ts))
        col = level_colors.get(self.level, dim)
        safe = xml_escape(self.message).replace("\n", " ")
        return (
            f"<span style='color:{dim}'>[{t}] [{xml_escape(self.channel)}] "
            f"[<span style='color:{col};font-weight:bold'>{xml_escape(self.level)}</span>] "
            f"</span>{safe}"
        )


class StudioLogger:
    """Thread-safe, strictly in-memory diagnostic ring buffer for Stable Horde,
    LLM API, Browser Bridge, SillyTavern, and Tile Upscale error handling."""

    def __init__(self, maxlen: int = 2000) -> None:
        self._lock = threading.Lock()
        self._records: "collections.deque[LogRecord]" = collections.deque(maxlen=maxlen)
        self._listeners: List[Callable[[LogRecord], None]] = []
        self._error_count = 0

    def subscribe(self, fn: Callable[[LogRecord], None]) -> None:
        with self._lock:
            if fn not in self._listeners:
                self._listeners.append(fn)

    def log(self, channel: str, level: str, message: str) -> LogRecord:
        rec = LogRecord(
            ts=time.time(),
            channel=(channel or "SYS").upper()[:6],
            level=(level or "INFO").upper()[:5],
            message=str(message or "").strip(),
        )
        with self._lock:
            self._records.append(rec)
            if rec.level == "ERROR":
                self._error_count += 1
            listeners = list(self._listeners)
        for fn in listeners:
            try:
                fn(rec)
            except Exception:  # noqa: BLE001 - logging hooks must never crash callers
                pass
        return rec

    def info(self, channel: str, msg: str) -> LogRecord:
        return self.log(channel, "INFO", msg)

    def ok(self, channel: str, msg: str) -> LogRecord:
        return self.log(channel, "OK", msg)

    def warn(self, channel: str, msg: str) -> LogRecord:
        return self.log(channel, "WARN", msg)

    def error(self, channel: str, msg: str) -> LogRecord:
        return self.log(channel, "ERROR", msg)

    def net(self, channel: str, msg: str) -> LogRecord:
        return self.log(channel, "NET", msg)

    def records(self, channel: Optional[str] = None, level: Optional[str] = None) -> List[LogRecord]:
        with self._lock:
            items = list(self._records)
        if channel and channel != "ALL":
            ch = channel.upper()
            items = [r for r in items if r.channel == ch]
        if level and level != "ALL":
            lv = level.upper()
            items = [r for r in items if r.level == lv]
        return items

    def clear(self) -> None:
        with self._lock:
            self._records.clear()
            self._error_count = 0

    @property
    def error_count(self) -> int:
        with self._lock:
            return self._error_count


STUDIO_LOG = StudioLogger()


def _global_excepthook(etype, value, tb) -> None:
    """Keep the app alive on unhandled exceptions raised inside Qt callbacks.

    PyQt6 aborts the whole process (qFatal "Unhandled Python exception") when
    a slot/event handler raises and the default excepthook is installed. This
    hook logs the full traceback to stderr and to the in-memory diagnostic log
    (visible in the QUEUE & LOG tab) instead, so errors become diagnosable
    rather than fatal. SystemExit / KeyboardInterrupt are delegated upstream.
    """
    if issubclass(etype, (SystemExit, KeyboardInterrupt)):
        sys.__excepthook__(etype, value, tb)
        return
    try:
        detail = "".join(traceback.format_exception(etype, value, tb))
        STUDIO_LOG.error("SYS", f"Unhandled exception: {etype.__name__}: {value}")
        try:
            sys.stderr.write(detail)
            sys.stderr.flush()
        except Exception:  # noqa: BLE001 - stderr itself may be broken
            pass
    except Exception:  # noqa: BLE001 - the hook must never raise
        pass


sys.excepthook = _global_excepthook


