# v11 scale doctrine: the former 140% is the new 100% (SCALE_REFERENCE).
# The stored value is the EFFECTIVE multiplier every painter already uses;
# the percent shown in the UI is  effective / SCALE_REFERENCE * 100.
SCALE_REFERENCE: float = 1.40
SCALE_MIN: float = 0.98   # ~70% display
SCALE_MAX: float = 1.96   # ~140% display
_UI_SCALE: float = SCALE_REFERENCE


def ui_scale() -> float:
    """Active global UI scale factor (effective multiplier, 0.98..1.96)
    shared by all custom painters & delegates. 1.40 == displayed "100%"."""
    return _UI_SCALE


def set_ui_scale(scale: float) -> float:
    global _UI_SCALE
    _UI_SCALE = max(SCALE_MIN, min(SCALE_MAX, float(scale)))
    return _UI_SCALE


def scale_percent(eff: float) -> int:
    """Displayed percentage for an effective scale factor (1.40 -> 100%)."""
    return int(round((float(eff) / SCALE_REFERENCE) * 100.0))


def migrate_legacy_scale(raw: Any) -> float:
    """Convert a pre-v11 stored font_scale (0.75..1.40 old display scale)
    into the new effective system, preserving the visual size the user had."""
    try:
        old = float(raw)
    except (TypeError, ValueError):
        return SCALE_REFERENCE
    if old <= 0.0:
        return SCALE_REFERENCE
    return max(SCALE_MIN, min(SCALE_MAX, old * SCALE_REFERENCE))


