            f"<path d='M4.2,20.8 C4.8,15.6 8.2,13.6 12,13.6 C15.8,13.6 19.2,15.6 19.8,20.8 Z' "
            f"fill='{core}' stroke='#ff82a9' stroke-width='2.0' stroke-linejoin='round'/>"
