MINI_ICON_KEYS: Set[str] = set(_MINI_ICON_MOTIFS.keys())


def build_mini_icon_svg(kind: str, palette: Optional[Dict[str, str]] = None) -> str:
    """24x24 full-bleed bold duotone vector glyph engineered for instant 50ms
    recognizability at 12px-16px toolbar scale across all 3 East-Asian themes.
    Zero cramped outer box clutter — maximum silhouette clarity and contrast."""
    p = palette or C
    defs = _svg_defs_common(p)
    pri, acc, core = _icon_duotone(p)
    motif_tpl = _MINI_ICON_MOTIFS.get(kind) or _MINI_ICON_MOTIFS["info"]
    motif = motif_tpl.format(pri=pri, acc=acc, core=core)
    return (
        f"<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'>{defs}"
        f"{motif}</svg>"
    )


class VectorAssetEngine:
    """High-DPI 3x-oversampled LRU-cached vector renderer for embedded SVG assets."""

    def __init__(self) -> None:
        self._cache: "collections.OrderedDict[Tuple[str, str, int, int, bool], QPixmap]" = collections.OrderedDict()

    def invalidate_theme(self) -> None:
        self._cache.clear()

    def pixmap_for_theme(
        self, asset_key: str, tkey: str, width: int, height: Optional[int] = None, disabled: bool = False
    ) -> QPixmap:
        w = max(8, int(width))
        h = max(8, int(height if height is not None else w))
        resolved = resolve_theme_key(tkey)
        pal = THEMES.get(resolved, C)
        ckey = (asset_key, pal["key"], w, h, bool(disabled))
        cached = self._cache.get(ckey)
        if cached is not None:
            self._cache.move_to_end(ckey)
            return cached
        dpr = 3
        pm = QPixmap(w * dpr, h * dpr)
        pm.fill(Qt.GlobalColor.transparent)
        pm.setDevicePixelRatio(float(dpr))
        if _HAS_QTSVG and QSvgRenderer is not None:
            if asset_key in MINI_ICON_KEYS:
                svg_bytes = build_mini_icon_svg(asset_key, pal).encode("utf-8")
            else:
                svg_bytes = build_svg_document(asset_key, pal).encode("utf-8")
            renderer = QSvgRenderer(QByteArray(svg_bytes))
            painter = QPainter(pm)
            painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
            if disabled:
                painter.setOpacity(0.36)
            renderer.render(painter, QRectF(0, 0, w, h))
            painter.end()
        else:
            self._fallback_paint(pm, asset_key)
        self._cache[ckey] = pm
        while len(self._cache) > 560:
            self._cache.popitem(last=False)
        return pm

    def pixmap(self, asset_key: str, width: int, height: Optional[int] = None) -> QPixmap:
        return self.pixmap_for_theme(asset_key, theme_name(), width, height)

    def icon(self, asset_key: str, size: int = 20) -> QIcon:
        return self.icon_for_theme(asset_key, theme_name(), size)

    def icon_for_theme(self, asset_key: str, tkey: str, size: int = 20) -> QIcon:
        ic = QIcon()
        ic.addPixmap(self.pixmap_for_theme(asset_key, tkey, size, size, disabled=False), QIcon.Mode.Normal)
        ic.addPixmap(self.pixmap_for_theme(asset_key, tkey, size, size, disabled=True), QIcon.Mode.Disabled)
        return ic

    @staticmethod
    def _fallback_paint(pm: QPixmap, asset_key: str) -> None:
        painter = QPainter(pm)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        w, h = pm.width(), pm.height()
        grad = QLinearGradient(0, 0, 0, h)
        grad.setColorAt(0.0, QColor(C["acc_spec"]))
        grad.setColorAt(0.45, QColor(C["acc_hi"]))
        grad.setColorAt(1.0, QColor(C["acc_lo"]))
        painter.setBrush(QBrush(grad))
        painter.setPen(QPen(QColor(C["acc_edge"]), 1.2))
        margin = max(2.0, w * 0.14)
        painter.drawRoundedRect(QRectF(margin, margin, w - 2 * margin, h - 2 * margin), 3, 3)
        painter.end()


VECTOR_ASSETS = VectorAssetEngine()


def _font(size: float, bold: bool = False, spacing: float = 0.0) -> QFont:
    f = QFont("Segoe UI")
    f.setPointSizeF(size)
    f.setBold(bold)
    if spacing:
        f.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, spacing)
    return f


# =============================================================================
#  6. Files, Settings, History, Templates, Tag Groups, Wildcards & LoRA Library
# =============================================================================
def _migrate_legacy_files() -> None:
    """Non-destructively copy legacy v1.x/v2.x files from script root into data/
    on first launch so existing users keep their API key, templates, and tags."""
    legacy_map = [
        (os.path.join(BASE_DIR, "key.txt"), KEY_FILE),
        (os.path.join(BASE_DIR, "settings.json"), SETTINGS_FILE),
        (os.path.join(BASE_DIR, "llm_settings.json"), LLM_SETTINGS_FILE),
        (os.path.join(BASE_DIR, "templates_anime.xml"), TEMPLATE_FILES["anime"]),
        (os.path.join(BASE_DIR, "templates_krea.xml"), TEMPLATE_FILES["krea"]),
        (os.path.join(BASE_DIR, "tag_groups.txt"), TAGS_FILE),
    ]
    for src, dst in legacy_map:
        if os.path.isfile(src) and not os.path.exists(dst):
            try:
                shutil.copy2(src, dst)
                STUDIO_LOG.info("SYS", f"Migrated legacy {os.path.basename(src)} into data/")
            except OSError:
                pass
    legacy_wc = os.path.join(BASE_DIR, "wildcards")
    if os.path.isdir(legacy_wc):
        try:
            for name in os.listdir(legacy_wc):
                src_p = os.path.join(legacy_wc, name)
                dst_p = os.path.join(WILDCARDS_DIR, name)
                if os.path.isfile(src_p) and not os.path.exists(dst_p):
                    shutil.copy2(src_p, dst_p)
        except OSError:
            pass


def ensure_dirs() -> None:
    for d in (DATA_DIR, OUTPUT_DIR, TEMP_DIR, TILES_DIR, WILDCARDS_DIR, SCRATCH_DIR, SOUNDS_DIR):
        try:
            os.makedirs(d, exist_ok=True)
        except OSError:
            pass
    _migrate_legacy_files()
    for key, path in TEMPLATE_FILES.items():
        if not os.path.exists(path):
            write_text(path, DEFAULT_TEMPLATES[key])
    if not os.path.exists(TAGS_FILE):
        write_text(TAGS_FILE, DEFAULT_TAGS)
    if not os.path.exists(KEY_FILE):
        save_api_key(ANON_KEY)
    try:
        if not any(f.lower().endswith(".txt") for f in os.listdir(WILDCARDS_DIR)):
            for fn, body in DEFAULT_WILDCARDS.items():
                write_text(os.path.join(WILDCARDS_DIR, fn), body)
    except OSError:
        pass


def read_text(path: str, default: str = "") -> str:
    try:
        with open(path, "r", encoding="utf-8") as fh:
            return fh.read()
    except OSError:
        return default


def write_text(path: str, text: str) -> bool:
    tmp = path + ".tmp"
    try:
        parent = os.path.dirname(path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(tmp, "w", encoding="utf-8", newline="\n") as fh:
            fh.write(text)
        os.replace(tmp, path)
        return True
    except OSError:
        return False


KEY_FILE_HEADER = (
    "# Stable Horde / AI Horde API key - one line, no spaces.\n"
    "# Register free at https://stablehorde.net/register ; 0000000000 = anonymous access.\n"
)


def save_api_key(key: str) -> bool:
    """Persist the API key into data/key.txt (atomic write, LF endings).
    An empty / missing key is stored as the default anonymous key."""
    return write_text(KEY_FILE, KEY_FILE_HEADER + f"{(key or '').strip() or ANON_KEY}\n")


def load_api_key() -> str:
    for raw in read_text(KEY_FILE).splitlines():
        line = raw.strip()
        if line and not line.startswith("#"):
            return line
    return ANON_KEY


def mask_key(key: str) -> str:
    if not key or key == ANON_KEY:
        return f"{ANON_KEY}  (anonymous)"
    if len(key) <= 8:
        return "*" * len(key)
    return f"{key[:4]}\u2026{key[-4:]}"


def deep_merge(base: Dict[str, Any], over: Dict[str, Any]) -> Dict[str, Any]:
    out = copy.deepcopy(base)
    for k, v in (over or {}).items():
        if isinstance(v, dict) and isinstance(out.get(k), dict):
            out[k] = deep_merge(out[k], v)
        else:
            out[k] = copy.deepcopy(v)
    return out


def load_settings() -> Dict[str, Any]:
    try:
        with open(SETTINGS_FILE, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        if isinstance(data, dict):
            merged = deep_merge(DEFAULT_SETTINGS, data)
            # Migrate legacy single negative prompt into per-model negatives
            if "negatives" not in data and isinstance(data.get("negative"), str) and data.get("negative").strip():
                legacy_neg = data["negative"]
                merged["negatives"] = {
                    "anime": legacy_neg,
                    "krea": legacy_neg,
                }
            # Migrate legacy "crimson" theme key seamlessly to "oriental" (Oriental Spirit)
            ui_cfg = merged.get("ui")
            if isinstance(ui_cfg, dict) and "theme" in ui_cfg:
                ui_cfg["theme"] = resolve_theme_key(str(ui_cfg.get("theme") or "seestation"))
            return merged
    except (OSError, ValueError):
        pass
    return copy.deepcopy(DEFAULT_SETTINGS)


def save_settings(data: Dict[str, Any]) -> None:
    write_text(SETTINGS_FILE, json.dumps(data, indent=2, ensure_ascii=False))


def load_llm_settings() -> Dict[str, Any]:
    try:
        with open(LLM_SETTINGS_FILE, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        if isinstance(data, dict):
            merged = deep_merge(DEFAULT_LLM_SETTINGS, data)
            # Ensure both model system prompt templates exist and are non-empty
            sp = merged.setdefault("system_prompts", {})
            for k in ("anime", "krea"):
                if not isinstance(sp.get(k), str) or not sp.get(k).strip():
                    sp[k] = DEFAULT_LLM_SYSTEM_PROMPTS[k]
            # v3.2: ensure the modular vision system prompts exist per mode
            vp = merged.setdefault("vision_prompts", {})
            if not isinstance(vp, dict):
                vp = {}
                merged["vision_prompts"] = vp
            for m in VISION_MODES:
                if not isinstance(vp.get(m), str) or not vp.get(m).strip():
                    vp[m] = build_default_vision_prompt(m)
            if merged.get("vision_mode") not in VISION_MODES:
                merged["vision_mode"] = "natural"
            # v4: ensure the modular motion (video) system prompts exist per mode
            mp = merged.setdefault("vision_motion_prompts", {})
            if not isinstance(mp, dict):
                mp = {}
                merged["vision_motion_prompts"] = mp
            for m in VIDEO_MOTION_MODES:
                if not isinstance(mp.get(m), str) or not mp.get(m).strip():
                    mp[m] = build_default_motion_prompt(m)
            if merged.get("vision_motion_mode") not in VIDEO_MOTION_MODES:
                merged["vision_motion_mode"] = "i2va"
            return merged
    except (OSError, ValueError):
        pass
    return copy.deepcopy(DEFAULT_LLM_SETTINGS)


def save_llm_settings(data: Dict[str, Any]) -> None:
    write_text(LLM_SETTINGS_FILE, json.dumps(data, indent=2, ensure_ascii=False))


# ---- Foldered LoRA library (data/loras.json) --------------------------------
def normalize_lora_entry(raw: Dict[str, Any]) -> Dict[str, Any]:
    """Coerce any legacy or partial LoRA dict into the full v2.0 schema."""
    folder = str(raw.get("folder") or "Improve-Overall").strip() or "Improve-Overall"
    m_val = float(raw.get("model", raw.get("preferred_strength", 1.0)))
    c_val = float(raw.get("clip", raw.get("preferred_clip", m_val)))
    pref_m = float(raw.get("preferred_strength", m_val))
    pref_c = float(raw.get("preferred_clip", c_val))
    use_slider = bool(raw.get("use_slider", folder == "Slider"))
    s_min = float(raw.get("slider_min", -2.0 if folder == "Slider" else 0.0))
    s_max = float(raw.get("slider_max", 2.0))
    if s_max <= s_min:
        s_max = s_min + 1.0

    # Parse multi-variant trigger words cleanly
    triggers: List[Dict[str, str]] = []
    raw_triggers = raw.get("triggers")
    if isinstance(raw_triggers, list):
        for idx, item in enumerate(raw_triggers):
            if isinstance(item, dict):
                txt = str(item.get("text") or "").strip()
                lbl = str(item.get("label") or f"Variant {idx + 1}").strip()
                if txt:
                    triggers.append({"label": lbl or f"Variant {idx + 1}", "text": txt})
            elif isinstance(item, str) and item.strip():
                triggers.append({"label": f"Variant {idx + 1}", "text": item.strip()})
    elif isinstance(raw.get("trained_words"), list):
        joined = ", ".join(str(w).strip() for w in raw["trained_words"] if str(w).strip())
        if joined:
            triggers.append({"label": "Default", "text": joined})

    inject_trig = raw.get("inject_trigger", "")
    if isinstance(inject_trig, bool):
        inject_trig = "any" if inject_trig else ""
    else:
        inject_trig = str(inject_trig or "").strip()

    # Index of the trigger variant currently feeding the prompt ghost text
    try:
        trig_sel = int(raw.get("trigger_sel", 0))
    except (TypeError, ValueError):
        trig_sel = 0
    if not triggers:
        trig_sel = 0
    trig_sel = max(0, min(trig_sel, len(triggers) - 1)) if triggers else 0

    return {
        "uid": str(raw.get("uid") or secrets.token_hex(6)),
        "id": str(raw.get("id") or raw.get("name_id") or "").strip(),
        "is_version": bool(raw.get("is_version", False)),
        "name": str(raw.get("name") or "").strip(),
        "folder": folder,
        "enabled": bool(raw.get("enabled", True)),
        "model": round(max(-5.0, min(5.0, m_val)), 2),
        "clip": round(max(-5.0, min(5.0, c_val)), 2),
        "preferred_strength": round(max(-5.0, min(5.0, pref_m)), 2),
        "preferred_clip": round(max(-5.0, min(5.0, pref_c)), 2),
        "use_slider": use_slider,
        "slider_min": round(max(-5.0, min(5.0, s_min)), 2),
        "slider_max": round(max(-5.0, min(5.0, s_max)), 2),
        "link_clip": bool(raw.get("link_clip", True)),
        "triggers": triggers,
        "trigger_sel": trig_sel,
        "inject_trigger": inject_trig,
        "notes": str(raw.get("notes") or "").strip(),
    }


def _lora_folders_for(lib: Dict[str, Any], key: str) -> List[str]:
    """Return the folder list of one model stack, migrating any legacy shapes.

    v4: each stack carries its OWN default folder set (Anima: anime-centric,
    Krea 2: photographic). Existing custom folders are always kept; missing
    v4 defaults for that stack are appended once. The moss stack has no
    folders (LoRAs are not applicable to MOSS-Image models)."""
    if key == "moss":
        return []
    defaults = DEFAULT_LORA_FOLDERS_BY_STACK.get(key, DEFAULT_LORA_FOLDERS)
    raw = lib.get("folders")
    out: List[str] = []
    if isinstance(raw, dict):
        seq = raw.get(key)
        if isinstance(seq, list):
            out = [str(f).strip() for f in seq if str(f).strip()]
    elif isinstance(raw, list) and key in ("anime", "krea"):
        # v2 library: one global folder list shared by both stacks
        out = [str(f).strip() for f in raw if str(f).strip()]
    if not out:
        out = list(defaults)
    for fn in defaults:
        if fn not in out:
            out.append(fn)
    return out


def load_lora_library(legacy_settings: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Load data/loras.json (v4 per-stack folders); migrate v2/v3/legacy shapes.

    v4 schema:
      {"version": 4,
       "folders": {"anime": [...], "krea": [...], "moss": []},  # per-stack sets
       "stacks":  {"anime": [...], "krea": [...], "moss": []}}
    """
    lib: Dict[str, Any] = {
        "version": 4,
        "folders": {k: list(f) for k, f in DEFAULT_LORA_FOLDERS_BY_STACK.items()},
        "stacks": {k: [] for k in LORA_STACK_KEYS},
    }
    loaded = False
    try:
        with open(LORAS_FILE, "r", encoding="utf-8") as fh:
            doc = json.load(fh)
        if isinstance(doc, dict):
            loaded = True
            raw_stacks = doc.get("stacks") or {}
            for key in LORA_STACK_KEYS:
                folders = _lora_folders_for(doc, key)
                entries: List[Dict[str, Any]] = []
                for item in raw_stacks.get(key) or []:
                    if isinstance(item, dict):
                        norm = normalize_lora_entry(item)
                        if norm["folder"] not in folders:
                            folders.append(norm["folder"])
                        entries.append(norm)
                lib["folders"][key] = folders
                lib["stacks"][key] = entries
    except (OSError, ValueError):
        pass

    if not loaded:
        # Migrate legacy loras from settings.json if present
        if isinstance(legacy_settings, dict):
            raw_l = legacy_settings.get("loras")
            if isinstance(raw_l, list):
                for item in raw_l:
                    if isinstance(item, dict):
                        lib["stacks"]["anime"].append(normalize_lora_entry(item))
                        lib["stacks"]["krea"].append(normalize_lora_entry(item))
            elif isinstance(raw_l, dict):
                for key in ("anime", "krea"):
                    for item in raw_l.get(key) or []:
                        if isinstance(item, dict):
                            lib["stacks"][key].append(normalize_lora_entry(item))
    return lib


def save_lora_library(lib: Dict[str, Any]) -> None:
    write_text(LORAS_FILE, json.dumps(lib, indent=2, ensure_ascii=False))


def lora_selected_trigger(entry: Dict[str, Any]) -> str:
    """Trigger text of the currently selected variant ("" when none)."""
    triggers = entry.get("triggers") or []
    if not triggers:
        return ""
    try:
        idx = int(entry.get("trigger_sel", 0))
    except (TypeError, ValueError):
        idx = 0
    if not (0 <= idx < len(triggers)):
        idx = 0
    return str(triggers[idx].get("text") or "").strip()


def lora_entry_to_horde_payload(entry: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Serialize one enabled LoRA entry into the AI Horde top-level `loras` array.

    AI Horde schema (ModelPayloadLorasStable):
      name           str   exact LoRA name or CivitAI model page ID
                         (CivitAI *version* ID when is_version is true)
      model          float -5..5   strength applied to the SD model
      clip           float -5..5   strength applied to the CLIP model
      inject_trigger str   1..30 chars, or "any"
      is_version     bool  treat `name` as a CivitAI version ID (must be integer)
    """
    ident = str(entry.get("id") or "").strip()
    if not ident or not entry.get("enabled", True):
        return None
    obj: Dict[str, Any] = {
        "name": ident,
        "model": round(float(entry.get("model", 1.0)), 2),
        "clip": round(float(entry.get("clip", 1.0)), 2),
    }
    if entry.get("is_version"):
        obj["is_version"] = True
    inj = str(entry.get("inject_trigger") or "").strip()
    if 1 <= len(inj) <= 30:
        obj["inject_trigger"] = inj
    return obj


# ---- Prompt History (data/history.json) -------------------------------------
def load_history() -> List[Dict[str, Any]]:
    """Load the persisted prompt history list (newest first on demand)."""
    try:
        with open(HISTORY_FILE, "r", encoding="utf-8") as fh:
            doc = json.load(fh)
        if isinstance(doc, list):
            out: List[Dict[str, Any]] = []
            for item in doc:
                if isinstance(item, dict) and str(item.get("prompt") or "").strip():
                    out.append({
                        "ts": float(item.get("ts") or 0.0),
                        "model": str(item.get("model") or ""),
                        "prompt": str(item.get("prompt") or ""),
                        "negative": str(item.get("negative") or ""),
                        "seed": str(item.get("seed") or ""),
                        "pinned": bool(item.get("pinned", False)),
                    })
            return out
    except (OSError, ValueError):
        pass
    return []


def save_history(entries: List[Dict[str, Any]]) -> None:
    write_text(HISTORY_FILE, json.dumps(entries, indent=2, ensure_ascii=False))


def push_history_entry(
    entries: List[Dict[str, Any]],
    model: str,
    prompt: str,
    negative: str,
    seed: str,
) -> List[Dict[str, Any]]:
    """Append a submission to the history (deduplicating consecutive repeats),
    keep pinned entries forever, and trim unpinned overflow to the cap.
    The list is kept newest-first."""
    prompt = (prompt or "").strip()
    if not prompt:
        return entries
    neg = (negative or "").strip()
    seed = (seed or "").strip()
    if entries:
        head = entries[0]
        if (
            not head.get("pinned")
            and head.get("prompt") == prompt
            and str(head.get("negative") or "") == neg
            and str(head.get("model") or "") == model
        ):
            head["ts"] = time.time()
            head["seed"] = seed
            return entries
    entries.insert(0, {
        "ts": time.time(),
        "model": model,
        "prompt": prompt,
        "negative": neg,
        "seed": seed,
        "pinned": False,
    })
    pinned = sum(1 for e in entries if e.get("pinned"))
    cap = max(HISTORY_CAPACITY, pinned)
    if len(entries) > cap:
        kept: List[Dict[str, Any]] = []
        unpinned = 0
        for e in entries:
            if e.get("pinned"):
                kept.append(e)
            else:
                if unpinned < HISTORY_CAPACITY:
                    kept.append(e)
                    unpinned += 1
        entries = kept
    return entries


# ---- Small shared helpers ----------------------------------------------------
def fmt_secs(s: Optional[float]) -> str:
    if s is None:
        return "--:--"
    s_i = max(0, int(s))
    return f"{s_i // 60:02d}:{s_i % 60:02d}"


def elide(text: str, n: int) -> str:
    t = " ".join((text or "").split())
    return t if len(t) <= n else t[: max(1, n - 1)] + "\u2026"


def open_path(path: str) -> None:
    QDesktopServices.openUrl(QUrl.fromLocalFile(path))


def apply_adaptive_dialog_geometry(
    dialog: QDialog,
    pref_w: int,
    pref_h: int,
    min_w: int = 480,
    min_h: int = 360,
) -> None:
    """Corporate-grade dialog sizing: prefer the caller's requested size (which
    for scrollable dialogs encodes the true content height), grow to the
    widget's own minimum hint when larger, then clamp to the available screen
    area so no control is ever clipped on small laptop displays (the v2 LoRA
    editor sizing bug)."""
    screen = None
    try:
        screen = QApplication.primaryScreen()
        if dialog.parent() is not None:
            parent_widget = dialog.parentWidget()
            if parent_widget is not None:
                screen = parent_widget.screen() or screen
    except Exception:  # noqa: BLE001 - headless / detached parents
        screen = None
    if screen is not None:
        avail = screen.availableGeometry()
    else:
        avail = QRect(0, 0, 1280, 800)
    max_w = max(min_w, avail.width() - 40)
    max_h = max(min_h, avail.height() - 56)
    hint = dialog.sizeHint()
    want_w = max(min_w, min(max(pref_w, hint.width() + 24), max_w))
    want_h = max(min_h, min(max(pref_h, hint.height() + 24), max_h))
    dialog.resize(want_w, want_h)
    dialog.setMinimumSize(QSize(min(min_w, want_w), min(min_h, want_h)))


# ---- Templates (XML) --------------------------------------------------------
def _norm_ws(text: str) -> str:
    lines = [" ".join(ln.split()) for ln in (text or "").splitlines()]
    return " ".join(ln for ln in lines if ln).strip()


def parse_templates(path: str) -> List[Dict[str, str]]:
    text = read_text(path)
    if not text.strip():
        return []
    root = None
    for candidate in (text, "<templates>" + text + "</templates>"):
        try:
            root = ET.fromstring(candidate)
            break
        except ET.ParseError:
            continue
    if root is None:
        return _parse_templates_loose(text)
    container_tags = {"templates", "root", "prompts", "list", "presets", "items"}
    if root.tag.lower() in container_tags or (not (root.text or "").strip() and len(root) > 0):
        items = list(root)
    else:
        items = [root]
    out: List[Dict[str, str]] = []
    for el in items:
        body = (el.text or "") + "".join(xml_unescape(ET.tostring(sub, encoding="unicode")) for sub in el)
        name = el.attrib.get("name") or el.attrib.get("title") or el.attrib.get("id") or el.tag
        body = _norm_ws(body)
        if body:
            out.append({"name": name.strip(), "body": body})
    return out


def _parse_templates_loose(text: str) -> List[Dict[str, str]]:
    out: List[Dict[str, str]] = []
    for m in re.finditer(r"<(\w+)([^>]*)>(.*?)</\1>", text, flags=re.S):
        attrs = m.group(2)
        nm = re.search(r'name\s*=\s*"([^"]*)"', attrs)
        out.append({"name": (nm.group(1) if nm else m.group(1)).strip(), "body": _norm_ws(m.group(3))})
    return out


def apply_template(body: str, prompt: str) -> str:
    if not body:
        return prompt
    if "{{insert}}" in body:
        return body.replace("{{insert}}", prompt.strip())
    return (body.strip() + ", " + prompt.strip()).strip(", ")


def append_template(path: str, name: str, body: str) -> bool:
    tpls = parse_templates(path)
    tpls.append({"name": name.strip() or "Template", "body": body.strip()})
    return save_templates_file(path, tpls)


def templates_to_xml(templates: List[Dict[str, str]]) -> str:
    out = ["<templates>"]
    for t in templates:
        safe_name = xml_escape((t.get("name") or "Template").replace('"', "'"))
        body = " ".join((t.get("body") or "").split())
        out.append(f'  <template name="{safe_name}">')
        out.append("    " + xml_escape(body))
        out.append("  </template>")
    out.append("</templates>")
    return "\n".join(out) + "\n"


def save_templates_file(path: str, templates: List[Dict[str, str]]) -> bool:
    return write_text(path, templates_to_xml(templates))


# ---- Tag Groups (Foldered) --------------------------------------------------
def parse_tag_groups(path: str) -> Tuple[List[str], Dict[str, List[Dict[str, str]]]]:
    folders: List[str] = []
    groups: Dict[str, List[Dict[str, str]]] = {}
    current = "General"
    for raw in read_text(path).splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("[") and line.endswith("]") and len(line) > 2:
            current = line[1:-1].strip() or "General"
            if current not in groups:
                groups[current] = []
                folders.append(current)
            continue
        if "|" in line:
            label, body = line.split("|", 1)
            label, body = label.strip(), body.strip()
        else:
            label = body = line
        if body:
            groups.setdefault(current, []).append({"label": label or body, "text": body, "folder": current})
    if "General" in groups and "General" not in folders:
        folders.insert(0, "General")
    if not folders:
        folders, groups = ["General"], {"General": []}
    return folders, groups


def append_tag_group(path: str, label: str, body: str, folder: str = "General") -> bool:
    folders, groups = parse_tag_groups(path)
    fld = folder.strip() or "General"
    if fld not in folders:
        folders.append(fld)
    groups.setdefault(fld, []).append({"label": label.strip() or body.strip(), "text": body.strip(), "folder": fld})
    return save_tags_file(path, folders, groups)


def tags_to_text(folders: List[str], groups: Dict[str, List[Dict[str, str]]]) -> str:
    out = [
        "# Tag groups - one per line.  Format:  Label | text appended to the prompt",
        "# Managed by Horde Studio Lite; manual edits are fully supported.",
        "# A line like [Artists] opens a folder.",
    ]
    for folder in folders:
        out.append("")
        out.append(f"[{folder}]")
        rows = groups.get(folder) or []
        if not rows:
            out.append("# (empty folder)")
        for g in rows:
            label = " ".join((g.get("label") or "").split()).replace("|", "/")
            body = " ".join((g.get("text") or "").split())
            if body:
                out.append(f"{label} | {body}" if label and label != body else body)
    return "\n".join(out) + "\n"


def save_tags_file(path: str, folders: List[str], groups: Dict[str, List[Dict[str, str]]]) -> bool:
    return write_text(path, tags_to_text(folders, groups))


def append_to_prompt(current: str, addition: str) -> str:
    new_text, _pos = append_to_prompt_pos(current, addition)
    return new_text


def append_to_prompt_pos(current: str, addition: str) -> Tuple[str, int]:
    cur = (current or "").rstrip()
    add = (addition or "").strip()
    if not add:
        return cur, len(cur)
    if not cur:
        return add, 0
    if cur.endswith((",", ".", ";", "\n")):
        sep = " " if not cur.endswith("\n") else ""
    else:
        sep = ", "
    joined = cur + sep + add
    return joined, len(cur) + len(sep)


# ---- Wildcards (dynamicprompts + built-in fallback + __[Folder]__) ----------
_RE_WILDCARD_SYNTAX = re.compile(r"__[^_\r\n]+__|\{[^{}\r\n]*\|[^{}\r\n]*\}")
_RE_FOLDER_WC = re.compile(r"__\[([^\[\]\r\n]+)\]__")
_RE_FILE_WC = re.compile(r"__([^_\[\]\r\n][^_\r\n]*)__")
_RE_BRACES = re.compile(r"\{([^{}]*)\}")


def has_wildcard_syntax(text: str) -> bool:
    return bool(text and _RE_WILDCARD_SYNTAX.search(text))


def expand_folder_wildcards(
    text: str,
    tags_by_folder: Optional[Dict[str, List[Dict[str, str]]]],
    rng: Optional[random.Random] = None,
) -> str:
    if not text or not tags_by_folder or "__[" not in text:
        return text
    r = rng or random
    lookup = {k.lower(): v for k, v in tags_by_folder.items()}

    def _sub(match: "re.Match[str]") -> str:
        name = match.group(1).strip().lower()
        entries = lookup.get(name) or []
        if not entries:
            return match.group(0)
        pick = r.choice(entries)
        return str(pick.get("text") or "").strip() or match.group(0)

    return _RE_FOLDER_WC.sub(_sub, text)


def _read_wildcard_lines(name: str) -> List[str]:
    clean = name.strip().replace("\\", "/").strip("/")
    candidates = [
        os.path.join(WILDCARDS_DIR, clean + ".txt"),
        os.path.join(WILDCARDS_DIR, clean),
    ]
    for cand in candidates:
        if os.path.isfile(cand):
            lines = [
                ln.strip()
                for ln in read_text(cand).splitlines()
                if ln.strip() and not ln.strip().startswith("#")
            ]
            if lines:
                return lines
    return []


def _builtin_expand(text: str, rng: Optional[random.Random] = None) -> str:
    r = rng or random
    cur = text
    for _depth in range(6):
        prev = cur

        def _file_sub(m: "re.Match[str]") -> str:
            lines = _read_wildcard_lines(m.group(1))
            return r.choice(lines) if lines else m.group(0)

        cur = _RE_FILE_WC.sub(_file_sub, cur)

        def _brace_sub(m: "re.Match[str]") -> str:
            inner = m.group(1)
            if "|" not in inner:
                return m.group(0)
            choices = [c.strip() for c in inner.split("|")]
            return r.choice(choices) if choices else ""

        cur = _RE_BRACES.sub(_brace_sub, cur)
        if cur == prev:
            break
    return cur


def expand_wildcards(
    text: str,
    tags_by_folder: Optional[Dict[str, List[Dict[str, str]]]] = None,
) -> str:
    if not text or not has_wildcard_syntax(text):
        return text
    step1 = expand_folder_wildcards(text, tags_by_folder)
    if _HAS_DYNAMICPROMPTS and WildcardManager is not None and RandomPromptGenerator is not None:
        try:
            wm = WildcardManager(WILDCARDS_DIR)
            gen = RandomPromptGenerator(wildcard_manager=wm)
            res = gen.generate(step1, num_images=1)
            if res and isinstance(res[0], str) and res[0].strip():
                return _builtin_expand(res[0])
        except Exception as exc:  # noqa: BLE001
            STUDIO_LOG.warn("SYS", f"dynamicprompts fallback triggered: {exc}")
    return _builtin_expand(step1)


# ---- Image Metadata & High-Quality Resizing ---------------------------------
def build_parameters_text(meta: Dict[str, Any]) -> str:
    prompt = str(meta.get("prompt") or "").strip()
    neg = str(meta.get("negative") or "").strip()
    lines = [prompt]
    if neg:
        lines.append(f"Negative prompt: {neg}")
    pairs = []
    if meta.get("steps") is not None:
        pairs.append(f"Steps: {meta['steps']}")
    if meta.get("sampler"):
        pairs.append(f"Sampler: {meta['sampler']}")
    if meta.get("scheduler"):
        pairs.append(f"Schedule type: {meta['scheduler']}")
    if meta.get("cfg") is not None:
        pairs.append(f"CFG scale: {meta['cfg']}")
    if meta.get("seed") is not None:
        pairs.append(f"Seed: {meta['seed']}")
    if meta.get("width") and meta.get("height"):
        pairs.append(f"Size: {meta['width']}x{meta['height']}")
    if meta.get("model"):
        pairs.append(f"Model: {meta['model']}")
    if meta.get("clip_skip"):
        pairs.append(f"Clip skip: {meta['clip_skip']}")
    if meta.get("denoise") is not None:
        pairs.append(f"Denoise: {meta['denoise']}")
    if isinstance(meta.get("aesthetic"), (int, float)):
        pairs.append(f"Aesthetic: {float(meta['aesthetic']):.2f}")
    if pairs:
        lines.append(", ".join(pairs))
    return "\n".join(lines)


def write_image_with_metadata(data: bytes, path: str, meta: Dict[str, Any]) -> str:
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)
    img = QImage.fromData(QByteArray(data))
    final_path = path
    if not img.isNull() and path.lower().endswith(".png"):
        img.setText("parameters", build_parameters_text(meta))
        img.setText("horde_studio_meta", json.dumps(meta, ensure_ascii=False))
        if not img.save(final_path, "PNG"):
            with open(final_path, "wb") as fh:
                fh.write(data)
    else:
        with open(final_path, "wb") as fh:
            fh.write(data)
    sidecar = os.path.splitext(final_path)[0] + ".json"
    write_text(sidecar, json.dumps(meta, indent=2, ensure_ascii=False))
    return final_path


def _parse_parameters_text(text: str) -> Dict[str, Any]:
    out: Dict[str, Any] = {}
    if not text:
        return out
    lines = text.splitlines()
    if not lines:
        return out
    neg_idx = None
    param_idx = None
    for idx, ln in enumerate(lines):
        if ln.startswith("Negative prompt:") and neg_idx is None:
            neg_idx = idx
        elif "Steps:" in ln and ("Sampler:" in ln or "Seed:" in ln):
            param_idx = idx
    p_end = neg_idx if neg_idx is not None else (param_idx if param_idx is not None else len(lines))
    out["prompt"] = "\n".join(lines[:p_end]).strip()
    if neg_idx is not None:
        n_end = param_idx if param_idx is not None else len(lines)
        neg_lines = list(lines[neg_idx:n_end])
        neg_lines[0] = neg_lines[0][len("Negative prompt:") :].strip()
        out["negative"] = "\n".join(neg_lines).strip()
    if param_idx is not None:
        tail = lines[param_idx]
        for key, pat, cast in (
            ("steps", r"Steps:\s*(\d+)", int),
            ("sampler", r"Sampler:\s*([^,]+)", str),
            ("scheduler", r"Schedule type:\s*([^,]+)", str),
            ("cfg", r"CFG scale:\s*([0-9.]+)", float),
            ("seed", r"Seed:\s*([^,]+)", str),
            ("model", r"Model:\s*([^,]+)", str),
            ("clip_skip", r"Clip skip:\s*(\d+)", int),
            ("denoise", r"Denoise:\s*([0-9.]+)", float),
            ("aesthetic", r"Aesthetic:\s*([0-9.]+)", float),
        ):
            m = re.search(pat, tail)
            if m:
                try:
                    out[key] = cast(m.group(1).strip())
                except ValueError:
                    pass
        ms = re.search(r"Size:\s*(\d+)x(\d+)", tail)
        if ms:
            out["width"] = int(ms.group(1))
            out["height"] = int(ms.group(2))
    return out


def read_image_metadata(path: str) -> Dict[str, Any]:
    if not path or not os.path.exists(path):
        return {}
    sidecar = os.path.splitext(path)[0] + ".json"
    if os.path.isfile(sidecar):
        try:
            with open(sidecar, "r", encoding="utf-8") as fh:
                doc = json.load(fh)
            if isinstance(doc, dict):
                return doc
        except (OSError, ValueError):
            pass
    try:
        reader = QImageReader(path)
        reader.setAutoTransform(False)
        raw_json = reader.text("horde_studio_meta")
        if raw_json:
            doc = json.loads(raw_json)
            if isinstance(doc, dict):
                return doc
        params = reader.text("parameters")
        if params:
            return _parse_parameters_text(params)
    except Exception:  # noqa: BLE001
        pass
    return {}


def update_image_metadata(path: str, patch: Dict[str, Any]) -> Dict[str, Any]:
    meta = read_image_metadata(path)
    meta.update(patch)
    sidecar = os.path.splitext(path)[0] + ".json"
    write_text(sidecar, json.dumps(meta, indent=2, ensure_ascii=False))
    if path.lower().endswith(".png") and os.path.isfile(path):
        img = QImage(path)
        if not img.isNull():
            img.setText("parameters", build_parameters_text(meta))
            img.setText("horde_studio_meta", json.dumps(meta, ensure_ascii=False))
            img.save(path, "PNG")
    return meta


def image_to_png_bytes(img: QImage) -> bytes:
    buf = QBuffer()
    buf.open(QBuffer.OpenModeFlag.WriteOnly)
    img.save(buf, "PNG")
    return bytes(buf.data())


def hq_resize(img: QImage, w: int, h: int) -> QImage:
    """High-quality resize: true Pillow Lanczos when installed, else Qt SmoothTransformation."""
    if img.isNull() or (img.width() == w and img.height() == h):
        return img
    if _HAS_PIL and _PILImage is not None:
        try:
            rgba = img.convertToFormat(QImage.Format.Format_RGBA8888)
            ptr = rgba.constBits()
            ptr.setsize(rgba.sizeInBytes())
            pil = _PILImage.frombytes("RGBA", (rgba.width(), rgba.height()), bytes(ptr))
            resample = getattr(getattr(_PILImage, "Resampling", _PILImage), "LANCZOS", _PILImage.BICUBIC)
            pil = pil.resize((w, h), resample)
            raw = pil.tobytes("raw", "RGBA")
            out = QImage(raw, w, h, w * 4, QImage.Format.Format_RGBA8888).copy()
            return out
        except Exception:  # noqa: BLE001
            pass
    return img.scaled(w, h, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)


def is_black_placeholder_frame(data: bytes, dark_luma: int = 12, ratio: float = 0.985) -> bool:
    """Detect censored / blank near-black worker placeholder frames."""
    img = QImage.fromData(QByteArray(data))
    if img.isNull():
        return True
    sample = img.scaled(48, 48, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.FastTransformation)
    sample = sample.convertToFormat(QImage.Format.Format_RGB32)
    w, h = sample.width(), sample.height()
    total = max(1, w * h)
    dark = 0
    for y in range(h):
        for x in range(w):
            px = sample.pixelColor(x, y)
            luma = (px.red() * 299 + px.green() * 587 + px.blue() * 114) // 1000
            if luma <= dark_luma:
                dark += 1
    return (dark / total) >= ratio


# =============================================================================
#  6b. Sound Notification Engine (synthesized WAV cues, plays while unfocused)
# =============================================================================
SOUND_EVENT_LABELS: Dict[str, str] = {
    "sent": "Request sent (GENERATE clicked)",
    "done": "Image generated",
    "fail": "Image failed",
    "upscale": "Tile upscale composed",
}


def _synth_wav(path: str, notes: Sequence[Sequence[float]]) -> None:
    """Render a compact 44.1 kHz 16-bit mono PCM cue. `notes` is a list of
    (freq_hz, start_s, dur_s, gain) tuples; each voice is a warm sine (with a
    touch of 2nd harmonic) under a 4 ms attack and an exponential decay."""
    rate = 44100
    total = int(rate * (max(n[1] + n[2] for n in notes) + 0.06)) + 1
    samples = [0.0] * total
    two_pi = 2.0 * math.pi
    for freq, start, dur, gain in notes:
        i0 = int(start * rate)
        n_len = int(dur * rate)
        decay = 5.5 / max(0.02, dur)
        for i in range(n_len):
            idx = i0 + i
            if idx >= total:
                break
            t = i / float(rate)
            env = min(1.0, t / 0.004) * math.exp(-t * decay)
            wave_s = math.sin(two_pi * freq * t) + 0.28 * math.sin(two_pi * freq * 2.0 * t)
            samples[idx] += wave_s * env * gain
    with wave.open(path, "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(rate)
        frames = bytearray(total * 2)
        for i, v in enumerate(samples):
            iv = int(round(max(-1.0, min(1.0, v)) * 32000.0))
            if iv < 0:
                iv += 65536
            frames[i * 2] = iv & 0xFF
            frames[i * 2 + 1] = (iv >> 8) & 0xFF
        wf.writeframes(bytes(frames))


class SoundEngine:
    """Corporate-grade event chimes synthesized once into data/sounds/ and
    played through QtMultimedia (Windows/macOS/Linux) or winsound (Windows),
    so cues are heard even when the app window is NOT active. Every dependency
    is optional - silence is a fully supported configuration."""

    EVENTS: Tuple[str, ...] = ("sent", "done", "fail", "upscale")
    _NOTES: Dict[str, List[Tuple[float, float, float, float]]] = {
        # soft two-note dispatch blip
        "sent": [(880.0, 0.0, 0.085, 0.30), (1318.51, 0.078, 0.125, 0.24)],
        # rising major arpeggio
        "done": [(523.25, 0.0, 0.10, 0.28), (659.25, 0.088, 0.10, 0.28), (783.99, 0.176, 0.21, 0.28)],
        # low minor descend
        "fail": [(220.0, 0.0, 0.15, 0.32), (164.81, 0.13, 0.32, 0.32)],
        # four-note flourish with octave shimmer
        "upscale": [
            (523.25, 0.0, 0.09, 0.24), (659.25, 0.082, 0.09, 0.24),
            (783.99, 0.164, 0.09, 0.24), (1046.50, 0.246, 0.28, 0.28),
        ],
    }

    def __init__(self) -> None:
        self.master = True
        self.enabled: Dict[str, bool] = {e: True for e in self.EVENTS}
        self._players: Dict[str, Any] = {}
        self.backend = "none"
        self._backend_ready = False
        try:
            os.makedirs(SOUNDS_DIR, exist_ok=True)
            dirty = False
            for ev, notes in self._NOTES.items():
                path = os.path.join(SOUNDS_DIR, f"{ev}.wav")
                if not os.path.isfile(path) or os.path.getsize(path) < 200:
                    _synth_wav(path, notes)
                    dirty = True
            if dirty:
                STUDIO_LOG.info("SYS", f"Sound cues synthesized into {SOUNDS_DIR}")
        except Exception as exc:  # noqa: BLE001 - sound must never break the app
            STUDIO_LOG.warn("SYS", f"Sound engine disabled ({exc})")

    def _ensure_backend(self) -> None:
        """Build the playback players lazily: QSoundEffect objects require a
        living QApplication, which does not exist at module-import time."""
        if self._backend_ready:
            return
        self._backend_ready = True
        if QApplication.instance() is None:
            return  # stay silent until an app exists
        try:
            if _HAS_QTMULTIMEDIA and QSoundEffect is not None:
                for ev in self.EVENTS:
                    eff = QSoundEffect()
                    eff.setSource(QUrl.fromLocalFile(os.path.join(SOUNDS_DIR, f"{ev}.wav")))
                    eff.setVolume(0.6)
                    self._players[ev] = eff
                self.backend = "qtmultimedia"
            elif _HAS_WINSOUND and winsound is not None:
                self.backend = "winsound"
        except Exception as exc:  # noqa: BLE001
            STUDIO_LOG.warn("SYS", f"Sound playback unavailable ({exc})")
            self.backend = "none"

    def set_prefs(self, master: bool, enabled_map: Optional[Dict[str, bool]] = None) -> None:
        self.master = bool(master)
        for ev in self.EVENTS:
            if enabled_map and ev in enabled_map:
                self.enabled[ev] = bool(enabled_map[ev])

    def play(self, event: str) -> None:
        if not self.master or not self.enabled.get(event, True):
            return
        self._ensure_backend()
        eff = self._players.get(event)
        if eff is not None:
            try:
                eff.play()
                return
            except Exception:  # noqa: BLE001
                pass
        if _HAS_WINSOUND and winsound is not None:
            try:
                winsound.PlaySound(
                    os.path.join(SOUNDS_DIR, f"{event}.wav"),
                    winsound.SND_FILENAME | winsound.SND_ASYNC | winsound.SND_NODEFAULT,
                )
            except Exception:  # noqa: BLE001
                pass


SOUNDS = SoundEngine()


# =============================================================================
#  6c. Image Edit Pipeline (Lightroom-style grading + masked compositing)
# -----------------------------------------------------------------------------
# The full-quality path runs through Pillow (C speed): LUT ops for exposure /
# temperature / highlights / shadows / contrast, ImageEnhance for saturation,
# an adaptive global approximation for vibrance, UnsharpMask for HDR local
# contrast, screen-blended blur for bloom and effect-noise grain. Without
# Pillow the pipeline degrades to C-speed Qt scanline LUTs (exposure,
# temperature, highlights, shadows, contrast, desaturation) and reports the
# skipped effect names so the UI can say so honestly.
# =============================================================================
EDIT_ADJUST_KEYS: Tuple[str, ...] = (
    "exposure", "contrast", "highlights", "shadows", "temperature",
    "saturation", "vibrance", "hdr", "bloom", "sharpness", "vignette", "grain",
)
EDIT_ADJUST_LABELS: Dict[str, str] = {
    "exposure": "Exposure",
    "contrast": "Contrast",
    "highlights": "Highlights",
    "shadows": "Shadows",
    "temperature": "Temp",
    "saturation": "Saturation",
    "vibrance": "Vibrance",
    "hdr": "Clarity / HDR",
    "bloom": "Bloom",
    "sharpness": "Sharpness",
    "vignette": "Vignette",
    "grain": "Film Grain",
}
EDIT_ADJUST_TOOLTIPS: Dict[str, str] = {
    "exposure": "Overall exposure in photographic stops (double-click to reset)",
    "contrast": "Midtone contrast around the 128 pivot (double-click to reset)",
    "highlights": "Highlights recovery / lift — bright region gain (double-click to reset)",
    "shadows": "Shadows recovery / deepen — dark region lift (double-click to reset)",
    "temperature": "Color temperature: warm golden (+) / cool sapphire (-) (double-click to reset)",
    "saturation": "Global color saturation (double-click to reset)",
    "vibrance": "Adaptive saturation — boosts muted colors while protecting skin & vivid hues",
    "hdr": "Local clarity / HDR micro-contrast (large-radius unsharp mask)",
    "bloom": "Optical highlight bloom / dreamy diffusion glow",
    "sharpness": "Crisp optical detail sharpening (+) or gentle soften (-)",
    "vignette": "Cinematic corner darkening (+) or airy bright-edge lift (-)",
    "grain": "Organic analog 35mm film grain texture",
}
EDIT_EFFECT_KEYS: Tuple[str, ...] = ("hdr", "bloom", "sharpness", "vignette", "grain", "vibrance")


def default_edit_adjustments() -> Dict[str, float]:
    return {k: 0.0 for k in EDIT_ADJUST_KEYS}


def edit_adjustments_active(adj: Dict[str, Any]) -> bool:
    return any(abs(float(adj.get(k, 0.0) or 0.0)) > 0.01 for k in EDIT_ADJUST_KEYS)


def _edit_lut(fn: Any) -> List[int]:
    out: List[int] = []
    for v in range(256):
        iv = int(fn(v) + 0.5)
        if iv < 0:
            iv = 0
        elif iv > 255:
            iv = 255
        out.append(iv)
    return out


def _qimg_to_pil(img: QImage):
    rgba = img.convertToFormat(QImage.Format.Format_RGBA8888)
    ptr = rgba.constBits()
    ptr.setsize(rgba.sizeInBytes())
    return _PILImage.frombytes("RGBA", (rgba.width(), rgba.height()), bytes(ptr))


def _pil_to_qimg(pil) -> QImage:
    pil = pil.convert("RGBA")
    raw = pil.tobytes("raw", "RGBA")
    return QImage(raw, pil.width, pil.height, pil.width * 4, QImage.Format.Format_RGBA8888).copy()


def _pil_mean_saturation(pil) -> float:
    try:
        hsv = pil.convert("RGB").resize((48, 48)).convert("HSV")
        hist = hsv.histogram()
        total = 48 * 48
        s_sum = sum(i * c for i, c in enumerate(hist[256:512]))
        return min(1.0, s_sum / float(total * 255))
    except Exception:  # noqa: BLE001
        return 0.35


def _apply_edit_pil(pil, a: Dict[str, float]):
    w, h = pil.size
    if abs(a["exposure"]) > 0.01:
        f = 2.0 ** (a["exposure"] / 100.0)
        pil = pil.point(_edit_lut(lambda v: v * f) * 3)
    if abs(a["temperature"]) > 0.01:
        t = a["temperature"] / 100.0
        r, g, b = pil.split()
        r = r.point(_edit_lut(lambda v: v * (1.0 + 0.35 * t)))
        b = b.point(_edit_lut(lambda v: v * (1.0 - 0.35 * t)))
        pil = _PILImage.merge("RGB", (r, g, b))
    if abs(a["highlights"]) > 0.01:
        k = a["highlights"] / 100.0
        pil = pil.point(_edit_lut(
            lambda v: v * (1.0 + 0.62 * k * ((max(0.0, v - 108.0) / 147.0) ** 1.4))
        ) * 3)
    if abs(a["shadows"]) > 0.01:
        k = a["shadows"] / 100.0
        pil = pil.point(_edit_lut(
            lambda v: v * (1.0 + 0.62 * k * ((max(0.0, 146.0 - v) / 146.0) ** 1.4))
        ) * 3)
    if abs(a["contrast"]) > 0.01:
        k = 1.0 + a["contrast"] / 100.0
        pil = pil.point(_edit_lut(lambda v: 128.0 + (v - 128.0) * k) * 3)
    if a["saturation"] < -0.01:
        pil = _PIL_ENH.Color(pil).enhance(max(0.0, 1.0 + a["saturation"] / 100.0))
    elif a["saturation"] > 0.01:
        pil = _PIL_ENH.Color(pil).enhance(1.0 + a["saturation"] / 100.0)
    if abs(a["vibrance"]) > 0.01:
        sat0 = _pil_mean_saturation(pil)
        pil = _PIL_ENH.Color(pil).enhance(max(0.0, 1.0 + (a["vibrance"] / 100.0) * (1.0 - sat0)))
    if a["hdr"] > 0.01:
        pil = pil.filter(_PIL_FILT.UnsharpMask(
            radius=max(8, min(w, h) // 14), percent=int(a["hdr"] * 1.5), threshold=3
        ))
    if a["bloom"] > 0.01:
        bright = pil.point(_edit_lut(lambda v: max(0.0, (v - 165.0) * 255.0 / 90.0)) * 3)
        bright = bright.filter(_PIL_FILT.GaussianBlur(radius=max(4, min(w, h) // 22)))
        screened = _PIL_CHOPS.screen(pil, bright)
        pil = _PILImage.blend(pil, screened, min(1.0, a["bloom"] / 100.0 * 0.85))
    if a.get("sharpness", 0.0) > 0.01:
        pil = pil.filter(_PIL_FILT.UnsharpMask(
            radius=max(1.0, min(w, h) / 480.0), percent=int(a["sharpness"] * 1.45), threshold=2
        ))
    elif a.get("sharpness", 0.0) < -0.01:
        r_blur = max(0.4, (-a["sharpness"] / 100.0) * max(1.5, min(w, h) / 260.0))
        pil = pil.filter(_PIL_FILT.GaussianBlur(radius=r_blur))
    if abs(a.get("vignette", 0.0)) > 0.01:
        vmask = _cached_vignette_mask(w, h)
        v_amt = min(0.88, abs(a["vignette"]) / 100.0 * 0.82)
        edge = _PILImage.new("RGB", (w, h), (8, 8, 12) if a["vignette"] > 0 else (250, 250, 252))
        pil = _PILImage.composite(edge, pil, vmask.point(lambda v: int(v * v_amt)))
    if a["grain"] > 0.01:
        try:
            noise = _PILImage.effect_noise((w, h), 6.0 + a["grain"] * 0.55).convert("RGB")
            noised = _PIL_CHOPS.add(pil, noise, 1.0, -128)
            pil = _PILImage.blend(pil, noised, a["grain"] / 100.0)
        except Exception:  # noqa: BLE001 - effect_noise unsupported on some builds
            pass
    return pil


_VIGNETTE_CACHE: Dict[Tuple[int, int], Any] = {}


def _cached_vignette_mask(w: int, h: int):
    key = (w, h)
    hit = _VIGNETTE_CACHE.get(key)
    if hit is not None:
        return hit
    gw, gh = 96, 96
    buf = bytearray(gw * gh)
    for y in range(gh):
        ny = (y / (gh - 1.0)) * 2.0 - 1.0
        row_off = y * gw
        for x in range(gw):
            nx = (x / (gw - 1.0)) * 2.0 - 1.0
            d = math.hypot(nx * 0.92, ny * 0.92)
            t = max(0.0, min(1.0, (d - 0.42) / 0.92))
            buf[row_off + x] = int(round(255.0 * (t * t * (3.0 - 2.0 * t))))
    base = _PILImage.frombytes("L", (gw, gh), bytes(buf))
    bi = getattr(getattr(_PILImage, "Resampling", _PILImage), "BILINEAR", 2)
    mask = base.resize((max(2, w), max(2, h)), bi)
    if len(_VIGNETTE_CACHE) > 8:
        _VIGNETTE_CACHE.clear()
    _VIGNETTE_CACHE[key] = mask
    return mask


def _compose_luts(outer: List[int], inner: List[int]) -> List[int]:
    """Compose two 256-entry LUTs: result[v] = outer[inner[v]]."""
    return [outer[inner[v]] for v in range(256)]


def _apply_edit_qt(img: QImage, a: Dict[str, float]) -> Tuple[QImage, List[str]]:
    """Qt-only fallback: C-speed scanline LUT ops via bytes.translate and
    stepped bytearray slice assignment; the PIL-exclusive effects are skipped
    and reported by name."""
    skipped: List[str] = []
    base_lut: Optional[List[int]] = None

    def _apply(lut: Optional[List[int]], fn: Any) -> List[int]:
        return fn if lut is None else _compose_luts(fn, lut)

    if abs(a["exposure"]) > 0.01:
        f = 2.0 ** (a["exposure"] / 100.0)
        base_lut = _apply(base_lut, _edit_lut(lambda v: v * f))
    if abs(a["highlights"]) > 0.01:
        k = a["highlights"] / 100.0
        base_lut = _apply(base_lut, _edit_lut(
            lambda v: v * (1.0 + 0.62 * k * ((max(0.0, v - 108.0) / 147.0) ** 1.4))
        ))
    if abs(a["shadows"]) > 0.01:
        k = a["shadows"] / 100.0
        base_lut = _apply(base_lut, _edit_lut(
            lambda v: v * (1.0 + 0.62 * k * ((max(0.0, 146.0 - v) / 146.0) ** 1.4))
        ))
    if abs(a["contrast"]) > 0.01:
        k = 1.0 + a["contrast"] / 100.0
        base_lut = _apply(base_lut, _edit_lut(lambda v: 128.0 + (v - 128.0) * k))
    lut_r: Optional[List[int]] = base_lut
    lut_g: Optional[List[int]] = base_lut
    lut_b: Optional[List[int]] = base_lut
    if abs(a["temperature"]) > 0.01:
        t = a["temperature"] / 100.0
        warm = _edit_lut(lambda v: v * (1.0 + 0.35 * t))
        cool = _edit_lut(lambda v: v * (1.0 - 0.35 * t))
        lut_r = warm if lut_r is None else _compose_luts(warm, lut_r)
        lut_b = cool if lut_b is None else _compose_luts(cool, lut_b)

    work = img.convertToFormat(QImage.Format.Format_RGB888)
    if lut_r is not None or lut_g is not None or lut_b is not None:
        w, h = work.width(), work.height()
        bpl = work.bytesPerLine()
        src_ptr = work.constBits()
        src_ptr.setsize(work.sizeInBytes())
        src = memoryview(src_ptr).cast("B")
        buf = bytearray(work.sizeInBytes())
        same = (lut_r is lut_g is lut_b)
        lr = bytes(lut_r) if lut_r is not None else None
        lg = bytes(lut_g) if lut_g is not None else None
        lb = bytes(lut_b) if lut_b is not None else None
        for y in range(h):
            base_off = y * bpl
            if same and lr is not None:
                buf[base_off : base_off + w * 3] = bytes(src[base_off : base_off + w * 3]).translate(lr)
                continue
            row = src[base_off : base_off + w * 3]
            r = bytes(row[0::3])
            g = bytes(row[1::3])
            b = bytes(row[2::3])
            if lr is not None:
                r = r.translate(lr)
            if lg is not None:
                g = g.translate(lg)
            if lb is not None:
                b = b.translate(lb)
            buf[base_off : base_off + w * 3 : 3] = r
            buf[base_off + 1 : base_off + w * 3 : 3] = g
            buf[base_off + 2 : base_off + w * 3 : 3] = b
        rebuilt = QImage(bytes(buf), w, h, bpl, QImage.Format.Format_RGB888).copy()
        work = rebuilt
    if a["saturation"] < -0.01:
        t = -a["saturation"] / 100.0
        gray = work.convertToFormat(QImage.Format.Format_Grayscale8).convertToFormat(
            QImage.Format.Format_RGB32
        )
        base32 = work.convertToFormat(QImage.Format.Format_RGB32)
        p = QPainter(base32)
        p.setOpacity(t)
        p.drawImage(0, 0, gray)
        p.end()
        work = base32.convertToFormat(QImage.Format.Format_RGB888)
    elif a["saturation"] > 0.01:
        skipped.append("saturation+")
    if abs(a["vibrance"]) > 0.01:
        skipped.append("vibrance")
    for k in ("hdr", "bloom", "grain"):
        if a[k] > 0.01:
            skipped.append(k)
    return work, skipped


def apply_edit_pipeline(
    img: QImage,
    adj: Dict[str, Any],
    mask: Optional[QImage] = None,
    invert_mask: bool = False,
    max_side: int = 0,
    lut_key: str = "",
    lut_intensity: int = 100,
    flares: Optional[List[Dict[str, Any]]] = None,
    depth_img: Optional[QImage] = None,
    depth_fx: Optional[Dict[str, Any]] = None,
) -> Tuple[QImage, List[str]]:
    """Apply the complete v7.0 studio grading stack to `img`:
    1. Manual tone/color adjustments + Cinematic LUT grade (mask scope respected)
    2. Cinematic Depth Map Post-Processing (multi-plane bokeh DOF, atmospheric
       haze, silhouette rim backlight, FG/BG relighting, optical lens CA & depth
       vignette) when `depth_img` is loaded and any depth effect is active
    3. Pure-vector horizontal anamorphic lens flares, with optional 3D depth
       occlusion behind foreground planes.
    Returns (image, skipped_effect_names)."""
    if img.isNull():
        return img, []
    a = {k: max(-100.0, min(100.0, float(adj.get(k, 0.0) or 0.0))) for k in EDIT_ADJUST_KEYS}
    base = img
    if max_side and (img.width() > max_side or img.height() > max_side):
        base = img.scaled(
            max_side, max_side, Qt.AspectRatioMode.KeepAspectRatio,
            Qt.TransformationMode.SmoothTransformation,
        )
    skipped: List[str] = []
    lut_active = bool(lut_key) and lut_key in LUT_FILTER_BY_KEY and int(lut_intensity) > 0
    if not edit_adjustments_active(a) and not lut_active:
        result = base
    elif _HAS_PIL and _PILImage is not None:
        pil = _qimg_to_pil(base).convert("RGB")
        if edit_adjustments_active(a):
            pil = _apply_edit_pil(pil, a)
        if lut_active:
            try:
                pil = _apply_lut_filter_pil(pil, LUT_FILTER_BY_KEY[lut_key], int(lut_intensity))
            except Exception:  # noqa: BLE001
                skipped.append("lut")
        result = _pil_to_qimg(pil).convertToFormat(QImage.Format.Format_RGB32)
    else:
        result, skipped_qt = _apply_edit_qt(base, a)
        if lut_active:
            try:
                result = _apply_lut_filter_qt(result, LUT_FILTER_BY_KEY[lut_key], int(lut_intensity))
            except Exception:  # noqa: BLE001
                skipped.append("lut")
        for k in skipped_qt:
            if k not in skipped:
                skipped.append(k)
        result = result.convertToFormat(QImage.Format.Format_RGB32)
    if mask is not None and not mask.isNull():
        if mask.width() != result.width() or mask.height() != result.height():
            mask = mask.scaled(
                result.width(), result.height(),
                Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.FastTransformation,
            )
        result = _composite_masked(base.convertToFormat(QImage.Format.Format_RGB32), result, mask, invert_mask)
    if depth_img is not None and not depth_img.isNull() and depth_fx and depth_fx_active(depth_fx):
        result, d_skip = apply_depth_cinematic_pipeline(result, depth_img, depth_fx)
        for k in d_skip:
            if k not in skipped:
                skipped.append(k)
    visible_flares = _effective_visible_flares(flares)
    if visible_flares:
        occ_str = int((depth_fx or {}).get("flare_occ", 0)) if (depth_img is not None and not depth_img.isNull()) else 0
        occ_plane = int((depth_fx or {}).get("flare_occ_plane", 55))
        occ_inv = bool((depth_fx or {}).get("invert_polarity", False))
        result = apply_flares_qt(
            result, visible_flares,
            depth_img=depth_img if occ_str > 0 else None,
            depth_occ=occ_str,
            depth_plane=occ_plane,
            invert_depth=occ_inv,
        )
    return result, skipped


def _composite_masked(base: QImage, adjusted: QImage, mask: QImage, invert: bool) -> QImage:
    """Keep `adjusted` only where the mask is painted (alpha > 0) - or the
    inverse when `invert` - via C-speed QPainter composition modes."""
    out = base.copy()
    layer = adjusted.convertToFormat(QImage.Format.Format_ARGB32)
    p = QPainter(layer)
    p.setCompositionMode(
        QPainter.CompositionMode.CompositionMode_DestinationOut if invert
        else QPainter.CompositionMode.CompositionMode_DestinationIn
    )
    p.drawImage(0, 0, mask.convertToFormat(QImage.Format.Format_ARGB32))
    p.end()
    p2 = QPainter(out)
    p2.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceOver)
    p2.drawImage(0, 0, layer)
    p2.end()
    return out


def stamp_edit_mask(mask: QImage, x: float, y: float, radius: float, softness: float, erase: bool) -> None:
    """Stamp one soft round brush dab into the mask (or erase with erase=True).
    alpha falls off from 1 at the core to 0 at radius; softness 0..100 widens
    the gradient ramp."""
    if mask.isNull() or radius <= 0.5:
        return
    p = QPainter(mask)
    p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    p.setCompositionMode(
        QPainter.CompositionMode.CompositionMode_DestinationOut if erase
        else QPainter.CompositionMode.CompositionMode_SourceOver
    )
    core = max(0.0, min(0.97, 1.0 - (softness / 100.0) * 0.92))
    grad = QRadialGradient(QPointF(x, y), radius)
    grad.setColorAt(0.0, QColor(255, 0, 0, 255))
    grad.setColorAt(core, QColor(255, 0, 0, 255))
    grad.setColorAt(1.0, QColor(255, 0, 0, 0))
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QBrush(grad))
    p.drawEllipse(QPointF(x, y), radius, radius)
    p.end()


def build_brush_dab(
    radius: float,
    softness: float,
    color: QColor,
    alpha: float = 1.0,
) -> QImage:
    """Pre-render one soft round brush dab into an ARGB32_Premultiplied stamp.
    Cached by EditCanvas so high-speed brush strokes blit the pre-baked dab in
    a single QPainter session — zero gradient reallocation, zero lag/freezes."""
    r = max(1.0, float(radius))
    dim = max(4, int(math.ceil(r * 2.0)) + 2)
    cx = dim * 0.5
    dab = QImage(dim, dim, QImage.Format.Format_ARGB32_Premultiplied)
    dab.fill(Qt.GlobalColor.transparent)
    p = QPainter(dab)
    p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    a = max(0.0, min(1.0, float(alpha)))
    core_col = QColor(color)
    core_col.setAlpha(int(round(255 * a)))
    mid_col = QColor(color)
    mid_col.setAlpha(int(round(255 * a * 0.42)))
    edge_col = QColor(color)
    edge_col.setAlpha(0)
    core = max(0.0, min(0.96, 1.0 - (max(0.0, min(100.0, float(softness))) / 100.0) * 0.92))
    grad = QRadialGradient(QPointF(cx, cx), r)
    grad.setColorAt(0.0, core_col)
    if core > 0.02:
        grad.setColorAt(core, core_col)
    if core < 0.88:
        grad.setColorAt(core + (1.0 - core) * 0.52, mid_col)
    grad.setColorAt(1.0, edge_col)
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QBrush(grad))
    p.drawEllipse(QPointF(cx, cx), r, r)
    p.end()
    return dab


def stamp_paint_dab(
    layer: QImage,
    x: float,
    y: float,
    radius: float,
    softness: float,
    color: QColor,
    alpha: float,
    erase: bool = False,
) -> None:
    if layer.isNull() or radius <= 0.5:
        return
    dab = build_brush_dab(radius, softness, color, alpha)
    p = QPainter(layer)
    p.setCompositionMode(
        QPainter.CompositionMode.CompositionMode_DestinationOut if erase
        else QPainter.CompositionMode.CompositionMode_SourceOver
    )
    half = dab.width() * 0.5
    p.drawImage(QPointF(x - half, y - half), dab)
    p.end()


def blur_alpha_qimage(img: QImage, radius: float) -> QImage:
    """Soften ONLY the alpha channel of an ARGB mask/shape image by ~radius px.
    Uses a true Gaussian blur when Pillow is available; falls back to a
    ping-pong downscale (C-speed, smooth filters) otherwise."""
    if img.isNull() or radius <= 0.5:
        return img
    if _HAS_PIL and _PIL_FILT is not None:
        pil = _qimg_to_pil(img.convertToFormat(QImage.Format.Format_ARGB32))
        r, g, b, a = pil.split()
        a = a.filter(_PIL_FILT.GaussianBlur(radius))
        # alpha-only blur keeps hue crisp while edges melt smoothly
        return _pil_to_qimg(_PILImage.merge("RGBA", (r, g, b, a)))
    # Fallback: down/up-scale ping-pong (always smooth, always C-speed)
    f = max(2.0, min(10.0, radius / 2.0))
    w = max(1, int(img.width() / f))
    h = max(1, int(img.height() / f))
    small = img.scaled(w, h, Qt.AspectRatioMode.IgnoreAspectRatio,
                       Qt.TransformationMode.SmoothTransformation)
    return small.scaled(img.width(), img.height(), Qt.AspectRatioMode.IgnoreAspectRatio,
                        Qt.TransformationMode.SmoothTransformation)


def polygon_signed_area(pts: Sequence[QPointF]) -> float:
    """Shoelace area (screen coords, y-down). Positive = clockwise on screen."""
    n = len(pts)
    if n < 3:
        return 0.0
    s = 0.0
    for i in range(n):
        p1 = pts[i]
        p2 = pts[(i + 1) % n]
        s += p1.x() * p2.y() - p2.x() * p1.y()
    return s / 2.0


def offset_polygon_points(pts: Sequence[QPointF], d: float) -> List[QPointF]:
    """Offset a closed polygon OUTWARD for d > 0 and INWARD for d < 0 using a
    miter (angle-bisector) construction with spike clamping. Returns the new
    vertex list; the input list is never modified."""
    n = len(pts)
    if n < 3 or abs(d) < 0.25:
        return [QPointF(p) for p in pts]
    # outward normals only flip when the winding is counter-clockwise on screen
    sign = 1.0 if polygon_signed_area(pts) >= 0 else -1.0
    out: List[QPointF] = []
    for i in range(n):
        p_prev = pts[(i - 1) % n]
        p_cur = pts[i]
        p_next = pts[(i + 1) % n]
        e1 = QPointF(p_cur.x() - p_prev.x(), p_cur.y() - p_prev.y())
        e2 = QPointF(p_next.x() - p_cur.x(), p_next.y() - p_cur.y())
        l1 = math.hypot(e1.x(), e1.y())
        l2 = math.hypot(e2.x(), e2.y())
        if l1 < 1e-6 or l2 < 1e-6:
            out.append(QPointF(p_cur))
            continue
        n1 = QPointF(sign * e1.y() / l1, -sign * e1.x() / l1)
        n2 = QPointF(sign * e2.y() / l2, -sign * e2.x() / l2)
        bx = n1.x() + n2.x()
        by = n1.y() + n2.y()
        bl = math.hypot(bx, by)
        if bl < 1e-6:
            out.append(QPointF(p_cur.x() + n1.x() * d, p_cur.y() + n1.y() * d))
            continue
        bx /= bl
        by /= bl
        cos_half = max(-1.0, min(1.0, bx * n1.x() + by * n1.y()))
        sin_half = math.sqrt(max(0.0, 1.0 - cos_half * cos_half))
        miter = d / max(0.45, sin_half)   # clamp spikes on very sharp corners
        out.append(QPointF(p_cur.x() + bx * miter, p_cur.y() + by * miter))
    return out


def polygon_path(pts: Sequence[QPointF]) -> QPainterPath:
    """Straight-edged closed polygon path."""
    path = QPainterPath()
    if not pts:
        return path
    path.moveTo(pts[0])
    for p in pts[1:]:
        path.lineTo(p)
    path.closeSubpath()
    return path


def smooth_polygon_path(pts: Sequence[QPointF]) -> QPainterPath:
    """Vector-like rounded selection: a closed Catmull-Rom spline through the
    clicked points, converted to cubic Bezier segments (centripetal-ish
    tangent scaling keeps overshoot small on uneven point spacing)."""
    n = len(pts)
    if n < 3:
        return polygon_path(pts)
    path = QPainterPath()
    path.moveTo(pts[0])
    for i in range(n):
        p0 = pts[(i - 1) % n]
        p1 = pts[i]
        p2 = pts[(i + 1) % n]
        p3 = pts[(i + 2) % n]
        c1 = QPointF(p1.x() + (p2.x() - p0.x()) / 6.0, p1.y() + (p2.y() - p0.y()) / 6.0)
        c2 = QPointF(p2.x() - (p3.x() - p1.x()) / 6.0, p2.y() - (p3.y() - p1.y()) / 6.0)
        path.cubicTo(c1, c2, p2)
    path.closeSubpath()
    return path


def rotate_qimage_about_center(img: QImage, deg: float) -> QImage:
    """Rotate an image around its own center WITHOUT changing the canvas size:
    the output keeps the exact input dimensions, content rotates under the
    frame and the corners leaving the original canvas become transparent —
    ready to be filled with the retouch brush."""
    if img.isNull() or abs(deg) < 0.01:
        return img
    out = QImage(img.size(), QImage.Format.Format_ARGB32_Premultiplied)
    out.fill(Qt.GlobalColor.transparent)
    p = QPainter(out)
    p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
    t = QTransform()
    t.translate(img.width() / 2.0, img.height() / 2.0)
    t.rotate(deg)
    t.translate(-img.width() / 2.0, -img.height() / 2.0)
    p.setTransform(t)
    p.drawImage(0, 0, img)
    p.end()
    return out


def mask_coverage(mask: QImage) -> float:
    """Fraction of the image covered by painted mask (sampled on a 96px grid)."""
    if mask.isNull():
        return 0.0
    small = mask.scaled(96, 96, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.FastTransformation)
    small = small.convertToFormat(QImage.Format.Format_ARGB32)
    hit = 0
    for y in range(96):
        for x in range(96):
            if (small.pixel(x, y) >> 24) > 16:
                hit += 1
    return hit / (96.0 * 96.0)


