def _lut_filmic_tone(s_curve: float, shoulder: float = 0.0, lift: float = 0.0) -> List[int]:
    """Monotone filmic curve: smoothstep S-contrast + highlight shoulder + floor lift."""
    k = max(0.0, min(1.0, float(s_curve)))
    sh = max(0.0, min(0.45, float(shoulder)))
    lf = max(0.0, min(0.10, float(lift)))
    out: List[int] = []
    for v in range(256):
        t = v / 255.0
        s = t * t * (3.0 - 2.0 * t)
        y = t + k * (s - t)
        if sh > 0.001 and y > 0.65:
            hi = (y - 0.65) / 0.35
            y = 0.65 + 0.35 * (hi - sh * 0.22 * hi * (1.0 - hi))
        y = y * (1.0 - lf) + lf
        out.append(max(0, min(255, int(round(255.0 * y)))))
    return out


def _lut_channel_gain(factor: float) -> List[int]:
    f = max(0.0, min(1.6, factor))
    return [min(255, int(round(v * f))) for v in range(256)]


def _lut_zone_mask_lut(zone: str) -> List[int]:
    out: List[int] = []
    for v in range(256):
        t = v / 255.0
        if zone == "shadow":
            x = max(0.0, 1.0 - t / 0.56) ** 1.65
        elif zone == "mid":
            x = max(0.0, 1.0 - abs(t - 0.50) / 0.42) ** 1.6
        else:
            x = max(0.0, (t - 0.42) / 0.58) ** 1.65
        out.append(max(0, min(255, int(round(255.0 * x)))))
    return out


def _apply_lut_filter_pil(pil, spec: Dict[str, Any], intensity: int):
    k = max(0.0, min(1.0, intensity / 100.0))
    if k <= 0.001:
        return pil
    w, h = pil.size
    graded = pil
    tone_lut = _lut_filmic_tone(spec.get("s_curve", 0.0), spec.get("shoulder", 0.0), spec.get("lift", 0.0))
    graded = graded.point(tone_lut * 3)
    mat = spec.get("matrix")
    if mat and len(mat) == 9:
        try:
            m12 = (mat[0], mat[1], mat[2], 0.0, mat[3], mat[4], mat[5], 0.0, mat[6], mat[7], mat[8], 0.0)
            graded = graded.convert("RGB", m12)
        except Exception:
            pass
    t = float(spec.get("temp", 0.0) or 0.0)
    tg = float(spec.get("tint_g", 0.0) or 0.0)
    if abs(t) > 0.001 or abs(tg) > 0.001:
        r, g, b = graded.split()
        if abs(t) > 0.001:
            r = r.point(_lut_channel_gain(1.0 + 0.16 * t))
            b = b.point(_lut_channel_gain(1.0 - 0.16 * t))
        if abs(tg) > 0.001:
            g = g.point(_lut_channel_gain(1.0 + 0.10 * tg))
        graded = _PILImage.merge("RGB", (r, g, b))
    s_amt = float(spec.get("shadow_amt", 0.0) or 0.0)
    m_amt = float(spec.get("mid_amt", 0.0) or 0.0)
    h_amt = float(spec.get("high_amt", 0.0) or 0.0)
    if s_amt > 0.001 or m_amt > 0.001 or h_amt > 0.001:
        luma = graded.convert("L")
        if s_amt > 0.001 and spec.get("shadow_color"):
            smask = luma.point(_lut_zone_mask_lut("shadow")).point(lambda v: int(v * s_amt))
            slayer = _PIL_CHOPS.multiply(graded, _PILImage.new("RGB", graded.size, spec["shadow_color"]))
            graded = _PILImage.composite(slayer, graded, smask)
        if m_amt > 0.001 and spec.get("mid_color"):
            mmask = luma.point(_lut_zone_mask_lut("mid")).point(lambda v: int(v * m_amt))
            mfn = getattr(_PIL_CHOPS, "soft_light", _PIL_CHOPS.multiply)
            mlayer = mfn(graded, _PILImage.new("RGB", graded.size, spec["mid_color"]))
            graded = _PILImage.composite(mlayer, graded, mmask)
        if h_amt > 0.001 and spec.get("high_color"):
            hmask = luma.point(_lut_zone_mask_lut("high")).point(lambda v: int(v * h_amt))
            hlayer = _PIL_CHOPS.screen(graded, _PILImage.new("RGB", graded.size, spec["high_color"]))
            graded = _PILImage.composite(hlayer, graded, hmask)
    sat = float(spec.get("sat", 1.0) or 1.0)
    if abs(sat - 1.0) > 0.001 and _PIL_ENH is not None:
        graded = _PIL_ENH.Color(graded).enhance(sat)
    hal = float(spec.get("halation", 0.0) or 0.0)
    if hal > 0.01 and _PIL_FILT is not None:
        bright = graded.point(_edit_lut(lambda v: max(0.0, (v - 182.0) * 255.0 / 73.0)) * 3)
        glow = bright.filter(_PIL_FILT.GaussianBlur(radius=max(3, min(w, h) // 42)))
        hc = spec.get("hal_color") or (255, 240, 225)
        gr, gg, gb = glow.split()
        gain_h = 0.46 * hal
        gr = gr.point(lambda v: min(255, int(v * gain_h * (hc[0] / 255.0))))
        gg = gg.point(lambda v: min(255, int(v * gain_h * (hc[1] / 255.0))))
        gb = gb.point(lambda v: min(255, int(v * gain_h * (hc[2] / 255.0))))
        graded = _PIL_CHOPS.screen(graded, _PILImage.merge("RGB", (gr, gg, gb)))
    if k >= 0.999:
        return graded
    return _PILImage.blend(pil, graded, k)


def _apply_lut_filter_qt(img: QImage, spec: Dict[str, Any], intensity: int) -> QImage:
    k = max(0.0, min(1.0, intensity / 100.0))
    if k <= 0.001 or img.isNull():
        return img
    tone = _lut_filmic_tone(spec.get("s_curve", 0.0), spec.get("shoulder", 0.0), spec.get("lift", 0.0))
    t = float(spec.get("temp", 0.0) or 0.0)
    tg = float(spec.get("tint_g", 0.0) or 0.0)
    sc = spec.get("shadow_color") or (0, 0, 0)
    hc = spec.get("high_color") or (255, 255, 255)
    sa = float(spec.get("shadow_amt", 0.0) or 0.0)
    ha = float(spec.get("high_amt", 0.0) or 0.0)
    gains = (1.0 + 0.16 * t, 1.0 + 0.10 * tg, 1.0 - 0.16 * t)
    ch_luts: List[bytes] = []
    for ci in range(3):
        tbl = bytearray(256)
        g_fac, s_col, h_col = gains[ci], sc[ci] / 255.0, hc[ci] / 255.0
        for v in range(256):
            y = min(1.0, (tone[v] / 255.0) * g_fac)
            sw = (max(0.0, 1.0 - y / 0.56) ** 1.65) * sa
            hw = (max(0.0, (y - 0.42) / 0.58) ** 1.65) * ha
            y = y * (1.0 - sw) + (y * s_col) * sw
            y = y * (1.0 - hw) + (1.0 - (1.0 - y) * (1.0 - h_col)) * hw
            fin = (v / 255.0) * (1.0 - k) + y * k
            tbl[v] = max(0, min(255, int(round(fin * 255.0))))
        ch_luts.append(bytes(tbl))
    work = img.convertToFormat(QImage.Format.Format_RGB888)
    w, h = work.width(), work.height()
    bpl = work.bytesPerLine()
    src_ptr = work.constBits()
    src_ptr.setsize(work.sizeInBytes())
    src = memoryview(src_ptr).cast("B")
    buf = bytearray(work.sizeInBytes())
    lr, lg, lb = ch_luts
    for y in range(h):
        off = y * bpl
        row = src[off : off + w * 3]
        buf[off : off + w * 3 : 3] = bytes(row[0::3]).translate(lr)
        buf[off + 1 : off + w * 3 : 3] = bytes(row[1::3]).translate(lg)
        buf[off + 2 : off + w * 3 : 3] = bytes(row[2::3]).translate(lb)
    return QImage(bytes(buf), w, h, bpl, QImage.Format.Format_RGB888).copy()


