def depth_fx_active(fx: Optional[Dict[str, Any]]) -> bool:
    if not fx:
        return False
    return (
        int(fx.get("dof_strength", 0)) > 0
        or int(fx.get("haze_strength", 0)) > 0
        or int(fx.get("rim_strength", 0)) > 0
        or abs(int(fx.get("fg_pop", 0))) > 0
        or abs(int(fx.get("bg_dim", 0))) > 0
        or abs(int(fx.get("bg_cool", 0))) > 0
        or int(fx.get("bg_desat", 0)) > 0
        or int(fx.get("depth_ca", 0)) > 0
        or int(fx.get("depth_vignette", 0)) > 0
    )


def _hex_to_rgb(hex_col: str, fallback: Tuple[int, int, int] = (72, 120, 184)) -> Tuple[int, int, int]:
    c = QColor(str(hex_col or ""))
    if not c.isValid():
        return fallback
    return (c.red(), c.green(), c.blue())


def _build_turbo_lut() -> Tuple[bytes, bytes, bytes]:
    """Compact 256-entry cinema heatmap RGB LUT (0=deep indigo far -> cyan ->
    emerald -> gold -> 255=crimson-white near) for instant depth inspection."""
    stops = (
        (0.00, (14, 18, 56)),
        (0.22, (26, 98, 196)),
        (0.45, (32, 198, 210)),
        (0.68, (186, 224, 64)),
        (0.86, (252, 140, 36)),
        (1.00, (255, 58, 76)),
    )
    rr, gg, bb = bytearray(256), bytearray(256), bytearray(256)
    for i in range(256):
        t = i / 255.0
        for s0, s1 in zip(stops, stops[1:]):
            if s0[0] <= t <= s1[0]:
                u = (t - s0[0]) / max(1e-6, s1[0] - s0[0])
                rr[i] = int(round(s0[1][0] + (s1[1][0] - s0[1][0]) * u))
                gg[i] = int(round(s0[1][1] + (s1[1][1] - s0[1][1]) * u))
                bb[i] = int(round(s0[1][2] + (s1[1][2] - s0[1][2]) * u))
                break
    return bytes(rr), bytes(gg), bytes(bb)


_TURBO_LUT_RGB = _build_turbo_lut()


def _depth_norm_l_pil(
    depth_img: QImage, w: int, h: int, invert_polarity: bool = False, auto_norm: bool = True,
):
    """Return a PIL 'L' grayscale depth map resized to (w, h), normalized so
    255 = NEAR foreground and 0 = FAR background."""
    pil_d = _qimg_to_pil(depth_img).convert("L")
    if pil_d.size != (w, h):
        pil_d = pil_d.resize((w, h), _PIL_RESAMPLE_BI)
    if invert_polarity:
        pil_d = _PIL_OPS.invert(pil_d) if _PIL_OPS is not None else pil_d.point(lambda v: 255 - v)
    if auto_norm:
        lo, hi = pil_d.getextrema()
        if hi - lo >= 4 and (lo > 2 or hi < 253):
            span = float(hi - lo)
            lut = [max(0, min(255, int(round((v - lo) * 255.0 / span)))) for v in range(256)]
            pil_d = pil_d.point(lut)
    return pil_d


def _depth_norm_gray_qt(
    depth_img: QImage, w: int, h: int, invert_polarity: bool = False, auto_norm: bool = True,
) -> QImage:
    """Pure-Qt fast grayscale depth map (Format_Grayscale8, 255=NEAR, 0=FAR)."""
    g = depth_img.convertToFormat(QImage.Format.Format_Grayscale8)
    if g.width() != w or g.height() != h:
        g = g.scaled(w, h, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)
        g = g.convertToFormat(QImage.Format.Format_Grayscale8)
    bpl = g.bytesPerLine()
    ptr = g.constBits()
    ptr.setsize(g.sizeInBytes())
    raw = bytes(memoryview(ptr).cast("B"))
    lo, hi = 255, 0
    if auto_norm:
        # Subsample every 4th row for instantaneous extrema scan
        for y in range(0, h, max(1, h // 64)):
            row = raw[y * bpl : y * bpl + w]
            if row:
                rlo, rhi = min(row), max(row)
                if rlo < lo:
                    lo = rlo
                if rhi > hi:
                    hi = rhi
    need_stretch = auto_norm and (hi - lo >= 4) and (lo > 2 or hi < 253)
    if not invert_polarity and not need_stretch:
        return g
    lut = bytearray(256)
    span = float(max(1, hi - lo))
    for v in range(256):
        val = (255 - v) if invert_polarity else v
        if need_stretch:
            src_v = (255 - val) if invert_polarity else val
            norm = max(0.0, min(1.0, (src_v - lo) / span))
            val = int(round((1.0 - norm if invert_polarity else norm) * 255.0))
        lut[v] = max(0, min(255, val))
    tbl = bytes(lut)
    out = bytearray(len(raw))
    for y in range(h):
        off = y * bpl
        out[off : off + w] = raw[off : off + w].translate(tbl)
    return QImage(bytes(out), w, h, bpl, QImage.Format.Format_Grayscale8).copy()


def sample_depth_at(
    depth_img: Optional[QImage], nx: float, ny: float, invert_polarity: bool = False,
) -> Optional[float]:
    """Sample normalized depth (0.0=far .. 100.0=near) at normalized coords (nx, ny)
    using a 3x3 micro-kernel average so clicks on noisy pixels stay rock-steady."""
    if depth_img is None or depth_img.isNull():
        return None
    w, h = depth_img.width(), depth_img.height()
    cx = max(0, min(w - 1, int(round(nx * (w - 1)))))
    cy = max(0, min(h - 1, int(round(ny * (h - 1)))))
    acc = 0.0
    cnt = 0
    for dy in (-1, 0, 1):
        yy = max(0, min(h - 1, cy + dy))
        for dx in (-1, 0, 1):
            xx = max(0, min(w - 1, cx + dx))
            c = depth_img.pixelColor(xx, yy)
            luma = 0.299 * c.red() + 0.587 * c.green() + 0.114 * c.blue()
            acc += (255.0 - luma) if invert_polarity else luma
            cnt += 1
    return round((acc / max(1, cnt)) * 100.0 / 255.0, 1)


def build_depth_mask_lut(params: Dict[str, Any]) -> bytes:
    """Compute a 256-entry alpha LUT mapping normalized depth d (0=far..255=near)
    to mask opacity (0..255). Supports Far->Opaque, Near->Opaque, Focus Band,
    and Outside Band with adjustable threshold, falloff ramp, curve & max opacity."""
    mode = str(params.get("mode") or "far_opaque")
    thresh = max(0.0, min(1.0, float(params.get("threshold", 50)) / 100.0))
    falloff = max(0.0, min(1.0, float(params.get("falloff", 35)) / 100.0))
    curve = max(-100.0, min(100.0, float(params.get("curve", 0)))) / 100.0
    max_op = max(0.05, min(1.0, float(params.get("max_opacity", 100)) / 100.0))

    lut = bytearray(256)
    ramp = max(0.004, falloff)
    for i in range(256):
        d = i / 255.0  # 0.0 = farthest, 1.0 = nearest
        if mode == "far_opaque":
            # Mask starts at threshold and ramps toward 0 (far)
            if falloff <= 0.004:
                t = 1.0 if d <= thresh else 0.0
            else:
                # Smooth ramp from thresh + ramp*0.5 (0) down to thresh - ramp*0.5 (1)
                lo = thresh - ramp * 0.5
                hi = thresh + ramp * 0.5
                t = max(0.0, min(1.0, (hi - d) / max(1e-5, hi - lo)))
        elif mode == "near_opaque":
            # Mask starts at threshold and ramps toward 1 (near)
            if falloff <= 0.004:
                t = 1.0 if d >= thresh else 0.0
            else:
                lo = thresh - ramp * 0.5
                hi = thresh + ramp * 0.5
                t = max(0.0, min(1.0, (d - lo) / max(1e-5, hi - lo)))
        elif mode == "focus_band":
            dist = abs(d - thresh)
            half_w = max(0.02, ramp * 0.55)
            feather_w = max(0.015, half_w * 0.65)
            if dist <= half_w - feather_w:
                t = 1.0
            elif dist >= half_w + feather_w:
                t = 0.0
            else:
                t = 1.0 - (dist - (half_w - feather_w)) / max(1e-5, 2.0 * feather_w)
        else:  # outside_band
            dist = abs(d - thresh)
            half_w = max(0.02, ramp * 0.55)
            feather_w = max(0.015, half_w * 0.65)
            if dist <= half_w - feather_w:
                t = 0.0
            elif dist >= half_w + feather_w:
                t = 1.0
            else:
                t = (dist - (half_w - feather_w)) / max(1e-5, 2.0 * feather_w)

        # Curve shaping: smoothstep S-curve at 0, steeper (>0) or gentler (<0)
        t = t * t * (3.0 - 2.0 * t)
        if curve > 0.01:
            t = t ** (1.0 + 2.4 * curve)
        elif curve < -0.01:
            t = t ** (1.0 / (1.0 + 2.4 * (-curve)))
        lut[i] = max(0, min(255, int(round(t * max_op * 255.0))))
    return bytes(lut)


def build_depth_mask(
    depth_img: Optional[QImage],
    params: Dict[str, Any],
    target_size: Optional[Tuple[int, int]] = None,
) -> Optional[QImage]:
    """Generate a ready-to-use ARGB32 red editor mask from `depth_img` using the
    adjustable depth mask parameters (threshold, falloff, curve, feather, mode)."""
    if depth_img is None or depth_img.isNull():
        return None
    w, h = target_size if target_size else (depth_img.width(), depth_img.height())
    w, h = max(1, int(w)), max(1, int(h))
    inv = bool(params.get("invert_polarity", False))
    auto_norm = bool(params.get("auto_norm", True))
    feather = max(0.0, min(32.0, float(params.get("feather", 0))))
    lut = build_depth_mask_lut(params)

    if _HAS_PIL and _PILImage is not None:
        pil_d = _depth_norm_l_pil(depth_img, w, h, invert_polarity=inv, auto_norm=auto_norm)
        alpha_l = pil_d.point(list(lut))
        if feather >= 0.6 and _PIL_FILT is not None:
            alpha_l = alpha_l.filter(_PIL_FILT.GaussianBlur(radius=feather))
        red = _PILImage.new("L", (w, h), 255)
        zero = _PILImage.new("L", (w, h), 0)
        rgba = _PILImage.merge("RGBA", (red, zero, zero, alpha_l))
        raw = rgba.tobytes("raw", "BGRA")
        return QImage(raw, w, h, w * 4, QImage.Format.Format_ARGB32).copy()

    # Pure-Qt fallback (C-speed bytes.translate + fast smooth alpha feather)
    g = _depth_norm_gray_qt(depth_img, w, h, invert_polarity=inv, auto_norm=auto_norm)
    bpl = g.bytesPerLine()
    ptr = g.constBits()
    ptr.setsize(g.sizeInBytes())
    src = memoryview(ptr).cast("B")
    buf = bytearray(w * h * 4)
    # ARGB32 little-endian memory order: B=0, G=0, R=255, A=lut[d]
    buf[2::4] = b"\xff" * (w * h)
    for y in range(h):
        a_row = bytes(src[y * bpl : y * bpl + w]).translate(lut)
        buf[y * w * 4 + 3 : (y + 1) * w * 4 : 4] = a_row
    out = QImage(bytes(buf), w, h, w * 4, QImage.Format.Format_ARGB32).copy()
    if feather >= 0.8:
        out = blur_alpha_qimage(out, feather)
    return out


def build_depth_visualization(
    depth_img: Optional[QImage],
    vis_mode: str = "turbo",
    focus_pct: float = 65.0,
    band_pct: float = 24.0,
    invert_polarity: bool = False,
    auto_norm: bool = True,
    max_side: int = 960,
) -> Optional[QImage]:
    """Build a crisp preview visualization overlay (Grayscale, Cinema Heatmap,
    or Focus Plane Highlight) in <3ms via 256-entry LUT translation."""
    if depth_img is None or depth_img.isNull() or vis_mode == "off":
        return None
    w, h = depth_img.width(), depth_img.height()
    if max_side and (w > max_side or h > max_side):
        scale = max_side / float(max(w, h))
        w = max(1, int(round(w * scale)))
        h = max(1, int(round(h * scale)))
    g = _depth_norm_gray_qt(depth_img, w, h, invert_polarity=invert_polarity, auto_norm=auto_norm)
    bpl = g.bytesPerLine()
    ptr = g.constBits()
    ptr.setsize(g.sizeInBytes())
    src = memoryview(ptr).cast("B")

    if vis_mode == "gray":
        return g.convertToFormat(QImage.Format.Format_ARGB32)

    if vis_mode == "focus":
        # Highlight focal plane in luminous cyan/gold, far in cool slate, near in warm coral
        f0 = max(0.0, min(1.0, focus_pct / 100.0))
        hw = max(0.03, min(0.45, band_pct / 200.0))
        lr, lg, lb, la = bytearray(256), bytearray(256), bytearray(256), bytearray(256)
        for i in range(256):
            d = i / 255.0
            dist = abs(d - f0)
            if dist <= hw:
                # Inside sharp focus plane: bright emerald-cyan glow band
                u = 1.0 - dist / max(1e-5, hw)
                lr[i] = int(40 + 180 * u)
                lg[i] = int(215 + 40 * u)
                lb[i] = 255
                la[i] = int(125 + 95 * u)
            elif d < f0:
                # Farther than focus: deep cobalt blue tint
                u = min(1.0, (f0 - d) / max(0.05, f0))
                lr[i], lg[i], lb[i], la[i] = 24, 62, 175, int(65 + 115 * u)
            else:
                # Closer than focus: warm amber-coral tint
                u = min(1.0, (d - f0) / max(0.05, 1.0 - f0))
                lr[i], lg[i], lb[i], la[i] = 245, 130, 56, int(65 + 115 * u)
        br, bg, bb, ba = bytes(lr), bytes(lg), bytes(lb), bytes(la)
        buf = bytearray(w * h * 4)
        for y in range(h):
            row = bytes(src[y * bpl : y * bpl + w])
            off = y * w * 4
            buf[off : off + w * 4 : 4] = row.translate(bb)
            buf[off + 1 : off + w * 4 : 4] = row.translate(bg)
            buf[off + 2 : off + w * 4 : 4] = row.translate(br)
            buf[off + 3 : off + w * 4 : 4] = row.translate(ba)
        return QImage(bytes(buf), w, h, w * 4, QImage.Format.Format_ARGB32).copy()

    # Default: "turbo" high-craft cinema heatmap
    br, bg, bb = _TURBO_LUT_RGB
    buf = bytearray(w * h * 4)
    buf[3::4] = b"\xff" * (w * h)
    for y in range(h):
        row = bytes(src[y * bpl : y * bpl + w])
        off = y * w * 4
        buf[off : off + w * 4 : 4] = row.translate(bb)
        buf[off + 1 : off + w * 4 : 4] = row.translate(bg)
        buf[off + 2 : off + w * 4 : 4] = row.translate(br)
    return QImage(bytes(buf), w, h, w * 4, QImage.Format.Format_ARGB32).copy()


def _depth_vertical_grad_pil(w: int, h: int, bias: float):
    """Cached 1D->2D subtle sky/top atmospheric vertical weight mask (PIL 'L')."""
    strip = _PILImage.new("L", (1, max(1, h)))
    pix = []
    for y in range(h):
        t = 1.0 - (y / float(max(1, h - 1)))  # 1 at top, 0 at bottom
        val = (1.0 - bias) + bias * (0.45 + 0.55 * t)
        pix.append(max(0, min(255, int(round(val * 255.0)))))
    strip.putdata(pix)
    return strip.resize((w, h), _PIL_RESAMPLE_BI)


def _apply_depth_cinematic_pil(pil, depth_img: QImage, fx: Dict[str, Any]):
    """Full C-speed PIL cinematic depth post-processing suite."""
    w, h = pil.size
    inv = bool(fx.get("invert_polarity", False))
    auto_norm = bool(fx.get("auto_norm", True))
    d_l = _depth_norm_l_pil(depth_img, w, h, invert_polarity=inv, auto_norm=auto_norm)
    mwh = float(min(w, h))
    focus = max(0.0, min(1.0, float(fx.get("dof_focus", 68)) / 100.0))

    # 1. Foreground / Background Relighting & Separation (before bokeh so blur inherits light)
    fg_pop = int(fx.get("fg_pop", 0))
    bg_dim = int(fx.get("bg_dim", 0))
    bg_cool = int(fx.get("bg_cool", 0))
    bg_desat = int(fx.get("bg_desat", 0))
    if fg_pop != 0 or bg_dim != 0 or bg_cool != 0 or bg_desat > 0:
        # Smooth foreground/background separation around focus plane
        fg_lut = [
            max(0, min(255, int(round(
                ((max(0.0, min(1.0, ((i / 255.0) - (focus - 0.24)) / 0.44)) ** 1.2) * 255.0)
            ))))
            for i in range(256)
        ]
        bg_lut = [255 - v for v in fg_lut]
        if fg_pop != 0:
            fg_layer = pil
            if fg_pop > 0:
                fg_layer = _PIL_ENH.Contrast(fg_layer).enhance(1.0 + fg_pop / 240.0)
                if _PIL_FILT is not None:
                    fg_layer = fg_layer.filter(_PIL_FILT.UnsharpMask(
                        radius=max(1.5, mwh / 220.0), percent=int(fg_pop * 0.95), threshold=2
                    ))
                lift = 1.0 + fg_pop / 620.0
                fg_layer = fg_layer.point(_edit_lut(lambda v: v * lift) * 3)
            else:
                fg_layer = _PIL_ENH.Contrast(fg_layer).enhance(max(0.55, 1.0 + fg_pop / 180.0))
            pil = _PILImage.composite(fg_layer, pil, d_l.point(fg_lut))
        if bg_dim != 0 or bg_cool != 0 or bg_desat > 0:
            bg_layer = pil
            if bg_dim != 0:
                fac = 2.0 ** (bg_dim / 145.0)
                bg_layer = bg_layer.point(_edit_lut(lambda v: v * fac) * 3)
            if bg_cool != 0:
                t = bg_cool / 100.0
                r_c, g_c, b_c = bg_layer.split()
                r_c = r_c.point(_edit_lut(lambda v: v * (1.0 + 0.26 * t)))
                b_c = b_c.point(_edit_lut(lambda v: v * (1.0 - 0.28 * t)))
                bg_layer = _PILImage.merge("RGB", (r_c, g_c, b_c))
            if bg_desat > 0:
                bg_layer = _PIL_ENH.Color(bg_layer).enhance(max(0.05, 1.0 - bg_desat / 105.0))
            pil = _PILImage.composite(bg_layer, pil, d_l.point(bg_lut))

    # 2. Multi-Plane Optical Depth-of-Field (4-tier bokeh pyramid + highlight bloom)
    dof_str = int(fx.get("dof_strength", 0))
    coc_l = None
    if dof_str > 0 and _PIL_FILT is not None:
        ap = max(0.04, min(0.80, float(fx.get("dof_aperture", 24)) / 100.0)) * 0.5
        fg_mul = max(0.0, min(1.0, float(fx.get("dof_fg_blur", 45)) / 100.0))
        bloom_k = max(0.0, min(1.0, float(fx.get("dof_bokeh_bloom", 25)) / 100.0))
        coc_lut = [0] * 256
        for i in range(256):
            d = i / 255.0
            dist = abs(d - focus)
            if dist <= ap:
                c = 0.0
            else:
                raw_c = min(1.0, (dist - ap) / max(0.10, 0.72 - ap))
                if d > focus:
                    raw_c *= fg_mul
                c = raw_c * raw_c * (3.0 - 2.0 * raw_c)
            coc_lut[i] = max(0, min(255, int(round(c * 255.0))))
        coc_l = d_l.point(coc_lut)
        max_r = max(1.4, (dof_str / 100.0) * max(4.0, mwh / 42.0))
        b1 = pil.filter(_PIL_FILT.GaussianBlur(radius=max(0.8, max_r * 0.28)))
        b2 = pil.filter(_PIL_FILT.GaussianBlur(radius=max(1.4, max_r * 0.62)))
        b3_src = pil
        if bloom_k > 0.02:
            # Creamy cinema bokeh specular highlight boost inside deep out-of-focus layer
            spec = pil.point(_edit_lut(lambda v: max(0.0, (v - 178.0) * 255.0 / 77.0)) * 3)
            spec = spec.filter(_PIL_FILT.GaussianBlur(radius=max(2.0, max_r * 0.85)))
            b3_src = _PILImage.blend(pil, _PIL_CHOPS.screen(pil, spec), min(0.85, bloom_k * 0.80))
        b3 = b3_src.filter(_PIL_FILT.GaussianBlur(radius=max_r))
        # Piecewise smooth crossfade across 3 blur tiers (0..85, 85..170, 170..255)
        m1 = coc_l.point([min(255, int(v * 3.0)) for v in range(256)])
        m2 = coc_l.point([max(0, min(255, int((v - 85) * 3.0))) for v in range(256)])
        m3 = coc_l.point([max(0, min(255, int((v - 170) * 3.0))) for v in range(256)])
        out_dof = _PILImage.composite(b1, pil, m1)
        out_dof = _PILImage.composite(b2, out_dof, m2)
        pil = _PILImage.composite(b3, out_dof, m3)

    # 3. Depth-Modulated Optical Lens Chromatic Fringing (strictly in out-of-focus/far zones)
    ca_amt = int(fx.get("depth_ca", 0))
    if ca_amt > 0:
        px_shift = max(1, int(round((ca_amt / 100.0) * max(2.0, mwh / 210.0))))
        r_c, g_c, b_c = pil.split()
        r_s = _PIL_CHOPS.offset(r_c, px_shift, 0)
        b_s = _PIL_CHOPS.offset(b_c, -px_shift, 0)
        ca_img = _PILImage.merge("RGB", (r_s, g_c, b_s))
        if coc_l is not None:
            ca_mask = coc_l.point(lambda v: int(v * min(0.90, ca_amt / 110.0)))
        else:
            ca_lut = [int(((1.0 - i / 255.0) ** 1.5) * 255.0 * min(0.85, ca_amt / 115.0)) for i in range(256)]
            ca_mask = d_l.point(ca_lut)
        pil = _PILImage.composite(ca_img, pil, ca_mask)

    # 4. Atmospheric Depth Haze / Aerial Perspective (exponential mist curve)
    haze_str = int(fx.get("haze_strength", 0))
    if haze_str > 0:
        h_start = max(0.05, min(0.95, float(fx.get("haze_start", 45)) / 100.0))
        h_k = min(0.94, haze_str / 100.0 * 0.90)
        h_lut = [0] * 256
        for i in range(256):
            d = i / 255.0  # 0=far, 1=near
            if d >= h_start:
                m = 0.0
            else:
                far_t = (h_start - d) / max(0.05, h_start)
                m = (1.0 - math.exp(-2.6 * far_t)) / (1.0 - math.exp(-2.6))
            h_lut[i] = max(0, min(255, int(round(m * h_k * 255.0))))
        h_mask = d_l.point(h_lut)
        sky_bias = max(0.0, min(1.0, float(fx.get("haze_sky", 35)) / 100.0))
        if sky_bias > 0.05:
            vgrad = _depth_vertical_grad_pil(w, h, sky_bias)
            h_mask = _PIL_CHOPS.multiply(h_mask, vgrad)
        h_col = _hex_to_rgb(str(fx.get("haze_color") or "#3b6ea5"))
        fog_solid = _PILImage.new("RGB", (w, h), h_col)
        # Hybrid natural mist + subtle luminous aerial scatter
        fog_screen = _PILImage.blend(fog_solid, _PIL_CHOPS.screen(pil, fog_solid), 0.32)
        pil = _PILImage.composite(fog_screen, pil, h_mask)

    # 5. Directional Silhouette Depth Rim-Light / Backlight Separation
    rim_str = int(fx.get("rim_strength", 0))
    if rim_str > 0:
        rim_w = max(1, min(18, int(round(float(fx.get("rim_width", 5)) * max(0.65, mwh / 720.0)))))
        rim_cut = max(0, min(255, int(round(float(fx.get("rim_cutoff", 48)) * 2.55))))
        rdir = str(fx.get("rim_dir") or "top_left")
        shifts = {
            "top": [(0, rim_w)],
            "left": [(rim_w, 0)],
            "right": [(-rim_w, 0)],
            "top_left": [(rim_w, 0), (0, rim_w)],
            "top_right": [(-rim_w, 0), (0, rim_w)],
            "all": [(rim_w, 0), (-rim_w, 0), (0, rim_w), (0, -rim_w)],
        }.get(rdir, [(rim_w, 0), (0, rim_w)])
        edge = None
        for dx, dy in shifts:
            sh = _PIL_CHOPS.offset(d_l, dx, dy)
            diff = _PIL_CHOPS.subtract(d_l, sh)
            edge = diff if edge is None else _PIL_CHOPS.lighter(edge, diff)
        if edge is not None:
            # Gate rim to foreground depth >= rim_cut and amplify crisp silhouette discontinuity
            fg_gate = d_l.point([255 if v >= rim_cut else max(0, int((v - max(0, rim_cut - 26)) * 255 / 26.0)) for v in range(256)])
            edge = _PIL_CHOPS.multiply(edge, fg_gate)
            edge = edge.point([min(255, int(max(0, v - 10) * 4.4)) for v in range(256)])
            if _PIL_FILT is not None:
                edge = edge.filter(_PIL_FILT.GaussianBlur(radius=max(1.2, rim_w * 0.72)))
            r_col = _hex_to_rgb(str(fx.get("rim_color") or "#ffe3a8"), (255, 227, 168))
            gain = min(1.0, rim_str / 100.0 * 0.92)
            rr = edge.point(lambda v: min(255, int(v * gain * (r_col[0] / 255.0))))
            rg = edge.point(lambda v: min(255, int(v * gain * (r_col[1] / 255.0))))
            rb = edge.point(lambda v: min(255, int(v * gain * (r_col[2] / 255.0))))
            pil = _PIL_CHOPS.screen(pil, _PILImage.merge("RGB", (rr, rg, rb)))

    # 6. Foreground-Preserving Depth Studio Vignette
    dvig = int(fx.get("depth_vignette", 0))
    if dvig > 0:
        vmask = _cached_vignette_mask(w, h)
        # Preserve foreground subjects near edges (attenuate vignette up to 72% on near depth)
        bg_keep = d_l.point([int((1.0 - 0.72 * (i / 255.0)) * 255.0) for i in range(256)])
        d_vmask = _PIL_CHOPS.multiply(vmask, bg_keep)
        v_amt = min(0.90, dvig / 100.0 * 0.85)
        edge_dark = _PILImage.new("RGB", (w, h), (5, 7, 12))
        pil = _PILImage.composite(edge_dark, pil, d_vmask.point(lambda v: int(v * v_amt)))

    return pil


def _qt_fast_blur_rgb(img: QImage, radius: float) -> QImage:
    """Fast pure-Qt smooth blur via downscale-upscale pyramid (zero lag fallback)."""
    r = max(0.5, float(radius))
    w, h = img.width(), img.height()
    if w < 4 or h < 4:
        return img
    factor = max(1.15, min(14.0, 1.0 + r * 0.45))
    sw = max(2, int(round(w / factor)))
    sh = max(2, int(round(h / factor)))
    small = img.scaled(sw, sh, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)
    return small.scaled(w, h, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)


def _apply_depth_cinematic_qt(img: QImage, depth_img: QImage, fx: Dict[str, Any]) -> Tuple[QImage, List[str]]:
    """Pure-Qt fallback for cinematic depth post-processing (works without Pillow)."""
    w, h = img.width(), img.height()
    inv = bool(fx.get("invert_polarity", False))
    auto_norm = bool(fx.get("auto_norm", True))
    out = img.convertToFormat(QImage.Format.Format_RGB32)
    mwh = float(min(w, h))

    # 1. Bokeh DOF via fast downscale-upscale depth-masked blur
    dof_str = int(fx.get("dof_strength", 0))
    if dof_str > 0:
        max_r = max(1.5, (dof_str / 100.0) * max(4.0, mwh / 42.0))
        blurred = _qt_fast_blur_rgb(out, max_r)
        coc_mask = build_depth_mask(
            depth_img,
            {
                "mode": "outside_band",
                "threshold": int(fx.get("dof_focus", 68)),
                "falloff": max(8, int(fx.get("dof_aperture", 24))),
                "curve": 10,
                "max_opacity": 100,
                "feather": 3,
                "invert_polarity": inv,
                "auto_norm": auto_norm,
            },
            target_size=(w, h),
        )
        if coc_mask is not None:
            out = _composite_masked(out, blurred, coc_mask, False)

    # 2. Atmospheric Depth Haze
    haze_str = int(fx.get("haze_strength", 0))
    if haze_str > 0:
        h_mask = build_depth_mask(
            depth_img,
            {
                "mode": "far_opaque",
                "threshold": int(fx.get("haze_start", 45)),
                "falloff": 65,
                "curve": -15,
                "max_opacity": min(92, haze_str),
                "feather": 4,
                "invert_polarity": inv,
                "auto_norm": auto_norm,
            },
            target_size=(w, h),
        )
        if h_mask is not None:
            h_col = QColor(str(fx.get("haze_color") or "#3b6ea5"))
            fog = QImage(w, h, QImage.Format.Format_RGB32)
            fog.fill(h_col if h_col.isValid() else QColor("#3b6ea5"))
            out = _composite_masked(out, fog, h_mask, False)

    # 3. Background dim / cool / desat
    bg_dim = int(fx.get("bg_dim", 0))
    bg_cool = int(fx.get("bg_cool", 0))
    bg_desat = int(fx.get("bg_desat", 0))
    if bg_dim != 0 or bg_cool != 0 or bg_desat > 0:
        bg_mask = build_depth_mask(
            depth_img,
            {
                "mode": "far_opaque",
                "threshold": int(fx.get("dof_focus", 68)),
                "falloff": 45,
                "curve": 0,
                "max_opacity": 100,
                "feather": 4,
                "invert_polarity": inv,
                "auto_norm": auto_norm,
            },
            target_size=(w, h),
        )
        if bg_mask is not None:
            adj_bg = default_edit_adjustments()
            adj_bg["exposure"] = float(bg_dim) * 0.72
            adj_bg["temperature"] = float(bg_cool) * 0.85
            adj_bg["saturation"] = -float(bg_desat) * 0.90
            graded_bg, _ = _apply_edit_qt(out, adj_bg)
            out = _composite_masked(out, graded_bg.convertToFormat(QImage.Format.Format_RGB32), bg_mask, False)

    skipped: List[str] = []
    if int(fx.get("rim_strength", 0)) > 0:
        skipped.append("depth_rim")
    if int(fx.get("depth_ca", 0)) > 0:
        skipped.append("depth_ca")
    return out, skipped


def apply_depth_cinematic_pipeline(
    img: QImage, depth_img: Optional[QImage], fx: Optional[Dict[str, Any]],
) -> Tuple[QImage, List[str]]:
    """Run all active Depth Map cinematic post-processing effects on `img`."""
    if img.isNull() or depth_img is None or depth_img.isNull() or not depth_fx_active(fx):
        return img, []
    try:
        if _HAS_PIL and _PILImage is not None:
            pil = _qimg_to_pil(img).convert("RGB")
            pil = _apply_depth_cinematic_pil(pil, depth_img, fx or {})
            return _pil_to_qimg(pil).convertToFormat(QImage.Format.Format_RGB32), []
        return _apply_depth_cinematic_qt(img, depth_img, fx or {})
    except Exception as exc:  # noqa: BLE001
        STUDIO_LOG.warn("SYS", f"Depth cinematic pipeline fallback: {exc}")
        return img, ["depth_fx"]


# =============================================================================
#  7. Prompt Element Tokenizer (Ctrl+Drag Tag Blocks) & Span Highlighter
# =============================================================================
@dataclass
class PromptElement:
    """One discrete prompt element separated by comma or sentence-ending dot.
    May be a single word, weighted tag, multi-word phrase, or full sentence."""
    index: int
    start: int       # inclusive char index of trimmed content start
    end: int         # exclusive char index of trimmed content end
    text: str        # trimmed element text (without trailing separator)
    sep: str         # trailing delimiter ("," or "." or "")


def parse_prompt_elements(text: str) -> List[PromptElement]:
    """Split a prompt into atomic tag/sentence elements separated by commas (,)
    or sentence-ending periods (.) while keeping decimals (1.5, v1.1), ellipses
    (...), and parenthesized weight syntax ((word:1.8)) completely intact."""
    if not text:
        return []
    n = len(text)
    elements: List[PromptElement] = []
    seg_start = 0
    paren_depth = 0
    brace_depth = 0
    bracket_depth = 0

    def _emit(end_pos: int, sep_char: str) -> None:
        raw_seg = text[seg_start:end_pos]
        lead = len(raw_seg) - len(raw_seg.lstrip(" \t\r\n"))
        trail = len(raw_seg) - len(raw_seg.rstrip(" \t\r\n"))
        t_start = seg_start + lead
        t_end = end_pos - trail
        if t_end > t_start:
            elements.append(
                PromptElement(
                    index=len(elements),
                    start=t_start,
                    end=t_end,
                    text=text[t_start:t_end],
                    sep=sep_char,
                )
            )

    i = 0
    while i < n:
        ch = text[i]
        if ch == "(":
            paren_depth += 1
        elif ch == ")" and paren_depth > 0:
            paren_depth -= 1
        elif ch == "{":
            brace_depth += 1
        elif ch == "}" and brace_depth > 0:
            brace_depth -= 1
        elif ch == "[":
            bracket_depth += 1
        elif ch == "]" and bracket_depth > 0:
            bracket_depth -= 1
        elif paren_depth == 0 and brace_depth == 0 and bracket_depth == 0:
            if ch == ",":
                _emit(i, ",")
                seg_start = i + 1
            elif ch == ".":
                prev_c = text[i - 1] if i > 0 else ""
                next_c = text[i + 1] if i + 1 < n else ""
                # Ignore decimals (1.5, v1.1), ellipses (...), and domain names (foo.com)
                is_ellipsis = prev_c == "." or next_c == "."
                is_decimal_or_token = prev_c.isdigit() and next_c.isdigit()
                is_boundary = (not next_c) or next_c.isspace()
                if is_boundary and not is_ellipsis and not is_decimal_or_token:
                    _emit(i, ".")
                    seg_start = i + 1
        i += 1
    if seg_start < n:
        _emit(n, "")
    return elements


def reorder_prompt_elements(
    text: str,
    selected_indices: Sequence[int],
    target_slot: int,
) -> Tuple[str, List[int], List[Tuple[int, int]]]:
    """Atomically move one or more prompt elements (in their relative order) to
    `target_slot` (0..len(elements)) in the original sequence.

    Returns:
        (new_text, new_selected_indices, moved_char_ranges)
    Preserves comma / sentence-dot separators cleanly with zero double commas
    or orphaned punctuation."""
    elems = parse_prompt_elements(text)
    if not elems or not selected_indices:
        return text, [], []
    valid_set = {idx for idx in selected_indices if 0 <= idx < len(elems)}
    if not valid_set:
        return text, [], []

    selected_ordered = [elems[i] for i in sorted(valid_set)]
    remaining = [e for e in elems if e.index not in valid_set]

    # Count how many remaining elements sit strictly before target_slot
    clamped_slot = max(0, min(len(elems), int(target_slot)))
    insert_at = sum(1 for e in remaining if e.index < clamped_slot)

    reordered = remaining[:insert_at] + selected_ordered + remaining[insert_at:]
    new_sel_indices = list(range(insert_at, insert_at + len(selected_ordered)))

    # Reconstruct cleanly while honoring each element's original comma/dot delimiter
    pieces: List[str] = []
    char_ranges: List[Tuple[int, int]] = []
    cursor = 0
    for pos, el in enumerate(reordered):
        is_last = pos == len(reordered) - 1
        start_c = cursor
        pieces.append(el.text)
        cursor += len(el.text)
        end_c = cursor
        if pos in new_sel_indices:
            char_ranges.append((start_c, end_c))
        if not is_last:
            delim = el.sep if el.sep in (",", ".") else ","
            joiner = f"{delim} "
            pieces.append(joiner)
            cursor += len(joiner)
        else:
            if el.sep == ".":
                pieces.append(".")
                cursor += 1
    return "".join(pieces), new_sel_indices, char_ranges


class SpanBook:
    """Tracks colored text spans inside a prompt editor (inserted Tag Groups AND
    inserted LoRA Trigger Words). Each span retains its folder highlight color
    until any character inside that exact span is modified."""

    def __init__(self) -> None:
        self.spans: List[Dict[str, Any]] = []

    def clear(self) -> None:
        self.spans.clear()

    def add(self, start: int, text: str, color: str, kind: str = "tag") -> None:
        if not text:
            return
        self.spans.append({
            "start": int(start),
            "end": int(start) + len(text),
            "text": text,
            "color": color,
            "kind": kind,
        })

    def snapshot(self) -> List[Dict[str, Any]]:
        return copy.deepcopy(self.spans)

    def restore(self, snap: List[Dict[str, Any]]) -> None:
        self.spans = copy.deepcopy(snap)


def maintain_spans(book: SpanBook, new_text: str) -> None:
    """Keep every untouched span aligned with its exact substring even when text
    before/after it changes or tags are Ctrl-dragged. Drop any span whose inner
    text was altered."""
    if not book.spans:
        return
    kept: List[Dict[str, Any]] = []
    used_intervals: List[Tuple[int, int]] = []
    for sp in book.spans:
        needle = sp.get("text") or ""
        if not needle:
            continue
        old_start = int(sp.get("start", 0))
        # Fast path: exact match at previous offset
        if new_text[old_start : old_start + len(needle)] == needle:
            pos = old_start
        else:
            # Find nearest non-overlapping exact occurrence (survives edits elsewhere & Ctrl-drag!)
            best_pos = -1
            best_dist = 10**9
            search_from = 0
            while True:
                idx = new_text.find(needle, search_from)
                if idx < 0:
                    break
                end_idx = idx + len(needle)
                overlaps = any(not (end_idx <= u0 or idx >= u1) for u0, u1 in used_intervals)
                if not overlaps:
                    dist = abs(idx - old_start)
                    if dist < best_dist:
                        best_dist = dist
                        best_pos = idx
                search_from = idx + 1
            pos = best_pos
        if pos >= 0:
            end_pos = pos + len(needle)
            used_intervals.append((pos, end_pos))
            kept.append({
                "start": pos,
                "end": end_pos,
                "text": needle,
                "color": sp["color"],
                "kind": sp.get("kind", "tag"),
            })
    book.spans = kept


class SpanHighlighter(QSyntaxHighlighter):
    """Highlights untouched Tag Group & LoRA Trigger Word spans inside QPlainTextEdit.

    v3.1: additionally renders the trailing LoRA-trigger GHOST region (the
    un-editable auto-appended trigger words) as dimmed italic "ghost text"."""

    def __init__(self, book: SpanBook, document) -> None:
        super().__init__(document)
        self.book = book
        self._ghost_start: int = -1
        self._ghost_end: int = -1

    def set_ghost_range(self, start: int, end: int) -> None:
        if start == self._ghost_start and end == self._ghost_end:
            return
        self._ghost_start = int(start)
        self._ghost_end = int(end)

    def highlightBlock(self, text: str) -> None:  # noqa: N802
        block_start = self.currentBlock().position()
        block_end = block_start + len(text)
        if self.book.spans:
            for sp in self.book.spans:
                s0, s1 = int(sp["start"]), int(sp["end"])
                if s1 <= block_start or s0 >= block_end:
                    continue
                ov_start = max(s0, block_start) - block_start
                ov_end = min(s1, block_end) - block_start
                if ov_end <= ov_start:
                    continue
                fmt = QTextCharFormat()
                col = QColor(sp["color"])
                fmt.setForeground(col)
                bg = QColor(col)
                bg.setAlpha(34 if sp.get("kind") == "lora" else 24)
                fmt.setBackground(bg)
                if sp.get("kind") == "lora":
                    fmt.setFontUnderline(True)
                    fmt.setUnderlineColor(QColor(col.red(), col.green(), col.blue(), 150))
                self.setFormat(ov_start, ov_end - ov_start, fmt)
        # Ghost (locked LoRA trigger) zone: greyed-out italic, but readable
        if self._ghost_start >= 0 and self._ghost_end > self._ghost_start:
            g0 = max(self._ghost_start, block_start) - block_start
            g1 = min(self._ghost_end, block_end) - block_start
            if g1 > g0:
                fmt = QTextCharFormat()
                fmt.setForeground(QColor(C["ghost"]))
                fmt.setFontItalic(True)
                self.setFormat(g0, g1 - g0, fmt)


# =============================================================================
#  8. OpenAI-Compatible LLM API Client (With Structured In-Memory Diagnostics)
# =============================================================================
class LlmError(Exception):
    def __init__(self, message: str, status: Optional[int] = None, raw_snippet: str = ""):
        super().__init__(message)
        self.message = message
        self.status = status
        self.raw_snippet = raw_snippet


def _llm_headers(api_key: str) -> Dict[str, str]:
    h = {"Content-Type": "application/json", "Accept": "application/json", "User-Agent": CLIENT_AGENT}
    if api_key and api_key.strip():
        h["Authorization"] = f"Bearer {api_key.strip()}"
    return h


def _llm_request(
    method: str,
    url: str,
    api_key: str,
    body: Optional[Dict[str, Any]] = None,
    timeout: float = 120.0,
) -> Dict[str, Any]:
    t0 = time.monotonic()
    headers = _llm_headers(api_key)
    STUDIO_LOG.net("LLM", f"{method} {url}")
    status = 0
    raw_text = ""
    try:
        if _HAS_REQUESTS and requests is not None:
            r = requests.request(method, url, headers=headers, json=body, timeout=timeout)
            status = r.status_code
            raw_text = r.text
        else:
            payload = json.dumps(body).encode("utf-8") if body is not None else None
            req = urllib.request.Request(url, data=payload, headers=headers, method=method)
            try:
                with urllib.request.urlopen(req, timeout=timeout) as resp:
                    status = resp.status
                    raw_text = resp.read().decode("utf-8", "replace")
            except urllib.error.HTTPError as exc:
                status = exc.code
                raw_text = exc.read().decode("utf-8", "replace")
    except Exception as exc:  # noqa: BLE001
        dt = int((time.monotonic() - t0) * 1000)
        msg = f"Connection error after {dt}ms: {exc.__class__.__name__}: {exc}"
        STUDIO_LOG.error("LLM", msg)
        raise LlmError(msg) from exc

    dt = int((time.monotonic() - t0) * 1000)
    try:
        data = json.loads(raw_text) if raw_text.strip() else {}
    except ValueError:
        snippet = raw_text[:280].replace("\n", " ")
        msg = f"HTTP {status} ({dt}ms) returned non-JSON body: {snippet}"
        STUDIO_LOG.error("LLM", msg)
        raise LlmError(msg, status=status, raw_snippet=snippet)

    if status >= 400:
        err_obj = data.get("error") if isinstance(data, dict) else None
        if isinstance(err_obj, dict):
            detail = err_obj.get("message") or str(err_obj)
        elif isinstance(err_obj, str):
            detail = err_obj
        else:
            detail = str(data.get("message") if isinstance(data, dict) else raw_text[:240])
        msg = f"HTTP {status} ({dt}ms): {detail}"
        STUDIO_LOG.error("LLM", msg)
        raise LlmError(msg, status=status, raw_snippet=raw_text[:240])

    STUDIO_LOG.ok("LLM", f"{method} {urllib.parse.urlsplit(url).path} -> HTTP {status} ({dt}ms)")
    return data if isinstance(data, dict) else {"data": data}


def llm_list_models(base_url: str, api_key: str, timeout: float = 30.0) -> List[str]:
    base = base_url.strip().rstrip("/")
    if not base:
        raise LlmError("API Base URL is empty (e.g. https://api.openai.com/v1 or http://127.0.0.1:1234/v1)")
    doc = _llm_request("GET", f"{base}/models", api_key, timeout=timeout)
    items = doc.get("data") or doc.get("models") or []
    out: List[str] = []
    for it in items:
        if isinstance(it, dict) and it.get("id"):
            out.append(str(it["id"]))
        elif isinstance(it, str) and it.strip():
            out.append(it.strip())
    out.sort(key=str.lower)
    return out


def llm_chat(
    base_url: str,
    api_key: str,
    model: str,
    system: str,
    user: str,
    temperature: float = 0.75,
    top_p: float = 0.92,
    timeout: float = 180.0,
) -> str:
    base = base_url.strip().rstrip("/")
    if not base:
        raise LlmError("API Base URL is empty.")
    if not model.strip():
        raise LlmError("No LLM model selected.")
    messages: List[Dict[str, str]] = []
    if system.strip():
        messages.append({"role": "system", "content": system.strip()})
    messages.append({"role": "user", "content": user.strip()})
    body = {
        "model": model.strip(),
        "messages": messages,
        "temperature": float(temperature),
        "top_p": float(top_p),
    }
    doc = _llm_request("POST", f"{base}/chat/completions", api_key, body=body, timeout=timeout)
    choices = doc.get("choices") or []
    if not choices or not isinstance(choices[0], dict):
        msg = f"Unexpected LLM response structure (no choices): {str(doc)[:220]}"
        STUDIO_LOG.error("LLM", msg)
        raise LlmError(msg)
    msg_obj = choices[0].get("message") or {}
    content = str(msg_obj.get("content") or choices[0].get("text") or "").strip()
    if not content:
        STUDIO_LOG.warn("LLM", "Endpoint returned empty assistant content.")
    return content


def llm_vision_chat(
    base_url: str,
    api_key: str,
    model: str,
    system: str,
    instruction: str,
    image_data_urls: Any,
    temperature: float = 0.4,
    top_p: float = 0.9,
    timeout: float = 240.0,
) -> str:
    """OpenAI-compatible multimodal chat completion with one or MANY image
    attachments (v4: pass a single data-URL string or a sequence of them).

    Sends the classic vision message shape:
      content = [ {"type":"text","text":...},
                  {"type":"image_url","image_url":{"url":"data:image/jpeg;base64,..."}},
                  ... one part per attached image ... ]
    Works with OpenAI, Gemini-compat gates, OpenRouter, LM Studio, Ollama
    (LLaVA/Qwen-VL), KoboldCpp and AI Horde chat-completions workers alike.
    """
    base = base_url.strip().rstrip("/")
    if not base:
        raise LlmError("API Base URL is empty.")
    if not model.strip():
        raise LlmError("No VLM model selected.")
    if isinstance(image_data_urls, str):
        image_data_urls = [image_data_urls]
    urls = [u for u in (image_data_urls or []) if isinstance(u, str) and u.strip()]
    if not urls:
        raise LlmError("No image attached for the vision request.")
    messages: List[Dict[str, Any]] = []
    if system.strip():
        messages.append({"role": "system", "content": system.strip()})
    content: List[Dict[str, Any]] = [
        {"type": "text", "text": instruction.strip() or "Caption this image as a text-to-image prompt."}
    ]
    for url in urls:
        content.append({"type": "image_url", "image_url": {"url": url}})
    messages.append({"role": "user", "content": content})
    body = {
        "model": model.strip(),
        "messages": messages,
        "temperature": float(temperature),
        "top_p": float(top_p),
    }
    doc = _llm_request("POST", f"{base}/chat/completions", api_key, body=body, timeout=timeout)
    choices = doc.get("choices") or []
    if not choices or not isinstance(choices[0], dict):
        msg = f"Unexpected VLM response structure (no choices): {str(doc)[:220]}"
        STUDIO_LOG.error("LLM", msg)
        raise LlmError(msg)
    msg_obj = choices[0].get("message") or {}
    content = msg_obj.get("content")
    if isinstance(content, list):  # some gateways echo multimodal content back
        content = "".join(
            str(p.get("text") or "") for p in content if isinstance(p, dict)
        )
    content = str(content or "").strip()
    if not content:
        STUDIO_LOG.warn("LLM", "VLM endpoint returned empty assistant content.")
    return content


def image_to_vlm_data_url(path: str, max_side: int = 1152) -> str:
    """Load an image, downscale it to a VLM-friendly size and return a JPEG
    data-URL (base64). Raises LlmError when the file cannot be decoded."""
    img = QImage(path)
    if img.isNull():
        raise LlmError(f"Cannot decode image: {os.path.basename(path)}")
    if img.width() * img.height() > IMAGE_SANITY_MAX_MP:
        raise LlmError("Image is too large to send to a VLM.")
    if img.width() > max_side or img.height() > max_side:
        img = img.scaled(
            max_side, max_side,
            Qt.AspectRatioMode.KeepAspectRatio,
            Qt.TransformationMode.SmoothTransformation,
        )
    if img.hasAlphaChannel():
        # flatten onto black so transparent PNGs survive the JPEG trip
        flat = QImage(img.size(), QImage.Format.Format_RGB32)
        flat.fill(Qt.GlobalColor.black)
        painter = QPainter(flat)
        painter.drawImage(0, 0, img)
        painter.end()
        img = flat
    else:
        img = img.convertToFormat(QImage.Format.Format_RGB32)
    buf = QBuffer()
    buf.open(QBuffer.OpenModeFlag.WriteOnly)
    if not img.save(buf, "JPEG", 90):
        buf.close()
        raise LlmError("JPEG re-encode of the image failed.")
    b64 = base64.b64encode(bytes(buf.data())).decode("ascii")
    buf.close()
    STUDIO_LOG.net("LLM", f"VLM attachment: {img.width()}x{img.height()} jpeg, {len(b64) // 1024} KiB b64")
    return f"data:image/jpeg;base64,{b64}"


def llm_single_line_prompt(reply: str) -> str:
    """Collapse a VLM reply into exactly one clean single-line prompt: strips
    code fences, quotes, XML tags, numbering and line breaks (batch-queue safe)."""
    t = _strip_code_fences(reply or "")
    t = re.sub(r"<prompt\b[^>]*>", "", t, flags=re.I)
    t = t.replace("</prompt>", "")
    t = re.sub(r"^\s*(?:prompt|caption|output)\s*[:\-]\s*", "", t, flags=re.I)
    t = t.replace("```", "")
    t = t.replace("\u201c", "").replace("\u201d", "")
    t = t.strip().strip('"').strip("'").strip()
    return " ".join(t.split())


def _strip_code_fences(t: str) -> str:
    t = t.strip()
    if t.startswith("```"):
        t = re.sub(r"^```[A-Za-z0-9_-]*\s*", "", t)
        t = re.sub(r"\s*```$", "", t)
    return t.strip()


def llm_reply_has_blocks(text: str) -> bool:
    return bool(re.search(r"<prompt\b[^>]*>.*?</prompt>", text or "", flags=re.I | re.S))


def llm_extract_prompts(text: str) -> List[str]:
    cleaned = _strip_code_fences(text or "")
    blocks = re.findall(r"<prompt\b[^>]*>(.*?)</prompt>", cleaned, flags=re.I | re.S)
    if blocks:
        return [" ".join(b.split()).strip() for b in blocks if b.strip()]
    # Fallback: line/paragraph splitting when a model ignored XML tags
    out: List[str] = []
    for ln in cleaned.splitlines():
        s = re.sub(r"^\s*(?:\d+[\.\)]\s*|[-*]\s*)", "", ln).strip()
        if len(s) >= 8:
            out.append(s)
    return out

# =============================================================================
#  9. Browser Bridge (Local VPN Tunnel for Tampermonkey Userscript)
# =============================================================================
class BridgeError(Exception):
    def __init__(self, message: str, network: bool = False):
        super().__init__(message)
        self.message = message
        self.network = network


class _BridgeRequest:
    __slots__ = (
        "id", "method", "url", "headers", "body", "deadline",
        "done", "status", "resp_headers", "data", "error", "created",
    )

    def __init__(
        self,
        method: str,
        url: str,
        headers: Dict[str, str],
        body: Optional[bytes],
        timeout: float,
    ) -> None:
        self.id = secrets.token_hex(8)
        self.method = method.upper()
        self.url = url
        self.headers = dict(headers or {})
        self.body = body
        self.deadline = time.time() + min(300.0, timeout + 25.0)
        self.done = threading.Event()
        self.status = 0
        self.resp_headers: Dict[str, str] = {}
        self.data = b""
        self.error = ""
        self.created = time.time()

    def payload(self) -> Dict[str, Any]:
        return {
            "id": self.id,
            "method": self.method,
            "url": self.url,
            "headers": self.headers,
            "body_b64": base64.b64encode(self.body).decode("ascii") if self.body else "",
            "timeout_ms": int(max(1000.0, self.deadline - time.time()) * 1000),
        }


class _BridgeHandler(BaseHTTPRequestHandler):
    server_version = "HSLBridge/4.0"  # tokenless long-poll protocol (v10.2)
    protocol_version = "HTTP/1.1"

    @property
    def bridge(self) -> "BrowserBridge":
        return self.server.bridge  # type: ignore[attr-defined]

    def log_message(self, fmt: str, *args: Any) -> None:
        pass

    def _cors(self) -> None:
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.send_header("Access-Control-Allow-Private-Network", "true")

    def _send_json(self, code: int, obj: Dict[str, Any], close: bool = False) -> None:
        data = json.dumps(obj).encode("utf-8")
        try:
            self.send_response(code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            if close:
                self.send_header("Connection", "close")
                self.close_connection = True
            self._cors()
            self.end_headers()
            self.wfile.write(data)
        except (BrokenPipeError, ConnectionResetError):
            self.close_connection = True

    def _read_body(self, cap: int) -> Optional[bytes]:
        try:
            n = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            n = 0
        if n <= 0:
            return b""
        if n > cap:
            return None
        return self.rfile.read(n)

    def do_OPTIONS(self) -> None:  # noqa: N802
        self.send_response(204)
        self.send_header("Content-Length", "0")
        self._cors()
        self.end_headers()

    def do_GET(self) -> None:  # noqa: N802
        # v10.1: the bridge is TOKENLESS — the connection itself is the only
        # credential. The listener is bound to 127.0.0.1 exclusively, so any
        # local browser tab that reaches it is trusted outright.
        path = urllib.parse.urlsplit(self.path).path
        if path == "/" or path == "/status":
            # v10.2: the relay answers with plain JSON status only — there is
            # no local bridge page anymore; the userscript lives on
            # stablehorde.net / aihorde.net pages, not on any local page.
            b = self.bridge
            self._send_json(200, {
                "app": f"{APP_NAME} {APP_VERSION}",
                "endpoint": HORDE_URL,
                "tokenless": True,
                "connected": b.is_connected(),
                "served": b.served,
                "client": b.client_label(),
            })
            return
        if path == "/poll":
            self._do_poll()
            return
        self._send_json(404, {"error": "unknown endpoint"})

    def _do_poll(self) -> None:
        b = self.bridge
        q = urllib.parse.parse_qs(urllib.parse.urlsplit(self.path).query)
        try:
            wait = min(30.0, max(1.0, float(q.get("timeout", ["25"])[0])))
        except (ValueError, IndexError):
            wait = BRIDGE_POLL_SECS
        b._poll_started(self.headers.get("User-Agent", ""))
        job: Optional[_BridgeRequest] = None
        try:
            deadline = time.time() + wait
            with b._cond:
                while True:
                    if b._queue:
                        job = b._queue.popleft()
                        break
                    rem = deadline - time.time()
                    if rem <= 0:
                        break
                    b._cond.wait(rem)
            self._send_json(200, {"job": job.payload() if job is not None else None})
        except (BrokenPipeError, ConnectionResetError):
            if job is not None:
                with b._cond:
                    b._queue.appendleft(job)
        finally:
            b._poll_ended()

    def do_POST(self) -> None:  # noqa: N802
        path = urllib.parse.urlsplit(self.path).path
        body = self._read_body(BRIDGE_BODY_CAP)
        if body is None:
            self._send_json(413, {"error": "reply too large"}, close=True)
            return
        if path != "/reply":
            self._send_json(404, {"error": "unknown endpoint"})
            return
        try:
            doc = json.loads(body.decode("utf-8") or "{}")
        except ValueError:
            self._send_json(400, {"error": "bad json"})
            return
        self._send_json(200 if self.bridge._deliver(doc) else 404, {"ok": True})


class BrowserBridge:
    """Local 127.0.0.1 relay that lets a browser tab (Tampermonkey userscript)
    execute every Horde API request inside the browser's network stack, so a
    VPN / proxy browser extension applies to all traffic.

    v10.2: fully TOKENLESS — connection itself is the credential. The server
    binds 127.0.0.1 only; any local tab reaching it is trusted, which removes
    the old token-mismatch deadlock where the app refused to even register a
    polling tab ("waiting for browser tab" forever). The app always ADDRESSES
    https://stablehorde.net/api/v2 — this relay only transports those requests
    through the browser while the VPN tunnel is enabled. The companion
    userscript ships as a separate file (horde_studio_bridge.user.js) and runs
    on stablehorde.net / aihorde.net pages, never on a local page."""

    def __init__(self, port: int) -> None:
        self.port = int(port)
        self._cond = threading.Condition()
        self._queue: "collections.deque[_BridgeRequest]" = collections.deque()
        self._waiters: Dict[str, _BridgeRequest] = {}
        self._active_polls = 0
        self._last_poll = 0.0
        self._last_serve = 0.0
        self._client = ""
        self._served = 0
        self._httpd: Optional[ThreadingHTTPServer] = None
        self._thread: Optional[threading.Thread] = None
        self.running = False
        self.last_error = ""

    def start(self) -> bool:
        if self.running:
            return True
        try:
            httpd = ThreadingHTTPServer(("127.0.0.1", self.port), _BridgeHandler)
        except OSError as exc:
            self.last_error = str(exc)
            STUDIO_LOG.error("BRIDGE", f"Failed to bind 127.0.0.1:{self.port}: {exc}")
            self.running = False
            return False
        httpd.daemon_threads = True
        httpd.bridge = self  # type: ignore[attr-defined]
        self._httpd = httpd
        self.running = True
        self.last_error = ""
        self._thread = threading.Thread(target=httpd.serve_forever, name="bridge-http", daemon=True)
        self._thread.start()
        STUDIO_LOG.ok("BRIDGE", f"Browser VPN bridge listening on 127.0.0.1:{self.port}")
        return True

    def stop(self) -> None:
        self.running = False
        httpd, self._httpd = self._httpd, None
        if httpd is not None:
            try:
                httpd.shutdown()
                httpd.server_close()
            except Exception:  # noqa: BLE001
                pass
        self._thread = None
        with self._cond:
            for job in list(self._waiters.values()):
                job.error = "bridge stopped"
                job.done.set()
            self._waiters.clear()
            self._queue.clear()
            self._cond.notify_all()
        STUDIO_LOG.info("BRIDGE", "Browser VPN bridge stopped")

    def _poll_started(self, label: str) -> None:
        with self._cond:
            self._active_polls += 1
            self._last_poll = time.time()
            if label:
                self._client = label

    def _poll_ended(self) -> None:
        with self._cond:
            self._active_polls = max(0, self._active_polls - 1)

    def _deliver(self, doc: Dict[str, Any]) -> bool:
        rid = str(doc.get("id") or "")
        with self._cond:
            job = self._waiters.pop(rid, None)
            if job is None:
                return False
            err = doc.get("error")
            if err:
                job.error = str(err)
            else:
                try:
                    job.status = int(doc.get("status") or 200)
                except (ValueError, TypeError):
                    job.status = 200
                job.resp_headers = dict(doc.get("headers") or {})
                b64 = doc.get("data_b64") or ""
                try:
                    job.data = base64.b64decode(b64) if b64 else b""
                except ValueError as exc:
                    job.error = f"corrupt base64 reply: {exc}"
                self._served += 1
                self._last_serve = time.time()
            job.done.set()
            return True

    def is_connected(self) -> bool:
        with self._cond:
            now = time.time()
            return (
                self._active_polls > 0
                or (now - self._last_poll) <= BRIDGE_CLIENT_TIMEOUT
                or (now - self._last_serve) <= BRIDGE_SERVE_GRACE
            )

    @property
    def served(self) -> int:
        with self._cond:
            return self._served

    def client_label(self) -> str:
        with self._cond:
            raw = self._client
        for tag in ("Firefox", "Edg/", "Chrome", "Safari", "Brave", "Opera"):
            if tag in raw:
                return "Edge" if tag == "Edg/" else tag
        return raw[:28] if raw else "browser"

    def request(
        self,
        method: str,
        url: str,
        headers: Dict[str, str],
        body: Optional[bytes],
        timeout: float,
    ) -> Tuple[int, Dict[str, str], bytes]:
        if not self.running:
            raise BridgeError("bridge is not running", network=False)
        if not self.is_connected():
            raise BridgeError(
                "browser bridge has no connected tab — install the companion "
                "horde_studio_bridge.user.js in Tampermonkey, then open "
                "https://stablehorde.net/ and keep that tab open (no token needed)",
                network=False,
            )
        job = _BridgeRequest(method, url, headers, body, timeout)
        with self._cond:
            self._waiters[job.id] = job
            self._queue.append(job)
            self._cond.notify()
        if not job.done.wait(max(5.0, timeout + 15.0)):
            with self._cond:
                self._waiters.pop(job.id, None)
                try:
                    self._queue.remove(job)
                except ValueError:
                    pass
            raise BridgeError(f"browser bridge timed out after {int(timeout)}s", network=True)
        if job.error:
            raise BridgeError(f"browser bridge: {job.error}", network=True)
        return job.status, job.resp_headers, job.data


# =============================================================================
#  10. Local SillyTavern Server (A1111-Compatible /sdapi/v1)
# =============================================================================
class LocalStServer:
    def __init__(
        self,
        port: int,
        state_fn: Callable[[], Dict[str, Any]],
        submit_fn: Callable[[str], Dict[str, Any]],
    ) -> None:
        self.port = int(port)
        self.state_fn = state_fn
        self.submit_fn = submit_fn
        self.running = False
        self.last_error = ""
        self.last_request = ""
        self._httpd: Optional[ThreadingHTTPServer] = None
        self._thread: Optional[threading.Thread] = None
        self._lock = threading.Lock()

    def _note(self, text: str, level: str = "INFO") -> None:
        with self._lock:
            self.last_request = text
        STUDIO_LOG.log("ST", level, text)

    def start(self) -> bool:
        if self.running:
            return True
        try:
            httpd = ThreadingHTTPServer(("127.0.0.1", self.port), _StHandler)
        except OSError as exc:
            self.last_error = str(exc)
            STUDIO_LOG.error("ST", f"Failed to bind SillyTavern port {self.port}: {exc}")
            self.running = False
            return False
        httpd.daemon_threads = True
        httpd.st = self  # type: ignore[attr-defined]
        self._httpd = httpd
        self.running = True
        self.last_error = ""
        self._thread = threading.Thread(target=httpd.serve_forever, name="st-server", daemon=True)
        self._thread.start()
        STUDIO_LOG.ok("ST", f"SillyTavern A1111 server listening on {self.address}")
        return True

    def stop(self) -> None:
        self.running = False
        httpd, self._httpd = self._httpd, None
        if httpd is not None:
            try:
                httpd.shutdown()
                httpd.server_close()
            except Exception:  # noqa: BLE001
                pass
        self._thread = None
        STUDIO_LOG.info("ST", "SillyTavern local server stopped")

    @property
    def address(self) -> str:
        return f"http://127.0.0.1:{self.port}"


class _StHandler(BaseHTTPRequestHandler):
    server_version = "HSLSt/3.0"
    protocol_version = "HTTP/1.1"

    @property
    def st(self) -> LocalStServer:
        return self.server.st  # type: ignore[attr-defined]

    def log_message(self, fmt: str, *args: Any) -> None:
        pass

    def _cors(self) -> None:
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")

    def _send_json(self, code: int, obj: Any, close: bool = False) -> None:
        data = json.dumps(obj).encode("utf-8")
        try:
            self.send_response(code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            if close:
                self.send_header("Connection", "close")
                self.close_connection = True
            self._cors()
            self.end_headers()
            self.wfile.write(data)
        except (BrokenPipeError, ConnectionResetError):
            self.close_connection = True

    def _read_json(self) -> Optional[Dict[str, Any]]:
        try:
            n = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            n = 0
        if n <= 0:
            return {}
        if n > ST_BODY_CAP:
            return None
        try:
            return json.loads(self.rfile.read(n).decode("utf-8") or "{}")
        except ValueError:
            return {}

    def do_OPTIONS(self) -> None:  # noqa: N802
        self.send_response(204)
        self.send_header("Content-Length", "0")
        self._cors()
        self.end_headers()

    def do_GET(self) -> None:  # noqa: N802
        path = urllib.parse.urlsplit(self.path).path
        try:
            state = self.st.state_fn() or {}
        except Exception:  # noqa: BLE001
            state = {}
        if path in ("/", ""):
            self._send_json(200, {"app": f"{APP_NAME} {APP_VERSION}", "status": "ok"})
        elif path == "/sdapi/v1/options":
            self._send_json(200, {
                "sd_model_checkpoint": state.get("model_label", ""),
                "sd_vae": "Automatic",
                "CLIP_stop_at_last_layers": 1,
                "forge_additional_modules": [],
                "forge_preset": "none",
            })
        elif path == "/sdapi/v1/sd-models":
            models = [
                {
                    "name": name,
                    "title": label,
                    "model_name": name,
                    "hash": "00000000",
                    "sha256": "0" * 64,
                    "filename": f"{name}.safetensors",
                    "config": None,
                }
                for name, label in state.get("models", [])
            ]
            self._send_json(200, models)
        elif path == "/sdapi/v1/samplers":
            self._send_json(200, [{"name": s, "aliases": [], "options": {}} for s in state.get("samplers", [])])
        elif path == "/sdapi/v1/schedulers":
            self._send_json(200, [{"name": s, "label": s.title()} for s in SCHEDULERS])
        elif path == "/sdapi/v1/upscalers":
            self._send_json(200, [{"name": lbl} for lbl, _n, _f in UPSCALERS] + [{"name": "Lanczos"}])
        elif path == "/sdapi/v1/latent-upscale-modes":
            self._send_json(200, [{"name": "Latent"}])
        elif path == "/sdapi/v1/progress":
            self._send_json(200, {
                "progress": 0,
                "eta_relative": 0.0,
                "state": {"skipped": False, "interrupted": False, "batch_index": 0},
                "current_image": None,
                "textinfo": None,
            })
        elif path.startswith("/sdapi/"):
            self._send_json(200, [])
        else:
            self._send_json(404, {"error": "unknown endpoint"})

    def do_POST(self) -> None:  # noqa: N802
        path = urllib.parse.urlsplit(self.path).path
        doc = self._read_json()
        if doc is None:
            self._send_json(413, {"error": "payload too large"}, close=True)
            return
        if path == "/sdapi/v1/png-info":
            self._send_json(200, {"info": "", "items": {}})
            return
        if path not in ("/sdapi/v1/txt2img", "/sdapi/v1/img2img"):
            self._send_json(404, {"error": "unknown endpoint"})
            return
        prompt = " ".join(str(doc.get("prompt") or "").split())
        if not prompt:
            self._send_json(400, {"error": "empty prompt"})
            return
        st = self.st
        st._note(f"Incoming request: {elide(prompt, 72)}")
        try:
            res = st.submit_fn(prompt)
        except Exception as exc:  # noqa: BLE001
            st._note(f"Submission error: {exc}", "ERROR")
            self._send_json(500, {"error": f"{exc.__class__.__name__}: {exc}"})
            return
        if not isinstance(res, dict) or not res.get("ok"):
            err = (res or {}).get("error") if isinstance(res, dict) else "generation failed"
            st._note(f"Generation failed: {err}", "ERROR")
            self._send_json(502, {"error": str(err or "generation failed")})
            return
        path_img = str(res.get("path") or "")
        try:
            with open(path_img, "rb") as fh:
                data = fh.read()
        except OSError as exc:
            st._note(f"Image read failed: {exc}", "ERROR")
            self._send_json(502, {"error": f"cannot read generated file: {exc}"})
            return
        meta = res.get("meta") or {}
        b64 = base64.b64encode(data).decode("ascii")
        info = json.dumps({
            "prompt": prompt,
            "seed": meta.get("seed"),
            "width": meta.get("width"),
            "height": meta.get("height"),
            "steps": meta.get("steps"),
            "sampler_name": meta.get("sampler"),
            "cfg_scale": meta.get("cfg"),
            "model": meta.get("model"),
        })
        params = {
            "prompt": prompt,
            "steps": meta.get("steps"),
            "width": meta.get("width"),
            "height": meta.get("height"),
            "cfg_scale": meta.get("cfg"),
            "sampler_name": meta.get("sampler"),
        }
        st._note(f"Delivered {os.path.basename(path_img)}", "OK")
        self._send_json(200, {"images": [b64], "parameters": params, "info": info})

# =============================================================================
#  11. Resilient AI Horde REST Client (requests / urllib / BrowserBridge)
# =============================================================================
class HordeError(Exception):
    def __init__(
        self,
        message: str,
        rc: Optional[str] = None,
        status: Optional[int] = None,
        retry_after: Optional[float] = None,
    ) -> None:
        super().__init__(message)
        self.message = message
        self.rc = rc
        self.status = status
        self.retry_after = retry_after


class HordeAPI:
    def __init__(self, base_url: str = HORDE_URL, api_key: str = ANON_KEY, client_agent: str = CLIENT_AGENT) -> None:
        self.base_url = base_url.rstrip("/")
        self.api_key = api_key or ANON_KEY
        self.client_agent = client_agent
        self.bridge: Optional[BrowserBridge] = None
        self._session = self._make_session()

    @property
    def transport(self) -> str:
        if self._bridge_active():
            return "browser-bridge"
        return "requests" if self._session is not None else "urllib"

    def _bridge_active(self) -> bool:
        return self.bridge is not None and self.bridge.running

    def _make_session(self):
        if not _HAS_REQUESTS or requests is None:
            return None
        session = requests.Session()
        try:
            from requests.adapters import HTTPAdapter
            try:
                from urllib3.util.retry import Retry
            except ImportError:
                from requests.packages.urllib3.util.retry import Retry  # type: ignore
            kwargs: Dict[str, Any] = dict(
                total=4,
                connect=4,
                read=2,
                backoff_factor=1.0,
                status_forcelist=(500, 502, 503, 504),
            )
            try:
                retry = Retry(allowed_methods=None, **kwargs)
            except TypeError:
                retry = Retry(method_whitelist=None, **kwargs)
            adapter = HTTPAdapter(max_retries=retry, pool_connections=8, pool_maxsize=16)
            session.mount("https://", adapter)
            session.mount("http://", adapter)
        except Exception:  # noqa: BLE001
            pass
        return session

    def _reset_session(self) -> None:
        if self._session is not None:
            try:
                self._session.close()
            except Exception:  # noqa: BLE001
                pass
            self._session = self._make_session()

    def _headers(self, auth: bool) -> Dict[str, str]:
        h = {"Client-Agent": self.client_agent, "Accept": "application/json"}
        if auth:
            h["apikey"] = self.api_key or ANON_KEY
        return h

    def call(
        self,
        method: str,
        path: str,
        body: Optional[Dict[str, Any]] = None,
        params: Optional[Dict[str, Any]] = None,
        timeout: float = 30,
        auth: bool = True,
        net_attempts: int = 3,
    ) -> Any:
        url = path if path.startswith("http") else self.base_url + path
        if params:
            url += ("&" if "?" in url else "?") + urllib.parse.urlencode(params)
        short_path = urllib.parse.urlsplit(url).path
        last: Optional[HordeError] = None
        for attempt in range(1, max(1, net_attempts) + 1):
            t0 = time.monotonic()
            try:
                return self._call_once(method, url, body, timeout, auth)
            except HordeError as exc:
                dt = int((time.monotonic() - t0) * 1000)
                if exc.rc != "Network" or attempt >= net_attempts:
                    STUDIO_LOG.error(
                        "HORDE",
                        f"{method} {short_path} failed ({dt}ms, HTTP {exc.status or '-'}, rc={exc.rc or '-'}): "
                        f"{exc.message[:220]}",
                    )
                    raise
                last = exc
                self._reset_session()
                STUDIO_LOG.net(
                    "HORDE",
                    f"Retry {attempt}/{net_attempts} on {method} {short_path} ({dt}ms): {exc.message[:140]}",
                )
                time.sleep(min(8.0, 1.5 * attempt))
        raise last or HordeError("Network error", rc="Network")

    def _call_once(
        self,
        method: str,
        url: str,
        body: Optional[Dict[str, Any]],
        timeout: float,
        auth: bool,
    ) -> Any:
        if self._bridge_active():
            return self._bridge_call(method, url, body, timeout, auth)
        headers = self._headers(auth)
        if body is not None:
            headers["Content-Type"] = "application/json"
        if self._session is not None and requests is not None:
            try:
                r = self._session.request(method, url, json=body, headers=headers, timeout=timeout)
            except requests.RequestException as exc:  # type: ignore[attr-defined]
                raise HordeError(f"Network error: {exc.__class__.__name__}: {exc}", rc="Network") from exc
            status = r.status_code
            try:
                data = r.json()
            except ValueError:
                data = {"message": r.text[:300]}
            retry_after = r.headers.get("Retry-After")
        else:
            payload = json.dumps(body).encode("utf-8") if body is not None else None
            req = urllib.request.Request(url, data=payload, headers=headers, method=method)
            try:
                with urllib.request.urlopen(req, timeout=timeout) as resp:
                    status = resp.status
                    raw = resp.read()
                    retry_after = resp.headers.get("Retry-After")
            except urllib.error.HTTPError as exc:
                status = exc.code
                raw = exc.read()
                retry_after = exc.headers.get("Retry-After")
            except (urllib.error.URLError, OSError, ValueError) as exc:
                raise HordeError(f"Network error: {exc}", rc="Network") from exc
            try:
                data = json.loads(raw.decode("utf-8")) if raw else {}
            except ValueError:
                data = {"message": raw[:300].decode("utf-8", "replace")}
        return self._finish_response(status, data, retry_after)

    def _bridge_call(
        self,
        method: str,
        url: str,
        body: Optional[Dict[str, Any]],
        timeout: float,
        auth: bool,
    ) -> Any:
        assert self.bridge is not None
        headers = self._headers(auth)
        payload: Optional[bytes] = None
        if body is not None:
            payload = json.dumps(body).encode("utf-8")
            headers["Content-Type"] = "application/json"
        try:
            status, _hdrs, raw = self.bridge.request(method, url, headers, payload, timeout)
        except BridgeError as exc:
            raise HordeError(exc.message, rc="Network" if exc.network else None) from exc
        try:
            data = json.loads(raw.decode("utf-8")) if raw else {}
        except ValueError:
            data = {"message": raw[:300].decode("utf-8", "replace")}
        return self._finish_response(status, data, None)

    @staticmethod
    def _finish_response(status: int, data: Any, retry_after: Optional[str]) -> Any:
        if status < 400:
            return data
        msg = data.get("message") if isinstance(data, dict) else str(data)
        errs = data.get("errors") if isinstance(data, dict) else None
        if isinstance(errs, dict) and errs:
            msg = f"{msg} ({'; '.join(f'{k}: {v}' for k, v in errs.items())})"
        rc = data.get("rc") if isinstance(data, dict) else None
        try:
            ra = float(retry_after) if retry_after else None
        except ValueError:
            ra = None
        raise HordeError(msg or f"HTTP {status}", rc=rc, status=status, retry_after=ra)

    # Generation endpoints
    def submit(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        params = payload.get("params")
        if isinstance(params, dict) and "seed" in params and not isinstance(params["seed"], str):
            payload = dict(payload, params=dict(params, seed=str(params["seed"])))
        return self.call("POST", "/generate/async", body=payload, timeout=60)

    def check(self, rid: str) -> Dict[str, Any]:
        return self.call("GET", f"/generate/check/{rid}", timeout=20, auth=False)

    def status(self, rid: str) -> Dict[str, Any]:
        return self.call("GET", f"/generate/status/{rid}", timeout=60, auth=False)

    def cancel(self, rid: str) -> Dict[str, Any]:
        return self.call("DELETE", f"/generate/status/{rid}", timeout=30, auth=False)

    # Alchemy interrogation endpoints
    def interrogate_submit(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        return self.call("POST", "/interrogate/async", body=payload, timeout=45)

    def interrogate_status(self, rid: str) -> Dict[str, Any]:
        return self.call("GET", f"/interrogate/status/{rid}", timeout=30, auth=False)

    def interrogate_cancel(self, rid: str) -> Dict[str, Any]:
        return self.call("DELETE", f"/interrogate/status/{rid}", timeout=30, auth=False)

    # Cluster info endpoints
    def models(self) -> List[Dict[str, Any]]:
        return self.call("GET", "/status/models", params={"type": "image"}, timeout=30, auth=False)

    def heartbeat(self) -> Dict[str, Any]:
        return self.call("GET", "/status/heartbeat", timeout=15, auth=False)

    def find_user(self) -> Dict[str, Any]:
        return self.call("GET", "/find_user", timeout=20)

    def sampler_constraints(self) -> Dict[str, Any]:
        return self.call("GET", "/status/sampler_constraints", timeout=30, auth=False)

    # HTTP codes that are TRANSIENT for R2/CDN image hand-offs: the worker
    # reports "done" while the upload to the R2 bucket is still propagating,
    # so 404/408/429/5xx must be retried with backoff instead of failing.
    _DL_RETRY_STATUS = frozenset({404, 408, 425, 429, 500, 502, 503, 504})

    def download(self, url: str, timeout: float = 90) -> bytes:
        """Fetch one image with production-grade persistence.

        v11: retries BOTH network errors and transient HTTP failures (the R2
        link can 404/503 for a while after the job reports done). Up to 8
        attempts with growing backoff (~2 minutes total) — the download is
        only abandoned when the retries run out or the server says the link
        is permanently gone."""
        delays = (1.5, 3.0, 5.0, 8.0, 12.0, 18.0, 26.0, 38.0)
        last: Optional[HordeError] = None
        for attempt in range(1, len(delays) + 1):
            try:
                return self._download_once(url, timeout)
            except HordeError as exc:
                retryable = exc.rc == "Network" or (exc.status or 0) in self._DL_RETRY_STATUS
                if not retryable or attempt >= len(delays):
                    STUDIO_LOG.error("HORDE", f"Image download failed: {exc.message[:180]}")
                    raise
                last = exc
                self._reset_session()
                STUDIO_LOG.net(
                    "HORDE",
                    f"Download retry {attempt}/{len(delays)} (HTTP {exc.status or '-'}) "
                    f"in {delays[attempt - 1]:.0f}s: {exc.message[:120]}",
                )
                time.sleep(delays[attempt - 1])
        raise last or HordeError("Download failed")

    def _download_once(self, url: str, timeout: float) -> bytes:
        if self._bridge_active():
            assert self.bridge is not None
            try:
                status, _hdrs, raw = self.bridge.request(
                    "GET", url, {"User-Agent": self.client_agent, "Accept": "*/*"}, None, timeout
                )
            except BridgeError as exc:
                raise HordeError(f"Download failed: {exc.message}", rc="Network" if exc.network else None) from exc
            if status >= 400:
                raise HordeError(f"Download failed: HTTP {status}", status=status)
            return raw
        if self._session is not None and requests is not None:
            try:
                r = self._session.get(url, timeout=timeout)
            except requests.RequestException as exc:  # type: ignore[attr-defined]
                raise HordeError(f"Download failed: {exc}", rc="Network") from exc
            if r.status_code >= 400:
                raise HordeError(f"Download failed: HTTP {r.status_code}", status=r.status_code)
            return r.content
        req = urllib.request.Request(url, headers={"User-Agent": self.client_agent})
        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                return resp.read()
        except (urllib.error.URLError, OSError) as exc:
            raise HordeError(f"Download failed: {exc}", rc="Network") from exc

    def civitai_lookup(self, ident: str, is_version: bool) -> Dict[str, Any]:
        url = (CIVITAI_VERSION_URL if is_version else CIVITAI_MODEL_URL).format(id=ident)
        data = self.call("GET", url, timeout=25, auth=False)
        out: Dict[str, Any] = {"name": "", "trained_words": [], "base": "", "type": ""}
        if is_version:
            out["name"] = f"{data.get('model', {}).get('name', '')} / {data.get('name', '')}".strip(" /")
            out["trained_words"] = data.get("trainedWords") or []
            out["base"] = data.get("baseModel", "")
            out["type"] = data.get("model", {}).get("type", "")
        else:
            out["name"] = data.get("name", "")
            out["type"] = data.get("type", "")
            vers = data.get("modelVersions") or []
            if vers:
                out["trained_words"] = vers[0].get("trainedWords") or []
                out["base"] = vers[0].get("baseModel", "")
        return out


# =============================================================================
#  12. Image Storage (outputs/, outputs/temp/ ring of 10, data/tiles/)
# =============================================================================
class ImageStore:
    def __init__(self, temp_dir: str, output_dir: str, capacity: int = TEMP_CAPACITY) -> None:
        self.temp_dir = temp_dir
        self.output_dir = output_dir
        self.capacity = capacity
        self._lock = threading.Lock()
        for d in (temp_dir, output_dir):
            try:
                os.makedirs(d, exist_ok=True)
            except OSError:
                pass
        self.orphans_cleaned = self.cleanup_orphan_metadata()

    def cleanup_orphan_metadata(self) -> int:
        removed = 0
        for d in (self.temp_dir, self.output_dir):
            try:
                names = os.listdir(d)
            except OSError:
                continue
            stems = {
                os.path.splitext(n)[0].lower()
                for n in names
                if n.lower().endswith((".png", ".webp", ".jpg", ".jpeg"))
            }
            for n in names:
                if n.lower().endswith(".json") and os.path.splitext(n)[0].lower() not in stems:
                    try:
                        os.remove(os.path.join(d, n))
                        removed += 1
                    except OSError:
                        pass
        return removed

    def _slot(self, i: int) -> str:
        return os.path.join(self.temp_dir, f"hsl_{i:02d}")

    def reserve(self) -> str:
        with self._lock:
            oldest, oldest_t = None, None
            for i in range(self.capacity):
                base = self._slot(i)
                existing = [base + ext for ext in (".png", ".webp") if os.path.exists(base + ext)]
                if not existing:
                    return base
                t = max(os.path.getmtime(p) for p in existing)
                if oldest_t is None or t < oldest_t:
                    oldest, oldest_t = base, t
            base = oldest or self._slot(0)
            # v4: depth-map attachments follow their source slot out of the ring
            for cand in (
                base + ".png", base + ".webp", base + ".json",
                base + DEPTH_POSTFIX + ".png", base + DEPTH_POSTFIX + ".json",
            ):
                try:
                    os.remove(cand)
                except OSError:
                    pass
            return base

    def save_temp(self, data: bytes, meta: Dict[str, Any]) -> str:
        base = self.reserve()
        return write_image_with_metadata(data, base + ".png", meta)

    def save_direct(self, data: bytes, meta: Dict[str, Any]) -> str:
        ensure_dirs()
        dest = self.output_name(meta, ".png")
        return write_image_with_metadata(data, dest, meta)

    def save_tile(self, data: bytes, meta: Dict[str, Any]) -> str:
        ensure_dirs()
        dest = meta.get("tile_target") or os.path.join(
            TILES_DIR, f"tile_{int(time.time() * 1000) % 100000}.png"
        )
        return write_image_with_metadata(data, dest, meta)

    @staticmethod
    def clean_group_tiles(gid: int) -> int:
        prefix = f"g{int(gid)}_"
        removed = 0
        try:
            for n in os.listdir(TILES_DIR):
                if n.startswith(prefix):
                    try:
                        os.remove(os.path.join(TILES_DIR, n))
                        removed += 1
                    except OSError:
                        pass
        except OSError:
            pass
        return removed

    def list_recent(self, include_output: bool = False) -> List[str]:
        dirs = [self.temp_dir] + ([self.output_dir] if include_output else [])
        files: List[str] = []
        for d in dirs:
            try:
                files += [
                    os.path.join(d, f)
                    for f in os.listdir(d)
                    if os.path.isfile(os.path.join(d, f))
                    and f.lower().endswith((".png", ".webp"))
                    and not is_depth_image_path(f)
                ]
            except OSError:
                continue
        files.sort(key=lambda p: os.path.getmtime(p), reverse=True)
        return files[: self.capacity]

    def output_name(self, meta: Dict[str, Any], ext: str) -> str:
        model = model_short(str(meta.get("model", ""))) or ("UPS" if meta.get("tile_upscale") else "IMG")
        seed = re.sub(r"[^A-Za-z0-9_-]", "", str(meta.get("seed", "")))[:16] or "noseed"
        stamp = time.strftime("%Y%m%d_%H%M%S", time.localtime(meta.get("saved_at") or time.time()))
        name = f"{stamp}_{model}_{seed}{ext}"
        dest = os.path.join(self.output_dir, name)
        idx = 2
        while os.path.exists(dest):
            dest = os.path.join(self.output_dir, f"{stamp}_{model}_{seed}_{idx}{ext}")
            idx += 1
        return dest

    def save_to_output(self, src: str, dest: Optional[str] = None) -> str:
        ensure_dirs()
        meta = read_image_metadata(src)
        ext = os.path.splitext(src)[1].lower() or ".png"
        target = dest or self.output_name(meta, ext)
        shutil.copy2(src, target)
        src_sidecar = os.path.splitext(src)[0] + ".json"
        if os.path.isfile(src_sidecar):
            shutil.copy2(src_sidecar, os.path.splitext(target)[0] + ".json")
        elif meta:
            write_text(os.path.splitext(target)[0] + ".json", json.dumps(meta, indent=2, ensure_ascii=False))
        # v4: a saved image carries its depth-map attachment along
        src_depth = depth_path_for(src)
        if os.path.isfile(src_depth):
            try:
                shutil.copy2(src_depth, depth_path_for(target))
                src_depth_json = os.path.splitext(src_depth)[0] + ".json"
                if os.path.isfile(src_depth_json):
                    shutil.copy2(src_depth_json, os.path.splitext(depth_path_for(target))[0] + ".json")
            except OSError:
                pass
        return target

    def delete_file(self, path: str) -> bool:
        ok = False
        depth = depth_path_for(path)
        for cand in (path, os.path.splitext(path)[0] + ".json", depth, os.path.splitext(depth)[0] + ".json"):
            if os.path.isfile(cand):
                try:
                    os.remove(cand)
                    ok = True
                except OSError:
                    pass
        return ok

# =============================================================================
#  13. Jobs, Background Workers, Alchemy & Tile Upscale Geometry
# =============================================================================
@dataclass
class Job:
    local_id: int
    payload: Dict[str, Any]
    meta: Dict[str, Any]
    kind: str = KIND_GEN
    group_id: Optional[int] = None
    state: str = STATE_QUEUED
    horde_id: str = ""
    wait_time: Optional[float] = None
    wait_initial: Optional[float] = None
    queue_position: Optional[int] = None
    finished: int = 0
    processing: int = 0
    waiting: int = 0
    restarted: int = 0
    is_possible: bool = True
    kudos: float = 0.0
    message: str = ""
    results: List[str] = field(default_factory=list)
    created_at: float = field(default_factory=time.time)
    started_at: Optional[float] = None
    ended_at: Optional[float] = None
    retry_after: float = 0.0
    # Group summary fields (KIND_GROUP)
    group_title: str = ""
    group_detail: str = ""
    group_progress: float = 0.0

    @property
    def active(self) -> bool:
        return self.state in ACTIVE_STATES

    @property
    def terminal(self) -> bool:
        return self.state in (STATE_DONE, STATE_FAILED, STATE_CANCELLED)

    def n_total(self) -> int:
        return int((self.payload.get("params") or {}).get("n", 1))

    def progress_fraction(self) -> float:
        if self.kind == KIND_GROUP:
            return max(0.0, min(1.0, self.group_progress))
        if self.state == STATE_DONE:
            return 1.0
        if self.state in (STATE_QUEUED, STATE_SUBMITTING):
            return 0.05 if self.state == STATE_SUBMITTING else 0.0
        if self.state == STATE_FETCHING:
            return 0.94
        n = max(1, self.n_total())
        if self.finished > 0:
            return min(0.92, 0.15 + 0.77 * (self.finished / n))
        if self.wait_initial and self.wait_time is not None and self.wait_initial > 0:
            return max(0.08, min(0.88, 1.0 - (self.wait_time / max(1.0, self.wait_initial))))
        return 0.35 if self.state == STATE_PROCESSING else 0.12

    def title_line(self) -> str:
        if self.kind == KIND_GROUP:
            return self.group_title or f"Tile Upscale #{self.group_id}"
        if self.kind == KIND_ALCH:
            form = str(self.meta.get("alchemy_form") or "upscale")
            return f"Base Upscale ({UPSCALER_BY_NAME.get(form, form)})"
        if self.kind == KIND_TILE_I2I:
            r, c = self.meta.get("tile_row", "?"), self.meta.get("tile_col", "?")
            return f"Tile r{r}c{c} \u2022 {model_short(str(self.meta.get('model', '')))}"
        if self.kind == KIND_DEPTH:
            return f"Depth Map \u2022 {elide(os.path.basename(str(self.meta.get('depth_source') or '?')), 54)}"
        return elide(str(self.meta.get("prompt") or "(empty)"), 68)

    def status_line(self) -> str:
        if self.kind == KIND_GROUP:
            return self.group_detail or self.state.upper()
        if self.state == STATE_QUEUED:
            if self.retry_after > 0:
                return f"Rate-limited, retrying in {max(0, int(self.retry_after - time.time()))}s"
            return "Queued locally"
        if self.state == STATE_SUBMITTING:
            return "Submitting to AI Horde\u2026"
        if self.state == STATE_WAITING:
            pos = f"pos #{self.queue_position}" if self.queue_position is not None else "in queue"
            eta = f"ETA {fmt_secs(self.wait_time)}" if self.wait_time is not None else ""
            return " \u2022 ".join(x for x in (pos, eta) if x)
        if self.state == STATE_PROCESSING:
            eta = f"ETA {fmt_secs(self.wait_time)}" if self.wait_time is not None else "working"
            return f"Rendering {self.finished}/{self.n_total()} \u2022 {eta}"
        if self.state == STATE_FETCHING:
            return "Downloading image(s)\u2026"
        if self.state == STATE_DONE:
            return f"Done ({len(self.results)} img, {self.kudos:.0f}k)" if self.kudos else f"Done ({len(self.results)} img)"
        if self.state == STATE_CANCELLED:
            return "Cancelled"
        return self.message or "Failed"


def _interruptible_sleep(secs: float, flag: Callable[[], bool], step: float = 0.2) -> bool:
    end = time.time() + max(0.0, secs)
    while time.time() < end:
        if flag():
            return False
        time.sleep(min(step, max(0.02, end - time.time())))
    return not flag()


class JobWorker(QThread):
    progress = pyqtSignal(int, dict)
    completed = pyqtSignal(int, list, str)
    failed = pyqtSignal(int, str, float)

    def __init__(
        self,
        api: HordeAPI,
        store: ImageStore,
        job: Job,
        poll_interval: float,
        save_direct: bool,
        parent: Optional[QObject] = None,
    ) -> None:
        super().__init__(parent)
        self.api = api
        self.store = store
        self.job = job
        self.poll_interval = max(1.5, float(poll_interval))
        self.save_direct = bool(save_direct)
        self._cancel = threading.Event()

    def request_cancel(self) -> None:
        self._cancel.set()

    def _sleep(self, secs: float) -> bool:
        return _interruptible_sleep(secs, self._cancel.is_set)

    def run(self) -> None:
        job = self.job
        jid = job.local_id
        self.progress.emit(jid, {"state": STATE_SUBMITTING, "started_at": time.time()})
        try:
            payload = self._materialize_payload(job.payload)
            sub = self.api.submit(payload)
        except HordeError as exc:
            ra = exc.retry_after or (15.0 if exc.status == 429 else 0.0)
            self.failed.emit(jid, exc.message, ra)
            return
        except Exception as exc:  # noqa: BLE001
            self.failed.emit(jid, f"{exc.__class__.__name__}: {exc}", 0.0)
            return

        rid = str(sub.get("id") or "")
        if not rid:
            self.failed.emit(jid, "AI Horde returned no request id", 0.0)
            return
        kudos = float(sub.get("kudos") or 0.0)
        STUDIO_LOG.info("HORDE", f"Job #{jid} submitted -> {rid[:10]} ({kudos:.0f} kudos)")
        self.progress.emit(jid, {"horde_id": rid, "kudos": kudos, "state": STATE_WAITING})

        net_errors = 0
        while True:
            if self._cancel.is_set():
                self._do_cancel(rid)
                return
            try:
                chk = self.api.check(rid)
                net_errors = 0
            except HordeError as exc:
                if exc.status == 404:
                    self.failed.emit(jid, "Request expired or not found on AI Horde", 0.0)
                    return
                if exc.status == 429:
                    # v11: horde rate-limiting the /check poll is routine —
                    # cool down politely and do NOT burn a failure slot.
                    cool = max(5.0, float(exc.retry_after or 0.0))
                    STUDIO_LOG.net("HORDE", f"#{jid} check rate-limited, cooling {cool:.0f}s")
                    if not self._sleep(cool):
                        self._do_cancel(rid)
                        return
                    continue
                net_errors += 1
                STUDIO_LOG.warn("HORDE", f"#{jid} check retry ({net_errors}/16): {exc.message}")
                if net_errors >= 16:
                    self.failed.emit(jid, f"Lost connection: {exc.message}", 0.0)
                    return
                if not self._sleep(min(12.0, 2.0 * net_errors)):
                    self._do_cancel(rid)
                    return
                continue
            if chk.get("faulted"):
                self.failed.emit(jid, "AI Horde faulted this request", 0.0)
                return
            fields: Dict[str, Any] = {
                "wait_time": chk.get("wait_time"),
                "queue_position": chk.get("queue_position"),
                "finished": chk.get("finished", 0),
                "processing": chk.get("processing", 0),
                "waiting": chk.get("waiting", 0),
                "restarted": chk.get("restarted", 0),
                "is_possible": chk.get("is_possible", True),
                "kudos": chk.get("kudos", job.kudos),
            }
            if job.wait_initial is None and chk.get("wait_time"):
                fields["wait_initial"] = chk.get("wait_time")
            if chk.get("done"):
                fields["state"] = STATE_FETCHING
                self.progress.emit(jid, fields)
                break
            fields["state"] = STATE_PROCESSING if (chk.get("processing") or chk.get("finished")) else STATE_WAITING
            self.progress.emit(jid, fields)
            if not self._sleep(self.poll_interval):
                self._do_cancel(rid)
                return

        # v11: "done" only means the workers finished — the R2 uploads can
        # lag behind, and the status payload may still carry an empty
        # generations array. Keep polling the status endpoint (with backoff,
        # for up to ~4 minutes) until the images actually exist. The task is
        # still alive on the horde during all of this, so we never give up
        # early. 404 is the only hard exit (the request expired server-side).
        status_delays = (2.0, 3.0, 4.0, 6.0, 8.0, 12.0, 16.0, 22.0, 30.0, 30.0, 30.0, 30.0)
        final: Optional[Dict[str, Any]] = None
        for attempt, delay in enumerate(status_delays, start=1):
            if self._cancel.is_set():
                self._do_cancel(rid)
                return
            try:
                final = self.api.status(rid)
                if final.get("generations"):
                    break
                # alive but empty — R2 upload still in flight
                STUDIO_LOG.net(
                    "HORDE",
                    f"#{jid} result not uploaded yet, waiting {delay:.0f}s ({attempt}/{len(status_delays)})",
                )
            except HordeError as exc:
                if exc.status == 404:
                    self.failed.emit(jid, "Result expired before download", 0.0)
                    return
                if exc.status == 429:
                    STUDIO_LOG.net("HORDE", f"#{jid} status rate-limited, cooling {delay:.0f}s")
                else:
                    STUDIO_LOG.warn("HORDE", f"#{jid} status retry ({attempt}/{len(status_delays)}): {exc.message}")
                final = None
            if not self._sleep(delay):
                self._do_cancel(rid)
                return
        if final is None or not final.get("generations"):
            self.failed.emit(jid, "Could not fetch final status (images never became available)", 0.0)
            return

        paths, censored, black = self._store_generations(final)
        if not paths:
            if job.kind == KIND_TILE_I2I and (censored or black):
                self.failed.emit(jid, TILE_CENSORED_MSG, 0.0)
                return
            self.failed.emit(jid, "AI Horde returned no usable images (censored or faulted)", 0.0)
            return
        STUDIO_LOG.ok("HORDE", f"Job #{jid} complete ({len(paths)} image(s))")
        self.completed.emit(jid, paths, STATE_DONE)

    def _do_cancel(self, rid: str) -> None:
        jid = self.job.local_id
        paths: List[str] = []
        try:
            res = self.api.cancel(rid)
            paths, _c, _b = self._store_generations(res)
            STUDIO_LOG.info("HORDE", f"Job #{jid} cancelled on AI Horde")
        except HordeError as exc:
            # The request may have FINISHED in the race between our cancel and
            # the horde — never throw away finished work: fetch it once.
            if exc.status in (400, 404) or "already" in str(exc.message).lower():
                try:
                    res = self.api.status(rid)
                    paths, _c, _b = self._store_generations(res)
                    STUDIO_LOG.info("HORDE", f"Job #{jid} finished before cancel — results kept")
                except HordeError as exc2:
                    STUDIO_LOG.warn("HORDE", f"Job #{jid} cancel error: {exc2.message}")
            else:
                STUDIO_LOG.warn("HORDE", f"Job #{jid} cancel error: {exc.message}")
        self.completed.emit(jid, paths, STATE_CANCELLED)

    def _materialize_payload(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(payload)
        src_path = out.pop("source_image_path", None)
        rect = out.pop("source_rect", None)
        mask_path = out.pop("source_mask_path", None)
        if src_path:
            try:
                with open(src_path, "rb") as fh:
                    data = fh.read()
            except OSError as exc:
                raise HordeError(f"img2img source missing: {src_path} ({exc})") from exc
            if rect is not None:
                img = QImage.fromData(QByteArray(data))
                if img.isNull():
                    raise HordeError(f"img2img source undecodable: {src_path}")
                rx, ry, rw, rh = (int(v) for v in rect)
                rx, ry = max(0, rx), max(0, ry)
                rw = max(8, min(rw, img.width() - rx))
                rh = max(8, min(rh, img.height() - ry))
                img = img.copy(rx, ry, rw, rh)
                data = image_to_png_bytes(img)
            out["source_image"] = base64.b64encode(data).decode("ascii")
            if mask_path:
                try:
                    with open(mask_path, "rb") as fh:
                        out["source_mask"] = base64.b64encode(fh.read()).decode("ascii")
                except OSError as exc:
                    raise HordeError(f"inpainting mask missing: {mask_path} ({exc})") from exc
                out.setdefault("source_processing", "inpainting")
            else:
                out.setdefault("source_processing", "img2img")
        return out

    def _store_generations(self, result: Dict[str, Any]) -> Tuple[List[str], int, int]:
        job = self.job
        is_tile = bool(job.meta.get("tile_job"))
        paths: List[str] = []
        censored = 0
        black = 0
        gens = list(result.get("generations") or [])
        # v11: a download that fails despite api.download()'s internal retries
        # is retried in ADDITIONAL passes (the R2 link can be slow to appear).
        # Nothing is dropped while the horde still knows the generation.
        pending = list(enumerate(gens))
        for pass_no in range(3):
            deferred: List[Tuple[int, Dict[str, Any]]] = []
            for idx, gen in pending:
                img_ref = gen.get("img") or ""
                if not img_ref:
                    continue
                data: Optional[bytes] = None
                try:
                    data = (
                        self.api.download(img_ref)
                        if img_ref.startswith("http")
                        else base64.b64decode(img_ref)
                    )
                except (HordeError, ValueError) as exc:
                    if pass_no < 2:
                        deferred.append((idx, gen))
                        STUDIO_LOG.net(
                            "HORDE",
                            f"#{job.local_id} image {idx + 1} deferred to retry pass "
                            f"{pass_no + 2}/3: {exc}",
                        )
                    else:
                        STUDIO_LOG.error(
                            "HORDE", f"#{job.local_id} image {idx + 1} download failed: {exc}"
                        )
                    continue
                notes: List[str] = []
                was_censored = bool(gen.get("censored"))
                for md in gen.get("gen_metadata") or []:
                    if md.get("type") == "censorship":
                        notes.append("censored: " + str(md.get("value")))
                        was_censored = True
                    elif md.get("type") == "lora":
                        notes.append(f"lora {md.get('ref', '')}: {md.get('value')}")
                if is_tile and was_censored:
                    censored += 1
                    STUDIO_LOG.warn(
                        "Upscale",
                        f"Tile r{job.meta.get('tile_row')}c{job.meta.get('tile_col')} censored — skipped",
                    )
                    continue
                if is_tile and is_black_placeholder_frame(data):
                    black += 1
                    STUDIO_LOG.warn(
                        "Upscale",
                        f"Tile r{job.meta.get('tile_row')}c{job.meta.get('tile_col')} black placeholder — skipped",
                    )
                    continue
                meta = dict(job.meta)
                meta.update({
                    "seed": gen.get("seed"),
                    "horde_request_id": result.get("id") or job.horde_id,
                    "generation_id": gen.get("id"),
                    "worker_name": gen.get("worker_name"),
                    "worker_id": gen.get("worker_id"),
                    "model": gen.get("model") or job.meta.get("model"),
                    "kudos": result.get("kudos", job.kudos),
                    "censored": was_censored,
                    "notes": notes,
                    "saved_at": time.time(),
                    "shared": result.get("shared"),
                    "app": f"{APP_NAME} {APP_VERSION}",
                    "index": idx,
                })
                if is_tile:
                    path = self.store.save_tile(data, meta)
                elif self.save_direct:
                    path = self.store.save_direct(data, meta)
                else:
                    path = self.store.save_temp(data, meta)
                paths.append(path)
            if not deferred:
                break
            pending = deferred
            if self._cancel.is_set() and job.kind == KIND_GEN:
                # user cancelled — one final quick pass, then bail out
                break
            if not self._sleep(6.0 * (pass_no + 1)):
                break
        return paths, censored, black


class TaskThread(QThread):
    done = pyqtSignal(object)
    error = pyqtSignal(str)

    def __init__(self, fn: Callable[[], Any], parent: Optional[QObject] = None) -> None:
        super().__init__(parent)
        self.fn = fn

    def run(self) -> None:
        try:
            self.done.emit(self.fn())
        except (HordeError, LlmError) as exc:
            self.error.emit(exc.message)
        except Exception as exc:  # noqa: BLE001
            self.error.emit(f"{exc.__class__.__name__}: {exc}")


class _LogBridge(QObject):
    logged = pyqtSignal(object)


class _StSubmitBridge(QObject):
    requested = pyqtSignal(str, object, dict)


def poll_interrogation(
    api: HordeAPI,
    rid: str,
    form_name: str,
    is_cancelled: Callable[[], bool],
    poll_interval: float = 2.5,
    timeout: float = 360.0,
) -> Optional[Dict[str, Any]]:
    deadline = time.time() + timeout
    net_errs = 0
    while time.time() < deadline:
        if is_cancelled():
            try:
                api.interrogate_cancel(rid)
            except HordeError:
                pass
            return None
        try:
            res = api.interrogate_status(rid)
            net_errs = 0
        except HordeError as exc:
            if exc.status == 404:
                raise HordeError("Alchemy interrogation expired on AI Horde") from exc
            net_errs += 1
            if net_errs >= 10:
                raise
            if not _interruptible_sleep(min(8.0, 1.5 * net_errs), is_cancelled):
                return None
            continue
        state = str(res.get("state") or "").lower()
        if state == "done":
            return res
        if state in ("faulted", "cancelled"):
            raise HordeError(f"Alchemy {form_name} {state}")
        if not _interruptible_sleep(poll_interval, is_cancelled):
            return None
    raise HordeError(f"Alchemy {form_name} timed out")


def alchemy_fetch_result(api: HordeAPI, res: Dict[str, Any], form_name: str) -> Any:
    for item in res.get("forms") or []:
        if item.get("form") == form_name or len(res.get("forms") or []) == 1:
            r = item.get("result")
            if isinstance(r, dict):
                if form_name in r:
                    return r[form_name]
                if "url" in r:
                    return api.download(str(r["url"]))
                if "result" in r:
                    return r["result"]
                return r
            if isinstance(r, str):
                if r.startswith("http"):
                    return api.download(r)
                return r
    return None


class AlchemyJobWorker(QThread):
    progress = pyqtSignal(int, dict)
    completed = pyqtSignal(int, list, str)
    failed = pyqtSignal(int, str, float)

    def __init__(
        self,
        api: HordeAPI,
        store: ImageStore,
        job: Job,
        poll_interval: float,
        parent: Optional[QObject] = None,
    ) -> None:
        super().__init__(parent)
        self.api = api
        self.store = store
        self.job = job
        self.poll_interval = max(1.5, float(poll_interval))
        self._cancel = threading.Event()

    def request_cancel(self) -> None:
        self._cancel.set()

    def run(self) -> None:
        job = self.job
        jid = job.local_id
        form_name = str(job.meta.get("alchemy_form") or DEFAULT_UPSCALER)
        src_path = str(job.payload.get("source_image_path") or "")
        target_w = int(job.meta.get("target_w") or 0)
        target_h = int(job.meta.get("target_h") or 0)
        target_path = str(job.meta.get("tile_target") or "")
        self.progress.emit(jid, {"state": STATE_SUBMITTING, "started_at": time.time()})

        # Local Lanczos pseudo-upscaler (zero network/kudos cost)
        if form_name == LANCZOS_UPSCALER:
            try:
                img = QImage(src_path)
                if img.isNull():
                    raise RuntimeError(f"Cannot load source image: {src_path}")
                out_img = hq_resize(img, target_w, target_h) if (target_w and target_h) else img
                data = image_to_png_bytes(out_img)
                path = self.store.save_tile(data, dict(job.meta, tile_target=target_path))
                STUDIO_LOG.ok("Upscale", f"Local Lanczos base ready ({out_img.width()}x{out_img.height()})")
                self.completed.emit(jid, [path], STATE_DONE)
            except Exception as exc:  # noqa: BLE001
                self.failed.emit(jid, f"Lanczos upscale failed: {exc}", 0.0)
            return

        try:
            with open(src_path, "rb") as fh:
                src_b64 = base64.b64encode(fh.read()).decode("ascii")
            sub = self.api.interrogate_submit({
                "source_image": src_b64,
                "forms": [{"name": form_name}],
            })
            rid = str(sub.get("id") or "")
            if not rid:
                raise HordeError("Alchemy returned no interrogation id")
            self.progress.emit(jid, {"horde_id": rid, "state": STATE_PROCESSING})
            STUDIO_LOG.info("Upscale", f"Whole-image Alchemy ({form_name}) submitted -> {rid[:10]}")
            res = poll_interrogation(self.api, rid, form_name, self._cancel.is_set, self.poll_interval)
            if res is None:
                self.completed.emit(jid, [], STATE_CANCELLED)
                return
            self.progress.emit(jid, {"state": STATE_FETCHING})
            raw = alchemy_fetch_result(self.api, res, form_name)
            if isinstance(raw, str):
                data = self.api.download(raw) if raw.startswith("http") else base64.b64decode(raw)
            elif isinstance(raw, (bytes, bytearray)):
                data = bytes(raw)
            else:
                raise HordeError(f"Alchemy returned unexpected payload for {form_name}")
            img = QImage.fromData(QByteArray(data))
            if img.isNull():
                raise HordeError("Alchemy upscaled image could not be decoded")
            if target_w and target_h and (img.width() != target_w or img.height() != target_h):
                img = hq_resize(img, target_w, target_h)
            out_data = image_to_png_bytes(img)
            path = self.store.save_tile(out_data, dict(job.meta, tile_target=target_path))
            STUDIO_LOG.ok("Upscale", f"Alchemy base upscaled to {img.width()}x{img.height()}")
            self.completed.emit(jid, [path], STATE_DONE)
        except HordeError as exc:
            self.failed.emit(jid, exc.message, exc.retry_after or 0.0)
        except Exception as exc:  # noqa: BLE001
            self.failed.emit(jid, f"{exc.__class__.__name__}: {exc}", 0.0)


class AestheticWorker(QThread):
    scored = pyqtSignal(str, float)

    def __init__(self, api: HordeAPI, path: str, parent: Optional[QObject] = None) -> None:
        super().__init__(parent)
        self.api = api
        self.path = path
        self._cancel = threading.Event()

    def request_cancel(self) -> None:
        self._cancel.set()

    def run(self) -> None:
        try:
            with open(self.path, "rb") as fh:
                b64 = base64.b64encode(fh.read()).decode("ascii")
            sub = self.api.interrogate_submit({"source_image": b64, "forms": [{"name": "aesthetics"}]})
            rid = str(sub.get("id") or "")
            if not rid:
                return
            res = poll_interrogation(self.api, rid, "aesthetics", self._cancel.is_set, 2.5, 180.0)
            if not res:
                return
            val = alchemy_fetch_result(self.api, res, "aesthetics")
            score: Optional[float] = None
            if isinstance(val, (int, float)):
                score = float(val)
            elif isinstance(val, dict):
                for k in ("score", "aesthetic", "aesthetics"):
                    if isinstance(val.get(k), (int, float)):
                        score = float(val[k])
                        break
            if score is not None:
                self.scored.emit(self.path, score)
        except Exception as exc:  # noqa: BLE001
            STUDIO_LOG.warn("HORDE", f"Aesthetic scoring failed for {os.path.basename(self.path)}: {exc}")


# ---- Depth-Map (Alchemy depth_anything_v2) background worker ----------------
class DepthMapWorker(QThread):
    """Requests a Depth Anything V2 annotation for one image through AI Horde
    Alchemy (interrogate/async) and writes the result beside the source as
    <name>_depth.png. The attachment never occupies a temp-ring slot and its
    lifecycle is tied to its source image."""

    progress = pyqtSignal(int, dict)
    completed = pyqtSignal(int, list, str)
    failed = pyqtSignal(int, str, float)

    def __init__(self, api: HordeAPI, job: Job, poll_interval: float, parent: Optional[QObject] = None) -> None:
        super().__init__(parent)
        self.api = api
        self.job = job
        self.poll_interval = max(1.5, float(poll_interval))
        self._cancel = threading.Event()

    def request_cancel(self) -> None:
        self._cancel.set()

    def run(self) -> None:
        job = self.job
        jid = job.local_id
        src_path = str(job.payload.get("source_image_path") or "")
        target = str(job.meta.get("depth_target") or depth_path_for(src_path))
        self.progress.emit(jid, {"state": STATE_SUBMITTING, "started_at": time.time()})
        try:
            with open(src_path, "rb") as fh:
                src_b64 = base64.b64encode(fh.read()).decode("ascii")
            sub = self.api.interrogate_submit({
                "source_image": src_b64,
                "forms": [{"name": DEPTH_FORM, "payload": {"control_type": DEPTH_CONTROL_TYPE}}],
            })
            rid = str(sub.get("id") or "")
            if not rid:
                raise HordeError("Alchemy returned no interrogation id for the depth map")
            self.progress.emit(jid, {"horde_id": rid, "state": STATE_PROCESSING})
            STUDIO_LOG.info("HORDE", f"Depth map ({DEPTH_CONTROL_TYPE}) submitted -> {rid[:10]}")
            res = poll_interrogation(self.api, rid, DEPTH_FORM, self._cancel.is_set, self.poll_interval, 480.0)
            if res is None:
                self.completed.emit(jid, [], STATE_CANCELLED)
                return
            self.progress.emit(jid, {"state": STATE_FETCHING})
            raw = alchemy_fetch_result(self.api, res, DEPTH_FORM)
            # The interrogation result shape varies by horde version: unwrap
            # common dict envelopes before decoding the image payload.
            if isinstance(raw, dict):
                for key in (DEPTH_CONTROL_TYPE, DEPTH_FORM, "url", "result", "image", "b64", "depth"):
                    val = raw.get(key)
                    if isinstance(val, (str, bytes, bytearray)):
                        raw = val
                        break
                else:
                    vals = [v for v in raw.values() if isinstance(v, (str, bytes)) and len(v) > 32]
                    if len(vals) == 1:
                        raw = vals[0]
            if isinstance(raw, str):
                data = self.api.download(raw) if raw.startswith("http") else base64.b64decode(raw)
            elif isinstance(raw, (bytes, bytearray)):
                data = bytes(raw)
            else:
                raise HordeError(f"Alchemy returned unexpected payload for {DEPTH_CONTROL_TYPE}")
            img = QImage.fromData(QByteArray(data))
            if img.isNull():
                raise HordeError("Depth map could not be decoded")
            if not os.path.isfile(src_path):
                self.failed.emit(jid, "Source image disappeared before the depth map arrived", 0.0)
                return
            meta = {
                "depth_of": src_path,
                "depth_model": DEPTH_CONTROL_TYPE,
                "width": img.width(),
                "height": img.height(),
                "saved_at": time.time(),
                "app": f"{APP_NAME} {APP_VERSION}",
            }
            write_image_with_metadata(image_to_png_bytes(img), target, meta)
            STUDIO_LOG.ok("HORDE", f"Depth map saved: {os.path.basename(target)} ({img.width()}x{img.height()})")
            self.completed.emit(jid, [target], STATE_DONE)
        except HordeError as exc:
            self.failed.emit(jid, exc.message, exc.retry_after or 0.0)
        except Exception as exc:  # noqa: BLE001
            self.failed.emit(jid, f"{exc.__class__.__name__}: {exc}", 0.0)


# ---- Tile Upscale Geometry & Feathered Blending -----------------------------
def snap64(v: float, lo: int = 64, hi: int = 3072) -> int:
    s = int(round(v / 64.0)) * 64
    return max(lo, min(hi, s))


def snap64_up(v: float, lo: int = 64, hi: int = 3072) -> int:
    """Ceil to the next multiple of 64 (never exceeds `hi`)."""
    s = int(math.ceil(v / 64.0)) * 64
    return max(lo, min(hi, s))


def snap64_nearest(v: float, lo: int = 64, hi: int = 3072) -> int:
    """Round to the NEAREST multiple of 64 (up or down, whichever is closer)
    and clamp into [lo, hi] - the AI Horde dimension requirement."""
    s = int(round(v / 64.0)) * 64
    return max(lo, min(hi, s))


def fit_pair_under_mp(w: float, h: float, max_mp: int = MEGAPIXEL_BUDGET) -> Tuple[int, int]:
    """Scale a W x H pair to fit under the megapixel budget while keeping the
    aspect ratio, snapping both dimensions to the nearest multiple of 64. If
    nearest-rounding still exceeds the budget, step the larger dimension down
    by 64 until it fits."""
    px = float(w) * float(h)
    if px <= 0:
        return (64, 64)
    if px > max_mp:
        s = math.sqrt(max_mp / px)
        w, h = w * s, h * s
    ow, oh = snap64_nearest(w), snap64_nearest(h)
    while ow * oh > max_mp and (ow > 64 or oh > 64):
        if ow >= oh and ow > 64:
            ow -= 64
        elif oh > 64:
            oh -= 64
        else:
            break
    return (ow, oh)


def plan_tile_grid(
    src_w: int,
    src_h: int,
    scale: float,
    overlap: int,
    max_mp: int = MEGAPIXEL_BUDGET,
) -> Dict[str, Any]:
    """Plan the A1111-style tiled upscale as a grid of UNIFORM SQUARE tiles.

    Design goals (v3.1 remaster):
      * Every tile that goes through img2img is a large S×S square (SDXL-optimal,
        aspect 1:1) — except an axis that fits inside a single tile, which then
        spans the full extent of that axis.
      * Tiles are evenly distributed across the image: the first tile starts at 0,
        the last tile ends exactly at the image edge, and every neighbour pair
        shares the SAME overlap. No tiny/narrow corner or edge remainder tiles —
        every request is a full-size square.
      * Each tile is 64px-aligned and stays within `max_mp` (the 1 MP AI Horde
        budget), so the worker never resizes the source and never rejects it.

    Algorithm:
      1. S_max = largest 64-multiple with S_max² <= max_mp (1024 for 1 MP).
      2. cols/rows = minimal tile counts whose S_max tiles (with `overlap`
         between neighbours) still cover the output canvas.
      3. S = smallest 64-multiple that covers BOTH axes with those counts →
         all tiles are exactly S×S (single-tile axes use the full extent).
      4. Tile origins are evenly spaced with a uniform step so the grid has no
         remainder slivers at the right/bottom edges.
    """
    out_w = max(128, snap64(src_w * scale, 128, 8192))
    out_h = max(128, snap64(src_h * scale, 128, 8192))
    ov = max(0, snap64(overlap, 0, 512))
    ov = min(ov, max(0, min(out_w, out_h) // 4))

    # Largest square tile the AI Horde megapixel budget allows (64-aligned).
    s_max = max(64, int(math.sqrt(max(1, max_mp))))
    s_max = (s_max // 64) * 64

    def _cells(total: int, tile: int) -> int:
        """Minimal tile count covering `total` with `tile`-sized steps + overlap."""
        if total <= tile:
            return 1
        if ov <= 0:
            return int(math.ceil(total / tile))
        return int(math.ceil((total - ov) / float(tile - ov)))

    def _need(total: int, n: int) -> int:
        """Smallest 64-aligned per-tile span covering `total` with n tiles."""
        if n <= 1:
            return total
        return snap64_up((total + (n - 1) * ov) / float(n), 64, s_max)

    cols = _cells(out_w, s_max)
    rows = _cells(out_h, s_max)
    # Uniform square tile size: the smallest S that covers both axes (S <= s_max
    # by construction because s_max is 64-aligned and _need never exceeds it).
    s = max(_need(out_w, cols), _need(out_h, rows))
    s = max(64, min(s, s_max))

    tile_w = s if cols > 1 else out_w   # single-column: full width
    tile_h = s if rows > 1 else out_h   # single-row: full height

    def _origins(total: int, n: int, tile_len: int) -> List[int]:
        if n <= 1:
            return [0]
        # Evenly space n tiles; first at 0, last ends exactly at `total`.
        step = (total - tile_len) / float(n - 1)
        return [int(round(i * step)) for i in range(n)]

    xs = _origins(out_w, cols, tile_w)
    ys = _origins(out_h, rows, tile_h)

    # Uniform neighbour overlap per axis (feathered seam width source)
    ov_x = (tile_w - (xs[1] - xs[0])) if cols > 1 else 0
    ov_y = (tile_h - (ys[1] - ys[0])) if rows > 1 else 0

    tiles: List[Dict[str, Any]] = []
    tid = 0
    for r, y0 in enumerate(ys):
        for c, x0 in enumerate(xs):
            edge_l = ov_x if c > 0 else 0
            edge_r = ov_x if c < cols - 1 else 0
            edge_t = ov_y if r > 0 else 0
            edge_b = ov_y if r < rows - 1 else 0
            tiles.append({
                "idx": tid,
                "row": r,
                "col": c,
                "x": x0,
                "y": y0,
                "w": tile_w,
                "h": tile_h,
                "send_w": tile_w,
                "send_h": tile_h,
                "edge_l": edge_l,
                "edge_t": edge_t,
                "edge_r": edge_r,
                "edge_b": edge_b,
                "state": TILE_PLANNED,
                "path": "",
                "error": "",
                "job_id": None,
            })
            tid += 1
    return {
        "src_w": src_w,
        "src_h": src_h,
        "out_w": out_w,
        "out_h": out_h,
        "cols": cols,
        "rows": rows,
        "tile": s,
        "overlap": ov,
        "tiles": tiles,
    }


def _feathered_tile(tile_img: QImage, e_l: int, e_t: int, e_r: int, e_b: int) -> QImage:
    """Apply smooth linear alpha feather ramps along shared overlap edges.

    v3 optimization: only the actual feather bands are processed (edge-restricted
    alpha), instead of the v2 full-image scan — several times faster per tile
    while producing bit-identical results."""
    img = tile_img.convertToFormat(QImage.Format.Format_ARGB32)
    w, h = img.width(), img.height()
    if w <= 0 or h <= 0:
        return img
    fl = max(0, min(w // 2, e_l * 2))
    fr = max(0, min(w // 2, e_r * 2))
    ft = max(0, min(h // 2, e_t * 2))
    fb = max(0, min(h // 2, e_b * 2))
    if fl == 0 and fr == 0 and ft == 0 and fb == 0:
        return img

    # Horizontal ramp only where a left/right feather exists
    ax: Optional[List[float]] = None
    if fl or fr:
        ax = [1.0] * w
        for x in range(fl):
            ax[x] = min(ax[x], (x + 0.5) / fl)
        for x in range(fr):
            ax[w - 1 - x] = min(ax[w - 1 - x], (x + 0.5) / fr)
    # Vertical ramp only where a top/bottom feather exists
    ay: Optional[List[float]] = None
    if ft or fb:
        ay = [1.0] * h
        for y in range(ft):
            ay[y] = min(ay[y], (y + 0.5) / ft)
        for y in range(fb):
            ay[h - 1 - y] = min(ay[h - 1 - y], (y + 0.5) / fb)

    for y in range(h):
        wy = ay[y] if ay is not None else 1.0
        if wy >= 0.9999 and ax is None:
            continue  # fully opaque row with no horizontal feather
        if wy >= 0.9999:
            # Row keeps full vertical opacity: only touch horizontal bands
            zones: List[Tuple[int, int]] = []
            if fl:
                zones.append((0, fl))
            if fr:
                zones.append((w - fr, w))
            for x0, x1 in zones:
                for x in range(x0, x1):
                    alpha = ax[x]
                    if alpha < 0.9999:
                        col = img.pixelColor(x, y)
                        col.setAlpha(int(round(col.alpha() * alpha)))
                        img.setPixelColor(x, y, col)
        else:
            # Vertical ramp active: process the full row
            for x in range(w):
                alpha = wy * (ax[x] if ax is not None else 1.0)
                if alpha < 0.9999:
                    col = img.pixelColor(x, y)
                    col.setAlpha(int(round(col.alpha() * alpha)))
                    img.setPixelColor(x, y, col)
    return img


def merge_tiles(
    tiles: List[Dict[str, Any]],
    out_w: int,
    out_h: int,
    base_path: Optional[str] = None,
) -> QImage:
    """Composite finished refined tiles with feathered seams over the upscaled base."""
    canvas = QImage(out_w, out_h, QImage.Format.Format_ARGB32)
    canvas.fill(QColor(0, 0, 0, 255))
    painter = QPainter(canvas)
    painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
    if base_path and os.path.isfile(base_path):
        base = QImage(base_path)
        if not base.isNull():
            if base.width() != out_w or base.height() != out_h:
                base = hq_resize(base, out_w, out_h)
            painter.drawImage(0, 0, base)
    for t in tiles:
        if t.get("state") != TILE_DONE or not t.get("path") or not os.path.isfile(t["path"]):
            continue
        timg = QImage(t["path"])
        if timg.isNull():
            continue
        tw, th = int(t["w"]), int(t["h"])
        if timg.width() != tw or timg.height() != th:
            timg = hq_resize(timg, tw, th)
        feathered = _feathered_tile(
            timg, int(t["edge_l"]), int(t["edge_t"]), int(t["edge_r"]), int(t["edge_b"])
        )
        painter.drawImage(int(t["x"]), int(t["y"]), feathered)
    painter.end()
    return canvas

# =============================================================================
#  14. Queue Manager (Parallel Slot Scheduler + Pinned Upscale Groups)
# =============================================================================
class QueueManager(QAbstractListModel):
    image_ready = pyqtSignal(str, dict)
    job_finished = pyqtSignal(object)
    summary_changed = pyqtSignal()

    def __init__(self, api: HordeAPI, store: ImageStore, parent: Optional[QObject] = None) -> None:
        super().__init__(parent)
        self.api = api
        self.store = store
        self.jobs: List[Job] = []
        self._workers: Dict[int, QThread] = {}
        self._purged: Dict[int, Job] = {}
        self._next_id = 1
        self.max_parallel = 2
        self.poll_interval = 2.5
        self.save_direct = False
        self.paused = False
        self._retry_timer = QTimer(self)
        self._retry_timer.setInterval(1500)
        self._retry_timer.timeout.connect(self._schedule)
        self._retry_timer.start()

    def rowCount(self, parent: QModelIndex = QModelIndex()) -> int:  # noqa: N802
        return 0 if parent.isValid() else len(self.jobs)

    def data(self, index: QModelIndex, role: int = Qt.ItemDataRole.DisplayRole) -> Any:
        if not index.isValid() or not (0 <= index.row() < len(self.jobs)):
            return None
        job = self.jobs[index.row()]
        if role == Qt.ItemDataRole.UserRole:
            return job
        if role == Qt.ItemDataRole.DisplayRole:
            return job.title_line()
        return None

    def _row_of(self, local_id: int) -> int:
        for i, j in enumerate(self.jobs):
            if j.local_id == local_id:
                return i
        return -1

    def _emit_row(self, row: int) -> None:
        if 0 <= row < len(self.jobs):
            ix = self.index(row, 0)
            self.dataChanged.emit(ix, ix)

    def _insert_index_for(self, kind: str) -> int:
        if kind == KIND_GROUP:
            # Pin tile upscale groups near top
            idx = 0
            while idx < len(self.jobs) and self.jobs[idx].kind == KIND_GROUP:
                idx += 1
            return idx
        return len(self.jobs)

    def enqueue(
        self,
        payload: Dict[str, Any],
        meta: Dict[str, Any],
        kind: str = KIND_GEN,
        group_id: Optional[int] = None,
    ) -> Job:
        job = Job(
            local_id=self._next_id,
            payload=copy.deepcopy(payload),
            meta=copy.deepcopy(meta),
            kind=kind,
            group_id=group_id,
        )
        self._next_id += 1
        row = self._insert_index_for(kind)
        self.beginInsertRows(QModelIndex(), row, row)
        self.jobs.insert(row, job)
        self.endInsertRows()
        self.summary_changed.emit()
        self._schedule()
        return job

    def add_group(self, gid: int, title: str, detail: str) -> Job:
        job = Job(
            local_id=self._next_id,
            payload={},
            meta={"tile_group": gid},
            kind=KIND_GROUP,
            group_id=gid,
            state=STATE_PROCESSING,
            group_title=title,
            group_detail=detail,
            group_progress=0.02,
        )
        self._next_id += 1
        row = self._insert_index_for(KIND_GROUP)
        self.beginInsertRows(QModelIndex(), row, row)
        self.jobs.insert(row, job)
        self.endInsertRows()
        self.summary_changed.emit()
        return job

    def update_group(
        self,
        gid: int,
        state: Optional[str] = None,
        detail: Optional[str] = None,
        progress: Optional[float] = None,
        results: Optional[List[str]] = None,
    ) -> None:
        for row, job in enumerate(self.jobs):
            if job.kind == KIND_GROUP and job.group_id == gid:
                if state is not None:
                    job.state = state
                if detail is not None:
                    job.group_detail = detail
                if progress is not None:
                    job.group_progress = progress
                if results is not None:
                    job.results = list(results)
                self._emit_row(row)
                self.summary_changed.emit()
                return

    def set_paused(self, paused: bool) -> None:
        self.paused = bool(paused)
        self.summary_changed.emit()
        if not self.paused:
            self._schedule()

    def cancel(self, job: Job) -> None:
        """v11: cancelling PURGES the task from the queue view immediately —
        the row disappears on the spot, without waiting for any network
        round-trip. The still-running worker is told to stop; whatever the
        horde already finished is still downloaded afterwards and surfaces
        through the purged-job bookkeeping (_purged)."""
        row = self._row_of(job.local_id)
        if row < 0:
            return
        if job.kind == KIND_GROUP and job.group_id is not None:
            # purge every live child of the tile group first
            for child in list(self.jobs):
                if (
                    child.group_id == job.group_id
                    and child.kind != KIND_GROUP
                    and not child.terminal
                ):
                    self.cancel(child)
            job.state = STATE_CANCELLED
            job.group_detail = "Cancelled"
            job.ended_at = time.time()
            self._remove_row(job)
            self.summary_changed.emit()
            return
        worker = self._workers.get(job.local_id)
        if worker is not None and hasattr(worker, "request_cancel"):
            # fire-and-forget: the worker keeps the horde-side DELETE +
            # partial-result download off the UI thread
            worker.request_cancel()  # type: ignore[attr-defined]
            job.state = STATE_CANCELLED
            job.ended_at = time.time()
            self._purged[job.local_id] = job
            self._remove_row(job)
        elif job.state == STATE_QUEUED:
            job.state = STATE_CANCELLED
            job.ended_at = time.time()
            self._remove_row(job)
            self.job_finished.emit(job)
        else:
            return  # terminal job (done/failed/cancelled) — nothing to cancel
        self.summary_changed.emit()

    def _remove_row(self, job: Job) -> None:
        row = self._row_of(job.local_id)
        if row >= 0:
            self.beginRemoveRows(QModelIndex(), row, row)
            self.jobs.pop(row)
            self.endRemoveRows()

    def cancel_all(self) -> None:
        for job in list(self.jobs):
            if not job.terminal:
                self.cancel(job)

    def retry(self, job: Job) -> Optional[Job]:
        if job.kind == KIND_GROUP:
            return None
        if job.state == STATE_FAILED:
            # Restart failed job in place
            job.state = STATE_QUEUED
            job.message = ""
            job.horde_id = ""
            job.retry_after = 0.0
            job.wait_time = None
            job.wait_initial = None
            job.queue_position = None
            job.finished = 0
            job.started_at = None
            job.ended_at = None
            row = self._row_of(job.local_id)
            self._emit_row(row)
            self.summary_changed.emit()
            self._schedule()
            return job
        return self.enqueue(job.payload, job.meta, kind=job.kind, group_id=job.group_id)

    def remove(self, job: Job) -> None:
        if job.active:
            self.cancel(job)
        if job.kind == KIND_GROUP and job.group_id is not None:
            children = [j for j in self.jobs if j.group_id == job.group_id and j.kind != KIND_GROUP]
            for ch in children:
                self.remove(ch)
        self._remove_row(job)
        self.summary_changed.emit()

    def move(self, job: Job, delta: int) -> None:
        row = self._row_of(job.local_id)
        if row < 0 or job.kind == KIND_GROUP:
            return
        target = row + delta
        if not (0 <= target < len(self.jobs)) or self.jobs[target].kind == KIND_GROUP:
            return
        self.beginResetModel()
        self.jobs[row], self.jobs[target] = self.jobs[target], self.jobs[row]
        self.endResetModel()

    def clear_finished(self) -> None:
        keep = [j for j in self.jobs if not (j.terminal and j.kind != KIND_GROUP)]
        if len(keep) == len(self.jobs):
            return
        self.beginResetModel()
        self.jobs = keep
        self.endResetModel()
        self.summary_changed.emit()

    def counts(self) -> Dict[str, int]:
        c = {"queued": 0, "active": 0, "done": 0, "failed": 0, "upscales": 0}
        for j in self.jobs:
            if j.kind == KIND_GROUP:
                if j.active:
                    c["upscales"] += 1
                continue
            if j.state == STATE_QUEUED:
                c["queued"] += 1
            elif j.active:
                c["active"] += 1
            elif j.state == STATE_DONE:
                c["done"] += 1
            elif j.state == STATE_FAILED:
                c["failed"] += 1
        return c

    def eta(self) -> Optional[float]:
        waits = [float(j.wait_time) for j in self.jobs if j.active and j.wait_time is not None]
        return max(waits) if waits else None

    def overall_progress(self) -> float:
        """Mean progress across active (and pending) jobs; 0 when idle."""
        live = [j for j in self.jobs if j.kind != KIND_GROUP and not j.terminal]
        if not live:
            return 0.0
        return sum(j.progress_fraction() for j in live) / len(live)

    def _schedule(self) -> None:
        if self.paused:
            return
        now = time.time()
        while len(self._workers) < max(1, int(self.max_parallel)):
            cand = next(
                (j for j in self.jobs if j.kind != KIND_GROUP and j.state == STATE_QUEUED and j.retry_after <= now),
                None,
            )
            if cand is None:
                break
            self._launch(cand)

    def _launch(self, job: Job) -> None:
        if job.kind == KIND_ALCH:
            worker: QThread = AlchemyJobWorker(self.api, self.store, job, self.poll_interval, self)
        elif job.kind == KIND_DEPTH:
            worker: QThread = DepthMapWorker(self.api, job, self.poll_interval, self)
        else:
            worker = JobWorker(self.api, self.store, job, self.poll_interval, self.save_direct, self)
        worker.progress.connect(self._on_progress)  # type: ignore[attr-defined]
        worker.completed.connect(self._on_completed)  # type: ignore[attr-defined]
        worker.failed.connect(self._on_failed)  # type: ignore[attr-defined]
        worker.finished.connect(lambda jid=job.local_id, w=worker: self._cleanup_worker(jid, w))
        self._workers[job.local_id] = worker
        job.state = STATE_SUBMITTING
        self._emit_row(self._row_of(job.local_id))
        self.summary_changed.emit()
        worker.start()

    def _on_progress(self, jid: int, fields: Dict[str, Any]) -> None:
        row = self._row_of(jid)
        if row < 0:
            return
        job = self.jobs[row]
        for k, v in fields.items():
            if hasattr(job, k):
                setattr(job, k, v)
        self._emit_row(row)
        self.summary_changed.emit()

    def _on_completed(self, jid: int, paths: List[str], final_state: str) -> None:
        job: Optional[Job] = None
        row = self._row_of(jid)
        if row >= 0:
            job = self.jobs[row]
            job.state = final_state
            job.results = list(paths)
            job.ended_at = time.time()
            self._emit_row(row)
        else:
            # v11: the job was cancelled & purged from the view while its
            # worker was mid-flight. Anything the horde managed to finish is
            # STILL delivered (cancelled jobs keep the images that arrived
            # before the cancel took effect).
            job = self._purged.pop(jid, None)
            if job is None:
                return
            job.state = final_state
            job.results = list(paths)
            job.ended_at = time.time()
        for p in paths:
            self.image_ready.emit(p, job.meta)
        self.job_finished.emit(job)
        self.summary_changed.emit()

    def _on_failed(self, jid: int, msg: str, retry_after: float) -> None:
        row = self._row_of(jid)
        if row < 0:
            purged = self._purged.pop(jid, None)
            if purged is not None:
                # purged (cancelled) job finally reported back — nothing to
                # show, the row is already gone; keep it silent.
                STUDIO_LOG.net("HORDE", f"Job #{jid} (cancelled) ended: {msg[:120]}")
            return
        job = self.jobs[row]
        if retry_after > 0:
            job.state = STATE_QUEUED
            job.retry_after = time.time() + retry_after
            job.message = f"Rate-limited, retrying in {int(retry_after)}s: {msg}"
            STUDIO_LOG.warn("HORDE", f"Job #{jid} backoff {int(retry_after)}s: {msg}")
        else:
            job.state = STATE_FAILED
            job.message = msg
            job.ended_at = time.time()
            STUDIO_LOG.error("HORDE", f"Job #{jid} failed: {msg}")
            self.job_finished.emit(job)
        self._emit_row(row)
        self.summary_changed.emit()

    def _cleanup_worker(self, jid: int, worker: QThread) -> None:
        if self._workers.get(jid) is worker:
            self._workers.pop(jid, None)
        worker.deleteLater()
        self._purged.pop(jid, None)
        self._schedule()

    def shutdown(self) -> None:
        self._retry_timer.stop()
        for w in list(self._workers.values()):
            if hasattr(w, "request_cancel"):
                w.request_cancel()  # type: ignore[attr-defined]
            w.wait(1200)

# =============================================================================
#  15. High-Craft East-Asian Custom Widgets & Delegates (v10.0 Remaster)
# =============================================================================
def make_button(
    text: str,
    slot: Optional[Callable[[], Any]] = None,
    small: bool = False,
    accent: bool = False,
    tip: str = "",
    icon_key: str = "",
    icon_size: int = 14,
    compress: bool = False,
) -> QPushButton:
    b = QPushButton(text)
    if accent:
        b.setObjectName("Accent")
    elif small:
        b.setObjectName("Small")
    b.setCursor(Qt.CursorShape.PointingHandCursor)
    if compress:
        b.setMinimumWidth(0)
        b.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Fixed)
    if tip:
        b.setToolTip(tip)
    if icon_key:
        b.setIcon(VECTOR_ASSETS.icon(icon_key, icon_size))
        b.setIconSize(QSize(icon_size, icon_size))
    if slot is not None:
        b.clicked.connect(slot)
    return b


def make_label(text: str, name: str = "") -> QLabel:
    lb = QLabel(text)
    if name:
        lb.setObjectName(name)
    return lb


class ElideLabel(QLabel):
    def __init__(self, text: str = "", parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self._full = text
        self.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Preferred)
        super().setText(text)

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        fm = QFontMetrics(self.font())
        return QSize(12, fm.height() + 2)

    def setText(self, text: str) -> None:  # noqa: N802
        self._full = text or ""
        self._apply_elide()

    def full_text(self) -> str:
        return self._full

    def resizeEvent(self, event) -> None:  # noqa: N802
        super().resizeEvent(event)
        self._apply_elide()

    def _apply_elide(self) -> None:
        fm = QFontMetrics(self.font())
        avail = max(16, self.width() - 8)
        super().setText(fm.elidedText(self._full, Qt.TextElideMode.ElideRight, avail))


class _ResettableSlider(QSlider):
    """Pro photography slider: double-clicking resets cleanly to default_value."""

    def __init__(
        self,
        orientation: Qt.Orientation = Qt.Orientation.Horizontal,
        default_value: int = 0,
        parent: Optional[QWidget] = None,
    ) -> None:
        super().__init__(orientation, parent)
        self._default_value = int(default_value)

    def mouseDoubleClickEvent(self, event) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton:
            self.setValue(self._default_value)
            event.accept()
            return
        super().mouseDoubleClickEvent(event)


class BevelDeck(QFrame):
    """Sculpted command deck with unmistakable bespoke architecture per theme:
    - SeeStation: Sony PS4 frosted sapphire OLED glass + XMB dual silk wave + cyan lightbar
    - Sarif Gold: Deus Ex: HR true 45-deg chamfered carbon plate + triangle facets + gold brackets
    - Oriental Spirit: Kuro-Urushi neutral jet-black altar + pure red torii double-lintel + hanko seals
    """

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setObjectName("Deck")

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        key = resolve_theme_key(C.get("key", "seestation"))
        grad = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        grad.setColorAt(0.0, QColor(C["deck_hi"]))
        grad.setColorAt(0.46, QColor(C["deck_mid"]))
        grad.setColorAt(1.0, QColor(C["deck_lo"]))
        frame_path = _theme_frame_path(r, key, rad_see=9.0, ch_gold=8.0)
        p.setBrush(QBrush(grad))
        p.setPen(QPen(QColor(C["line_hi"] if key == "seestation" else C["line"]), 1.05))
        p.drawPath(frame_path)

        p.save()
        p.setClipPath(frame_path)
        if key == "seestation":
            for dy, amp, al, lw in ((24.0, 14.0, 52, 1.7), (34.0, 10.0, 28, 1.1)):
                wave = QPainterPath()
                wave.moveTo(r.left() - 6, r.top() + dy)
                wave.cubicTo(
                    r.left() + r.width() * 0.30, r.top() + dy - amp,
                    r.left() + r.width() * 0.68, r.top() + dy + amp,
                    r.right() + 6, r.top() + dy - amp * 0.4,
                )
                wc = QColor(C["acc_hi"]); wc.setAlpha(al)
                p.setPen(QPen(wc, lw))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawPath(wave)
            rail = QLinearGradient(r.left(), r.top(), r.right(), r.top())
            a0 = QColor(C["acc_hi"]); a0.setAlpha(0)
            rail.setColorAt(0.0, a0)
            rail.setColorAt(0.22, QColor(C["acc_mid"]))
            rail.setColorAt(0.50, QColor(C["acc_spec"]))
            rail.setColorAt(0.78, QColor(C["acc_mid"]))
            rail.setColorAt(1.0, a0)
            p.setPen(QPen(QBrush(rail), 2.1))
            p.drawLine(QPointF(r.left() + 8, r.top() + 1.5), QPointF(r.right() - 8, r.top() + 1.5))
        elif key == "oriental":
            # Strictly pure red Torii lintels + subtle katana glint over neutral jet-black lacquer
            p.setPen(QPen(QColor(C["acc_hi"]), 2.2))
            p.drawLine(QPointF(r.left() + 1, r.top() + 1.2), QPointF(r.right() - 1, r.top() + 1.2))
            p.setPen(QPen(QColor(C["acc_lo"]), 1.0))
            p.drawLine(QPointF(r.left() + 14, r.top() + 5.0), QPointF(r.right() - 14, r.top() + 5.0))
            slash = QLinearGradient(r.right() - 70, r.top(), r.right() - 18, r.bottom())
            slash.setColorAt(0.0, QColor(245, 16, 10, 0))
            slash.setColorAt(0.5, QColor(245, 16, 10, 36))
            slash.setColorAt(1.0, QColor(245, 16, 10, 0))
            p.setPen(QPen(QBrush(slash), 1.5))
            p.drawLine(QPointF(r.right() - 62, r.top()), QPointF(r.right() - 22, r.bottom()))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(QColor(C["acc_hi"])))
            p.drawPolygon(QPolygonF([QPointF(r.left() + 1, r.top() + 1), QPointF(r.left() + 13, r.top() + 1), QPointF(r.left() + 1, r.top() + 13)]))
            p.setBrush(QBrush(QColor(C["acc_mid"])))
            p.drawPolygon(QPolygonF([QPointF(r.right() - 1, r.bottom() - 1), QPointF(r.right() - 11, r.bottom() - 1), QPointF(r.right() - 1, r.bottom() - 11)]))
        else:
            p.setPen(Qt.PenStyle.NoPen)
            step = 24.0
            for ci in range(0, int(r.width() // step) + 2):
                if (ci * 5 + 1) % 3 == 0:
                    tx = r.left() + ci * step
                    p.setBrush(QColor(247, 194, 62, 13))
                    p.drawPolygon(QPolygonF([QPointF(tx, r.top()), QPointF(tx + step, r.top()), QPointF(tx + step * 0.5, r.top() + 20)]))
            p.setPen(QPen(QColor(C["acc_mid"]), 1.8))
            p.drawLine(QPointF(r.left() + 8, r.top() + 1.3), QPointF(r.right() - 8, r.top() + 1.3))
            p.setPen(QPen(QColor(C["acc_spec"]), 1.5))
            ch = 8.0
            p.drawLine(QPointF(r.left() + 1.5, r.top() + ch + 9), QPointF(r.left() + 1.5, r.top() + ch))
            p.drawLine(QPointF(r.left() + 1.5, r.top() + ch), QPointF(r.left() + ch, r.top() + 1.5))
            p.drawLine(QPointF(r.right() - 1.5, r.top() + ch + 9), QPointF(r.right() - 1.5, r.top() + ch))
            p.drawLine(QPointF(r.right() - 1.5, r.top() + ch), QPointF(r.right() - ch, r.top() + 1.5))
            p.drawLine(QPointF(r.right() - 1.5, r.bottom() - ch - 9), QPointF(r.right() - 1.5, r.bottom() - ch))
            p.drawLine(QPointF(r.right() - 1.5, r.bottom() - ch), QPointF(r.right() - ch, r.bottom() - 1.5))
        p.restore()
        p.setPen(QPen(QColor(C["sunken_bot"]), 1.0))
        p.drawLine(QPointF(r.left() + 6, r.bottom() - 1.5), QPointF(r.right() - 6, r.bottom() - 1.5))
        p.end()


class SectionHeader(QWidget):
    """Crisp East-Asian technical section header with distinctive per-theme emblem & rule."""

    def __init__(self, title: str, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setMinimumHeight(23)
        self._lay = QHBoxLayout(self)
        self._lay.setContentsMargins(0, 1, 0, 1)
        self._lay.setSpacing(3)
        self.title_label = ElideLabel("")
        self.title_label.setObjectName("Kicker")
        self.title_label.setFont(_font(9.0 * ui_scale(), True, 0.4))
        self.title_label.setText(title)
        self._lay.addSpacing(13)
        self._lay.addWidget(self.title_label, 1)

    def apply_scale(self, scale: float) -> None:
        s = max(0.75, min(1.40, float(scale)))
        self.title_label.setFont(_font(9.0 * s, True, 0.4))
        self.setMinimumHeight(max(20, int(round(23 * s))))
        self.update()

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        return QSize(24, self.minimumHeight())

    def set_title(self, title: str) -> None:
        self.title_label.setText(title)

    def add_right(self, w: QWidget) -> None:
        self._lay.addWidget(w)

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        cy = self.height() / 2.0
        key = resolve_theme_key(C.get("key", "seestation"))
        if key == "seestation":
            halo = QColor(C["hdr_dot"]); halo.setAlpha(72)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(halo))
            p.drawEllipse(QRectF(0.4, cy - 5.0, 10.0, 10.0))
            p.setBrush(QBrush(QColor(C["hdr_dot"])))
            p.drawEllipse(QRectF(2.2, cy - 3.2, 6.4, 6.4))
            p.setBrush(QColor(255, 255, 255, 190))
            p.drawEllipse(QRectF(3.6, cy - 2.2, 2.2, 2.2))
            rule = QLinearGradient(12.0, cy, self.width(), cy)
            rule.setColorAt(0.0, QColor(C["acc_hi"]))
            rule.setColorAt(0.55, QColor(C["hdr_line"]))
            fade = QColor(C["hdr_line"]); fade.setAlpha(0)
            rule.setColorAt(1.0, fade)
            p.setPen(QPen(QBrush(rule), 1.3))
            p.drawLine(QPointF(12.0, self.height() - 1.2), QPointF(self.width(), self.height() - 1.2))
        elif key == "oriental":
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(QColor(C["hdr_dot"])))
            p.drawPolygon(QPolygonF([
                QPointF(3.8, cy - 4.8), QPointF(9.2, cy - 4.8),
                QPointF(5.4, cy + 4.8), QPointF(0.0, cy + 4.8),
            ]))
            p.setPen(QPen(QColor(C["acc_hi"]), 1.3))
            p.drawLine(QPointF(0.0, self.height() - 2.0), QPointF(self.width(), self.height() - 2.0))
            p.setPen(QPen(QColor(C["hdr_line"]), 0.9))
            p.drawLine(QPointF(10.0, self.height() - 0.5), QPointF(self.width() - 6.0, self.height() - 0.5))
            p.setPen(QPen(QColor(C["acc_hi"]), 1.6))
            p.drawLine(QPointF(self.width() - 1.5, self.height() - 6.5), QPointF(self.width() - 1.5, self.height() - 1.5))
        else:
            poly = QPolygonF([
                QPointF(5.2, cy - 4.5), QPointF(9.6, cy),
                QPointF(5.2, cy + 4.5), QPointF(0.8, cy),
            ])
            p.setBrush(QBrush(QColor(C["hdr_dot"])))
            p.setPen(QPen(QColor(C["acc_spec"]), 0.9))
            p.drawPolygon(poly)
            p.setPen(QPen(QColor(C["acc_mid"]), 1.15))
            p.drawLine(QPointF(0.0, self.height() - 1.2), QPointF(self.width() - 6.0, self.height() - 1.2))
            p.setPen(QPen(QColor(C["acc_spec"]), 1.2))
            p.drawLine(QPointF(self.width() - 6.0, self.height() - 1.2), QPointF(self.width() - 1.0, self.height() - 6.2))
        p.end()


class CollapsibleSection(QWidget):
    toggled = pyqtSignal(bool)

    def __init__(self, title: str, body: QWidget, expanded: bool = False, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self._expanded = bool(expanded)
        self.body = body
        lay = QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(3)
        self.header = SectionHeader(title)
        self.toggle_btn = QToolButton()
        self.toggle_btn.setObjectName("Small")
        self.toggle_btn.setCheckable(True)
        self.toggle_btn.setChecked(self._expanded)
        self.toggle_btn.setFixedWidth(26)
        self.toggle_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.toggle_btn.setToolTip("Expand / collapse this section")
        self.toggle_btn.toggled.connect(self.set_expanded)
        self.header.add_right(self.toggle_btn)
        lay.addWidget(self.header)
        lay.addWidget(self.body)
        self._sync_ui()

    def is_expanded(self) -> bool:
        return self._expanded

    def set_expanded(self, on: bool) -> None:
        on = bool(on)
        if self._expanded == on and self.body.isVisible() == on:
            return
        self._expanded = on
        if self.toggle_btn.isChecked() != on:
            self.toggle_btn.blockSignals(True)
            self.toggle_btn.setChecked(on)
            self.toggle_btn.blockSignals(False)
        self._sync_ui()
        self.toggled.emit(on)

    def _sync_ui(self) -> None:
        self.body.setVisible(self._expanded)
        self.toggle_btn.setText("\u25BE" if self._expanded else "\u25B8")


class FolderChipButton(QAbstractButton):
    """Glossy bevelled folder chip button carrying its signature folder color stripe."""

    def __init__(
        self,
        label: str,
        color: str,
        icon_key: str = "",
        parent: Optional[QWidget] = None,
    ) -> None:
        super().__init__(parent)
        self.setText(label)
        self.folder_color = color
        self.icon_key = icon_key
        self.setCheckable(True)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setMinimumHeight(max(22, int(round(24 * ui_scale()))))
        self.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Fixed)

    def sizeHint(self) -> QSize:  # noqa: N802
        s = ui_scale()
        fm = QFontMetrics(_font(8.1 * s, True))
        ico = int(round(14 * s)) if self.icon_key else 0
        w = fm.horizontalAdvance(self.text()) + (ico + 16 if self.icon_key else 15)
        h = max(21, int(round(24 * s)))
        return QSize(max(38, w), h)

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        sh = self.sizeHint()
        return QSize(min(sh.width(), 44), sh.height())

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        checked = self.isChecked()
        hovered = self.underMouse()
        grad = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        if checked:
            grad.setColorAt(0.0, QColor(C["tab_on_hi"]))
            grad.setColorAt(1.0, QColor(C["tab_on_lo"]))
        elif hovered:
            grad.setColorAt(0.0, QColor(C["btn_hov_hi"]))
            grad.setColorAt(1.0, QColor(C["btn_hov_lo"]))
        else:
            grad.setColorAt(0.0, QColor(C["btn_hi"]))
            grad.setColorAt(1.0, QColor(C["btn_lo"]))
        tkey = resolve_theme_key(C.get("key", "seestation"))
        frame = _theme_frame_path(r, tkey, rad_see=6.5, ch_gold=3.5)
        p.setBrush(QBrush(grad))
        p.setPen(QPen(QColor(self.folder_color if checked else C["line_hi"]), 1.25 if checked else 0.9))
        p.drawPath(frame)
        p.save()
        p.setClipPath(frame)
        p.setBrush(QBrush(QColor(self.folder_color)))
        p.setPen(Qt.PenStyle.NoPen)
        if tkey == "seestation":
            bar_h = 2.4 if checked else 1.5
            p.drawRoundedRect(QRectF(r.left() + 6.0, r.bottom() - bar_h - 0.8, max(4.0, r.width() - 12.0), bar_h), 1.2, 1.2)
        elif tkey == "oriental":
            p.drawRect(QRectF(r.left() + 0.5, r.top() + 0.5, 3.2 if checked else 2.0, r.height() - 1.0))
            if checked:
                p.drawPolygon(QPolygonF([QPointF(r.right(), r.top()), QPointF(r.right() - 6.0, r.top()), QPointF(r.right(), r.top() + 6.0)]))
        else:
            p.drawRect(QRectF(r.left() + 3.0, r.top() + 0.8, max(4.0, r.width() - 6.0), 2.5 if checked else 1.7))
        p.restore()
        s = ui_scale()
        tx = int(r.left() + (6 if tkey == "oriental" else 5))
        if self.icon_key:
            isz = max(12, min(18, int(round(13.5 * s))))
            pm = VECTOR_ASSETS.pixmap(self.icon_key, isz, isz)
            p.drawPixmap(tx, int((self.height() - isz) / 2), pm)
            tx += isz + 4
        p.setFont(_font(8.1 * s, True))
        p.setPen(QColor(C["text_hi"] if checked else C["text"]))
        text_rect = QRect(tx, 1, max(10, int(r.right()) - tx - 3), self.height() - 2)
        elided = QFontMetrics(p.font()).elidedText(self.text(), Qt.TextElideMode.ElideRight, text_rect.width())
        p.drawText(
            text_rect,
            Qt.AlignmentFlag.AlignCenter if not self.icon_key else (Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft),
            elided,
        )
        p.end()


class _HScrollWheelFilter(QObject):
    """Converts vertical wheel events into horizontal scrolling when attached."""

    def __init__(self, scroll: QScrollArea, parent: Optional[QObject] = None) -> None:
        super().__init__(parent or scroll)
        self._scroll = scroll

    def eventFilter(self, obj, event) -> bool:  # noqa: N802
        if event.type() == QEvent.Type.Wheel:
            dy = event.angleDelta().y()
            if dy:
                sb = self._scroll.horizontalScrollBar()
                sb.setValue(sb.value() - int(dy * 1.2))
                return True
        return super().eventFilter(obj, event)


class ThinProgressBar(QProgressBar):
    """6px illuminated lacquer channel showing overall queue progress."""

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setFixedHeight(6)
        self.setTextVisible(False)
        self.setRange(0, 100)
        self.setValue(0)

    def sizeHint(self) -> QSize:  # noqa: N802
        return QSize(56, 6)

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        return QSize(28, 6)


class Toast(QWidget):
    """Single glossy toast card in the corner notification stack."""

    clicked = pyqtSignal(object)

    def __init__(
        self,
        text: str,
        kind: str = "ok",
        payload: Any = None,
        parent: Optional[QWidget] = None,
    ) -> None:
        super().__init__(parent)
        self._text = text
        self._kind = kind
        self._payload = payload
        self._alpha = 1.0
        self._fading = False
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, False)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        s = ui_scale()
        self.setFont(_font(9.0 * s, True))
        fm = QFontMetrics(self.font())
        self._w = max(160, min(340, fm.horizontalAdvance(text) + 56))
        self._h = max(30, int(round(34 * s)))
        self.setFixedSize(self._w, self._h)

    def fade_out(self) -> None:
        self._fading = True

    @property
    def fading(self) -> bool:
        return self._fading

    @property
    def alpha(self) -> float:
        return self._alpha

    def set_alpha(self, a: float) -> None:
        self._alpha = max(0.0, min(1.0, a))
        self.setVisible(self._alpha > 0.02)
        self.update()

    def mousePressEvent(self, event) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton:
            self.clicked.emit(self._payload)
            event.accept()
            return
        super().mousePressEvent(event)

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        p.setOpacity(self._alpha)
        r = QRectF(self.rect()).adjusted(1.0, 1.0, -1.0, -1.0)
        tkey = resolve_theme_key(C.get("key", "seestation"))
        frame = _theme_frame_path(r, tkey, rad_see=8.0, ch_gold=6.0)
        grad = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        grad.setColorAt(0.0, QColor(C["btn_hov_hi"]))
        grad.setColorAt(1.0, QColor(C["btn_lo"]))
        p.setBrush(QBrush(grad))
        p.setPen(QPen(QColor(C["acc_hi"] if tkey == "seestation" else C["acc_mid"]), 1.25))
        p.drawPath(frame)
        kind_col = {"ok": C["ok"], "err": C["err"], "warn": C["warn"], "info": C["info"]}.get(self._kind, C["info"])
        p.save()
        p.setClipPath(frame)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QBrush(QColor(kind_col)))
        if tkey == "seestation":
            p.drawRoundedRect(QRectF(r.left() + 3, r.top() + 5, 3.2, r.height() - 10), 1.6, 1.6)
        elif tkey == "oriental":
            p.drawRect(QRectF(r.left(), r.top(), 4.0, r.height()))
            p.drawPolygon(QPolygonF([QPointF(r.right(), r.top()), QPointF(r.right() - 10, r.top()), QPointF(r.right(), r.top() + 10)]))
        else:
            p.drawRect(QRectF(r.left() + 2, r.top() + 6, 3.5, r.height() - 12))
        spec = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        glass = QColor(C["svg_glass"]); glass.setAlpha(28 if tkey == "seestation" else 18)
        spec.setColorAt(0.0, glass)
        glass2 = QColor(C["svg_glass"]); glass2.setAlpha(0)
        spec.setColorAt(1.0, glass2)
        p.setBrush(QBrush(spec))
        p.drawRect(QRectF(r.left() + 1, r.top() + 1, r.width() - 2, r.height() * 0.46))
        p.restore()
        icon_key = {"ok": "check", "err": "cross", "warn": "warning", "info": "info"}.get(self._kind, "info")
        p.drawPixmap(10, int((self._h - 16) / 2), VECTOR_ASSETS.pixmap(icon_key, 16, 16))
        p.setFont(_font(9.0 * ui_scale(), True))
        p.setPen(QColor(C["text_hi"]))
        text_r = QRectF(r.left() + 32, r.top(), r.width() - 36, r.height())
        p.drawText(text_r, Qt.AlignmentFlag.AlignVCenter, QFontMetrics(p.font()).elidedText(
            self._text, Qt.TextElideMode.ElideRight, int(text_r.width())))
        p.end()


class ToastOverlay(QWidget):
    """Corner toast stack manager (max 3 visible, auto-fade, click-to-act)."""

    def __init__(self, parent: QWidget) -> None:
        super().__init__(parent)
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self._toasts: List[Toast] = []
        self._births: Dict[int, float] = {}
        self._timer = QTimer(self)
        self._timer.setInterval(64)
        self._timer.timeout.connect(self._tick)
        self.hide()

    def notify(self, text: str, kind: str = "ok", payload: Any = None, on_click: Optional[Callable[[Any], None]] = None) -> None:
        while len(self._toasts) >= 3:
            old = self._toasts.pop(0)
            self._births.pop(id(old), None)
            old.deleteLater()
        toast = Toast(text, kind, payload, self)
        if on_click is not None:
            toast.clicked.connect(on_click)
        else:
            toast.clicked.connect(lambda _p: None)
        self._toasts.append(toast)
        self._births[id(toast)] = time.monotonic()
        toast.show()
        toast.raise_()
        self._reposition()
        if not self._timer.isActive():
            self._timer.start()

    def _reposition(self) -> None:
        host = self.parentWidget()
        if host is None:
            return
        y = host.height() - 10
        for toast in reversed(self._toasts):
            y -= toast.height() + 6
            tx = max(8, host.width() - toast.width() - 10)
            toast.move(tx, max(8, y))
        if self._toasts:
            self.resize(host.size())
            self.show()
            self.raise_()

    def _tick(self) -> None:
        now = time.monotonic()
        alive: List[Toast] = []
        for toast in self._toasts:
            tid_t = id(toast)
            if tid_t not in self._births:
                self._births[tid_t] = now
            age = now - self._births[tid_t]
            if age > 3.6 and not toast.fading:
                toast.fade_out()
            if toast.fading:
                toast.set_alpha(toast.alpha - 0.12)
            if toast.alpha > 0.02:
                alive.append(toast)
            else:
                self._births.pop(tid_t, None)
                toast.deleteLater()
        self._toasts = alive
        if not self._toasts:
            self._timer.stop()
            self.hide()
        else:
            self._reposition()

    def resizeEvent(self, event) -> None:  # noqa: N802
        super().resizeEvent(event)
        self._reposition()


# =============================================================================
#  16. Corporate East-Asian GENERATE Ignition Button (v10.0 Zero-Glitch Engine)
#      - Single monotonic animation driver (~30 FPS ONLY during transitions;
#        strictly 0% CPU when idle, hidden, minimized, or unfocused).
#      - Smooth cubic ease-in-out beveled specular shimmer with sinusoidal
#        edge fade-in/out and 1.8s hover cooldown (eliminates rapid-repeat bug).
#      - Fully distinct Sony/SCE SeeStation, Sarif Gold, and Oriental Spirit
#        (pure neutral black + exact pure red) craftsmanship.
# =============================================================================
class IgnitionGenerateButton(QPushButton):
    """Flagship East-Asian 'ENGAGE / SORTIE' style Generate CTA button."""

    _SHEEN_DURATION = 0.92      # seconds for one smooth specular glide
    _IDLE_CADENCE_MS = 7800     # calm ambient shimmer cadence when active
    _HOVER_COOLDOWN = 1.85      # minimum seconds between hover sheen triggers
    _GLOW_DURATION = 0.20       # smooth hover corona fade time

    def __init__(self, text: str = "GENERATE", parent: Optional[QWidget] = None) -> None:
        super().__init__(text, parent)
        self._ui_scale: float = 1.0
        self._compact_mode: bool = False
        self._sub_text: str = "KREA 2  \u2022  \u00d71  \u2022  1024\u00d71024"
        self._active_badge: str = ""
        self._in_flight: int = 0

        # Smooth monotonic animation state (single driver timer, ZERO timer leaks!)
        self._hovered: bool = False
        self._hover_glow: float = 0.0
        self._glow_start_val: float = 0.0
        self._glow_target: float = 0.0
        self._glow_t0: float = 0.0
        self._glow_animating: bool = False

        self._sheen_active: bool = False
        self._sheen_t0: float = 0.0
        self._sheen_progress: float = -1.0   # 0.0..1.0 while sweeping, <0 at rest
        self._last_sheen_trigger: float = 0.0

        self.setMinimumHeight(46)
        self.setMaximumHeight(52)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.setCursor(Qt.CursorShape.PointingHandCursor)

        # Single lightweight frame driver: ONLY runs while sheen or hover glow is moving
        self._anim_timer = QTimer(self)
        self._anim_timer.setInterval(33)  # ~30 FPS capped, zero CPU when stopped
        self._anim_timer.timeout.connect(self._tick_animation)

        # Single calm idle ambient shimmer timer
        self._idle_timer = QTimer(self)
        self._idle_timer.setInterval(self._IDLE_CADENCE_MS)
        self._idle_timer.timeout.connect(self._on_idle_cadence)
        self._idle_timer.start()

    def apply_metrics(self, scale: float, compact: bool = False) -> None:
        """Update button height & font metrics cleanly WITHOUT touching live state or timers."""
        self._ui_scale = max(SCALE_MIN, min(SCALE_MAX, float(scale)))
        self._compact_mode = bool(compact)
        base_h = 40 if self._compact_mode else 48
        h = max(36, min(74, int(round(base_h * self._ui_scale))))
        if self.minimumHeight() != h or self.maximumHeight() != h:
            self.setMinimumHeight(h)
            self.setMaximumHeight(h)
        self.update()

    def stop_animations(self) -> None:
        """Stop all timers immediately (called on hide/shutdown)."""
        self._anim_timer.stop()
        self._idle_timer.stop()
        self._sheen_active = False
        self._sheen_progress = -1.0
        self._glow_animating = False

    def set_sub_info(self, sub_text: str, active_badge: str = "") -> None:
        if sub_text != self._sub_text or active_badge != self._active_badge:
            self._sub_text = sub_text
            self._active_badge = active_badge
            self.update()

    def set_in_flight(self, count: int) -> None:
        count = max(0, int(count))
        if count != self._in_flight:
            self._in_flight = count
            self.update()

    def _can_animate(self) -> bool:
        if not self.isVisible() or not self.isEnabled():
            return False
        win = self.window()
        if win is not None and (win.isMinimized() or not win.isActiveWindow()):
            return False
        return True

    def _on_idle_cadence(self) -> None:
        if self._sheen_active or self.isDown() or not self._can_animate():
            return
        now = time.monotonic()
        if now - self._last_sheen_trigger < self._HOVER_COOLDOWN:
            return
        self._start_sheen(now)

    def _start_sheen(self, now: Optional[float] = None) -> None:
        ts = time.monotonic() if now is None else now
        self._sheen_active = True
        self._sheen_t0 = ts
        self._sheen_progress = 0.0
        self._last_sheen_trigger = ts
        if not self._anim_timer.isActive():
            self._anim_timer.start()

    def _start_glow(self, target: float) -> None:
        self._glow_start_val = self._hover_glow
        self._glow_target = max(0.0, min(1.0, float(target)))
        self._glow_t0 = time.monotonic()
        self._glow_animating = abs(self._glow_target - self._glow_start_val) > 0.005
        if self._glow_animating and not self._anim_timer.isActive():
            self._anim_timer.start()

    def _tick_animation(self) -> None:
        if not self.isVisible():
            self._sheen_active = False
            self._sheen_progress = -1.0
            self._glow_animating = False
            self._anim_timer.stop()
            return
        now = time.monotonic()
        still_running = False

        if self._sheen_active:
            u = (now - self._sheen_t0) / self._SHEEN_DURATION
            if u >= 1.0:
                self._sheen_active = False
                self._sheen_progress = -1.0
            else:
                # Smoothstep cubic ease-in-out: serene acceleration & deceleration
                self._sheen_progress = max(0.0, min(1.0, u))
                still_running = True

        if self._glow_animating:
            g_u = (now - self._glow_t0) / self._GLOW_DURATION
            if g_u >= 1.0:
                self._hover_glow = self._glow_target
                self._glow_animating = False
            else:
                eased = 1.0 - (1.0 - g_u) * (1.0 - g_u)
                self._hover_glow = self._glow_start_val + (self._glow_target - self._glow_start_val) * eased
                still_running = True

        self.update()
        if not still_running:
            self._anim_timer.stop()

    def showEvent(self, event) -> None:  # noqa: N802
        super().showEvent(event)
        if not self._idle_timer.isActive():
            self._idle_timer.start()

    def hideEvent(self, event) -> None:  # noqa: N802
        self._anim_timer.stop()
        self._idle_timer.stop()
        self._sheen_active = False
        self._sheen_progress = -1.0
        self._glow_animating = False
        super().hideEvent(event)

    def enterEvent(self, event) -> None:  # noqa: N802
        self._hovered = True
        self._start_glow(1.0)
        now = time.monotonic()
        if not self._sheen_active and (now - self._last_sheen_trigger) >= self._HOVER_COOLDOWN and self._can_animate():
            self._start_sheen(now)
        super().enterEvent(event)

    def leaveEvent(self, event) -> None:  # noqa: N802
        self._hovered = False
        self._start_glow(0.0)
        super().leaveEvent(event)

    def mousePressEvent(self, event) -> None:  # noqa: N802
        self.update()
        super().mousePressEvent(event)

    def mouseReleaseEvent(self, event) -> None:  # noqa: N802
        self.update()
        super().mouseReleaseEvent(event)

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)

        pressed = self.isDown()
        enabled = self.isEnabled()
        r = QRectF(self.rect()).adjusted(1.5, 1.5, -1.5, -1.5)
        if pressed:
            r.translate(0.0, 1.0)

        tkey = resolve_theme_key(C.get("key", "seestation"))
        bezel_path = QPainterPath()
        if tkey == "seestation":
            ch = 8.5
            bezel_path.addRoundedRect(r, 8.5, 8.5)
        elif tkey == "oriental":
            ch = 0.0
            bezel_path.addRect(r)
        else:
            ch = 7.0
            bezel_path = _chamfer_path(r, ch)

        # 1. Restrained hover corona glow (zero jitter, smooth ease-out)
        if enabled and self._hover_glow > 0.02 and not pressed:
            glow_outer = QColor(C["acc_glow"])
            glow_outer.setAlpha(int(36 * self._hover_glow))
            p.setPen(QPen(glow_outer, 4.4))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(bezel_path)
            glow_inner = QColor(C["acc_glow"])
            glow_inner.setAlpha(int(84 * self._hover_glow))
            p.setPen(QPen(glow_inner, 1.8))
            p.drawPath(bezel_path)

        # 2. Multi-stop luminous lacquer body fill
        grad = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        if not enabled:
            grad.setColorAt(0.0, QColor(C["btn_mid"]))
            grad.setColorAt(1.0, QColor(C["btn_lo"]))
        elif pressed:
            grad.setColorAt(0.0, QColor(C["acc_deep"]))
            grad.setColorAt(0.45, QColor(C["acc_lo"]))
            grad.setColorAt(1.0, QColor(C["acc_mid"]))
        elif self._hover_glow > 0.05:
            # Smoothly blend hover brightness
            grad.setColorAt(0.0, QColor(C["acc_hov_hi"]))
            grad.setColorAt(0.44, QColor(C["acc_hov_mid"]))
            grad.setColorAt(0.54, QColor(C["acc_mid"]))
            grad.setColorAt(1.0, QColor(C["acc_lo"]))
        else:
            grad.setColorAt(0.0, QColor(C["acc_hi"]))
            grad.setColorAt(0.46, QColor(C["acc_mid"]))
            grad.setColorAt(0.54, QColor(C["acc_lo"]))
            grad.setColorAt(1.0, QColor(C["acc_deep"]))

        border_col = QColor(C["acc_edge"] if (self._hovered and enabled) else C["acc_edge_lo"])
        p.setBrush(QBrush(grad))
        p.setPen(QPen(border_col, 1.35))
        p.drawPath(bezel_path)

        # Clip internal specular, watermark, and sheen layers strictly inside bezel
        p.save()
        p.setClipPath(bezel_path)

        # 3. Sculpted upper lacquer glass reflection band
        if not pressed and enabled:
            spec_rect = QRectF(r.left() + 1.0, r.top() + 1.0, r.width() - 2.0, r.height() * 0.45)
            sg = QLinearGradient(spec_rect.left(), spec_rect.top(), spec_rect.left(), spec_rect.bottom())
            sg.setColorAt(0.0, QColor(255, 255, 255, int(92 + 34 * self._hover_glow)))
            sg.setColorAt(0.68, QColor(255, 255, 255, 18))
            sg.setColorAt(1.0, QColor(255, 255, 255, 0))
            p.setBrush(QBrush(sg))
            p.setPen(Qt.PenStyle.NoPen)
            p.drawRect(spec_rect)

        # 4. Subtle lower ambient bounce light
        bounce_rect = QRectF(r.left(), r.bottom() - 9.0, r.width(), 9.0)
        bg = QLinearGradient(0, bounce_rect.top(), 0, bounce_rect.bottom())
        bcol0 = QColor(C["acc_spec"]); bcol0.setAlpha(0)
        bcol1 = QColor(C["acc_spec"]); bcol1.setAlpha(int(48 + 38 * self._hover_glow))
        bg.setColorAt(0.0, bcol0)
        bg.setColorAt(1.0, bcol1)
        p.setBrush(QBrush(bg))
        p.setPen(Qt.PenStyle.NoPen)
        p.drawRect(bounce_rect)

        # 5. Theme-specific architectural craftsmanship inside plate
        if tkey == "seestation":
            wpath = QPainterPath()
            wpath.moveTo(r.left() - 6, r.bottom() - 7)
            wpath.cubicTo(
                r.left() + r.width() * 0.34, r.top() + 10,
                r.left() + r.width() * 0.68, r.bottom() - 4,
                r.right() + 6, r.top() + 13,
            )
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(QColor(220, 245, 255, int(34 + 22 * self._hover_glow)), 1.5))
            p.drawPath(wpath)
        elif tkey == "oriental":
            # Oriental Spirit: crisp pure jet-black lacquer left/right torii pillar edges
            # & warm-neutral ivory-red specular accents (G >= B, ZERO purple/pink cast!)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(0, 0, 0, 210))
            p.drawRect(QRectF(r.left(), r.top(), 4.0, r.height()))
            p.drawRect(QRectF(r.right() - 4.0, r.top(), 4.0, r.height()))
            p.setBrush(QColor(255, 232, 224, int(52 + 30 * self._hover_glow)))
            p.drawPolygon(QPolygonF([QPointF(r.left() + 4, r.top()), QPointF(r.left() + 16, r.top()), QPointF(r.left() + 4, r.top() + 12)]))
            p.drawPolygon(QPolygonF([QPointF(r.right() - 4, r.bottom()), QPointF(r.right() - 16, r.bottom()), QPointF(r.right() - 4, r.bottom() - 12)]))
            p.setPen(QPen(QColor(255, 220, 212, 34), 1.0))
            p.drawLine(QPointF(r.right() - 42, r.top()), QPointF(r.right() - 22, r.bottom()))
        else:
            # Sarif Gold: subtle isometric chamfer micro-facets
            p.setPen(QPen(QColor(255, 242, 180, 26), 0.7))
            step_g = 18.0
            gx = r.left()
            while gx < r.right() + r.height():
                p.drawLine(QPointF(gx, r.top()), QPointF(gx - r.height() * 0.55, r.bottom()))
                gx += step_g

        # 6. Harmonious Monotonic Dual-Layer Specular Sheen (eased position + sinusoidal alpha!)
        if enabled and not pressed and 0.0 <= self._sheen_progress <= 1.0:
            u = self._sheen_progress
            eased = u * u * (3.0 - 2.0 * u)
            env = math.sin(math.pi * u)  # 0 at both ends -> smooth fade-in & fade-out
            span_w = r.width() + 90.0
            sx = r.left() - 45.0 + span_w * eased
            slant = r.height() * 0.42
            # Wide soft ambient glide
            wide_half = 30.0
            sh_wide = QLinearGradient(sx - wide_half, r.top(), sx + wide_half, r.top())
            a_wide = int(68 * env)
            sh_wide.setColorAt(0.0, QColor(255, 255, 255, 0))
            sh_wide.setColorAt(0.5, QColor(255, 255, 255, a_wide))
            sh_wide.setColorAt(1.0, QColor(255, 255, 255, 0))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(sh_wide))
            p.drawPolygon(QPolygonF([
                QPointF(sx - wide_half + slant * 0.5, r.top()),
                QPointF(sx + wide_half + slant * 0.5, r.top()),
                QPointF(sx + wide_half - slant * 0.5, r.bottom()),
                QPointF(sx - wide_half - slant * 0.5, r.bottom()),
            ]))
            # Crisp narrow specular blade edge
            thin_half = 8.0
            sh_thin = QLinearGradient(sx - thin_half, r.top(), sx + thin_half, r.top())
            a_thin = int(96 * env)
            sh_thin.setColorAt(0.0, QColor(255, 255, 255, 0))
            sh_thin.setColorAt(0.5, QColor(255, 255, 255, a_thin))
            sh_thin.setColorAt(1.0, QColor(255, 255, 255, 0))
            p.setBrush(QBrush(sh_thin))
            p.drawPolygon(QPolygonF([
                QPointF(sx - thin_half + slant * 0.5, r.top()),
                QPointF(sx + thin_half + slant * 0.5, r.top()),
                QPointF(sx + thin_half - slant * 0.5, r.bottom()),
                QPointF(sx - thin_half - slant * 0.5, r.bottom()),
            ]))

        # 7. Top catch-light hairline
        p.setPen(QPen(QColor(255, 255, 255, int(112 + 54 * self._hover_glow)), 1.0))
        p.drawLine(QPointF(r.left() + max(2.0, ch), r.top() + 1.2), QPointF(r.right() - max(2.0, ch), r.top() + 1.2))
        p.restore()

        # 8. Signature outer trim accents
        if tkey == "seestation":
            p.setPen(QPen(QColor(C["acc_spec"]), 1.4))
            uw = min(46.0, r.width() * 0.20)
            p.drawLine(QPointF(r.left() + 10, r.bottom() - 3.2), QPointF(r.left() + 10 + uw, r.bottom() - 3.2))
        elif tkey == "oriental":
            p.setPen(QPen(QColor(C["acc_spec"]), 1.3))
            p.drawLine(QPointF(r.left() + 4.5, r.top() + 1.2), QPointF(r.right() - 4.5, r.top() + 1.2))
        else:
            p.setPen(QPen(QColor(C["acc_spec"]), 1.5))
            p.drawLine(QPointF(r.left() + 2, r.top() + ch + 5), QPointF(r.left() + 2, r.top() + ch))
            p.drawLine(QPointF(r.left() + 2, r.top() + ch), QPointF(r.left() + ch, r.top() + 2))
            p.drawLine(QPointF(r.right() - 2, r.bottom() - ch - 5), QPointF(r.right() - 2, r.bottom() - ch))
            p.drawLine(QPointF(r.right() - 2, r.bottom() - ch), QPointF(r.right() - ch, r.bottom() - 2))

        # 9. Ignition Vector Emblem + Responsive Typography + In-Flight / Hotkey Pill
        bh = max(34.0, r.height())
        icon_sz = max(20, min(30, int(round(bh * 0.56))))
        pm = VECTOR_ASSETS.pixmap("generate_core", icon_sz, icon_sz)
        icon_x = int(r.left() + (11 if tkey == "oriental" else 9))
        icon_y = int(r.center().y() - icon_sz / 2)
        p.drawPixmap(icon_x, icon_y, pm)

        txt_left = icon_x + icon_sz + 8
        badge_w = 0
        if self._in_flight > 0:
            badge_txt = f"{self._in_flight} LIVE" if r.width() < 280 else f"{self._in_flight} ACTIVE"
            p.setFont(_font(7.2 * self._ui_scale, True, 0.5))
            fm_b = QFontMetrics(p.font())
            badge_w = fm_b.horizontalAdvance(badge_txt) + 14
            bx = int(r.right() - badge_w - (9 if tkey == "oriental" else 7))
            by = int(r.center().y() - 8)
            badge_r = QRectF(bx, by, badge_w, 16)
            p.setBrush(QColor(0, 0, 0, 195))
            p.setPen(QPen(QColor(C["acc_spec"]), 1.0))
            p.drawPath(_theme_frame_path(badge_r, tkey, rad_see=4.5, ch_gold=3.0))
            p.setPen(QColor(C["acc_spec"]))
            p.drawText(badge_r, Qt.AlignmentFlag.AlignCenter, badge_txt)
        elif r.width() >= 255:
            hint_txt = "CTRL+\u21B5"
            p.setFont(_font(6.8 * self._ui_scale, True, 0.4))
            fm_h = QFontMetrics(p.font())
            badge_w = fm_h.horizontalAdvance(hint_txt) + 10
            bx = int(r.right() - badge_w - (9 if tkey == "oriental" else 7))
            by = int(r.center().y() - 7)
            badge_r = QRectF(bx, by, badge_w, 15)
            p.setBrush(QColor(0, 0, 0, 95))
            p.setPen(QPen(QColor(255, 255, 255, 72), 0.9))
            p.drawPath(_theme_frame_path(badge_r, tkey, rad_see=4.0, ch_gold=2.5))
            hc = QColor(C["acc_text"]); hc.setAlpha(200)
            p.setPen(hc)
            p.drawText(badge_r, Qt.AlignmentFlag.AlignCenter, hint_txt)

        right_pad = 10 + (badge_w + 6 if badge_w > 0 else 0)
        txt_w = max(24, int(r.right() - txt_left - right_pad))
        title_h = int(round(bh * 0.54))
        sub_h = max(12, int(bh) - title_h - 4)
        title_rect = QRect(txt_left, int(r.top() + 2), txt_w, title_h)
        sub_rect = QRect(txt_left, int(r.top() + title_h - 1), txt_w, sub_h)

        title_pt = max(9.4, min(14.0, (10.5 if self._compact_mode else 11.8) * self._ui_scale))
        title_font = _font(title_pt, True, 1.8)
        p.setFont(title_font)
        if tkey == "oriental":
            shadow_col = QColor(0, 0, 0, 175)
        elif tkey == "seestation":
            shadow_col = QColor(3, 10, 22, 175)
        else:
            shadow_col = QColor(255, 246, 200, 100)
        title_el = QFontMetrics(title_font).elidedText(self.text().upper(), Qt.TextElideMode.ElideRight, title_rect.width())
        p.setPen(shadow_col)
        p.drawText(title_rect.translated(0, 1), Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter, title_el)
        p.setPen(QColor(C["acc_text"] if enabled else C["dim"]))
        p.drawText(title_rect, Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter, title_el)

        sub_font = _font(max(6.8, 7.6 * self._ui_scale), True, 0.5)
        p.setFont(sub_font)
        sub_col = QColor(C["acc_text"] if enabled else C["dim"])
        sub_col.setAlpha(215)
        p.setPen(sub_col)
        sub_txt = self._active_badge if self._active_badge else self._sub_text
        sub_el = QFontMetrics(sub_font).elidedText(sub_txt, Qt.TextElideMode.ElideRight, sub_rect.width())
        p.drawText(sub_rect, Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter, sub_el)
        p.end()


# =============================================================================
#  17. Unique Prompt Editor: Ctrl+Hold Tag Block Selection & Drag-and-Drop
# =============================================================================
class TagFlowPromptEdit(QPlainTextEdit):
    """Enhanced prompt / negative editor with Ctrl+Hold Tag-Element Drag-and-Drop:
    - Hold Ctrl to work with comma- and sentence-period-separated elements as
      discrete tactile blocks (single words, weighted tags, or full sentences).
    - Ctrl+Click toggles/selects individual tags; Ctrl+Shift+Click selects a
      range; dragging inside a normal text selection lifts all intersecting tags.
    - Dragging renders a floating translucent ghost badge and snaps a glowing
      insertion beacon between elements. Drop reorders atomically in one undo step.
    - Also accepts drag-and-drop from Tags tab and LoRA trigger chips, and offers
      a pro right-click tag context menu.
    - v3.1 GHOST ZONE: the trailing LoRA trigger words live in a read-only,
      greyed-out "ghost" tail of the document. They are rendered dim/italic,
      cannot be edited, selected, deleted or dragged, and are excluded from
      toPlainText() — the app appends them to the real payload automatically.
    """

    tags_reordered = pyqtSignal()
    save_as_tag_group_requested = pyqtSignal(str)
    external_drop_received = pyqtSignal(str, str, str)  # text, color, kind
    ghost_changed = pyqtSignal(str)                    # current ghost text

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setMouseTracking(True)
        self.viewport().setMouseTracking(True)
        self.setAcceptDrops(True)
        self.setWordWrapMode(QTextOption.WrapMode.WrapAtWordBoundaryOrAnywhere)
        self._ctrl_mode = False
        self._elements: List[PromptElement] = []
        self._hover_idx: int = -1
        self._selected_indices: Set[int] = set()
        self._anchor_idx: int = -1
        self._dragging = False
        self._press_pos: Optional[QPoint] = None
        self._drag_pos: Optional[QPoint] = None
        self._drag_indices: List[int] = []
        self._drop_slot: int = -1
        self._flash_ranges: List[Tuple[int, int]] = []
        self._pending_toggle_idx: int = -1
        # ---- LoRA trigger ghost zone (read-only tail of the document) ----
        self._ghost_text: str = ""
        self._ghost_start: int = 0          # document position where the ghost begins
        self._ghost_updating: bool = False  # re-entrancy guard
        self._flash_timer = QTimer(self)
        self._flash_timer.setSingleShot(True)
        self._flash_timer.setInterval(480)
        self._flash_timer.timeout.connect(self._clear_flash)
        self.textChanged.connect(self._on_text_mutated)

    # ---- Ghost zone public API ---------------------------------------------
    def _full_text(self) -> str:
        """Raw document text INCLUDING the ghost zone."""
        return QPlainTextEdit.toPlainText(self)

    def _ghost_part(self) -> str:
        """Exact document tail occupied by the ghost (separator + text)."""
        if not self._ghost_text:
            return ""
        editable = self._full_text()[: self._ghost_start] if self._ghost_start >= 0 else ""
        sep = "\n" if editable else ""
        return sep + self._ghost_text

    def ghost_range(self) -> Tuple[int, int]:
        """(start, end) document positions of the ghost zone (end==start when none)."""
        if not self._ghost_text:
            return (self._ghost_start, self._ghost_start)
        part = self._ghost_part()
        return (self._ghost_start, self._ghost_start + len(part))

    def editable_end(self) -> int:
        """First document position owned by the ghost (== end of editable text)."""
        return self._ghost_start if self._ghost_text else len(self._full_text())

    def editable_text(self) -> str:
        return self._full_text()[: self.editable_end()]

    def set_ghost(self, text: str) -> None:
        """Replace the read-only ghost tail (LoRA triggers) without touching the
        editable part, the caret or the span book."""
        new_ghost = " ".join(str(text or "").split())
        if new_ghost == self._ghost_text:
            return
        self._ghost_text = new_ghost
        self._apply_ghost()

    def _apply_ghost(self) -> None:
        self._ghost_updating = True
        try:
            editable = self._full_text()[: self._ghost_start] if (self._ghost_text and self._ghost_start >= 0) else self._full_text()
            if not self._ghost_text:
                editable = self._full_text()
            sep = "\n" if (editable and self._ghost_text) else ""
            full = editable + sep + self._ghost_text
            cur = self.textCursor()
            keep = min(cur.position(), len(editable))
            keep_anchor = min(cur.anchor(), len(editable))
            tc = QTextCursor(self.document())
            tc.beginEditBlock()
            tc.select(QTextCursor.SelectionType.Document)
            tc.insertText(full)
            tc.endEditBlock()
            if cur.hasSelection() and keep_anchor != keep:
                cur.setPosition(keep_anchor)
                cur.setPosition(keep, QTextCursor.MoveMode.KeepAnchor)
            else:
                cur.setPosition(keep)
            self.setTextCursor(cur)
            # ghost_start points at the START of the separator so the editable
            # value never contains the trailing newline.
            self._ghost_start = len(editable)
        finally:
            self._ghost_updating = False
        self.ghost_changed.emit(self._ghost_text)
        self.viewport().update()

    def set_editable_text(self, text: str) -> None:
        """Replace ONLY the editable part; the ghost tail is preserved."""
        self._ghost_updating = True
        try:
            cur = self.textCursor()
            keep = min(cur.position(), len(text))
            sep = "\n" if (text and self._ghost_text) else ""
            full = text + sep + self._ghost_text
            tc = QTextCursor(self.document())
            tc.beginEditBlock()
            tc.select(QTextCursor.SelectionType.Document)
            tc.insertText(full)
            tc.endEditBlock()
            cur.setPosition(keep)
            self.setTextCursor(cur)
            self._ghost_start = len(text)
        finally:
            self._ghost_updating = False
        self.ghost_changed.emit(self._ghost_text)

    # ---- Qt overrides: the ghost tail is invisible to callers & untouchable --
    def toPlainText(self) -> str:  # noqa: N802 - Python-side override
        """Editable text only — the ghost tail is NEVER part of the prompt value."""
        if self._ghost_text:
            return self._full_text()[: self._ghost_start]
        return self._full_text()

    def setPlainText(self, text: str) -> None:  # noqa: N802
        self.set_editable_text(text)

    def clear(self) -> None:  # noqa: N802
        self.set_editable_text("")

    def selectAll(self) -> None:  # noqa: N802
        tc = self.textCursor()
        tc.setPosition(0)
        tc.setPosition(self.editable_end(), QTextCursor.MoveMode.KeepAnchor)
        self.setTextCursor(tc)

    def insertFromMimeData(self, source) -> None:  # noqa: N802
        self._clamp_cursor()
        super().insertFromMimeData(source)

    def _clamp_cursor(self) -> None:
        """Keep the caret & selection out of the ghost zone."""
        if not self._ghost_text:
            return
        limit = self.editable_end()
        tc = self.textCursor()
        changed = False
        if tc.position() > limit or tc.anchor() > limit:
            changed = True
            if tc.hasSelection():
                a0 = min(tc.anchor(), tc.position())
                a1 = max(tc.anchor(), tc.position())
                n0 = min(a0, limit)
                n1 = min(a1, limit)
                if n1 > n0:
                    tc.setPosition(n0)
                    tc.setPosition(n1, QTextCursor.MoveMode.KeepAnchor)
                else:
                    tc.setPosition(limit)
            else:
                tc.setPosition(limit)
        if changed:
            self.setTextCursor(tc)

    def _on_text_mutated(self) -> None:
        # Ghost-zone integrity: typing at the editable/ghost boundary legitimately
        # shifts the ghost; real damage (should be impossible through the guarded
        # UI paths) triggers a full tail rebuild.
        if self._ghost_text and not self._ghost_updating:
            full = self._full_text()
            gt = self._ghost_text
            if full.endswith(gt):
                new_start = len(full) - len(gt)
                if new_start > 0 and full[new_start - 1] == "\n":
                    new_start -= 1
                self._ghost_start = max(0, new_start)
            else:
                self._ghost_updating = True
                try:
                    editable = full[: self._ghost_start]
                    sep = "\n" if editable else ""
                    tc = QTextCursor(self.document())
                    tc.beginEditBlock()
                    tc.select(QTextCursor.SelectionType.Document)
                    tc.insertText(editable + sep + gt)
                    tc.endEditBlock()
                    self._ghost_start = len(editable)
                finally:
                    self._ghost_updating = False
                self.ghost_changed.emit(gt)
        self._elements = parse_prompt_elements(self.toPlainText())
        if not self._dragging:
            self._selected_indices = {i for i in self._selected_indices if 0 <= i < len(self._elements)}
            if self._hover_idx >= len(self._elements):
                self._hover_idx = -1

    def _clear_flash(self) -> None:
        self._flash_ranges = []
        self.viewport().update()

    def _is_ctrl_held(self) -> bool:
        return bool(QApplication.keyboardModifiers() & Qt.KeyboardModifier.ControlModifier)

    def _sync_ctrl_mode(self, active: bool) -> None:
        if active == self._ctrl_mode:
            return
        self._ctrl_mode = active
        if active:
            self._elements = parse_prompt_elements(self.toPlainText())
            self._promote_text_selection_to_tags()
            self.viewport().setCursor(Qt.CursorShape.OpenHandCursor)
        else:
            if not self._dragging:
                self._hover_idx = -1
                self._drop_slot = -1
                self.viewport().setCursor(Qt.CursorShape.IBeamCursor)
        self.viewport().update()

    def _promote_text_selection_to_tags(self) -> None:
        """If the user highlighted a range of text covering one or more tags
        before pressing Ctrl, automatically select all intersecting tag blocks."""
        tc = self.textCursor()
        if not tc.hasSelection():
            return
        s0, s1 = tc.selectionStart(), tc.selectionEnd()
        found = {el.index for el in self._elements if not (el.end <= s0 or el.start >= s1)}
        if found:
            self._selected_indices = found
            self._anchor_idx = min(found)

    def _element_at_pos(self, pos: QPoint) -> int:
        if not self._elements:
            return -1
        cur = self.cursorForPosition(pos)
        cpos = cur.position()
        for el in self._elements:
            if el.start <= cpos <= el.end:
                return el.index
        # Soft tolerance: within 2 chars of an element boundary (e.g. clicking on comma/space)
        best_i, best_d = -1, 4
        for el in self._elements:
            d = min(abs(cpos - el.start), abs(cpos - el.end))
            if d < best_d:
                best_d = d
                best_i = el.index
        return best_i

    def _slot_at_pos(self, pos: QPoint) -> int:
        if not self._elements:
            return 0
        cur = self.cursorForPosition(pos)
        cpos = cur.position()
        for el in self._elements:
            mid = (el.start + el.end) / 2.0
            if cpos < mid:
                return el.index
        return len(self._elements)

    def _rects_for_range(self, start: int, end: int) -> List[QRect]:
        """Compute visual viewport rectangles for a character span (handles wrapping)."""
        doc_len = len(self._full_text())
        if start >= end or start < 0 or end > doc_len:
            return []
        rects: List[QRect] = []
        tc = self.textCursor()
        cur_p = start
        while cur_p < end:
            tc.setPosition(cur_p)
            r0 = self.cursorRect(tc)
            # Walk to end of current visual line or end of span
            line_end = cur_p + 1
            last_r = r0
            while line_end <= end:
                tc.setPosition(line_end)
                rn = self.cursorRect(tc)
                if abs(rn.top() - r0.top()) > 4:
                    break
                last_r = rn
                line_end += 1
            x1 = min(r0.left(), last_r.left())
            x2 = max(r0.right(), last_r.right())
            if x2 - x1 < 4:
                x2 = x1 + 6
            rects.append(QRect(x1 - 2, r0.top() - 1, (x2 - x1) + 4, r0.height() + 2))
            cur_p = line_end
            if line_end <= start:
                break
        return rects

    # ---- Keyboard events ----------------------------------------------------
    def keyPressEvent(self, event: QKeyEvent) -> None:  # noqa: N802
        if event.key() == Qt.Key.Key_Control:
            self._sync_ctrl_mode(True)
        elif event.key() == Qt.Key.Key_Escape and (self._dragging or self._selected_indices):
            self._cancel_drag()
            self._selected_indices.clear()
            self.viewport().update()
            event.accept()
            return
        elif self._ghost_text and event.key() in (
            Qt.Key.Key_Delete, Qt.Key.Key_Backspace,
            Qt.Key.Key_Return, Qt.Key.Key_Enter,
        ) and not self._ctrl_mode:
            # Swallow edits that would eat the locked ghost tail:
            #  - Delete/Backspace with a selection reaching into the ghost
            #  - newline typed while the caret sits inside the ghost
            tc = self.textCursor()
            limit = self.editable_end()
            if tc.hasSelection() and max(tc.anchor(), tc.position()) > limit:
                event.accept()
                return
            if tc.position() > limit and not tc.hasSelection():
                event.accept()
                return
            if event.key() == Qt.Key.Key_Delete and tc.position() == limit and not tc.hasSelection():
                event.accept()
                return
        if event.matches(QKeySequence.StandardKey.SelectAll):
            self.selectAll()
            event.accept()
            return
        self._clamp_cursor()
        super().keyPressEvent(event)
        # A typed character may land exactly at the boundary and is fine; but if
        # some path still moved the caret into the ghost, snap it back.
        if self._ghost_text:
            self._clamp_cursor()

    def keyReleaseEvent(self, event: QKeyEvent) -> None:  # noqa: N802
        if event.key() == Qt.Key.Key_Control and not self._dragging:
            self._sync_ctrl_mode(False)
        super().keyReleaseEvent(event)

    def leaveEvent(self, event) -> None:  # noqa: N802
        if not self._dragging:
            self._hover_idx = -1
            if not self._is_ctrl_held():
                self._sync_ctrl_mode(False)
            self.viewport().update()
        super().leaveEvent(event)

    # ---- Mouse events (Ctrl Tag-Element Selection & Drag-Reorder) -----------
    def mousePressEvent(self, event: QMouseEvent) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton and self._is_ctrl_held():
            self._sync_ctrl_mode(True)
            self._elements = parse_prompt_elements(self.toPlainText())
            self._promote_text_selection_to_tags()
            pos = event.position().toPoint()
            idx = self._element_at_pos(pos)
            if idx >= 0:
                self._press_pos = pos
                self._drag_pos = pos
                if event.modifiers() & Qt.KeyboardModifier.ShiftModifier and self._anchor_idx >= 0:
                    lo, hi = min(self._anchor_idx, idx), max(self._anchor_idx, idx)
                    self._selected_indices.update(range(lo, hi + 1))
                elif idx in self._selected_indices:
                    # Keep multi-selection intact in case the user is initiating a group drag;
                    # if released without dragging, mouseReleaseEvent will toggle it off.
                    self._pending_toggle_idx = idx
                else:
                    self._pending_toggle_idx = -1
                    self._selected_indices.add(idx)
                    self._anchor_idx = idx
                self._drag_indices = sorted(self._selected_indices)
                self.viewport().update()
                event.accept()
                return
            else:
                self._selected_indices.clear()
                self._anchor_idx = -1
                self.viewport().update()
                event.accept()
                return
        # Normal editing clears tag-block selection
        if self._selected_indices and not self._is_ctrl_held():
            self._selected_indices.clear()
            self.viewport().update()
        super().mousePressEvent(event)
        if self._ghost_text and not self._ctrl_mode:
            # Clicks that land inside the ghost zone snap the caret back to the
            # end of the editable text.
            self._clamp_cursor()

    def mouseDoubleClickEvent(self, event) -> None:  # noqa: N802
        super().mouseDoubleClickEvent(event)
        if self._ghost_text:
            self._clamp_cursor()

    def mouseMoveEvent(self, event: QMouseEvent) -> None:  # noqa: N802
        pos = event.position().toPoint()
        ctrl = self._is_ctrl_held()
        if not self._dragging:
            self._sync_ctrl_mode(ctrl)
        if self._press_pos is not None and (event.buttons() & Qt.MouseButton.LeftButton):
            if not self._dragging and (pos - self._press_pos).manhattanLength() >= 6:
                self._dragging = True
                self._pending_toggle_idx = -1
                self.viewport().setCursor(Qt.CursorShape.ClosedHandCursor)
            if self._dragging:
                self._drag_pos = pos
                self._drop_slot = self._slot_at_pos(pos)
                self.viewport().update()
                event.accept()
                return
        if self._ctrl_mode:
            self._elements = parse_prompt_elements(self.toPlainText())
            new_h = self._element_at_pos(pos)
            if new_h != self._hover_idx:
                self._hover_idx = new_h
                self.viewport().update()
            self.viewport().setCursor(
                Qt.CursorShape.OpenHandCursor if new_h >= 0 else Qt.CursorShape.ArrowCursor
            )
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event: QMouseEvent) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton and (self._dragging or self._press_pos is not None):
            was_dragging = self._dragging
            drop_slot = self._drop_slot
            drag_indices = list(self._drag_indices)
            pending_toggle = self._pending_toggle_idx
            self._cancel_drag()
            if was_dragging and drag_indices and drop_slot >= 0:
                self._commit_reorder(drag_indices, drop_slot)
            elif pending_toggle >= 0:
                self._selected_indices.discard(pending_toggle)
            if not self._is_ctrl_held():
                self._sync_ctrl_mode(False)
            self.viewport().update()
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def _cancel_drag(self) -> None:
        self._dragging = False
        self._press_pos = None
        self._drag_pos = None
        self._drag_indices = []
        self._drop_slot = -1
        self._pending_toggle_idx = -1
        self.viewport().setCursor(
            Qt.CursorShape.OpenHandCursor if self._is_ctrl_held() else Qt.CursorShape.IBeamCursor
        )

    def _commit_reorder(self, indices: List[int], target_slot: int) -> None:
        old_text = self.toPlainText()
        new_text, new_sel, ranges = reorder_prompt_elements(old_text, indices, target_slot)
        if new_text == old_text:
            return
        self.set_editable_text(new_text)
        self._elements = parse_prompt_elements(new_text)
        self._selected_indices = set(new_sel)
        self._flash_ranges = ranges
        self._flash_timer.start()
        self.tags_reordered.emit()
        self.viewport().update()

    # ---- External Drag-and-Drop (Tags tab / LoRA triggers) ------------------
    def dragEnterEvent(self, event) -> None:  # noqa: N802
        md = event.mimeData()
        if md.hasFormat("application/x-hsl-snippet") or md.hasText():
            event.acceptProposedAction()
            return
        super().dragEnterEvent(event)

    def dragMoveEvent(self, event) -> None:  # noqa: N802
        md = event.mimeData()
        if md.hasFormat("application/x-hsl-snippet") or md.hasText():
            event.acceptProposedAction()
            return
        super().dragMoveEvent(event)

    def dropEvent(self, event) -> None:  # noqa: N802
        md = event.mimeData()
        if md.hasFormat("application/x-hsl-snippet"):
            try:
                raw = bytes(md.data("application/x-hsl-snippet")).decode("utf-8")
                doc = json.loads(raw)
                txt = str(doc.get("text") or "").strip()
                col = str(doc.get("color") or C["acc_hi"])
                kind = str(doc.get("kind") or "tag")
                if txt:
                    self.external_drop_received.emit(txt, col, kind)
                    event.acceptProposedAction()
                    return
            except Exception:  # noqa: BLE001
                pass
        super().dropEvent(event)

    # ---- Pro Tag Context Menu -----------------------------------------------
    def contextMenuEvent(self, event) -> None:  # noqa: N802
        self._elements = parse_prompt_elements(self.toPlainText())
        self._promote_text_selection_to_tags()
        self._clamp_cursor()  # the standard Cut/Delete actions must never touch the ghost
        pos = event.pos()
        hit = self._element_at_pos(pos)
        menu = self.createStandardContextMenu()
        if hit >= 0 or self._selected_indices:
            target_set = sorted(self._selected_indices) if (self._selected_indices and (hit < 0 or hit in self._selected_indices)) else [hit]
            target_set = [i for i in target_set if 0 <= i < len(self._elements)]
            if target_set:
                label = f"{len(target_set)} tags" if len(target_set) > 1 else f"'{elide(self._elements[target_set[0]].text, 24)}'"
                menu.addSeparator()
                tag_menu = menu.addMenu(f"Tag Element ({label})")
                tag_menu.addAction("Move to Start", lambda: self._commit_reorder(target_set, 0))
                tag_menu.addAction("Move Left", lambda: self._commit_reorder(target_set, max(0, min(target_set) - 1)))
                tag_menu.addAction("Move Right", lambda: self._commit_reorder(target_set, min(len(self._elements), max(target_set) + 2)))
                tag_menu.addAction("Move to End", lambda: self._commit_reorder(target_set, len(self._elements)))
                tag_menu.addSeparator()
                tag_menu.addAction("Weight \u00d71.2  (SDXL/standard)", lambda: self._wrap_weight(target_set, 1.2))
                tag_menu.addAction("Weight \u00d71.8  (Anima strong)", lambda: self._wrap_weight(target_set, 1.8))
                tag_menu.addAction("Unwrap Weight", lambda: self._unwrap_weight(target_set))
                tag_menu.addSeparator()
                tag_menu.addAction("Duplicate Tag(s)", lambda: self._duplicate_tags(target_set))
                tag_menu.addAction("Delete Tag(s)", lambda: self._delete_tags(target_set))
                combined = ", ".join(self._elements[i].text for i in target_set)
                tag_menu.addAction("Save as Tag Group\u2026", lambda: self.save_as_tag_group_requested.emit(combined))
        menu.exec(event.globalPos())

    def _replace_element_texts(self, mapper: Callable[[PromptElement], Optional[str]]) -> None:
        elems = parse_prompt_elements(self.toPlainText())
        pieces: List[str] = []
        out_elems: List[Tuple[str, str]] = []
        for el in elems:
            res = mapper(el)
            if res is not None and res.strip():
                out_elems.append((res.strip(), el.sep))
        for pos, (txt, sep) in enumerate(out_elems):
            pieces.append(txt)
            if pos < len(out_elems) - 1:
                pieces.append(f"{sep if sep in (',', '.') else ','} ")
            elif sep == ".":
                pieces.append(".")
        new_text = "".join(pieces)
        self.set_editable_text(new_text)
        self._selected_indices.clear()
        self.tags_reordered.emit()

    def _wrap_weight(self, indices: List[int], weight: float) -> None:
        iset = set(indices)

        def _fn(el: PromptElement) -> str:
            if el.index not in iset:
                return el.text
            core = re.sub(r"^\((.+):[0-9.]+\)$", r"\1", el.text.strip())
            return f"({core}:{weight:g})"

        self._replace_element_texts(_fn)

    def _unwrap_weight(self, indices: List[int]) -> None:
        iset = set(indices)

        def _fn(el: PromptElement) -> str:
            if el.index not in iset:
                return el.text
            return re.sub(r"^\((.+):[0-9.]+\)$", r"\1", el.text.strip())

        self._replace_element_texts(_fn)

    def _duplicate_tags(self, indices: List[int]) -> None:
        elems = parse_prompt_elements(self.toPlainText())
        iset = set(indices)
        out: List[Tuple[str, str]] = []
        for el in elems:
            out.append((el.text, el.sep))
            if el.index in iset:
                out.append((el.text, el.sep))
        pieces: List[str] = []
        for pos, (txt, sep) in enumerate(out):
            pieces.append(txt)
            if pos < len(out) - 1:
                pieces.append(f"{sep if sep in (',', '.') else ','} ")
            elif sep == ".":
                pieces.append(".")
        self.set_editable_text("".join(pieces))
        self.tags_reordered.emit()

    def _delete_tags(self, indices: List[int]) -> None:
        iset = set(indices)
        self._replace_element_texts(lambda el: None if el.index in iset else el.text)

    # ---- Paint overlays: Tag Pill Frames, Insertion Beacon, Drag Ghost & HUD
    def paintEvent(self, event) -> None:  # noqa: N802
        super().paintEvent(event)
        p = QPainter(self.viewport())
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)

        # Ghost-zone marker: a small dim "LORA TRIGGERS · AUTO" badge drawn in
        # the FREE SPACE below the last document line (never overlaps text; when
        # the editor is completely full the badge simply doesn't draw).
        if self._ghost_text:
            try:
                tc = QTextCursor(self.document())
                tc.movePosition(QTextCursor.MoveOperation.End)
                br = self.cursorRect(tc)
                free_below = self.viewport().height() - br.bottom()
                if free_below >= 18:
                    p.setFont(_font(7.4, True))
                    fm = QFontMetrics(p.font())
                    lbl = "\u25A3 LORA TRIGGERS \u00b7 AUTO"
                    lw = fm.horizontalAdvance(lbl) + 12
                    chip = QRectF(
                        max(2.0, self.viewport().width() - lw - 6),
                        float(br.bottom() + 3),
                        lw,
                        13,
                    )
                    bg = QColor(C["deep"])
                    bg.setAlpha(215)
                    p.setBrush(QBrush(bg))
                    p.setPen(QPen(QColor(C["ghost"]), 0.8))
                    p.drawRoundedRect(chip, 2.0, 2.0)
                    p.setPen(QColor(C["ghost"]))
                    p.drawText(chip, Qt.AlignmentFlag.AlignCenter, lbl)
            except Exception:  # noqa: BLE001 - decoration must never break painting
                pass

        if not (self._ctrl_mode or self._selected_indices or self._dragging or self._flash_ranges):
            p.end()
            return

        # Brief drop confirmation glow
        for s0, s1 in self._flash_ranges:
            col = QColor(C["acc_hi"])
            col.setAlpha(68)
            p.setBrush(QBrush(col))
            p.setPen(QPen(QColor(C["acc_spec"]), 1.2))
            for rc in self._rects_for_range(s0, s1):
                p.drawRoundedRect(QRectF(rc), 3.0, 3.0)

        # Hover & multi-selected tag pill outlines while Ctrl is held or selection active
        if self._ctrl_mode or self._selected_indices:
            sel_order = sorted(self._selected_indices)
            for el in self._elements:
                is_sel = el.index in self._selected_indices
                is_hov = self._ctrl_mode and el.index == self._hover_idx
                if not (is_sel or is_hov):
                    continue
                rects = self._rects_for_range(el.start, el.end)
                bg = QColor(C["tag_sel_bg"] if is_sel else C["tag_hover_bg"])
                bg.setAlpha(115 if is_sel else 85)
                pen_col = QColor(C["tag_sel_border"] if is_sel else C["tag_hover_border"])
                p.setBrush(QBrush(bg))
                p.setPen(QPen(pen_col, 1.4 if is_sel else 1.1))
                for rc in rects:
                    p.drawRoundedRect(QRectF(rc), 3.0, 3.0)
                # Numbered multi-select chip when selecting multiple tags
                if is_sel and len(sel_order) > 1 and rects:
                    ord_num = str(sel_order.index(el.index) + 1)
                    badge = QRectF(rects[0].left() - 2, rects[0].top() - 7, 13, 12)
                    p.setBrush(QBrush(QColor(C["acc_hi"])))
                    p.setPen(Qt.PenStyle.NoPen)
                    p.drawRoundedRect(badge, 2.0, 2.0)
                    p.setFont(_font(7.0, True))
                    p.setPen(QColor(C["acc_text"]))
                    p.drawText(badge, Qt.AlignmentFlag.AlignCenter, ord_num)

        # Live glowing insertion beacon while dragging
        if self._dragging and self._drop_slot >= 0 and self._elements:
            tc = self.textCursor()
            if self._drop_slot < len(self._elements):
                tc.setPosition(self._elements[self._drop_slot].start)
                br = self.cursorRect(tc)
                bx = float(br.left() - 2)
            else:
                tc.setPosition(self._elements[-1].end)
                br = self.cursorRect(tc)
                bx = float(br.right() + 2)
            by0, by1 = float(br.top() - 2), float(br.bottom() + 2)
            beacon = QColor(C["beacon"])
            p.setPen(QPen(beacon, 2.6))
            p.drawLine(QPointF(bx, by0), QPointF(bx, by1))
            p.setBrush(QBrush(beacon))
            p.setPen(Qt.PenStyle.NoPen)
            for cy in (by0, by1):
                p.drawPolygon(QPolygonF([
                    QPointF(bx, cy - 3.5),
                    QPointF(bx + 3.5, cy),
                    QPointF(bx, cy + 3.5),
                    QPointF(bx - 3.5, cy),
                ]))

        # Floating translucent drag ghost badge tracking cursor
        if self._dragging and self._drag_pos is not None and self._drag_indices:
            valid = [self._elements[i].text for i in self._drag_indices if 0 <= i < len(self._elements)]
            if valid:
                lbl = (
                    f"[{len(valid)} TAGS] {elide(', '.join(valid), 30)}"
                    if len(valid) > 1
                    else elide(valid[0], 34)
                )
                p.setFont(_font(8.5, True))
                fm = QFontMetrics(p.font())
                gw = fm.horizontalAdvance(lbl) + 18
                gh = 22
                gx = max(4, min(self.viewport().width() - gw - 4, self._drag_pos.x() + 12))
                gy = max(4, min(self.viewport().height() - gh - 4, self._drag_pos.y() - 26))
                gr = QRectF(gx, gy, gw, gh)
                ggrad = QLinearGradient(gr.left(), gr.top(), gr.left(), gr.bottom())
                ggrad.setColorAt(0.0, QColor(C["acc_hi"]))
                ggrad.setColorAt(1.0, QColor(C["acc_lo"]))
                p.setBrush(QBrush(ggrad))
                p.setPen(QPen(QColor(C["acc_spec"]), 1.2))
                p.drawRoundedRect(gr, 3.0, 3.0)
                p.setPen(QColor(C["acc_text"]))
                p.drawText(gr, Qt.AlignmentFlag.AlignCenter, lbl)

        # Compact bottom-right Ctrl-Tag-Mode status HUD chip
        if self._ctrl_mode:
            hud = (
                f"CTRL TAG MODE \u2022 {len(self._selected_indices)} selected \u2022 Drag to reorder"
                if self._selected_indices
                else "CTRL TAG MODE \u2022 Click=Select \u2022 Drag=Reorder"
            )
            p.setFont(_font(7.6, True))
            fm = QFontMetrics(p.font())
            hw = fm.horizontalAdvance(hud) + 14
            hh = 17
            hr = QRectF(
                max(4, self.viewport().width() - hw - 5),
                max(4, self.viewport().height() - hh - 4),
                hw,
                hh,
            )
            bg = QColor(C["deep"])
            bg.setAlpha(225)
            p.setBrush(QBrush(bg))
            p.setPen(QPen(QColor(C["acc_mid"]), 1.0))
            p.drawRoundedRect(hr, 2.5, 2.5)
            p.setPen(QColor(C["acc_hi"]))
            p.drawText(hr, Qt.AlignmentFlag.AlignCenter, hud)

        p.end()

# =============================================================================
#  18. Aspect Ratio Picker (Compact Glossy Tiles — 800x600 & HiDPI Scalable)
# =============================================================================
class AspectButton(QAbstractButton):
    """Compact glossy aspect tile with luminous selected state."""

    def __init__(self, key: str, w: int, h: int, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.key = key
        self.w_px = w
        self.h_px = h
        self.setCheckable(True)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setMinimumWidth(0)
        self.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Fixed)
        self.setMinimumHeight(max(26, int(round(32 * ui_scale()))))
        self.setToolTip(f"{key}  \u2014  {w} \u00d7 {h} px")

    def sizeHint(self) -> QSize:  # noqa: N802
        s = ui_scale()
        return QSize(max(44, int(round(58 * s))), max(26, int(round(32 * s))))

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        checked = self.isChecked()
        hovered = self.underMouse()
        grad = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        if checked:
            grad.setColorAt(0.0, QColor(C["acc_hi"]))
            grad.setColorAt(0.52, QColor(C["acc_mid"]))
            grad.setColorAt(1.0, QColor(C["acc_lo"]))
        elif hovered:
            grad.setColorAt(0.0, QColor(C["btn_hov_hi"]))
            grad.setColorAt(1.0, QColor(C["btn_hov_lo"]))
        else:
            grad.setColorAt(0.0, QColor(C["btn_hi"]))
            grad.setColorAt(1.0, QColor(C["btn_lo"]))
        tkey = resolve_theme_key(C.get("key", "seestation"))
        rad = {"seestation": 6.0, "oriental": 0.0}.get(tkey, 1.0)
        p.setBrush(QBrush(grad))
        p.setPen(QPen(QColor(C["acc_edge"] if checked else C["line_hi"]), 1.2 if checked else 0.9))
        if tkey == "gold":
            p.drawPath(_chamfer_path(r, 3.5))
        else:
            p.drawRoundedRect(r, rad, rad)
        if checked:
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QBrush(QColor(C["acc_spec"])))
            if tkey == "seestation":
                p.drawRoundedRect(QRectF(r.left() + 6.0, r.bottom() - 2.8, max(4.0, r.width() - 12.0), 2.0), 1.0, 1.0)
            elif tkey == "oriental":
                p.drawRect(QRectF(r.left() + 1.0, r.top() + 1.0, 3.0, r.height() - 2.0))
            else:
                p.drawRect(QRectF(r.left() + 4.0, r.top() + 1.0, max(4.0, r.width() - 8.0), 2.0))
        s = ui_scale()
        top_h = r.height() * 0.54
        p.setFont(_font(max(7.2, 8.4 * s), True))
        p.setPen(QColor(C["acc_text"] if checked else C["text_hi"]))
        p.drawText(
            QRectF(r.left() + 2, r.top() + 1, r.width() - 4, top_h),
            Qt.AlignmentFlag.AlignCenter,
            self.key,
        )
        p.setFont(_font(max(6.2, 6.9 * s)))
        p.setPen(QColor(C["acc_text"] if checked else C["muted"]))
        dim_txt = f"{self.w_px}\u00d7{self.h_px}"
        dim_el = QFontMetrics(p.font()).elidedText(dim_txt, Qt.TextElideMode.ElideRight, max(16, int(r.width() - 4)))
        p.drawText(
            QRectF(r.left() + 2, r.top() + top_h - 1, r.width() - 4, r.height() - top_h),
            Qt.AlignmentFlag.AlignCenter,
            dim_el,
        )
        p.end()


class AspectPicker(QWidget):
    """Grid of aspect tiles. The landscape and portrait families are swapped
    through the LAND / PORT segmented switch (plain switching buttons:
    exactly one side is always active and they never toggle themselves off);
    the square tile is always visible."""

    changed = pyqtSignal(str)
    orient_clicked = pyqtSignal(str)  # "land" / "port" — user clicks only

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self._group = "land"
        self._grid = QGridLayout(self)
        self._grid.setContentsMargins(0, 0, 0, 0)
        self._grid.setHorizontalSpacing(3)
        self._grid.setVerticalSpacing(3)
        self._btn_group = QButtonGroup(self)
        self._btn_group.setExclusive(True)
        self._buttons: Dict[str, AspectButton] = {}
        for a in ASPECTS:
            b = AspectButton(a["key"], a["w"], a["h"])
            b.setVisible(a["group"] == "square")
            self._btn_group.addButton(b)
            self._buttons[a["key"]] = b
        self._btn_group.buttonClicked.connect(lambda b: self.changed.emit(b.key))
        self._rebuild()
        # Orientation segmented pair (placed in the compact aspect mode bar).
        # v11.0.1 FIX: LAND / PORT used to be two INDEPENDENT checkable
        # toggles — clicking the active one turned it OFF, and clicking PORT
        # did nothing except flipping its own on/off check mark. They are now
        # plain switching buttons wired into ONE exclusive QButtonGroup:
        # exactly one side is always lit, clicking the lit side keeps it lit,
        # and any click simply swaps the visible tile family.
        self.orient_land = QToolButton()
        self.orient_land.setObjectName("Small")
        self.orient_land.setText("LAND")
        self.orient_land.setCheckable(True)
        self.orient_land.setMinimumWidth(0)
        self.orient_land.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Fixed)
        self.orient_land.setCursor(Qt.CursorShape.PointingHandCursor)
        self.orient_land.setToolTip("Show landscape aspect tiles")
        self.orient_port = QToolButton()
        self.orient_port.setObjectName("Small")
        self.orient_port.setText("PORT")
        self.orient_port.setCheckable(True)
        self.orient_port.setMinimumWidth(0)
        self.orient_port.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Fixed)
        self.orient_port.setCursor(Qt.CursorShape.PointingHandCursor)
        self.orient_port.setToolTip("Show portrait aspect tiles")
        self._orient_group = QButtonGroup(self)
        self._orient_group.setExclusive(True)
        self._orient_group.addButton(self.orient_land)
        self._orient_group.addButton(self.orient_port)
        self._orient_group.buttonClicked.connect(self._on_orient_clicked)
        self.orient_land.setChecked(True)

    def _on_orient_clicked(self, btn: QAbstractButton) -> None:
        group = "port" if btn is self.orient_port else "land"
        if group != self._group:
            self._group = group
            self._rebuild()
        self.orient_clicked.emit(group)

    def set_group(self, group: str) -> None:
        """Programmatically show a tile family ("land" / "port") without
        emitting orient_clicked (no user gesture happened)."""
        if group not in ("land", "port"):
            return
        target = self.orient_port if group == "port" else self.orient_land
        if not target.isChecked():
            target.setChecked(True)  # exclusive pair flips the other off itself
        if self._group != group:
            self._group = group
            self._rebuild()

    def set_portrait(self, on: bool) -> None:
        self.set_group("port" if on else "land")

    def _rebuild(self) -> None:
        while self._grid.count():
            item = self._grid.takeAt(0)
            w = item.widget()
            if w is not None:
                self._grid.removeWidget(w)
        keys = [a["key"] for a in ASPECTS if a["group"] in ("square", self._group)]
        key_set = set(keys)
        for k, b in self._buttons.items():
            b.setVisible(k in key_set)
        n = len(keys)
        cols = 3 if n == 6 else 4
        for i, k in enumerate(keys):
            self._grid.addWidget(self._buttons[k], i // cols, i % cols)

    def current(self) -> Dict[str, Any]:
        for k, b in self._buttons.items():
            if b.isChecked():
                return ASPECT_BY_KEY[k]
        return ASPECT_BY_KEY["1:1"]

    def set_current(self, key: str) -> None:
        a = ASPECT_BY_KEY.get(key)
        if a is None:
            return
        if a["group"] == "port" and self._group != "port":
            self.set_portrait(True)
        elif a["group"] == "land" and self._group != "land":
            self.set_portrait(False)
        self._buttons[a["key"]].setChecked(True)
        self.changed.emit(a["key"])


# =============================================================================
#  19. Zero-Scroll Tab Rails, Wrapping FlowContainer, LoRA Rack & Live Sliders
# =============================================================================
class _IconTabBarStyle(QProxyStyle):
    """Zero-bloat tab metrics for the left icon rail so all 9 icon tabs always
    fit edge-to-edge at any panel width (down to 210px on 800x600 displays)."""

    def pixelMetric(self, metric, option=None, widget=None):  # noqa: N802
        if metric == QStyle.PixelMetric.PM_TabBarTabHSpace:
            return 0
        if metric == QStyle.PixelMetric.PM_TabBarTabVSpace:
            return 2
        if metric == QStyle.PixelMetric.PM_TabBarTabOverlap:
            return 0
        return super().pixelMetric(metric, option, widget)


class _AutoFitIconTabBar(QTabBar):
    """Zero-scroll equal-distribution icon tab bar (v10.0):
    Every tab receives an exact integer share of the parent QTabWidget width
    down to 200px with ZERO horizontal scroll arrows ever, plus bespoke
    per-theme active tab illumination (PS4 cyan lightbar / Sarif chamfered
    amber cap / Oriental Spirit pure-red torii beam & hanko corner seal)."""

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setUsesScrollButtons(False)
        self.setExpanding(True)
        self.setDrawBase(False)
        self.setElideMode(Qt.TextElideMode.ElideNone)
        self._rail_h = tab_rail_height(1.0)
        self._avail_w = 0

    def set_rail_height(self, h: int) -> None:
        nh = max(24, int(h))
        if nh != self._rail_h:
            self._rail_h = nh
            self.setFixedHeight(self._rail_h)
            self.updateGeometry()

    def set_available_width(self, w: int) -> None:
        nw = max(0, int(w))
        if nw != self._avail_w:
            self._avail_w = nw
            self.updateGeometry()
            self.update()

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        return QSize(max(1, self.count()) * 18, self._rail_h)

    def sizeHint(self) -> QSize:  # noqa: N802
        pw = self._avail_w or (self.parentWidget().width() if self.parentWidget() is not None else 0)
        return QSize(max(pw, self.minimumSizeHint().width()), self._rail_h)

    def tabSizeHint(self, index: int) -> QSize:  # noqa: N802
        n = max(1, self.count())
        pw = self._avail_w or (self.parentWidget().width() if self.parentWidget() is not None else self.width())
        avail = max(n * 18, pw - 2)
        base = avail // n
        rem = avail - base * n
        tw = base + (1 if index < rem else 0)
        return QSize(max(18, tw), self._rail_h)

    def resizeEvent(self, event) -> None:  # noqa: N802
        super().resizeEvent(event)
        self.update()

    def paintEvent(self, event) -> None:  # noqa: N802
        super().paintEvent(event)
        cur = self.currentIndex()
        if cur < 0 or cur >= self.count():
            return
        tr = QRectF(self.tabRect(cur)).adjusted(0.5, 0.5, -0.5, -0.5)
        if tr.width() < 6 or tr.height() < 6:
            return
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        tkey = resolve_theme_key(C.get("key", "seestation"))
        if tkey == "seestation":
            aura = QRadialGradient(tr.center().x(), tr.bottom(), tr.width() * 0.72)
            c0 = QColor(C["acc_hi"]); c0.setAlpha(68)
            c1 = QColor(C["acc_hi"]); c1.setAlpha(0)
            aura.setColorAt(0.0, c0)
            aura.setColorAt(1.0, c1)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(aura)
            p.drawRect(tr)
            bar = QLinearGradient(tr.left() + 3, 0, tr.right() - 3, 0)
            bar.setColorAt(0.0, QColor(C["acc_mid"]))
            bar.setColorAt(0.5, QColor(C["acc_spec"]))
            bar.setColorAt(1.0, QColor(C["acc_mid"]))
            p.setBrush(bar)
            p.drawRoundedRect(QRectF(tr.left() + 3.0, tr.bottom() - 2.6, max(4.0, tr.width() - 6.0), 2.4), 1.2, 1.2)
        elif tkey == "oriental":
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(C["acc_hi"]))
            p.drawRect(QRectF(tr.left(), tr.top(), tr.width(), 2.4))
            p.drawPolygon(QPolygonF([
                QPointF(tr.left(), tr.top()),
                QPointF(tr.left() + 6.5, tr.top()),
                QPointF(tr.left(), tr.top() + 6.5),
            ]))
            p.setBrush(QColor(C["acc_mid"]))
            p.drawRect(QRectF(tr.left() + 1.0, tr.bottom() - 2.0, max(2.0, tr.width() - 2.0), 1.8))
        else:
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(C["acc_spec"]))
            p.drawRect(QRectF(tr.left() + 2.0, tr.top(), max(4.0, tr.width() - 4.0), 2.2))
            cx = tr.center().x()
            p.setBrush(QColor(C["acc_hi"]))
            p.drawPolygon(QPolygonF([
                QPointF(cx - 3.5, tr.bottom()),
                QPointF(cx + 3.5, tr.bottom()),
                QPointF(cx, tr.bottom() - 3.2),
            ]))
        p.end()


class _AutoFitTextTabBar(QTabBar):
    """Zero-scroll equal-distribution sub-tab bar (for Edit sub-tabs) that fits
    cleanly on narrow 800x600 laptop panels without scroll buttons."""

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setUsesScrollButtons(False)
        self.setExpanding(True)
        self.setDrawBase(False)
        self.setElideMode(Qt.TextElideMode.ElideRight)

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        return QSize(max(1, self.count()) * 32, max(24, int(round(25 * ui_scale()))))

    def tabSizeHint(self, index: int) -> QSize:  # noqa: N802
        n = max(1, self.count())
        pw = self.parentWidget().width() if self.parentWidget() is not None else self.width()
        avail = max(n * 32, pw - 2)
        base = avail // n
        rem = avail - base * n
        h = max(24, int(round(26 * ui_scale())), super().tabSizeHint(index).height())
        return QSize(max(32, base + (1 if index < rem else 0)), h)


class _CompactStackedWidget(QStackedWidget):
    """Zero-bloat QStackedWidget whose size hint tracks ONLY the active page
    with height-for-width support for wrapping FlowLayout bars."""

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Minimum)
        self.currentChanged.connect(lambda _i: self.updateGeometry())

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        cur = self.currentWidget()
        if cur is not None:
            lay = cur.layout()
            if lay is not None and lay.hasHeightForWidth():
                w = max(180, self.width() if self.width() > 60 else 360)
                return QSize(160, max(24, lay.heightForWidth(w)))
            sh = cur.minimumSizeHint()
            return QSize(min(160, sh.width()), max(24, sh.height()))
        return QSize(160, 26)

    def sizeHint(self) -> QSize:  # noqa: N802
        return self.minimumSizeHint()

    def hasHeightForWidth(self) -> bool:  # noqa: N802
        cur = self.currentWidget()
        return bool(cur is not None and cur.layout() is not None and cur.layout().hasHeightForWidth())

    def heightForWidth(self, w: int) -> int:  # noqa: N802
        cur = self.currentWidget()
        if cur is not None and cur.layout() is not None and cur.layout().hasHeightForWidth():
            return max(24, cur.layout().heightForWidth(max(160, w)))
        return self.minimumSizeHint().height()


class FlowLayout(QLayout):
    """Corporate-hardened wrapping FlowLayout (v10.0):
    - Skips hidden child widgets cleanly (zero ghost gaps!)
    - Clamps oversized child widths to container width (never overflows horizontally!)
    - Immediate widget detach on clear_items() (zero single-frame visual ghosting!)"""

    def __init__(self, parent: Optional[QWidget] = None, margin: int = 0, spacing: int = 3) -> None:
        super().__init__(parent)
        self.setContentsMargins(margin, margin, margin, margin)
        self._hspacing = spacing
        self._vspacing = spacing
        self._items: List[Any] = []

    def __del__(self) -> None:
        self._items = []

    def addItem(self, item) -> None:  # noqa: N802
        self._items.append(item)

    def horizontalSpacing(self) -> int:  # noqa: N802
        return self._hspacing

    def verticalSpacing(self) -> int:  # noqa: N802
        return self._vspacing

    def count(self) -> int:  # noqa: N802
        return len(self._items)

    def itemAt(self, i: int):  # noqa: N802
        return self._items[i] if 0 <= i < len(self._items) else None

    def takeAt(self, i: int):  # noqa: N802
        return self._items.pop(i) if 0 <= i < len(self._items) else None

    def expandingDirections(self):  # noqa: N802
        return Qt.Orientation(0)

    def hasHeightForWidth(self) -> bool:  # noqa: N802
        return True

    def heightForWidth(self, w: int) -> int:  # noqa: N802
        return self._do_layout(QRect(0, 0, max(40, w), 0), True)

    def setGeometry(self, rect: QRect) -> None:  # noqa: N802
        super().setGeometry(rect)
        self._do_layout(rect, False)

    def sizeHint(self) -> QSize:  # noqa: N802
        pw = self.parentWidget().width() if self.parentWidget() is not None and self.parentWidget().width() > 60 else 280
        return QSize(self.minimumSize().width(), max(self.minimumSize().height(), self.heightForWidth(pw)))

    def minimumSize(self) -> QSize:  # noqa: N802
        min_h = 0
        for item in self._items:
            wid = item.widget()
            if wid is not None and wid.isHidden():
                continue
            min_h = max(min_h, item.minimumSize().height())
        m = self.contentsMargins()
        return QSize(24 + m.left() + m.right(), min_h + m.top() + m.bottom())

    def _do_layout(self, rect: QRect, test_only: bool) -> int:
        m = self.contentsMargins()
        eff = rect.adjusted(m.left(), m.top(), -m.right(), -m.bottom())
        x, y = eff.x(), eff.y()
        line_height = 0
        hs = self._hspacing
        vs = self._vspacing
        max_w = max(24, eff.width())
        for item in self._items:
            wid = item.widget()
            if wid is not None and wid.isHidden():
                continue
            sh = item.sizeHint()
            iw = min(max(16, sh.width()), max_w)
            ih = max(16, sh.height())
            next_x = x + iw + hs
            if x > eff.x() and (x + iw) > (eff.x() + max_w) and line_height > 0:
                x = eff.x()
                y = y + line_height + vs
                next_x = x + iw + hs
                line_height = 0
            if not test_only:
                item.setGeometry(QRect(QPoint(x, y), QSize(iw, ih)))
            x = next_x
            line_height = max(line_height, ih)
        return y + line_height - rect.y() + m.bottom()

    def clear_items(self) -> None:
        """Remove and immediately detach every widget in the flow."""
        while self._items:
            item = self.takeAt(0)
            w = item.widget() if item is not None else None
            if w is not None:
                w.hide()
                w.setParent(None)
                w.deleteLater()
        self.invalidate()


class FlowContainer(QWidget):
    """Self-sizing wrapping FlowLayout host widget that cleanly expands vertically
    when resized narrower (so folder rails, swatch strips & toolbars NEVER clip
    or force horizontal scrollbars on 800x600 displays)."""

    def __init__(self, margin: int = 0, spacing: int = 3, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setObjectName("Transparent")
        self.flow = FlowLayout(self, margin=margin, spacing=spacing)
        sp = QSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Preferred)
        sp.setHeightForWidth(True)
        self.setSizePolicy(sp)

    def hasHeightForWidth(self) -> bool:  # noqa: N802
        return True

    def heightForWidth(self, w: int) -> int:  # noqa: N802
        return max(0, self.flow.heightForWidth(max(40, w)))

    def sizeHint(self) -> QSize:  # noqa: N802
        w = self.width() if self.width() > 60 else 260
        return QSize(40, max(20, self.flow.heightForWidth(w)))

    def minimumSizeHint(self) -> QSize:  # noqa: N802
        w = self.width() if self.width() > 60 else 220
        return QSize(24, max(18, self.flow.heightForWidth(w)))

    def resizeEvent(self, event) -> None:  # noqa: N802
        super().resizeEvent(event)
        self.updateGeometry()


class LoraRowDelegate(QStyledItemDelegate):
    """Compact 2-line hardware-strip row per LoRA (v10.0 — fully UI-scaled & narrow-safe)."""

    LAMP_W = 24

    def __init__(self, view: "LoraListView", parent: Optional[QObject] = None) -> None:
        super().__init__(parent or view)
        self._view = view

    def sizeHint(self, option: QStyleOptionViewItem, index: QModelIndex) -> QSize:  # noqa: N802
        h = max(28, int(round(self._view.row_height() * ui_scale())))
        return QSize(160, h)

    def paint(self, painter: QPainter, option: QStyleOptionViewItem, index: QModelIndex) -> None:  # noqa: N802
        entry = self._view.entry_for_uid(str(index.data(Qt.ItemDataRole.UserRole) or ""))
        if not isinstance(entry, dict):
            super().paint(painter, option, index)
            return
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(option.rect)
        s = ui_scale()
        state = option.state
        selected = bool(state & QStyle.StateFlag.State_Selected)
        hovered = bool(state & QStyle.StateFlag.State_MouseOver)
        tkey = resolve_theme_key(C.get("key", "seestation"))
        if selected:
            painter.setOpacity(0.92)
            painter.fillRect(r, QColor(C["sel_bg"]))
            painter.setOpacity(1.0)
            painter.setPen(QPen(QColor(C["sel_border"]), 1.0))
            painter.drawRect(r.adjusted(0.5, 0.5, -0.5, -0.5))
            if tkey == "oriental":
                painter.fillRect(QRectF(r.left() + 1, r.top() + 1, 3.0, r.height() - 2), QColor(C["acc_hi"]))
        elif hovered:
            painter.setOpacity(0.52)
            painter.fillRect(r, QColor(C["tag_hover_bg"]))
            painter.setOpacity(1.0)

        enabled = bool(entry.get("enabled", True))
        fcol = QColor(lora_folder_color(entry.get("folder", "Improve-Overall")))
        if not enabled:
            fcol.setAlpha(90)

        # Folder stripe
        painter.fillRect(QRectF(r.left(), r.top() + 2, 3.0, r.height() - 4), fcol)

        # Enable lamp (toggle hit zone)
        lamp_c = r.left() + 14.0
        lamp_y = r.top() + r.height() * 0.5
        if enabled:
            grad = QLinearGradient(lamp_c - 5, lamp_y - 5, lamp_c - 5, lamp_y + 5)
            grad.setColorAt(0.0, QColor(C["acc_spec"]))
            grad.setColorAt(0.5, QColor(C["acc_hi"]))
            grad.setColorAt(1.0, QColor(C["acc_lo"]))
            painter.setBrush(QBrush(grad))
            painter.setPen(QPen(QColor(C["acc_edge"]), 1.0))
            painter.drawEllipse(QPointF(lamp_c, lamp_y), 4.5, 4.5)
            painter.setPen(QPen(QColor(C["acc_text"]), 1.1))
            painter.drawPoint(QPointF(lamp_c, lamp_y))
        else:
            painter.setBrush(Qt.BrushStyle.NoBrush)
            painter.setPen(QPen(QColor(C["dim"]), 1.2))
            painter.drawEllipse(QPointF(lamp_c, lamp_y), 4.1, 4.1)

        # Right-edge weight plate
        m_w = float(entry.get("model", 1.0))
        c_w = float(entry.get("clip", m_w))
        painter.setFont(_font(max(7.2, 8.2 * s), True))
        w_txt = f"{m_w:+.2f}"
        fmw = QFontMetrics(painter.font())
        ww = fmw.horizontalAdvance(w_txt) + 10
        line_h = max(13.0, r.height() * 0.46)
        wr = QRectF(r.right() - ww - 4, r.top() + 3, ww, line_h - 1)
        wbg = QColor(C["acc_deep"]) if enabled else QColor(C["line"])
        painter.setOpacity(0.88 if enabled else 0.5)
        painter.fillRect(wr, wbg)
        painter.setOpacity(1.0)
        painter.setPen(QColor(C["acc_spec"] if enabled else C["muted"]))
        painter.drawText(wr, Qt.AlignmentFlag.AlignCenter, w_txt)

        # Line 1: name (+ #id only if width permits)
        text_x = r.left() + self.LAMP_W
        name_w = max(24.0, r.width() - self.LAMP_W - ww - 10)
        name = str(entry.get("name") or f"LoRA #{entry.get('id', '?')}")
        painter.setFont(_font(max(7.6, 8.8 * s), True))
        painter.setPen(QColor(C["text"] if enabled else C["dim"]))
        fmn = QFontMetrics(painter.font())
        show_id = name_w >= 105
        id_w = 38.0 if show_id else 0.0
        avail_name = max(20, int(name_w - id_w))
        name_el = fmn.elidedText(name, Qt.TextElideMode.ElideRight, avail_name)
        painter.drawText(
            QRectF(text_x, r.top() + 2, avail_name, line_h),
            Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,
            name_el,
        )
        if show_id:
            id_txt = f"#{entry.get('id', '?')}"
            painter.setFont(_font(max(6.8, 7.4 * s), True))
            painter.setPen(QColor(fcol) if enabled else QColor(C["dim"]))
            painter.drawText(
                QRectF(text_x + avail_name, r.top() + 2, id_w, line_h),
                Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight,
                id_txt,
            )

        # Line 2: weights + folder/trigger preview
        painter.setFont(_font(max(6.8, 7.6 * s), False))
        painter.setPen(QColor(C["muted"] if enabled else C["dim"]))
        trig = lora_selected_trigger(entry)
        info = f"M{m_w:+.2f} C{c_w:+.2f}"
        if entry.get("use_slider"):
            info += " \u29bf"
        fmi = QFontMetrics(painter.font())
        info_w = fmi.horizontalAdvance(info) + 6
        sub = QRectF(text_x, r.top() + line_h + 1, max(20.0, r.width() - self.LAMP_W - 6), max(12.0, r.height() - line_h - 3))
        painter.drawText(
            QRectF(sub.left(), sub.top(), min(info_w, sub.width()), sub.height()),
            Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,
            info,
        )
        tail = ""
        tail_col = QColor(C["dim"])
        if getattr(self._view, "show_folder_names", False):
            tail = str(entry.get("folder") or "")
            tail_col = QColor(fcol)
        elif trig:
            tail = trig
        rem_tail = int(sub.width() - info_w - 2)
        if tail and rem_tail > 18:
            tail_el = fmi.elidedText(tail, Qt.TextElideMode.ElideMiddle, rem_tail)
            painter.setPen(tail_col)
            painter.drawText(
                QRectF(sub.left() + info_w, sub.top(), rem_tail, sub.height()),
                Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,
                tail_el,
            )
        painter.restore()


class LoraListView(QListWidget):
    """Compact LoRA list: lamp click toggles, double-click edits, Space toggles."""

    toggle_requested = pyqtSignal(str)
    edit_requested = pyqtSignal(str)
    remove_requested = pyqtSignal(str)

    ROW_COMPACT = 36
    ROW_COMFORT = 48

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self._entry_map: Dict[str, Dict[str, Any]] = {}
        self._row_height = self.ROW_COMPACT
        self.show_folder_names: bool = False
        self.setItemDelegate(LoraRowDelegate(self))
        self.setSelectionMode(QAbstractItemView.SelectionMode.ExtendedSelection)
        self.setAlternatingRowColors(True)
        self.setUniformItemSizes(True)
        self.setLayoutMode(QListView.LayoutMode.Batched)
        self.setBatchSize(64)
        self.setVerticalScrollMode(QAbstractItemView.ScrollMode.ScrollPerItem)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.setMouseTracking(True)

    def set_row_height(self, height: int) -> None:
        self._row_height = max(28, min(64, int(height)))
        self.refresh_scaled_rows()

    def refresh_scaled_rows(self) -> None:
        h = max(28, int(round(self._row_height * ui_scale())))
        for i in range(self.count()):
            it = self.item(i)
            if it is not None:
                it.setSizeHint(QSize(160, h))
        self.doItemsLayout()
        self.viewport().update()

    def row_height(self) -> int:
        return self._row_height

    def set_entries(self, entries: List[Dict[str, Any]]) -> None:
        self._entry_map = {str(e.get("uid") or ""): e for e in entries}

    def entry_for_uid(self, uid: str) -> Optional[Dict[str, Any]]:
        return self._entry_map.get(str(uid or ""))

    def _entry_at(self, pos: QPoint) -> Optional[Dict[str, Any]]:
        it = self.itemAt(pos)
        if it is None:
            return None
        return self.entry_for_uid(str(it.data(Qt.ItemDataRole.UserRole) or ""))

    def _selected_entries(self) -> List[Dict[str, Any]]:
        out: List[Dict[str, Any]] = []
        for it in self.selectedItems():
            e = self.entry_for_uid(str(it.data(Qt.ItemDataRole.UserRole) or ""))
            if e is not None:
                out.append(e)
        return out

    def mousePressEvent(self, event) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton:
            pos = event.position().toPoint()
            entry = self._entry_at(pos)
            if entry is not None and pos.x() <= LoraRowDelegate.LAMP_W:
                entry["enabled"] = not bool(entry.get("enabled", True))
                self.toggle_requested.emit(str(entry.get("uid") or ""))
                self.viewport().update()
                event.accept()
                return
        super().mousePressEvent(event)

    def mouseDoubleClickEvent(self, event) -> None:  # noqa: N802
        entry = self._entry_at(event.position().toPoint())
        if entry is not None:
            self.edit_requested.emit(str(entry.get("uid") or ""))
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def keyPressEvent(self, event) -> None:  # noqa: N802
        it = self.currentItem()
        entry = self.entry_for_uid(str(it.data(Qt.ItemDataRole.UserRole) or "")) if it is not None else None
        if isinstance(entry, dict):
            if event.key() == Qt.Key.Key_Space:
                sel = self._selected_entries()
                targets = sel if len(sel) > 1 else [entry]
                any_off = any(not bool(e.get("enabled", True)) for e in targets)
                new_val = True if any_off else False
                for e in targets:
                    e["enabled"] = new_val
                    self.toggle_requested.emit(str(e.get("uid") or ""))
                self.viewport().update()
                event.accept()
                return
            if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
                self.edit_requested.emit(str(entry.get("uid") or ""))
                event.accept()
                return
            if event.key() in (Qt.Key.Key_Delete, Qt.Key.Key_Backspace):
                if len(self._selected_entries()) > 1:
                    for e in self._selected_entries():
                        self.remove_requested.emit(str(e.get("uid") or ""))
                else:
                    self.remove_requested.emit(str(entry.get("uid") or ""))
                event.accept()
                return
        super().keyPressEvent(event)


class ActiveLoraSlidersBar(QWidget):
    """Responsive live weight slider rack embedded in the Prompt tab (narrow-safe!)."""

    weight_changed = pyqtSignal(str, float)

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self._lay = QVBoxLayout(self)
        self._lay.setContentsMargins(4, 2, 4, 2)
        self._lay.setSpacing(3)

    def rebuild(self, entries: List[Dict[str, Any]]) -> int:
        while self._lay.count():
            item = self._lay.takeAt(0)
            w = item.widget()
            if w is not None:
                w.hide()
                w.setParent(None)
                w.deleteLater()
        active_sliders = [e for e in entries if e.get("enabled") and e.get("use_slider")]
        for e in active_sliders:
            row_w = QWidget()
            row_w.setObjectName("Transparent")
            rl = QHBoxLayout(row_w)
            rl.setContentsMargins(0, 0, 0, 0)
            rl.setSpacing(4)
            fcol = lora_folder_color(e.get("folder", "Slider"))
            nm = ElideLabel(str(e.get("name") or f"#{e.get('id')}"))
            nm.setMinimumWidth(52)
            nm.setMaximumWidth(104)
            nm.setStyleSheet(f"color: {fcol}; font-weight: bold;")
            sl = QSlider(Qt.Orientation.Horizontal)
            sl.setMinimumWidth(56)
            s_min = float(e.get("slider_min", -2.0))
            s_max = float(e.get("slider_max", 2.0))
            sl.setRange(int(round(s_min * 20)), int(round(s_max * 20)))
            sl.setValue(int(round(float(e.get("model", 1.0)) * 20)))
            sl.setCursor(Qt.CursorShape.PointingHandCursor)
            vl = make_label(f"{float(e.get('model', 1.0)):+.2f}", "Value")
            vl.setMinimumWidth(34)
            vl.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
            uid = str(e["uid"])

            def _on_val(v: int, u: str = uid, lab: QLabel = vl) -> None:
                fw = round(v / 20.0, 2)
                lab.setText(f"{fw:+.2f}")
                self.weight_changed.emit(u, fw)

            sl.valueChanged.connect(_on_val)
            rl.addWidget(nm, 2)
            rl.addWidget(sl, 3)
            rl.addWidget(vl, 0)
            self._lay.addWidget(row_w)
        return len(active_sliders)


# =============================================================================
#  20. Queue Delegate & Tile Upscale Live Previews / Delegate
# =============================================================================
STATE_TINT: Dict[str, str] = {
    STATE_QUEUED: "muted",
    STATE_SUBMITTING: "info",
    STATE_WAITING: "warn",
    STATE_PROCESSING: "acc_hi",
    STATE_FETCHING: "info",
    STATE_DONE: "ok",
    STATE_FAILED: "err",
    STATE_CANCELLED: "dim",
}


class QueueDelegate(QStyledItemDelegate):
    """Rich queue row: state lamp, title, live status line, ETA progress bar,
    kudos pill and terminal-state dimming — scaled cleanly with ui_scale()."""

    def __init__(self, compact: bool = False, parent: Optional[QObject] = None) -> None:
        super().__init__(parent)
        self.compact = compact

    def sizeHint(self, option: QStyleOptionViewItem, index: QModelIndex) -> QSize:  # noqa: N802
        base_h = 36 if self.compact else 52
        return QSize(max(140, option.rect.width()), max(30, int(round(base_h * ui_scale()))))

    def paint(self, painter: QPainter, option: QStyleOptionViewItem, index: QModelIndex) -> None:  # noqa: N802
        job = index.data(Qt.ItemDataRole.UserRole)
        if not isinstance(job, Job):
            super().paint(painter, option, index)
            return
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        s = ui_scale()
        r = QRectF(option.rect).adjusted(1.0, 1.0, -1.0, -1.0)
        hovered = bool(option.state & QStyle.StateFlag.State_MouseOver)
        selected = bool(option.state & QStyle.StateFlag.State_Selected)

        grad = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        if selected:
            grad.setColorAt(0.0, QColor(C["sel_bg"]))
            grad.setColorAt(1.0, QColor(C["tag_sel_bg"]))
        elif hovered:
            grad.setColorAt(0.0, QColor(C["btn_hov_hi"]))
            grad.setColorAt(1.0, QColor(C["btn_hov_lo"]))
        else:
            grad.setColorAt(0.0, QColor(C["plate_hi"]))
            grad.setColorAt(1.0, QColor(C["plate_lo"]))
        tkey = resolve_theme_key(C.get("key", "seestation"))
        qframe = _theme_frame_path(r, tkey, rad_see=6.5, ch_gold=5.0)
        painter.setBrush(QBrush(grad))
        painter.setPen(QPen(QColor(C["sel_border"] if selected else C["line"]), 1.15 if selected else 0.8))
        painter.drawPath(qframe)
        if selected:
            if tkey == "oriental":
                painter.fillRect(QRectF(r.left() + 1.0, r.top() + 1.0, 3.2, r.height() - 2.0), QColor(C["acc_hi"]))
            elif tkey == "seestation":
                painter.fillRect(QRectF(r.left() + 8.0, r.bottom() - 2.2, max(6.0, r.width() - 16.0), 1.8), QColor(C["acc_hi"]))
            else:
                painter.fillRect(QRectF(r.left() + 5.0, r.top() + 1.0, max(6.0, r.width() - 10.0), 1.8), QColor(C["acc_spec"]))

        lamp_col = QColor(C.get(STATE_TINT.get(job.state, "muted"), C["muted"]))
        lamp_col.setAlpha(235)
        lamp_r = QRectF(r.left() + 6, r.top() + (9 if not self.compact else 7), 8, 8)
        painter.setBrush(QBrush(lamp_col))
        painter.setPen(QPen(QColor(C["acc_edge"]), 0.7))
        painter.drawEllipse(lamp_r)
        if job.active:
            halo = QColor(lamp_col); halo.setAlpha(70)
            painter.setPen(QPen(halo, 2.2))
            painter.setBrush(Qt.BrushStyle.NoBrush)
            painter.drawEllipse(lamp_r.adjusted(-2, -2, 2, 2))

        kudos_w = 0.0
        if job.kudos:
            painter.setFont(_font(max(6.8, 7.4 * s), True))
            k_txt = f"{job.kudos:.0f}k"
            fm_k = QFontMetrics(painter.font())
            kudos_w = fm_k.horizontalAdvance(k_txt) + 10
            kr = QRectF(r.right() - kudos_w - 5, r.top() + 3, kudos_w, max(12.0, 13.0 * s))
            painter.setBrush(QBrush(QColor(C["deep"])))
            painter.setPen(QPen(QColor(C["line"]), 0.8))
            painter.drawRoundedRect(kr, 2.0, 2.0)
            painter.setPen(QColor(C["kicker"]))
            painter.drawText(kr, Qt.AlignmentFlag.AlignCenter, k_txt)

        tx = r.left() + 20
        title_font = _font(max(7.6, 8.8 * s), True)
        painter.setFont(title_font)
        painter.setPen(QColor(C["text_hi"] if not job.terminal else C["muted"]))
        title_w = max(20.0, r.width() - 26 - (kudos_w + 4 if kudos_w else 0))
        title_h = max(13.0, (15.0 if not self.compact else 14.0) * s)
        title_r = QRectF(tx, r.top() + 2, title_w, title_h)
        painter.drawText(title_r, Qt.AlignmentFlag.AlignVCenter, QFontMetrics(title_font).elidedText(
            job.title_line(), Qt.TextElideMode.ElideRight, int(title_r.width())))

        if not self.compact:
            painter.setFont(_font(max(7.0, 8.0 * s)))
            painter.setPen(QColor(C["muted"]))
            st_r = QRectF(tx, r.top() + title_h + 2, max(20.0, r.width() - 24), max(12.0, 14.0 * s))
            painter.drawText(st_r, Qt.AlignmentFlag.AlignVCenter, QFontMetrics(painter.font()).elidedText(
                job.status_line(), Qt.TextElideMode.ElideRight, int(st_r.width())))

        prog = job.progress_fraction()
        bar_h = 5.0
        bar_y = r.bottom() - 5.0
        bar_r = QRectF(r.left() + 6, bar_y - bar_h, max(12.0, r.width() - 12), bar_h)
        painter.setBrush(QBrush(QColor(C["deep"])))
        painter.setPen(QPen(QColor(C["sunken_edge"]), 0.8))
        painter.drawRoundedRect(bar_r, 2.0, 2.0)
        if prog > 0.01:
            fill_r = QRectF(bar_r.left() + 1, bar_r.top() + 1, max(2.0, (bar_r.width() - 2) * prog), bar_r.height() - 2)
            pgrad = QLinearGradient(fill_r.left(), fill_r.top(), fill_r.left(), fill_r.bottom())
            state_col = STATE_TINT.get(job.state, "muted")
            pgrad.setColorAt(0.0, QColor(C["acc_spec"]))
            pgrad.setColorAt(0.5, QColor(C.get(state_col, C["acc_hi"])))
            pgrad.setColorAt(1.0, QColor(C["acc_lo"]))
            painter.setBrush(QBrush(pgrad))
            painter.setPen(Qt.PenStyle.NoPen)
            painter.drawRoundedRect(fill_r, 2.0, 2.0)
        painter.restore()


class TilePlanPreview(QLabel):
    """Source image with the planned tile grid overlaid (before upscale)."""

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setMinimumHeight(86)
        self.setMaximumHeight(140)
        self.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.setScaledContents(False)
        self._source: Optional[str] = None
        self._plan: Optional[Dict[str, Any]] = None

    def set_data(self, source: Optional[str], plan: Optional[Dict[str, Any]]) -> None:
        self._source = source
        self._plan = plan
        self._render()

    def _render(self) -> None:
        if not self._source or not os.path.isfile(self._source):
            self.clear()
            self.setText("no source image")
            return
        img = QImage(self._source)
        if img.isNull():
            self.clear()
            self.setText("cannot decode source")
            return
        tw = max(60, self.width() - 8)
        th = max(50, self.height() - 8)
        scale = min(tw / img.width(), th / img.height())
        disp_w, disp_h = int(img.width() * scale), int(img.height() * scale)
        canvas = QImage(max(disp_w, 1), max(disp_h, 1), QImage.Format.Format_ARGB32)
        canvas.fill(QColor(C["deep"]))
        p = QPainter(canvas)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        p.drawImage(QRect(0, 0, disp_w, disp_h), img)
        if self._plan:
            sx = disp_w / max(1, self._plan["out_w"])
            sy = disp_h / max(1, self._plan["out_h"])
            p.setRenderHint(QPainter.RenderHint.Antialiasing, False)
            for t in self._plan["tiles"]:
                rect = QRectF(
                    t["x"] * sx, t["y"] * sy,
                    max(1.0, t["w"] * sx), max(1.0, t["h"] * sy),
                )
                p.setPen(QPen(QColor(C["acc_mid"]), 1.0))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawRect(rect)
                state_col = QColor(TILE_STATE_COLORS.get(t.get("state", TILE_PLANNED), "#928976"))
                p.setBrush(QBrush(state_col))
                p.setPen(Qt.PenStyle.NoPen)
                p.drawRect(QRectF(rect.right() - 4, rect.top() + 1, 3, 3))
        p.end()
        self.setPixmap(QPixmap.fromImage(canvas))

    def resizeEvent(self, event) -> None:  # noqa: N802
        super().resizeEvent(event)
        self._render()


class TileCanvasPreview(QLabel):
    """Live merged-canvas preview: the upscaled base with per-tile state tint."""

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setMinimumHeight(86)
        self.setMaximumHeight(140)
        self.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self._plan: Optional[Dict[str, Any]] = None
        self._base: Optional[str] = None

    def set_run(self, plan: Optional[Dict[str, Any]], base_path: Optional[str]) -> None:
        self._plan = plan
        self._base = base_path
        self._render()

    def _render(self) -> None:
        if not self._plan:
            self.clear()
            self.setText("no active run")
            return
        out_w, out_h = self._plan["out_w"], self._plan["out_h"]
        tw = max(60, self.width() - 8)
        th = max(50, self.height() - 8)
        scale = min(tw / out_w, th / out_h)
        disp_w, disp_h = int(out_w * scale), int(out_h * scale)
        canvas = QImage(max(disp_w, 1), max(disp_h, 1), QImage.Format.Format_ARGB32)
        canvas.fill(QColor(C["deep"]))
        p = QPainter(canvas)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        if self._base and os.path.isfile(self._base):
            base = QImage(self._base)
            if not base.isNull():
                p.drawImage(QRect(0, 0, disp_w, disp_h), base)
        else:
            p.setPen(QColor(C["dim"]))
            p.setFont(_font(8.5))
            p.drawText(QRect(0, 0, disp_w, disp_h), Qt.AlignmentFlag.AlignCenter, "base upscaling\u2026")
        p.setRenderHint(QPainter.RenderHint.Antialiasing, False)
        sx, sy = disp_w / out_w, disp_h / out_h
        for t in self._plan["tiles"]:
            state = t.get("state", TILE_PLANNED)
            if state != TILE_DONE:
                tint = QColor(TILE_STATE_COLORS.get(state, "#928976"))
                tint.setAlpha(60 if state == TILE_REFINING else 92)
                p.setBrush(QBrush(tint))
                p.setPen(QPen(QColor(C["plate_edge"]), 0.6))
                p.drawRect(QRectF(t["x"] * sx, t["y"] * sy, max(1.0, t["w"] * sx), max(1.0, t["h"] * sy)))
            p.setPen(QPen(QColor(C["line"]), 0.6))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawRect(QRectF(t["x"] * sx, t["y"] * sy, max(1.0, t["w"] * sx), max(1.0, t["h"] * sy)))
        p.end()
        self.setPixmap(QPixmap.fromImage(canvas))

    def resizeEvent(self, event) -> None:  # noqa: N802
        super().resizeEvent(event)
        self._render()


class TileGridDelegate(QStyledItemDelegate):
    """Paints one tile state chip in the tile rack grid."""

    def __init__(self, parent: Optional[QObject] = None) -> None:
        super().__init__(parent)

    def sizeHint(self, option: QStyleOptionViewItem, index: QModelIndex) -> QSize:  # noqa: N802
        return QSize(52, 40)

    def paint(self, painter: QPainter, option: QStyleOptionViewItem, index: QModelIndex) -> None:  # noqa: N802
        t = index.data(Qt.ItemDataRole.UserRole)
        if not isinstance(t, dict):
            super().paint(painter, option, index)
            return
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(option.rect).adjusted(2.0, 2.0, -2.0, -2.0)
        state = t.get("state", TILE_PLANNED)
        col = QColor(TILE_STATE_COLORS.get(state, "#928976"))
        grad = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        grad.setColorAt(0.0, col)
        col2 = QColor(col)
        col2.setAlpha(120)
        grad.setColorAt(1.0, col2)
        painter.setBrush(QBrush(grad))
        painter.setPen(QPen(QColor(C["line"]), 0.8))
        painter.drawRoundedRect(r, 3.0, 3.0)
        # Glass spec
        glass = QColor(C["svg_glass"])
        glass.setAlpha(34)
        painter.setBrush(QBrush(glass))
        painter.setPen(Qt.PenStyle.NoPen)
        painter.drawRect(QRectF(r.left() + 1, r.top() + 1, r.width() - 2, r.height() * 0.42))
        painter.setFont(_font(8.0, True))
        painter.setPen(QColor(C["text_hi"]))
        painter.drawText(r.adjusted(0, 1, 0, -11), Qt.AlignmentFlag.AlignCenter, f"r{t.get('row', '?')}c{t.get('col', '?')}")
        painter.setFont(_font(7.2, True))
        painter.setPen(QColor(C["text"]))
        painter.drawText(r.adjusted(0, 11, 0, -1), Qt.AlignmentFlag.AlignCenter, TILE_STATE_SHORT.get(state, "?"))
        painter.restore()

# =============================================================================
#  21. Image Viewer (Zoom, Pan, Drag-Drop & Themed Vector Watermark)
# =============================================================================
class _ViewerCanvas(QWidget):
    def __init__(self, viewer: "ImageViewer") -> None:
        super().__init__(viewer)
        self._viewer = viewer
        self.setAttribute(Qt.WidgetAttribute.WA_OpaquePaintEvent, True)

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        paint_theme_backdrop(p, self.rect())
        pm = self._viewer._pixmap
        if pm is None or pm.isNull():
            # Cinematic themed vector centerpiece watermark
            sz = min(210, max(96, min(self.width(), self.height()) // 2))
            wm = VECTOR_ASSETS.pixmap("viewer_watermark", sz, sz)
            wx = (self.width() - sz) // 2
            wy = (self.height() - sz) // 2 - 16
            p.drawPixmap(wx, wy, wm)
            p.setFont(_font(11.0, True, 0.9))
            p.setPen(QColor(C["text_hi"]))
            p.drawText(
                QRect(12, wy + sz + 4, self.width() - 24, 22),
                Qt.AlignmentFlag.AlignCenter,
                f"{APP_NAME}  v{APP_VERSION}  ·  {C['name']}",
            )
            p.setFont(_font(8.8))
            p.setPen(QColor(C["muted"]))
            p.drawText(
                QRect(12, wy + sz + 26, self.width() - 24, 20),
                Qt.AlignmentFlag.AlignCenter,
                "Enter a prompt and press Generate (Ctrl+Enter)  ·  or drop an image here",
            )
            p.end()
            return
        tw = max(1, int(round(pm.width() * self._viewer._scale)))
        th = max(1, int(round(pm.height() * self._viewer._scale)))
        ox = max(0, (self.width() - tw) // 2)
        oy = max(0, (self.height() - th) // 2)
        p.drawPixmap(QRect(ox, oy, tw, th), pm)
        zr = getattr(self._viewer, "_zoom_rect", None)
        if zr is not None and zr.width() > 2:
            zp = QPen(QColor(C["acc_spec"]), 1.4, Qt.PenStyle.DashLine)
            p.setPen(zp)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawRect(QRectF(zr).adjusted(0.5, 0.5, -0.5, -0.5))
            fillc = QColor(C["acc_spec"])
            fillc.setAlpha(26)
            p.fillRect(QRectF(zr), fillc)
        p.end()


class ImageViewer(QScrollArea):
    toggled_fit = pyqtSignal(bool)
    zoom_changed = pyqtSignal(float, bool)
    image_dropped = pyqtSignal(str)
    menu_requested = pyqtSignal(QPoint)  # v10.1: right-click menu (global pos)

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setWidgetResizable(False)
        self.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.setFrameShape(QFrame.Shape.NoFrame)
        self.setAcceptDrops(True)
        self.path: Optional[str] = None
        self.meta: Dict[str, Any] = {}
        self._pixmap: Optional[QPixmap] = None
        self._fit = True
        self._scale = 1.0
        self._panning = False
        self._pan_start = QPoint()
        self._h_start = 0
        self._v_start = 0
        self._zoom_rect: Optional[QRect] = None
        self._canvas = _ViewerCanvas(self)
        self.setWidget(self._canvas)

    def set_image(self, path: Optional[str]) -> None:
        self.path = path if (path and os.path.isfile(path)) else None
        self.meta = read_image_metadata(self.path) if self.path else {}
        self._pixmap = QPixmap(self.path) if self.path else None
        if self._fit:
            self._recompute_fit()
        else:
            self._update_canvas_size()
        self._canvas.update()

    def set_fit(self, fit: bool) -> None:
        self._fit = bool(fit)
        if self._fit:
            self._recompute_fit()
        else:
            self._scale = 1.0
            self._update_canvas_size()
        self.toggled_fit.emit(self._fit)
        self.zoom_changed.emit(self._scale, self._fit)
        self._canvas.update()

    def zoom_by(self, factor: float, anchor: Optional[QPoint] = None) -> None:
        if self._pixmap is None or self._pixmap.isNull():
            return
        old_s = self._scale
        new_s = max(0.08, min(12.0, old_s * factor))
        if abs(new_s - old_s) < 1e-4:
            return
        self._fit = False
        vp = self.viewport()
        if anchor is None:
            anchor = QPoint(vp.width() // 2, vp.height() // 2)
        hbar = self.horizontalScrollBar()
        vbar = self.verticalScrollBar()
        img_x = (hbar.value() + anchor.x()) / max(1e-6, old_s)
        img_y = (vbar.value() + anchor.y()) / max(1e-6, old_s)
        self._scale = new_s
        self._update_canvas_size()
        hbar.setValue(int(round(img_x * new_s - anchor.x())))
        vbar.setValue(int(round(img_y * new_s - anchor.y())))
        self.toggled_fit.emit(False)
        self.zoom_changed.emit(self._scale, False)
        self._canvas.update()

    def _recompute_fit(self) -> None:
        vp = self.viewport().size()
        if self._pixmap is None or self._pixmap.isNull() or vp.width() <= 4 or vp.height() <= 4:
            self._scale = 1.0
            self._canvas.resize(max(10, vp.width()), max(10, vp.height()))
            return
        sx = (vp.width() - 8) / max(1, self._pixmap.width())
        sy = (vp.height() - 8) / max(1, self._pixmap.height())
        self._scale = max(0.05, min(sx, sy, 1.0))
        self._canvas.resize(max(10, vp.width()), max(10, vp.height()))
        self.zoom_changed.emit(self._scale, True)

    def _update_canvas_size(self) -> None:
        vp = self.viewport().size()
        if self._pixmap is None or self._pixmap.isNull():
            self._canvas.resize(max(10, vp.width()), max(10, vp.height()))
            return
        tw = max(vp.width(), int(round(self._pixmap.width() * self._scale)))
        th = max(vp.height(), int(round(self._pixmap.height() * self._scale)))
        self._canvas.resize(tw, th)

    def resizeEvent(self, event) -> None:  # noqa: N802
        super().resizeEvent(event)
        if self._fit:
            self._recompute_fit()
        else:
            self._update_canvas_size()
        self._canvas.update()

    def wheelEvent(self, event) -> None:  # noqa: N802
        if event.modifiers() & Qt.KeyboardModifier.ControlModifier:
            delta = event.angleDelta().y()
            if delta:
                self.zoom_by(1.22 if delta > 0 else 1.0 / 1.22, event.position().toPoint())
            event.accept()
            return
        super().wheelEvent(event)

    def mouseDoubleClickEvent(self, event) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton and self._pixmap is not None:
            self.set_fit(not self._fit)
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def mousePressEvent(self, event) -> None:  # noqa: N802
        if (
            event.button() == Qt.MouseButton.RightButton
            and (event.modifiers() & Qt.KeyboardModifier.ControlModifier)
            and self._pixmap is not None
        ):
            self.set_fit(True)
            event.accept()
            return
        if event.button() == Qt.MouseButton.LeftButton and self._pixmap is not None:
            if event.modifiers() & Qt.KeyboardModifier.ControlModifier:
                # v4: Ctrl+Drag draws a zoom frame (wheel-free zoom)
                self._zoom_rect = QRect(event.position().toPoint(), event.position().toPoint())
                event.accept()
                return
            if not self._fit:
                self._panning = True
                self._pan_start = event.position().toPoint()
                self._h_start = self.horizontalScrollBar().value()
                self._v_start = self.verticalScrollBar().value()
                self.viewport().setCursor(Qt.CursorShape.ClosedHandCursor)
                event.accept()
                return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event) -> None:  # noqa: N802
        if self._zoom_rect is not None:
            self._zoom_rect = QRect(self._zoom_rect.topLeft(), event.position().toPoint()).normalized()
            self._canvas.update()
            event.accept()
            return
        if self._panning:
            d = event.position().toPoint() - self._pan_start
            self.horizontalScrollBar().setValue(self._h_start - d.x())
            self.verticalScrollBar().setValue(self._v_start - d.y())
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton and self._zoom_rect is not None:
            r = QRect(self._zoom_rect)
            self._zoom_rect = None
            self._canvas.update()
            if r.width() >= 14 and r.height() >= 14:
                self._zoom_to_rect(r)
            event.accept()
            return
        if self._panning and event.button() == Qt.MouseButton.LeftButton:
            self._panning = False
            self.viewport().setCursor(Qt.CursorShape.ArrowCursor)
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def _zoom_to_rect(self, r: QRect) -> None:
        """Zoom so the Ctrl-dragged frame fills the viewport."""
        vp = self.viewport().size()
        factor = min(vp.width() / float(r.width()), vp.height() / float(r.height())) * 0.97
        old = self._scale
        new = max(0.05, min(12.0, old * factor))
        if abs(new - old) < 1e-4:
            return
        hbar, vbar = self.horizontalScrollBar(), self.verticalScrollBar()
        cx_doc = (hbar.value() + r.center().x()) / max(1e-6, old)
        cy_doc = (vbar.value() + r.center().y()) / max(1e-6, old)
        self._fit = False
        self._scale = new
        self._update_canvas_size()
        hbar.setValue(int(round(cx_doc * new - vp.width() / 2.0)))
        vbar.setValue(int(round(cy_doc * new - vp.height() / 2.0)))
        self.toggled_fit.emit(False)
        self.zoom_changed.emit(new, False)
        self._canvas.update()

    def contextMenuEvent(self, event) -> None:  # noqa: N802
        """v10.1: right-click on a loaded image opens the viewer context menu
        (copy to clipboard, prompt reuse, editor routing, delete)."""
        if self._pixmap is not None and not self._pixmap.isNull():
            self.menu_requested.emit(event.globalPos())
            event.accept()
            return
        super().contextMenuEvent(event)

    def dragEnterEvent(self, event) -> None:  # noqa: N802
        if event.mimeData().hasUrls():
            for u in event.mimeData().urls():
                if u.isLocalFile() and u.toLocalFile().lower().endswith((".png", ".webp", ".jpg", ".jpeg")):
                    event.acceptProposedAction()
                    return
        super().dragEnterEvent(event)

    def dropEvent(self, event) -> None:  # noqa: N802
        if event.mimeData().hasUrls():
            for u in event.mimeData().urls():
                if u.isLocalFile() and u.toLocalFile().lower().endswith((".png", ".webp", ".jpg", ".jpeg")):
                    self.image_dropped.emit(u.toLocalFile())
                    event.acceptProposedAction()
                    return
        super().dropEvent(event)


# =============================================================================
#  22. Recent Filmstrip Gallery & Paginated Output Gallery Browser
# =============================================================================
def gallery_tooltip(meta: Dict[str, Any], path: str) -> str:
    lines = [os.path.basename(path)]
    if meta.get("model"):
        lines.append(f"Model: {meta['model']}")
    if meta.get("width") and meta.get("height"):
        lines.append(f"Size: {meta['width']}x{meta['height']}")
    if meta.get("seed") is not None:
        lines.append(f"Seed: {meta['seed']}")
    if isinstance(meta.get("aesthetic"), (int, float)):
        lines.append(f"Aesthetic: {float(meta['aesthetic']):.2f}")
    if meta.get("worker_name"):
        lines.append(f"Worker: {meta['worker_name']}")
    if meta.get("_has_depth"):
        lines.append("Depth map attached (depth_anything_v2)")
    if meta.get("prompt"):
        lines.append("")
        lines.append(elide(str(meta["prompt"]), 220))
    return "\n".join(lines)


class ThumbDelegate(QStyledItemDelegate):
    """Filmstrip thumbnail with hover zoom hint & favorite star."""

    def __init__(self, parent: Optional[QObject] = None) -> None:
        super().__init__(parent)

    def sizeHint(self, option: QStyleOptionViewItem, index: QModelIndex) -> QSize:  # noqa: N802
        return QSize(76, 60)

    def paint(self, painter: QPainter, option: QStyleOptionViewItem, index: QModelIndex) -> None:  # noqa: N802
        path = index.data(Qt.ItemDataRole.UserRole + 1)
        pm = index.data(Qt.ItemDataRole.UserRole + 3)
        meta = index.data(Qt.ItemDataRole.UserRole + 2) or {}
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(option.rect).adjusted(2.0, 2.0, -2.0, -2.0)
        selected = bool(option.state & QStyle.StateFlag.State_Selected)
        painter.setBrush(QBrush(QColor(C["plate_lo"])))
        painter.setPen(QPen(QColor(C["sel_border"] if selected else C["line"]), 1.2 if selected else 0.8))
        painter.drawRoundedRect(r, 3.0, 3.0)
        if isinstance(pm, QPixmap) and not pm.isNull():
            target = r.adjusted(1.5, 1.5, -1.5, -1.5)
            scaled = pm.scaled(
                int(target.width()), int(target.height()),
                Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation,
            )
            ox = int(target.left() + (target.width() - scaled.width()) / 2)
            oy = int(target.top() + (target.height() - scaled.height()) / 2)
            painter.drawPixmap(ox, oy, scaled)
        if meta.get("favorite"):
            star = VECTOR_ASSETS.pixmap("star_on", 14, 14)
            painter.drawPixmap(int(r.right()) - 15, int(r.top()) + 1, star)
        if meta.get("_has_depth"):
            painter.drawPixmap(int(r.left()) + 2, int(r.bottom()) - 12, VECTOR_ASSETS.pixmap("depth", 10, 10))
        painter.restore()


class RecentStripGallery(QListWidget):
    """Horizontal filmstrip of the last renders (temp ring + optional outputs)."""

    ROLE_PATH = Qt.ItemDataRole.UserRole + 1
    ROLE_META = Qt.ItemDataRole.UserRole + 2
    ROLE_PIXMAP = Qt.ItemDataRole.UserRole + 3

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setViewMode(QListView.ViewMode.IconMode)
        self.setFlow(QListView.Flow.LeftToRight)
        self.setWrapping(False)
        self.setMovement(QListView.Movement.Static)
        self.setResizeMode(QListView.ResizeMode.Adjust)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.setSelectionMode(QAbstractItemView.SelectionMode.SingleSelection)
        self.setUniformItemSizes(True)
        self.setSpacing(3)
        self.setFixedHeight(66)
        self.setItemDelegate(ThumbDelegate(self))
        self.setCursor(Qt.CursorShape.PointingHandCursor)

    def refresh(self, paths: List[str], select: Optional[str] = None) -> None:
        """Rebuild the strip from `paths` (newest first).

        v11: signals are BLOCKED during the rebuild — the old implementation
        fired currentItemChanged(None) mid-clear, which wiped the viewer via
        show_image(None) right after a fresh render was focused. Optionally
        selects (and scrolls to) `select` so the newest image is the focused
        one, and reports whether the selection landed."""
        self.blockSignals(True)
        self.clear()
        for path in paths[:TEMP_CAPACITY]:
            pm = QPixmap(path)
            if pm.isNull():
                continue
            if pm.width() > 116 or pm.height() > 116:
                pm = pm.scaled(116, 116, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
            meta = read_image_metadata(path)
            meta["_has_depth"] = has_depth_map(path)
            it = QListWidgetItem()
            it.setData(self.ROLE_PATH, path)
            it.setData(self.ROLE_META, meta)
            it.setData(self.ROLE_PIXMAP, pm)
            it.setToolTip(gallery_tooltip(meta, path))
            self.addItem(it)
        sel_row = -1
        if select:
            for i in range(self.count()):
                it = self.item(i)
                if it and it.data(self.ROLE_PATH) == select:
                    sel_row = i
                    break
        if sel_row >= 0:
            self.setCurrentRow(sel_row)
        elif self.count() > 0 and select is None and self.currentRow() < 0:
            pass  # keep the viewer untouched when there is nothing to focus
        self.blockSignals(False)
        if sel_row >= 0:
            # re-emit the manual selection change once, outside the block
            cur = self.item(sel_row)
            if cur is not None:
                self.currentItemChanged.emit(cur, None)
                self.scrollTo(self.indexFromItem(cur), QAbstractItemView.ScrollHint.PositionAtCenter)


class GalleryThumbLoader(QThread):
    """Background thumbnail generator for the paginated output gallery."""
    loaded = pyqtSignal(str, QImage, int)

    def __init__(self, paths: List[str], size_px: int, parent: Optional[QObject] = None) -> None:
        super().__init__(parent)
        self._paths = list(paths)
        self._size = int(size_px)
        self._stop = False

    def stop(self) -> None:
        self._stop = True

    def run(self) -> None:
        for p in self._paths:
            if self._stop:
                return
            try:
                reader = QImageReader(p)
                reader.setAutoTransform(True)
                sz = reader.size()
                if sz.isValid() and sz.width() > 0 and sz.height() > 0:
                    scale = min(self._size / sz.width(), self._size / sz.height())
                    reader.setScaledSize(QSize(
                        max(1, int(sz.width() * scale)),
                        max(1, int(sz.height() * scale)),
                    ))
                img = reader.read()
                if not img.isNull():
                    self.loaded.emit(p, img, self._size)
            except Exception:  # noqa: BLE001
                continue


class GalleryTileDelegate(QStyledItemDelegate):
    """Output gallery tile: thumbnail plate, favorite star, model chip, score."""

    def __init__(self, tile_px: int, parent: Optional[QObject] = None) -> None:
        super().__init__(parent)
        self.tile_px = int(tile_px)

    def set_tile_px(self, px: int) -> None:
        self.tile_px = max(64, int(px))

    def sizeHint(self, option: QStyleOptionViewItem, index: QModelIndex) -> QSize:  # noqa: N802
        return QSize(self.tile_px, self.tile_px)

    def paint(self, painter: QPainter, option: QStyleOptionViewItem, index: QModelIndex) -> None:  # noqa: N802
        pm = index.data(Qt.ItemDataRole.UserRole + 3)
        meta = index.data(Qt.ItemDataRole.UserRole + 2) or {}
        selected = bool(option.state & QStyle.StateFlag.State_Selected)
        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(option.rect).adjusted(2.0, 2.0, -2.0, -2.0)
        grad = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        grad.setColorAt(0.0, QColor(C["plate_hi"] if selected else C["plate_lo"]))
        grad.setColorAt(1.0, QColor(C["plate_lo"]))
        tkey = resolve_theme_key(C.get("key", "seestation"))
        gframe = _theme_frame_path(r, tkey, rad_see=6.0, ch_gold=5.5)
        painter.setBrush(QBrush(grad))
        painter.setPen(QPen(QColor(C["sel_border"] if selected else C["line"]), 1.25 if selected else 0.85))
        painter.drawPath(gframe)
        if selected and tkey == "oriental":
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(QColor(C["acc_hi"]))
            painter.drawPolygon(QPolygonF([QPointF(r.left(), r.top()), QPointF(r.left() + 9, r.top()), QPointF(r.left(), r.top() + 9)]))
        img_r = r.adjusted(2.0, 2.0, -2.0, -12.0)
        if isinstance(pm, QPixmap) and not pm.isNull():
            scaled = pm.scaled(
                int(img_r.width()), int(img_r.height()),
                Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation,
            )
            ox = int(img_r.left() + (img_r.width() - scaled.width()) / 2)
            oy = int(img_r.top() + (img_r.height() - scaled.height()) / 2)
            painter.drawPixmap(ox, oy, scaled)
        else:
            painter.setPen(QColor(C["dim"]))
            painter.setFont(_font(8.0))
            painter.drawText(img_r, Qt.AlignmentFlag.AlignCenter, "\u2026")
        # Caption strip
        cap_r = QRectF(r.left() + 1, r.bottom() - 11, r.width() - 2, 10)
        painter.setPen(QColor(C["muted"]))
        painter.setFont(_font(7.0))
        short = model_short(str(meta.get("model", ""))) or ("UPS" if meta.get("tile_upscale") else "IMG")
        cap = short
        if isinstance(meta.get("aesthetic"), (int, float)):
            cap += f"  \u2605{float(meta['aesthetic']):.1f}"
        painter.drawText(cap_r, Qt.AlignmentFlag.AlignVCenter, cap)
        if meta.get("favorite"):
            painter.drawPixmap(int(r.right()) - 15, int(r.top()) + 2, VECTOR_ASSETS.pixmap("star_on", 13, 13))
        if meta.get("_has_depth"):
            painter.drawPixmap(int(r.right()) - 14, int(r.bottom()) - 13, VECTOR_ASSETS.pixmap("depth", 11, 11))
        painter.restore()

# =============================================================================
#  23. Paginated Output Gallery Browser (ACDSee / Pixiv style)
# =============================================================================
class GalleryBrowser(QWidget):
    """Paginated ACDSee/Pixiv-style output browser over outputs/ with search,
    model / aesthetic-score / favorites filters, tile sizing and safe actions."""

    ROLE_PATH = Qt.ItemDataRole.UserRole + 1
    ROLE_META = Qt.ItemDataRole.UserRole + 2
    ROLE_PIXMAP = Qt.ItemDataRole.UserRole + 3

    open_in_viewer = pyqtSignal(str)
    send_to_upscale = pyqtSignal(str)
    send_to_vlm = pyqtSignal(str)
    use_from_file = pyqtSignal(str, str, dict)  # what, path, meta
    favorite_toggled = pyqtSignal(str)
    settings_changed = pyqtSignal()
    # v4: editor / depth-map actions
    open_in_editor = pyqtSignal(str)
    request_depth = pyqtSignal(str)
    delete_depth = pyqtSignal(str)

    TILE_SIZES = {"S": 116, "M": 152, "L": 208}

    def __init__(self, output_dir: str, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.output_dir = output_dir
        self._all_entries: List[Dict[str, Any]] = []
        self._filtered: List[Dict[str, Any]] = []
        self._page = 0
        self._page_size = 60
        self._tile_key = "M"
        self._fav_only = False
        self._dirty = True
        self._thumb_cache: Dict[Tuple[str, int], QPixmap] = {}
        self._loader: Optional[GalleryThumbLoader] = None
        self._build()

    def _build(self) -> None:
        lay = QVBoxLayout(self)
        lay.setContentsMargins(4, 4, 4, 4)
        lay.setSpacing(4)

        # Filter toolbar row 1a (Search + Reload) & row 1b (Model / Score / Fav / Sort — zero overflow at 240px!)
        r1a = QHBoxLayout()
        r1a.setSpacing(3)
        self.search_edit = QLineEdit()
        self.search_edit.setPlaceholderText("Search prompt or filename\u2026")
        self.search_edit.setClearButtonEnabled(True)
        self.search_edit.setMinimumWidth(48)
        self.search_edit.textChanged.connect(lambda _t: self._apply_filters(reset_page=True))
        self.fav_btn = QToolButton()
        self.fav_btn.setObjectName("Small")
        self.fav_btn.setText("\u2605")
        self.fav_btn.setCheckable(True)
        self.fav_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.fav_btn.setToolTip("Show favorites only")
        self.fav_btn.toggled.connect(lambda _v: self._apply_filters(reset_page=True))
        self.reload_dir_btn = make_button("", self.reload_dir, small=True, tip="Refresh outputs/ folder", icon_key="reset", icon_size=13)
        r1a.addWidget(self.search_edit, 1)
        r1a.addWidget(self.fav_btn)
        r1a.addWidget(self.reload_dir_btn)
        lay.addLayout(r1a)

        r1b = QHBoxLayout()
        r1b.setSpacing(3)
        self.model_combo = QComboBox()
        model_shorts: List[str] = []
        for _mn, _ms in MODELS.items():
            if _ms["short"] not in model_shorts:
                model_shorts.append(_ms["short"])
        self.model_combo.addItems(["ALL"] + model_shorts)
        self.model_combo.setSizeAdjustPolicy(QComboBox.SizeAdjustPolicy.AdjustToMinimumContentsLengthWithIcon)
        self.model_combo.setMinimumContentsLength(4)
        self.model_combo.setMinimumWidth(52)
        self.model_combo.currentIndexChanged.connect(lambda _i: self._apply_filters(reset_page=True))
        self.score_spin = QDoubleSpinBox()
        self.score_spin.setRange(0.0, 10.0)
        self.score_spin.setSingleStep(0.5)
        self.score_spin.setDecimals(1)
        self.score_spin.setPrefix("\u2605\u2265")
        self.score_spin.setMinimumWidth(54)
        self.score_spin.setMaximumWidth(72)
        self.score_spin.setToolTip("Minimum Alchemy aesthetic score filter (0 = all)")
        self.score_spin.valueChanged.connect(lambda _v: self._apply_filters(reset_page=True))
        self.sort_combo = QComboBox()
        self.sort_combo.addItem("Newest", "date_desc")
        self.sort_combo.addItem("Oldest", "date_asc")
        self.sort_combo.addItem("Best \u2605", "score_desc")
        self.sort_combo.addItem("Name", "name_asc")
        self.sort_combo.setSizeAdjustPolicy(QComboBox.SizeAdjustPolicy.AdjustToMinimumContentsLengthWithIcon)
        self.sort_combo.setMinimumContentsLength(5)
        self.sort_combo.setMinimumWidth(58)
        self.sort_combo.currentIndexChanged.connect(self._on_sort_changed)
        r1b.addWidget(self.model_combo, 1)
        r1b.addWidget(self.score_spin, 0)
        r1b.addWidget(self.sort_combo, 1)
        lay.addLayout(r1b)

        # Toolbar row 2: Tile size + compact actions + paging (fits cleanly at 800x600)
        r2 = QHBoxLayout()
        r2.setSpacing(2)
        self.size_btns: Dict[str, QToolButton] = {}
        self._sz_grp = QButtonGroup(self)
        self._sz_grp.setExclusive(True)
        for k in ("S", "M", "L"):
            b = QToolButton()
            b.setObjectName("Small")
            b.setText(k)
            b.setCheckable(True)
            b.setChecked(k == "M")
            b.setFixedWidth(22)
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.clicked.connect(lambda _c=False, kk=k: self.set_tile_size(kk))
            self._sz_grp.addButton(b)
            self.size_btns[k] = b
            r2.addWidget(b)
        r2.addSpacing(2)
        for lbl_g, fn_g, tip_g in (
            ("Info", self._show_info, "Inspect metadata"),
            ("Prompt", self._copy_prompt, "Copy full prompt (Ctrl+P)"),
            ("Copy", self._copy_image, "Copy image to clipboard (Ctrl+C)"),
            ("Rename", self._rename_selected, "Rename file"),
            ("Del", self._delete_selected, "Delete selected image (Delete)"),
        ):
            gb = make_button(lbl_g, fn_g, small=True, tip=tip_g)
            gb.setMinimumWidth(0)
            gb.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Fixed)
            r2.addWidget(gb, 1)
        r2.addStretch(1)
        self.prev_btn = make_button("\u25C0", lambda: self._step_page(-1), small=True)
        self.prev_btn.setFixedWidth(24)
        self.page_lbl = make_label("0/0", "InfoBar")
        self.next_btn = make_button("\u25B6", lambda: self._step_page(1), small=True)
        self.next_btn.setFixedWidth(24)
        r2.addWidget(self.prev_btn)
        r2.addWidget(self.page_lbl)
        r2.addWidget(self.next_btn)
        lay.addLayout(r2)

        # Grid view
        self.view = QListWidget()
        self.view.setViewMode(QListView.ViewMode.IconMode)
        self.view.setFlow(QListView.Flow.LeftToRight)
        self.view.setWrapping(True)
        self.view.setMovement(QListView.Movement.Static)
        self.view.setResizeMode(QListView.ResizeMode.Adjust)
        self.view.setSelectionMode(QAbstractItemView.SelectionMode.ExtendedSelection)
        self.view.setUniformItemSizes(True)
        self.view.setSpacing(3)
        self._delegate = GalleryTileDelegate(self.TILE_SIZES["M"], self.view)
        self.view.setItemDelegate(self._delegate)
        self.view.itemDoubleClicked.connect(self._on_double_click)
        self.view.itemSelectionChanged.connect(self._update_status)
        self.view.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.view.customContextMenuRequested.connect(self._context_menu)
        lay.addWidget(self.view, 1)

        self.status_lbl = ElideLabel("outputs/ — 0 files")
        self.status_lbl.setObjectName("InfoBar")
        self.status_lbl.setMinimumHeight(22)
        lay.addWidget(self.status_lbl)

        QShortcut(QKeySequence("Ctrl+C"), self, activated=self._copy_image)
        QShortcut(QKeySequence("Ctrl+P"), self, activated=self._copy_prompt)
        QShortcut(QKeySequence(Qt.Key.Key_Delete), self.view, activated=self._delete_selected)

    def mark_dirty(self) -> None:
        self._dirty = True

    def ensure_loaded(self) -> None:
        if self._dirty:
            self.reload_dir()

    def set_preferences(self, sort_key: str, tile_key: str, page_size: int = 60, fav_only: bool = False) -> None:
        ix = self.sort_combo.findData(sort_key)
        if ix >= 0:
            self.sort_combo.blockSignals(True)
            self.sort_combo.setCurrentIndex(ix)
            self.sort_combo.blockSignals(False)
        self._page_size = max(12, min(200, int(page_size)))
        self._fav_only = bool(fav_only)
        self.fav_btn.setChecked(self._fav_only)
        self.set_tile_size(tile_key if tile_key in self.TILE_SIZES else "M", emit=False)

    def current_sort_key(self) -> str:
        return str(self.sort_combo.currentData() or "date_desc")

    def current_tile_key(self) -> str:
        return self._tile_key

    def is_fav_only(self) -> bool:
        return self.fav_btn.isChecked()

    def set_page(self, page: int) -> None:
        self._page = max(0, int(page))
        self._render_page()

    def current_page(self) -> int:
        return self._page

    def set_tile_size(self, key: str, emit: bool = True) -> None:
        if key not in self.TILE_SIZES:
            return
        self._tile_key = key
        for k, b in self.size_btns.items():
            b.setChecked(k == key)
        self._delegate.set_tile_px(self.TILE_SIZES[key])
        self._render_page()
        if emit:
            self.settings_changed.emit()

    def _on_sort_changed(self) -> None:
        self._apply_filters(reset_page=True)
        self.settings_changed.emit()

    def reload_dir(self) -> None:
        self._dirty = False
        entries: List[Dict[str, Any]] = []
        if os.path.isdir(self.output_dir):
            try:
                for fn in os.listdir(self.output_dir):
                    full = os.path.join(self.output_dir, fn)
                    if not os.path.isfile(full):
                        continue
                    if not fn.lower().endswith((".png", ".webp", ".jpg", ".jpeg")):
                        continue
                    if is_depth_image_path(fn):
                        continue  # depth attachments are badges, not gallery tiles
                    try:
                        st = os.stat(full)
                        mtime, fsize = st.st_mtime, st.st_size
                    except OSError:
                        mtime, fsize = 0.0, 0
                    meta = read_image_metadata(full)
                    meta["_has_depth"] = has_depth_map(full)
                    entries.append({"path": full, "name": fn, "mtime": mtime, "size": fsize, "meta": meta})
            except OSError:
                pass
        self._all_entries = entries
        self._apply_filters(reset_page=False)

    def on_meta_changed(self, path: str) -> None:
        for e in self._all_entries:
            if e["path"] == path:
                e["meta"] = read_image_metadata(path)
                e["meta"]["_has_depth"] = has_depth_map(path)
                break
        for i in range(self.view.count()):
            it = self.view.item(i)
            if it and it.data(self.ROLE_PATH) == path:
                meta = read_image_metadata(path)
                it.setData(self.ROLE_META, meta)
                it.setToolTip(gallery_tooltip(meta, path))
                self.view.viewport().update()
                break

    def _apply_filters(self, reset_page: bool = False) -> None:
        q = self.search_edit.text().strip().lower()
        m_filt = self.model_combo.currentText()
        min_sc = self.score_spin.value()
        fav_only = self.fav_btn.isChecked()
        res: List[Dict[str, Any]] = []
        for e in self._all_entries:
            meta = e["meta"]
            if m_filt != "ALL":
                short = model_short(str(meta.get("model", "")))
                if short != m_filt:
                    continue
            if min_sc > 0.0:
                sc = meta.get("aesthetic")
                if not isinstance(sc, (int, float)) or float(sc) < min_sc:
                    continue
            if fav_only and not meta.get("favorite"):
                continue
            if q:
                hay = f"{e['name']} {meta.get('prompt', '')} {meta.get('raw_prompt', '')}".lower()
                if q not in hay:
                    continue
            res.append(e)
        skey = self.current_sort_key()
        if skey == "date_asc":
            res.sort(key=lambda x: x["mtime"])
        elif skey == "score_desc":
            res.sort(key=lambda x: (float(x["meta"].get("aesthetic") or -1.0), x["mtime"]), reverse=True)
        elif skey == "name_asc":
            res.sort(key=lambda x: x["name"].lower())
        else:
            res.sort(key=lambda x: x["mtime"], reverse=True)
        self._filtered = res
        if reset_page:
            self._page = 0
        self._render_page()

    def _render_page(self) -> None:
        self._stop_loader()
        total = len(self._filtered)
        pages = max(1, math.ceil(total / self._page_size))
        self._page = max(0, min(self._page, pages - 1))
        start = self._page * self._page_size
        chunk = self._filtered[start : start + self._page_size]
        self.page_lbl.setText(f"{self._page + 1}/{pages}" if total else "0/0")
        self.prev_btn.setEnabled(self._page > 0)
        self.next_btn.setEnabled(self._page + 1 < pages)

        px = self.TILE_SIZES[self._tile_key]
        self.view.clear()
        to_load: List[str] = []
        for e in chunk:
            it = QListWidgetItem()
            it.setData(self.ROLE_PATH, e["path"])
            it.setData(self.ROLE_META, e["meta"])
            it.setToolTip(gallery_tooltip(e["meta"], e["path"]))
            cached = self._thumb_cache.get((e["path"], px))
            if cached is not None:
                it.setData(self.ROLE_PIXMAP, cached)
            else:
                to_load.append(e["path"])
            self.view.addItem(it)

        self._update_status()
        if to_load:
            self._loader = GalleryThumbLoader(to_load, px, self)
            self._loader.loaded.connect(lambda p, img, sz=px: self._on_thumb_loaded(p, img, sz))
            self._loader.start()

    def _stop_loader(self) -> None:
        if self._loader is not None:
            self._loader.stop()
            self._loader.wait(500)
            self._loader.deleteLater()
            self._loader = None

    def _on_thumb_loaded(self, path: str, img: QImage, px: int) -> None:
        pm = QPixmap.fromImage(img)
        if len(self._thumb_cache) > 400:
            self._thumb_cache.clear()
        self._thumb_cache[(path, px)] = pm
        for i in range(self.view.count()):
            it = self.view.item(i)
            if it and it.data(self.ROLE_PATH) == path:
                it.setData(self.ROLE_PIXMAP, pm)
                self.view.viewport().update()
                break

    def _step_page(self, delta: int) -> None:
        self._page += delta
        self._render_page()
        self.settings_changed.emit()

    def _selected_items(self) -> List[QListWidgetItem]:
        return self.view.selectedItems()

    def _current_entry(self) -> Optional[Tuple[str, Dict[str, Any]]]:
        items = self._selected_items()
        it = items[0] if items else self.view.currentItem()
        if it is None:
            return None
        return str(it.data(self.ROLE_PATH)), dict(it.data(self.ROLE_META) or {})

    def _update_status(self) -> None:
        sel = self._selected_items()
        base = f"{len(self._filtered)} / {len(self._all_entries)} images in outputs/"
        if len(sel) == 1:
            p = str(sel[0].data(self.ROLE_PATH))
            m = sel[0].data(self.ROLE_META) or {}
            kb = (os.path.getsize(p) / 1024.0) if os.path.isfile(p) else 0.0
            dim = f"{m.get('width', '?')}\u00d7{m.get('height', '?')}" if m.get("width") else ""
            self.status_lbl.setText(f"{base}  \u2022  {os.path.basename(p)}  {dim}  ({kb:.0f} KB)")
        elif len(sel) > 1:
            self.status_lbl.setText(f"{base}  \u2022  {len(sel)} selected")
        else:
            self.status_lbl.setText(base)

    def _on_double_click(self, item: QListWidgetItem) -> None:
        p = str(item.data(self.ROLE_PATH) or "")
        if p:
            self.open_in_viewer.emit(p)

    def _toggle_favorite(self) -> None:
        items = self._selected_items()
        if not items:
            return
        for it in items:
            p = str(it.data(self.ROLE_PATH) or "")
            meta = dict(it.data(self.ROLE_META) or {})
            if not p:
                continue
            new_val = not meta.get("favorite")
            meta = update_image_metadata(p, {"favorite": new_val})
            it.setData(self.ROLE_META, meta)
            it.setToolTip(gallery_tooltip(meta, p))
            self.favorite_toggled.emit(p)
        self.view.viewport().update()
        self._update_status()

    def _show_info(self) -> None:
        cur = self._current_entry()
        if cur:
            ImageInfoDialog(cur[0], cur[1], self).exec()

    def _copy_prompt(self, raw: bool = False) -> None:
        cur = self._current_entry()
        if not cur:
            return
        m = cur[1]
        txt = str(m.get("raw_prompt") if raw else m.get("prompt") or m.get("raw_prompt") or "")
        if txt:
            QApplication.clipboard().setText(txt)

    def _copy_image(self) -> None:
        cur = self._current_entry()
        if not cur:
            return
        img = QImage(cur[0])
        if not img.isNull():
            QApplication.clipboard().setImage(img)

    def _rename_selected(self) -> None:
        cur = self._current_entry()
        if not cur:
            return
        old_path = cur[0]
        old_name = os.path.basename(old_path)
        stem, ext = os.path.splitext(old_name)
        new_stem, ok = QInputDialog.getText(self, "Rename image", "New filename (without extension):", text=stem)
        if not ok or not new_stem.strip() or new_stem.strip() == stem:
            return
        safe = re.sub(r'[<>:"/\\|?*]', "_", new_stem.strip())
        new_path = os.path.join(os.path.dirname(old_path), safe + ext)
        if os.path.exists(new_path):
            QMessageBox.warning(self, "Rename failed", "A file with that name already exists.")
            return
        try:
            os.rename(old_path, new_path)
            old_sc = os.path.splitext(old_path)[0] + ".json"
            if os.path.isfile(old_sc):
                os.rename(old_sc, os.path.splitext(new_path)[0] + ".json")
        except OSError as exc:
            QMessageBox.warning(self, "Rename failed", str(exc))
            return
        self.reload_dir()

    def _delete_selected(self) -> None:
        items = self._selected_items()
        if not items:
            return
        for it in items:
            p = str(it.data(self.ROLE_PATH) or "")
            for cand in (p, os.path.splitext(p)[0] + ".json"):
                if os.path.isfile(cand):
                    try:
                        os.remove(cand)
                    except OSError:
                        pass
        self.reload_dir()

    def _context_menu(self, pos: QPoint) -> None:
        it = self.view.itemAt(pos)
        if it is None:
            return
        if not it.isSelected():
            self.view.clearSelection()
            it.setSelected(True)
        p = str(it.data(self.ROLE_PATH))
        meta = dict(it.data(self.ROLE_META) or {})
        m = QMenu(self)
        m.addAction("Open in Viewer", lambda: self.open_in_viewer.emit(p))
        m.addAction(
            ("\u2605 Unfavorite" if meta.get("favorite") else "\u2606 Add to Favorites"),
            self._toggle_favorite,
        )
        m.addAction("Send to Tile Upscale", lambda: self.send_to_upscale.emit(p))
        m.addAction("Edit in Image Editor", lambda: self.open_in_editor.emit(p))
        m.addAction("Extract t2i Prompt via VLM", lambda: self.send_to_vlm.emit(p))
        m.addSeparator()
        if has_depth_map(p):
            m.addAction("Re-request Depth Map (Depth Anything V2)", lambda: self.request_depth.emit(p))
            m.addAction("Delete Depth Map", lambda: self.delete_depth.emit(p))
        else:
            m.addAction("Request Depth Map (Depth Anything V2)", lambda: self.request_depth.emit(p))
        m.addSeparator()
        m.addAction("Inspect Metadata / Parameters\u2026", self._show_info)
        m.addSeparator()
        m.addAction("Use Prompt in Editor", lambda: self.use_from_file.emit("prompt", p, meta))
        m.addAction("Use Seed", lambda: self.use_from_file.emit("seed", p, meta))
        m.addAction("Use Everything (Prompt, Model, Size, LoRAs)", lambda: self.use_from_file.emit("all", p, meta))
        m.addSeparator()
        m.addAction("Copy Full Prompt", lambda: self._copy_prompt(False))
        m.addAction("Copy Unique (Pre-Template) Prompt", lambda: self._copy_prompt(True))
        m.addAction("Copy Image to Clipboard", self._copy_image)
        m.addAction("Copy File Path", lambda: QApplication.clipboard().setText(p))
        m.addSeparator()
        m.addAction("Open with System Viewer", lambda: open_path(p))
        m.addAction("Open outputs/ Folder", lambda: open_path(self.output_dir))
        m.addAction("Rename\u2026", self._rename_selected)
        m.addAction("Delete Selected", self._delete_selected)
        m.exec(self.view.viewport().mapToGlobal(pos))

    def step_slideshow(self) -> Optional[str]:
        if not self._filtered:
            return None
        cur = self.view.currentRow()
        nxt = (cur + 1) % max(1, self.view.count())
        self.view.setCurrentRow(nxt)
        it = self.view.item(nxt)
        return str(it.data(self.ROLE_PATH)) if it else None

    def shutdown(self) -> None:
        self._stop_loader()

