class HistoryDialog(QDialog):
    """Prompt History browser: restore, pin, delete, clear all."""

    def __init__(self, entries: List[Dict[str, Any]], parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setWindowTitle("Prompt History")
        self.entries = entries  # newest-first; mutated in place
        self.result_action = ""      # "restore" | "restore_prompt" | ""
        self.result_entry: Optional[Dict[str, Any]] = None
        self._build()
        self._refill()

    def _build(self) -> None:
        lay = QVBoxLayout(self)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        hdr = SectionHeader("Recent Submissions (per model)")
        self.search_ed = QLineEdit()
        self.search_ed.setPlaceholderText("Filter prompts\u2026")
        self.search_ed.setClearButtonEnabled(True)
        self.search_ed.textChanged.connect(lambda _t: self._refill())
        hdr.add_right(self.search_ed)
        lay.addWidget(hdr)

        self.list_w = QListWidget()
        self.list_w.setAlternatingRowColors(True)
        self.list_w.itemDoubleClicked.connect(lambda _it: self._do_restore())
        lay.addWidget(self.list_w, 1)

        row = QHBoxLayout()
        row.addWidget(make_button("RESTORE ALL", self._do_restore, accent=True,
                                  tip="Restore prompt, negative and seed into the editor"))
        row.addWidget(make_button("PROMPT ONLY", self._do_restore_prompt))
        row.addWidget(make_button("PIN / UNPIN", self._toggle_pin, small=True,
                                  icon_key="pin", tip="Pinned entries are never trimmed"))
        row.addWidget(make_button("DELETE", self._delete, small=True))
        row.addWidget(make_button("CLEAR UNPINNED", self._clear_unpinned, small=True))
        row.addStretch(1)
        row.addWidget(make_button("CLOSE", self.reject, small=True))
        lay.addLayout(row)
        apply_adaptive_dialog_geometry(self, 660, 480, min_w=480, min_h=360)

    def _refill(self) -> None:
        q = self.search_ed.text().strip().lower()
        self._visible: List[int] = []
        self.list_w.clear()
        for idx, e in enumerate(self.entries):
            if q and q not in f"{e.get('prompt', '')} {e.get('model', '')}".lower():
                continue
            self._visible.append(idx)
            t = time.strftime("%m-%d %H:%M", time.localtime(e.get("ts") or 0))
            model = model_short(e.get("model", "")) or "?"
            pin = "\u2605 " if e.get("pinned") else ""
            it = QListWidgetItem(f"{pin}{t}  [{model}]  {elide(e.get('prompt', ''), 72)}")
            it.setToolTip(e.get("prompt", ""))
            self.list_w.addItem(it)

    def _sel_index(self) -> int:
        row = self.list_w.currentRow()
        if 0 <= row < len(getattr(self, "_visible", [])):
            return self._visible[row]
        return -1

    def _do_restore(self) -> None:
        idx = self._sel_index()
        if idx >= 0:
            self.result_action = "restore"
            self.result_entry = self.entries[idx]
            self.accept()

    def _do_restore_prompt(self) -> None:
        idx = self._sel_index()
        if idx >= 0:
            self.result_action = "restore_prompt"
            self.result_entry = self.entries[idx]
            self.accept()

    def _toggle_pin(self) -> None:
        idx = self._sel_index()
        if idx >= 0:
            self.entries[idx]["pinned"] = not self.entries[idx].get("pinned")
            self._refill()

    def _delete(self) -> None:
        idx = self._sel_index()
        if idx >= 0:
            self.entries.pop(idx)
            self._refill()

    def _clear_unpinned(self) -> None:
        self.entries[:] = [e for e in self.entries if e.get("pinned")]
        self._refill()


class LoraEditorDialog(QDialog):
    """Full Add/Edit LoRA Dialog (v3 remaster):
    - Civitai Model / Version ID + live Civitai lookup
    - Folder selection (Improve-Overall, Style, Slider, or custom folder)
    - Preferred strength (Model & CLIP) + current strength
    - Optional horizontal slider mode + configurable min/max range
    - Multi-variant manual trigger words editor (Add / Edit / Remove / Copy / Insert)

    v3 FIX for the v2 sizing glitch: the whole editor body now lives inside a
    QScrollArea and the dialog geometry is computed adaptively from the
    available screen area, so every control (including the bottom button row)
    is always fully visible — even on an 800x600 laptop display."""

    def __init__(
        self,
        entry: Optional[Dict[str, Any]],
        folders: List[str],
        api: HordeAPI,
        parent: Optional[QWidget] = None,
    ) -> None:
        super().__init__(parent)
        self.api = api
        self._is_new = entry is None
        self.data = normalize_lora_entry(
            entry
            or {
                "folder": "Improve-Overall",
                "model": 1.0,
                "clip": 1.0,
                "preferred_strength": 1.0,
                "preferred_clip": 1.0,
                "is_version": True,  # v5: Civitai VERSION-ID lookup on by default
            }
        )
        self._folders = list(folders)
        self._lookup_thread: Optional[TaskThread] = None
        self.setWindowTitle("Add LoRA Entry" if self._is_new else f"Edit LoRA — {self.data.get('name') or self.data.get('id')}")
        self.setSizeGripEnabled(True)
        self._build()
        self._load_fields()
        # Adaptive, never-clipped geometry (the v2 bug fix): preferred height is
        # derived from the actual editor body so the dialog opens tall enough to
        # show every control without scrolling whenever the screen allows it.
        body_min = self._body_lay.totalMinimumSize()
        apply_adaptive_dialog_geometry(self, 620, body_min.height() + 118, min_w=540, min_h=420)
        QTimer.singleShot(0, self._ensure_ok_button_visible)
        # v5: quick-add prefilled with a Civitai ID -> fetch it automatically
        if self._is_new and str(self.data.get("id") or "").strip():
            QTimer.singleShot(220, self._do_lookup)

    def _ensure_ok_button_visible(self) -> None:
        """Second-pass guarantee: if the scrolled content is taller than the
        dialog, extend the dialog (clamped to the screen) so the OK / Cancel
        row remains immediately reachable."""
        btn = getattr(self, "_btn_box", None)
        scroll = getattr(self, "_scroll", None)
        if btn is None or scroll is None:
            return
        need_h = btn.mapTo(self, QPoint(0, 0)).y() + btn.height() + 14
        if need_h > self.height():
            screen = self.screen() if hasattr(self, "screen") else QApplication.primaryScreen()
            avail_h = screen.availableGeometry().height() - 40 if screen else 720
            self.resize(self.width(), min(max(self.height(), need_h), avail_h))

    def _build(self) -> None:
        outer = QVBoxLayout(self)
        outer.setContentsMargins(9, 9, 9, 9)
        outer.setSpacing(5)

        # Scrollable body — the heart of the v3 sizing fix
        self._scroll = QScrollArea()
        self._scroll.setWidgetResizable(True)
        self._scroll.setFrameShape(QFrame.Shape.NoFrame)
        self._scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        body = QWidget()
        body.setObjectName("Transparent")
        lay = QVBoxLayout(body)
        lay.setContentsMargins(2, 2, 2, 2)
        lay.setSpacing(6)
        self._body_lay = lay
        self._scroll.setWidget(body)
        outer.addWidget(self._scroll, 1)

        lay.addWidget(SectionHeader("LoRA Identity & Folder"))
        form = QGridLayout()
        form.setHorizontalSpacing(6)
        form.setVerticalSpacing(5)

        self.id_edit = QLineEdit()
        self.id_edit.setPlaceholderText("Civitai model ID, version ID, or exact Horde LoRA name")
        self.ver_cb = QCheckBox("Version ID")
        self.lookup_btn = make_button("FETCH CIVITAI", self._do_lookup, small=True, accent=True)
        self.id_edit.returnPressed.connect(self._do_lookup)
        id_row = QHBoxLayout()
        id_row.setSpacing(4)
        id_row.addWidget(self.id_edit, 1)
        id_row.addWidget(self.ver_cb)
        id_row.addWidget(self.lookup_btn)

        self.name_edit = QLineEdit()
        self.name_edit.setPlaceholderText("Display name (e.g., Flat Color Anime Style)")

        self.folder_combo = QComboBox()
        self.folder_combo.setEditable(True)
        for fn in self._folders:
            self.folder_combo.addItem(fn)
        self.folder_combo.currentTextChanged.connect(self._on_folder_changed)

        self.enabled_cb = QCheckBox("Enabled for active model")
        self.inject_edit = QLineEdit()
        self.inject_edit.setPlaceholderText("Optional Horde auto-inject_trigger (blank or 'any')")

        form.addWidget(make_label("Civitai ID", "Caption"), 0, 0)
        form.addLayout(id_row, 0, 1)
        form.addWidget(make_label("Name", "Caption"), 1, 0)
        form.addWidget(self.name_edit, 1, 1)
        form.addWidget(make_label("Folder", "Caption"), 2, 0)
        frow = QHBoxLayout()
        frow.addWidget(self.folder_combo, 1)
        frow.addWidget(self.enabled_cb)
        form.addLayout(frow, 2, 1)
        form.addWidget(make_label("Auto-Inject", "Caption"), 3, 0)
        form.addWidget(self.inject_edit, 3, 1)
        form.setColumnStretch(1, 1)
        lay.addLayout(form)

        self.lookup_status = make_label("", "Caption")
        lay.addWidget(self.lookup_status)

        # Strength & Optional Horizontal Slider
        lay.addWidget(SectionHeader("Strength & Optional Horizontal Slider"))
        sg = QGridLayout()
        sg.setHorizontalSpacing(6)
        sg.setVerticalSpacing(4)
        self.pref_m_spin = QDoubleSpinBox()
        self.pref_c_spin = QDoubleSpinBox()
        self.cur_m_spin = QDoubleSpinBox()
        self.cur_c_spin = QDoubleSpinBox()
        for sp in (self.pref_m_spin, self.pref_c_spin, self.cur_m_spin, self.cur_c_spin):
            sp.setRange(-5.0, 5.0)
            sp.setSingleStep(0.05)
            sp.setDecimals(2)
        sg.addWidget(make_label("Preferred Model", "Caption"), 0, 0)
        sg.addWidget(self.pref_m_spin, 0, 1)
        sg.addWidget(make_label("Preferred CLIP", "Caption"), 0, 2)
        sg.addWidget(self.pref_c_spin, 0, 3)
        sg.addWidget(make_label("Current Model", "Caption"), 1, 0)
        sg.addWidget(self.cur_m_spin, 1, 1)
        sg.addWidget(make_label("Current CLIP", "Caption"), 1, 2)
        sg.addWidget(self.cur_c_spin, 1, 3)

        self.slider_cb = QCheckBox("Enable live horizontal weight slider on LoRA card & Prompt drawer")
        self.slider_cb.toggled.connect(self._update_slider_bounds_enabled)
        self.link_cb = QCheckBox("Link CLIP to slider")
        self.smin_spin = QDoubleSpinBox()
        self.smax_spin = QDoubleSpinBox()
        for sp in (self.smin_spin, self.smax_spin):
            sp.setRange(-5.0, 5.0)
            sp.setSingleStep(0.5)
            sp.setDecimals(2)
        sl_row = QHBoxLayout()
        sl_row.addWidget(self.slider_cb, 1)
        sl_row.addWidget(self.link_cb)
        sl_row.addWidget(make_button(
            "PREF \u2192 CUR", self._pref_to_current, small=True,
            tip="Copy the preferred strengths onto the current strengths",
        ))
        lay.addLayout(sg)
        lay.addLayout(sl_row)
        rng_row = QHBoxLayout()
        rng_row.addWidget(make_label("Slider Min", "Caption"))
        rng_row.addWidget(self.smin_spin)
        rng_row.addWidget(make_label("Slider Max", "Caption"))
        rng_row.addWidget(self.smax_spin)
        rng_row.addStretch(1)
        lay.addLayout(rng_row)

        # Multi-Variant Manual Trigger Words
        lay.addWidget(SectionHeader("Trigger Words (Multiple Manual Variants)"))
        self.trig_list = QListWidget()
        self.trig_list.setMinimumHeight(86)
        self.trig_list.setMaximumHeight(150)
        self.trig_list.currentRowChanged.connect(self._on_trig_selected)
        lay.addWidget(self.trig_list)

        ed_row = QHBoxLayout()
        ed_row.setSpacing(4)
        self.tv_label = QLineEdit()
        self.tv_label.setPlaceholderText("Variant name (e.g. Default / Outfit A / Strong)")
        self.tv_label.setFixedWidth(150)
        self.tv_text = QLineEdit()
        self.tv_text.setPlaceholderText("Trigger words to insert or copy\u2026")
        self.tv_text.returnPressed.connect(self._add_trigger_variant)
        ed_row.addWidget(self.tv_label)
        ed_row.addWidget(self.tv_text, 1)
        lay.addLayout(ed_row)

        tb_row = QHBoxLayout()
        tb_row.setSpacing(4)
        tb_row.addWidget(make_button("+ ADD VARIANT", self._add_trigger_variant, small=True, accent=True))
        tb_row.addWidget(make_button("UPDATE SELECTED", self._update_trigger_variant, small=True))
        tb_row.addWidget(make_button("REMOVE", self._remove_trigger_variant, small=True))
        tb_row.addWidget(make_button("COPY", self._copy_trigger_variant, small=True))
        tb_row.addWidget(make_button("USE", self._use_trigger_variant, small=True,
                                     tip="Mark the selected variant as the active ghost/auto trigger"))
        tb_row.addWidget(make_button("DUP", self._dup_trigger_variant, small=True,
                                     tip="Duplicate the selected variant"))
        tb_row.addStretch(1)
        lay.addLayout(tb_row)

        self.notes_edit = QLineEdit()
        self.notes_edit.setPlaceholderText("Optional notes (compatible checkpoint, recommended CFG, etc.)")
        lay.addWidget(self.notes_edit)
        lay.addStretch(1)

        # Always-visible footer outside the scroll area
        self._btn_box = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
        self._btn_box.accepted.connect(self._on_accept)
        self._btn_box.rejected.connect(self.reject)
        outer.addWidget(self._btn_box)

    def _load_fields(self) -> None:
        d = self.data
        self.id_edit.setText(d["id"])
        self.ver_cb.setChecked(d["is_version"])
        self.name_edit.setText(d["name"])
        ix = self.folder_combo.findText(d["folder"])
        if ix >= 0:
            self.folder_combo.setCurrentIndex(ix)
        else:
            self.folder_combo.setEditText(d["folder"])
        self.enabled_cb.setChecked(d["enabled"])
        self.inject_edit.setText(d["inject_trigger"])
        self.pref_m_spin.setValue(d["preferred_strength"])
        self.pref_c_spin.setValue(d["preferred_clip"])
        self.cur_m_spin.setValue(d["model"])
        self.cur_c_spin.setValue(d["clip"])
        self.slider_cb.setChecked(d["use_slider"])
        self.link_cb.setChecked(d["link_clip"])
        self.smin_spin.setValue(d["slider_min"])
        self.smax_spin.setValue(d["slider_max"])
        self.notes_edit.setText(d["notes"])
        self._update_slider_bounds_enabled()
        self._refill_triggers()

    def _on_folder_changed(self, text: str) -> None:
        if text.strip() == "Slider" and self._is_new:
            self.slider_cb.setChecked(True)
            if self.smin_spin.value() >= 0.0:
                self.smin_spin.setValue(-2.0)

    def _update_slider_bounds_enabled(self) -> None:
        on = self.slider_cb.isChecked()
        self.smin_spin.setEnabled(on)
        self.smax_spin.setEnabled(on)
        self.link_cb.setEnabled(on)

    def _refill_triggers(self) -> None:
        self.trig_list.clear()
        sel = 0
        try:
            sel = max(0, int(self.data.get("trigger_sel", 0)))
        except (TypeError, ValueError):
            sel = 0
        for idx, tv in enumerate(self.data["triggers"]):
            mark = "\u25b8 " if idx == sel else ""
            it = QListWidgetItem(f"{mark}[{tv['label']}]  {tv['text']}")
            it.setData(Qt.ItemDataRole.UserRole, dict(tv))
            self.trig_list.addItem(it)

    def _on_trig_selected(self, row: int) -> None:
        if 0 <= row < len(self.data["triggers"]):
            tv = self.data["triggers"][row]
            self.tv_label.setText(tv["label"])
            self.tv_text.setText(tv["text"])

    def _add_trigger_variant(self) -> None:
        txt = self.tv_text.text().strip()
        if not txt:
            return
        lbl = self.tv_label.text().strip() or f"Variant {len(self.data['triggers']) + 1}"
        self.data["triggers"].append({"label": lbl, "text": txt})
        self._refill_triggers()
        self.trig_list.setCurrentRow(len(self.data["triggers"]) - 1)
        self.tv_label.clear()
        self.tv_text.clear()

    def _update_trigger_variant(self) -> None:
        row = self.trig_list.currentRow()
        txt = self.tv_text.text().strip()
        if not (0 <= row < len(self.data["triggers"])) or not txt:
            return
        lbl = self.tv_label.text().strip() or f"Variant {row + 1}"
        self.data["triggers"][row] = {"label": lbl, "text": txt}
        self._refill_triggers()
        self.trig_list.setCurrentRow(row)

    def _remove_trigger_variant(self) -> None:
        row = self.trig_list.currentRow()
        if 0 <= row < len(self.data["triggers"]):
            self.data["triggers"].pop(row)
            self._refill_triggers()

    def _copy_trigger_variant(self) -> None:
        txt = self.tv_text.text().strip()
        if not txt:
            row = self.trig_list.currentRow()
            if 0 <= row < len(self.data["triggers"]):
                txt = self.data["triggers"][row]["text"]
        if txt:
            QApplication.clipboard().setText(txt)
            self.lookup_status.setText("Trigger variant copied to clipboard.")

    def _pref_to_current(self) -> None:
        self.cur_m_spin.setValue(self.pref_m_spin.value())
        self.cur_c_spin.setValue(self.pref_c_spin.value())
        self.lookup_status.setText("Preferred strengths copied to current.")

    def _use_trigger_variant(self) -> None:
        row = self.trig_list.currentRow()
        if 0 <= row < len(self.data["triggers"]):
            self.data["trigger_sel"] = row
            self._refill_triggers()
            self.trig_list.setCurrentRow(row)

    def _dup_trigger_variant(self) -> None:
        row = self.trig_list.currentRow()
        if 0 <= row < len(self.data["triggers"]):
            tv = dict(self.data["triggers"][row])
            tv["label"] = tv.get("label", "Variant") + " (copy)"
            self.data["triggers"].insert(row + 1, tv)
            self._refill_triggers()
            self.trig_list.setCurrentRow(row + 1)

    def _do_lookup(self) -> None:
        ident = self.id_edit.text().strip()
        if not ident:
            self.lookup_status.setText("Enter a Civitai model or version ID first.")
            return
        self.lookup_btn.setEnabled(False)
        self.lookup_status.setText("Querying Civitai API\u2026")
        is_ver = self.ver_cb.isChecked()
        th = TaskThread(lambda: self.api.civitai_lookup(ident, is_ver), self)
        th.done.connect(self._on_lookup_done)
        th.error.connect(self._on_lookup_err)
        self._lookup_thread = th
        th.start()

    def _on_lookup_done(self, info: Dict[str, Any]) -> None:
        self.lookup_btn.setEnabled(True)
        if info.get("name") and not self.name_edit.text().strip():
            self.name_edit.setText(str(info["name"]))
        words = [str(w).strip() for w in (info.get("trained_words") or []) if str(w).strip()]
        if words:
            joined = ", ".join(words)
            if not any(tv["text"] == joined for tv in self.data["triggers"]):
                self.data["triggers"].append({"label": "Civitai All", "text": joined})
            if len(words) > 1:
                for i, w in enumerate(words[:5], 1):
                    if not any(tv["text"] == w for tv in self.data["triggers"]):
                        self.data["triggers"].append({"label": f"Word {i}", "text": w})
            self._refill_triggers()
        base = info.get("base") or "?"
        self.lookup_status.setText(f"Found: {info.get('name', '?')}  (Base: {base}, {len(words)} trigger word(s))")

    def _on_lookup_err(self, msg: str) -> None:
        self.lookup_btn.setEnabled(True)
        self.lookup_status.setText(f"Lookup error: {msg}")

    def _on_accept(self) -> None:
        ident = self.id_edit.text().strip()
        if not ident:
            QMessageBox.warning(self, "Missing ID", "Please provide a Civitai model/version ID or LoRA name.")
            return
        # Auto-commit any typed unsaved trigger variant
        if self.tv_text.text().strip() and not any(
            tv["text"] == self.tv_text.text().strip() for tv in self.data["triggers"]
        ):
            self._add_trigger_variant()
        s_min, s_max = self.smin_spin.value(), self.smax_spin.value()
        if s_max <= s_min:
            s_max = s_min + 1.0
        folder = self.folder_combo.currentText().strip() or "Improve-Overall"
        self.data.update({
            "id": ident,
            "is_version": self.ver_cb.isChecked(),
            "name": self.name_edit.text().strip() or f"LoRA #{ident}",
            "folder": folder,
            "enabled": self.enabled_cb.isChecked(),
            "preferred_strength": round(self.pref_m_spin.value(), 2),
            "preferred_clip": round(self.pref_c_spin.value(), 2),
            "model": round(self.cur_m_spin.value(), 2),
            "clip": round(self.cur_c_spin.value(), 2),
            "use_slider": self.slider_cb.isChecked(),
            "link_clip": self.link_cb.isChecked(),
            "slider_min": round(s_min, 2),
            "slider_max": round(s_max, 2),
            "inject_trigger": self.inject_edit.text().strip(),
            "notes": self.notes_edit.text().strip(),
        })
        self.accept()

class TemplateEditorDialog(QDialog):
    def __init__(self, tset: str, templates: List[Dict[str, str]], sample_prompt: str, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.tset = tset
        self.templates = [dict(t) for t in templates]
        self.sample_prompt = sample_prompt or "1girl, silver hair, neon city night"
        self.setWindowTitle(f"Template Editor — {tset.upper()}")
        self._build()
        self._refill(0 if self.templates else -1)
        apply_adaptive_dialog_geometry(self, 640, 460, min_w=500, min_h=360)

    def _build(self) -> None:
        lay = QVBoxLayout(self)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        split = QSplitter(Qt.Orientation.Horizontal)

        left = QWidget()
        ll = QVBoxLayout(left)
        ll.setContentsMargins(0, 0, 4, 0)
        self.list_w = QListWidget()
        self.list_w.currentRowChanged.connect(self._on_sel)
        ll.addWidget(self.list_w, 1)
        lr = QHBoxLayout()
        lr.addWidget(make_button("+ NEW", self._add, small=True, accent=True))
        lr.addWidget(make_button("DUP", self._dup, small=True))
        lr.addWidget(make_button("Delete", self._del, small=True))
        lr.addWidget(make_button("\u25B2", lambda: self._move(-1), small=True))
        lr.addWidget(make_button("\u25BC", lambda: self._move(1), small=True))
        ll.addLayout(lr)

        right = QWidget()
        rl = QVBoxLayout(right)
        rl.setContentsMargins(4, 0, 0, 0)
        rl.addWidget(make_label("Template Name", "Kicker"))
        self.name_ed = QLineEdit()
        self.name_ed.textEdited.connect(self._sync_cur)
        rl.addWidget(self.name_ed)
        rl.addWidget(make_label("Template Body  (use {{insert}} for prompt position)", "Kicker"))
        self.body_ed = QPlainTextEdit()
        self.body_ed.textChanged.connect(self._sync_cur)
        rl.addWidget(self.body_ed, 2)
        self.val_lbl = make_label("", "Caption")
        rl.addWidget(self.val_lbl)
        rl.addWidget(make_label("Live Composed Preview", "Kicker"))
        self.prev_ed = QPlainTextEdit()
        self.prev_ed.setReadOnly(True)
        self.prev_ed.setMaximumHeight(95)
        rl.addWidget(self.prev_ed, 1)

        split.addWidget(left)
        split.addWidget(right)
        split.setStretchFactor(0, 1)
        split.setStretchFactor(1, 2)
        lay.addWidget(split, 1)

        btns = QDialogButtonBox(QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Cancel)
        btns.accepted.connect(self.accept)
        btns.rejected.connect(self.reject)
        lay.addWidget(btns)

    def _refill(self, sel: int) -> None:
        self._busy = True
        self.list_w.clear()
        for t in self.templates:
            self.list_w.addItem(t.get("name") or "Template")
        self._busy = False
        if 0 <= sel < len(self.templates):
            self.list_w.setCurrentRow(sel)
        else:
            self._on_sel(-1)

    def _on_sel(self, row: int) -> None:
        self._busy = True
        if 0 <= row < len(self.templates):
            t = self.templates[row]
            self.name_ed.setEnabled(True)
            self.body_ed.setEnabled(True)
            self.name_ed.setText(t["name"])
            self.body_ed.setPlainText(t["body"])
        else:
            self.name_ed.setEnabled(False)
            self.body_ed.setEnabled(False)
            self.name_ed.clear()
            self.body_ed.clear()
        self._busy = False
        self._update_preview()

    def _sync_cur(self) -> None:
        if getattr(self, "_busy", False):
            return
        row = self.list_w.currentRow()
        if not (0 <= row < len(self.templates)):
            return
        nm = self.name_ed.text().strip() or "Template"
        bd = self.body_ed.toPlainText().strip()
        self.templates[row] = {"name": nm, "body": bd}
        it = self.list_w.item(row)
        if it:
            it.setText(nm)
        self._update_preview()

    def _update_preview(self) -> None:
        bd = self.body_ed.toPlainText().strip()
        if not bd:
            self.val_lbl.setText("")
            self.prev_ed.clear()
            return
        if "{{insert}}" in bd:
            self.val_lbl.setText("\u2713 Contains {{insert}} placeholder")
            self.val_lbl.setStyleSheet(f"color: {C['ok']};")
        else:
            self.val_lbl.setText("\u26A0 No {{insert}} marker — prompt will be appended to the end")
            self.val_lbl.setStyleSheet(f"color: {C['warn']};")
        self.prev_ed.setPlainText(apply_template(bd, self.sample_prompt))

    def _add(self) -> None:
        self.templates.append({"name": "New Template", "body": "{{insert}}"})
        self._refill(len(self.templates) - 1)

    def _dup(self) -> None:
        r = self.list_w.currentRow()
        if 0 <= r < len(self.templates):
            c = dict(self.templates[r])
            c["name"] = c["name"] + " (copy)"
            self.templates.insert(r + 1, c)
            self._refill(r + 1)

    def _del(self) -> None:
        r = self.list_w.currentRow()
        if 0 <= r < len(self.templates):
            self.templates.pop(r)
            self._refill(min(r, len(self.templates) - 1))

    def _move(self, delta: int) -> None:
        r = self.list_w.currentRow()
        t = r + delta
        if 0 <= r < len(self.templates) and 0 <= t < len(self.templates):
            self.templates[r], self.templates[t] = self.templates[t], self.templates[r]
            self._refill(t)


class TagEditorDialog(QDialog):
    def __init__(self, folders: List[str], groups: Dict[str, List[Dict[str, str]]], parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.folders = list(folders)
        self.groups = {k: [dict(g) for g in v] for k, v in groups.items()}
        self.setWindowTitle("Tag Groups Editor")
        self._build()
        self._refill_folders(0 if self.folders else -1)
        apply_adaptive_dialog_geometry(self, 680, 470, min_w=520, min_h=380)

    def _build(self) -> None:
        lay = QVBoxLayout(self)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        split = QSplitter(Qt.Orientation.Horizontal)

        # Column 1: Folders
        fcol = QWidget()
        fl = QVBoxLayout(fcol)
        fl.setContentsMargins(0, 0, 4, 0)
        fl.addWidget(make_label("Folders", "Kicker"))
        self.folder_list = QListWidget()
        self.folder_list.currentRowChanged.connect(lambda _r: self._refill_groups(0))
        fl.addWidget(self.folder_list, 1)
        fr = QHBoxLayout()
        fr.addWidget(make_button("+ ADD", self._add_folder, small=True, accent=True))
        fr.addWidget(make_button("REN", self._ren_folder, small=True))
        fr.addWidget(make_button("Delete", self._del_folder, small=True))
        fl.addLayout(fr)

        # Column 2: Groups in folder
        gcol = QWidget()
        gl = QVBoxLayout(gcol)
        gl.setContentsMargins(4, 0, 4, 0)
        gl.addWidget(make_label("Tag Groups", "Kicker"))
        self.search_ed = QLineEdit()
        self.search_ed.setPlaceholderText("Filter groups\u2026")
        self.search_ed.textChanged.connect(lambda _t: self._refill_groups(0))
        gl.addWidget(self.search_ed)
        self.group_list = QListWidget()
        self.group_list.currentRowChanged.connect(self._on_group_sel)
        gl.addWidget(self.group_list, 1)
        gr = QHBoxLayout()
        gr.addWidget(make_button("+ NEW", self._add_group, small=True, accent=True))
        gr.addWidget(make_button("DUP", self._dup_group, small=True))
        gr.addWidget(make_button("Delete", self._del_group, small=True))
        gr.addWidget(make_button("\u25B2", lambda: self._move_group(-1), small=True))
        gr.addWidget(make_button("\u25BC", lambda: self._move_group(1), small=True))
        gl.addLayout(gr)

        # Column 3: Edit panel
        ecol = QWidget()
        el = QVBoxLayout(ecol)
        el.setContentsMargins(4, 0, 0, 0)
        el.addWidget(make_label("Group Label", "Kicker"))
        self.lbl_ed = QLineEdit()
        self.lbl_ed.textEdited.connect(self._sync_group)
        el.addWidget(self.lbl_ed)
        el.addWidget(make_label("Tags Text", "Kicker"))
        self.txt_ed = QPlainTextEdit()
        self.txt_ed.textChanged.connect(self._sync_group)
        el.addWidget(self.txt_ed, 1)

        split.addWidget(fcol)
        split.addWidget(gcol)
        split.addWidget(ecol)
        split.setStretchFactor(0, 1)
        split.setStretchFactor(1, 2)
        split.setStretchFactor(2, 2)
        lay.addWidget(split, 1)

        btns = QDialogButtonBox(QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Cancel)
        btns.accepted.connect(self.accept)
        btns.rejected.connect(self.reject)
        lay.addWidget(btns)

    def _cur_folder(self) -> str:
        r = self.folder_list.currentRow()
        return self.folders[r] if 0 <= r < len(self.folders) else (self.folders[0] if self.folders else "General")

    def _refill_folders(self, sel: int) -> None:
        self.folder_list.blockSignals(True)
        self.folder_list.clear()
        for f in self.folders:
            it = QListWidgetItem(f"\u25A0 {f}")
            it.setForeground(QColor(tag_folder_color(f)))
            self.folder_list.addItem(it)
        self.folder_list.blockSignals(False)
        if 0 <= sel < len(self.folders):
            self.folder_list.setCurrentRow(sel)
        self._refill_groups(0)

    def _refill_groups(self, sel: int) -> None:
        f = self._cur_folder()
        q = self.search_ed.text().strip().lower()
        self._visible_indices: List[int] = []
        self.group_list.blockSignals(True)
        self.group_list.clear()
        for idx, g in enumerate(self.groups.get(f, [])):
            if q and q not in f"{g['label']} {g['text']}".lower():
                continue
            self._visible_indices.append(idx)
            self.group_list.addItem(g["label"])
        self.group_list.blockSignals(False)
        if 0 <= sel < len(self._visible_indices):
            self.group_list.setCurrentRow(sel)
            self._on_group_sel(sel)
        else:
            self._on_group_sel(-1)

    def _cur_group_idx(self) -> int:
        r = self.group_list.currentRow()
        return self._visible_indices[r] if 0 <= r < len(self._visible_indices) else -1

    def _on_group_sel(self, row: int) -> None:
        self._busy = True
        idx = self._visible_indices[row] if 0 <= row < len(self._visible_indices) else -1
        f = self._cur_folder()
        rows = self.groups.get(f, [])
        if 0 <= idx < len(rows):
            self.lbl_ed.setEnabled(True)
            self.txt_ed.setEnabled(True)
            self.lbl_ed.setText(rows[idx]["label"])
            self.txt_ed.setPlainText(rows[idx]["text"])
        else:
            self.lbl_ed.setEnabled(False)
            self.txt_ed.setEnabled(False)
            self.lbl_ed.clear()
            self.txt_ed.clear()
        self._busy = False

    def _sync_group(self) -> None:
        if getattr(self, "_busy", False):
            return
        idx = self._cur_group_idx()
        f = self._cur_folder()
        rows = self.groups.get(f, [])
        if not (0 <= idx < len(rows)):
            return
        lbl = self.lbl_ed.text().strip() or "Group"
        txt = self.txt_ed.toPlainText().strip()
        rows[idx] = {"label": lbl, "text": txt, "folder": f}
        it = self.group_list.currentItem()
        if it:
            it.setText(lbl)

    def _add_folder(self) -> None:
        name, ok = QInputDialog.getText(self, "New folder", "Folder name:")
        name = name.strip()
        if ok and name and name not in self.folders:
            self.folders.append(name)
            self.groups[name] = []
            self._refill_folders(len(self.folders) - 1)

    def _ren_folder(self) -> None:
        r = self.folder_list.currentRow()
        if not (0 <= r < len(self.folders)):
            return
        old = self.folders[r]
        name, ok = QInputDialog.getText(self, "Rename folder", "New name:", text=old)
        name = name.strip()
        if ok and name and name != old and name not in self.folders:
            self.folders[r] = name
            self.groups[name] = self.groups.pop(old, [])
            for g in self.groups[name]:
                g["folder"] = name
            self._refill_folders(r)

    def _del_folder(self) -> None:
        r = self.folder_list.currentRow()
        if len(self.folders) <= 1 or not (0 <= r < len(self.folders)):
            return
        old = self.folders.pop(r)
        self.groups.pop(old, None)
        self._refill_folders(min(r, len(self.folders) - 1))

    def _add_group(self) -> None:
        f = self._cur_folder()
        self.groups.setdefault(f, []).append({"label": "New group", "text": "", "folder": f})
        self.search_ed.clear()
        self._refill_groups(len(self.groups[f]) - 1)

    def _dup_group(self) -> None:
        idx = self._cur_group_idx()
        f = self._cur_folder()
        rows = self.groups.get(f, [])
        if 0 <= idx < len(rows):
            c = dict(rows[idx])
            c["label"] += " (copy)"
            rows.insert(idx + 1, c)
            self._refill_groups(idx + 1)

    def _del_group(self) -> None:
        idx = self._cur_group_idx()
        f = self._cur_folder()
        rows = self.groups.get(f, [])
        if 0 <= idx < len(rows):
            rows.pop(idx)
            self._refill_groups(max(0, idx - 1))

    def _move_group(self, delta: int) -> None:
        if self.search_ed.text().strip():
            return
        idx = self._cur_group_idx()
        f = self._cur_folder()
        rows = self.groups.get(f, [])
        t = idx + delta
        if 0 <= idx < len(rows) and 0 <= t < len(rows):
            rows[idx], rows[t] = rows[t], rows[idx]
            self._refill_groups(t)

