class BatchQueueDialog(QDialog):
    """Batch Prompt Queue (v3.2): paste any number of SINGLE-LINE prompts
    (typically copied from the LLM tab or any prompt list) and queue one AI
    Horde request per line — each built through the exact same pipeline as
    GENERATE (active template, model-specific negative, LoRA stack, wildcards,
    options).

    The dialog shows a live pipeline summary so the user always knows what
    each line will be wrapped with before committing."""

    def __init__(self, parent: Optional[QWidget] = None, clipboard_text: str = "") -> None:
        super().__init__(parent)
        self.setWindowTitle("Batch Prompt Queue — one prompt per line")
        self.setSizeGripEnabled(True)
        self.lines: List[str] = []

        lay = QVBoxLayout(self)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(6)
        lay.addWidget(SectionHeader("Paste prompts — one per line"))

        self.edit = QPlainTextEdit()
        self.edit.setObjectName("SmallEdit")
        self.edit.setPlaceholderText(
            "one prompt per line...\nanother prompt...\n(you can also drop a .txt / .csv file here)"
        )
        self.edit.setMinimumHeight(180)
        if clipboard_text and len(clipboard_text.splitlines()) >= 2:
            self.edit.setPlainText(clipboard_text)
        self.edit.textChanged.connect(self._refresh_count)
        lay.addWidget(self.edit, 1)

        self.info_label = make_label("", "Caption")
        self.info_label.setWordWrap(True)
        lay.addWidget(self.info_label)

        row = QHBoxLayout()
        row.setSpacing(4)
        row.addWidget(make_button("PASTE CLIPBOARD", self._paste_clipboard, small=True, icon_key="copy", icon_size=13))
        row.addWidget(make_button("CLEAR", lambda: self.edit.clear(), small=True))
        row.addStretch(1)
        self.count_label = make_label("0 prompts", "Value")
        row.addWidget(self.count_label)
        row.addWidget(make_button("QUEUE ALL", self._accept_batch, accent=True))
        row.addWidget(make_button("CLOSE", self.reject, small=True))
        lay.addLayout(row)

        self.setAcceptDrops(True)
        apply_adaptive_dialog_geometry(self, 620, 430, min_w=520, min_h=340)
        self._refresh_count()

    # ---- drag & drop of .txt / .csv prompt lists -----------------------------
    def dragEnterEvent(self, event) -> None:  # noqa: N802
        md = event.mimeData()
        if md.hasUrls() and any(u.isLocalFile() and u.toLocalFile().lower().endswith((".txt", ".csv", ".json")) for u in md.urls()):
            event.acceptProposedAction()
            return
        if md.hasText():
            event.acceptProposedAction()
            return
        super().dragEnterEvent(event)

    def dropEvent(self, event) -> None:  # noqa: N802
        md = event.mimeData()
        if md.hasUrls():
            loaded = []
            for u in md.urls():
                path = u.toLocalFile()
                if path and path.lower().endswith((".txt", ".csv", ".json")):
                    try:
                        with open(path, "r", encoding="utf-8", errors="replace") as fh:
                            loaded.append(fh.read())
                    except OSError:
                        pass
            if loaded:
                self.edit.setPlainText("\n".join(loaded))
                event.acceptProposedAction()
                return
        if md.hasText():
            self.edit.setPlainText(md.text())
            event.acceptProposedAction()
            return
        super().dropEvent(event)

    # ---- helpers --------------------------------------------------------------
    def _paste_clipboard(self) -> None:
        txt = QApplication.clipboard().text()
        if txt.strip():
            cur = self.edit.toPlainText().rstrip()
            self.edit.setPlainText((cur + "\n" + txt) if cur else txt)

    def set_pipeline_info(self, text: str) -> None:
        self.info_label.setText(text)

    def parse_lines(self) -> List[str]:
        out: List[str] = []
        seen: Set[str] = set()
        for raw in self.edit.toPlainText().splitlines():
            line = " ".join(raw.split())
            if not line or line.startswith("#"):
                continue
            low = line.lower()
            if low in seen:
                continue
            seen.add(low)
            out.append(line)
        return out

    def _refresh_count(self) -> None:
        n = len(self.parse_lines())
        self.count_label.setText(f"{n} prompt{'s' if n != 1 else ''}")

    def _accept_batch(self) -> None:
        lines = self.parse_lines()
        if not lines:
            self.count_label.setText("paste at least one prompt")
            return
        self.lines = lines
        self.accept()


class _ImageDropLabel(QLabel):
    """Compact drag-and-drop target that accepts one local image file."""
    dropped = pyqtSignal(str)

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setAcceptDrops(True)
        self.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.set_minimum_style()

    def set_minimum_style(self) -> None:
        self.setMinimumHeight(58)

    def dragEnterEvent(self, event) -> None:  # noqa: N802
        if event.mimeData().hasUrls():
            for u in event.mimeData().urls():
                if u.isLocalFile() and u.toLocalFile().lower().endswith((".png", ".webp", ".jpg", ".jpeg")):
                    event.acceptProposedAction()
                    return
        super().dragEnterEvent(event)

    def dropEvent(self, event) -> None:  # noqa: N802
        if event.mimeData().hasUrls():
            for u in event.mimeData().urls():
                if u.isLocalFile() and u.toLocalFile().lower().endswith((".png", ".webp", ".jpg", ".jpeg")):
                    self.dropped.emit(u.toLocalFile())
                    event.acceptProposedAction()
                    return
        super().dropEvent(event)

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        grad = QLinearGradient(r.left(), r.top(), r.left(), r.bottom())
        grad.setColorAt(0.0, QColor(C["field_top"]))
        grad.setColorAt(1.0, QColor(C["field_bot"]))
        p.setBrush(QBrush(grad))
        p.setPen(QPen(QColor(C["acc_mid"]), 1.0))
        p.drawRoundedRect(r, 3.0, 3.0)
        # Dashed inner frame to signal the drop affordance
        p.setPen(QPen(QColor(C["line_hi"]), 1.0, Qt.PenStyle.DashLine))
        p.drawRoundedRect(r.adjusted(3, 3, -3, -3), 2.0, 2.0)
        pm = VECTOR_ASSETS.pixmap("image", 18, 18)
        p.drawPixmap(int(r.left() + 8), int(r.center().y() - 9), pm)
        p.setFont(_font(8.2, True))
        p.setPen(QColor(C["muted"]))
        text_r = QRectF(r.left() + 30, r.top(), r.width() - 34, r.height())
        p.drawText(text_r, Qt.AlignmentFlag.AlignVCenter, self.text() or "Drop image here")
        p.end()



class EditCanvas(QWidget):
    """Edit Studio stage: displays the graded preview and hosts the full v4.2
    toolset over a professional checkerboard:

    * NAV              — drag to pan, wheel to zoom, Ctrl+drag frame zoom
    * MASK BRUSH/ERASE — soft full-res adjustment mask painting (B / E)
    * RETOUCH PAINT    — Photoshop-class color brush for small raster fixes:
                         size / softness / flow, Alt+Left-click samples the
                         color under the cursor straight from the image,
                         every stroke is Ctrl+Z-undoable until APPLY, and the
                         dedicated paint ERASER removes only painted strokes
                         — never the photo underneath (P / X)
    * POLYGON MASK     — click a point series, close by clicking the start
                         point / pressing A / double-click, Esc cancels; the
                         finished selection can be smoothed into a vector-like
                         curve, expanded outward, shrunk inward and feathered,
                         previewed in the same red as the painted mask and
                         merged with it (G)
    * CROP             — draggable frame with edge/corner handles and the same
                         aspect-ratio lock set as generation (C); APPLY crops
                         the working image in memory (nothing is saved yet)
    * TILT/ROTATE      — live straightening preview where the canvas borders
                         stay STATIC and the image rotates under them; corners
                         leaving the canvas turn transparent (fill them with
                         the retouch brush) (R)
    * FLARE            — anamorphic flare placement / dragging (F)

    The mask and paint layers are stored full-resolution; the graded preview
    is pushed in by MainWindow through set_display()."""

    mask_changed = pyqtSignal()
    paint_changed = pyqtSignal()                     # emitted only on paint stroke end / clear
    zoom_changed = pyqtSignal(float, bool)
    image_dropped_in = pyqtSignal(str)
    flare_placed = pyqtSignal(float, float)          # normalized x, y
    flare_selected = pyqtSignal(int)                 # index, -1 = none
    flare_moved = pyqtSignal(int, float, float)      # index, normalized x, y
    flare_scaled = pyqtSignal(int, int)              # index, scale percent (30..250)
    color_picked = pyqtSignal(QColor)                # Alt+Click eyedropper
    crop_changed = pyqtSignal()                      # crop frame moved/resized
    rot_changed = pyqtSignal(float)                  # tilt angle changed
    poly_state_changed = pyqtSignal(bool)            # selection shape exists
    fit_restored = pyqtSignal()                      # Ctrl+Right-Click restored fit view
    depth_sampled = pyqtSignal(float)                # Depth Eyedropper clicked (0..100%)

    TOOL_NAV = "nav"
    TOOL_BRUSH = "brush"
    TOOL_ERASE = "erase"
    TOOL_PAINT = "paint"
    TOOL_POLY = "poly"
    TOOL_CROP = "crop"
    TOOL_ROTATE = "rotate"
    TOOL_FLARE = "flare"
    TOOL_DEPTH = "depth"
    ALL_TOOLS = (TOOL_NAV, TOOL_BRUSH, TOOL_ERASE, TOOL_PAINT,
                 TOOL_POLY, TOOL_CROP, TOOL_ROTATE, TOOL_FLARE, TOOL_DEPTH)

    _FLARE_HIT_PX = 16.0                             # screen-space handle radius
    _CROP_HIT_PX = 12.0                              # crop handle grab radius
    _POLY_CLOSE_PX = 12.0                            # click-to-close radius
    _CROP_MIN = 24.0                                 # smallest crop rect (doc px)
    _STROKE_UNDO_MAX = 10                            # stroke history entries
    _STROKE_UNDO_BUDGET = 96 * 1024 * 1024           # stroke history byte cap

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setAcceptDrops(True)
        self.setMouseTracking(True)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.setMinimumHeight(170)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.setAttribute(Qt.WidgetAttribute.WA_OpaquePaintEvent, True)
        self._doc: Optional[QImage] = None
        self._display: Optional[QImage] = None
        self._mask: Optional[QImage] = None
        self._mask_disp: Optional[QImage] = None
        self._mask_disp_opaque = True
        self._mask_visible = True
        self._disp_pm: Optional[QPixmap] = None
        self._doc_pm: Optional[QPixmap] = None
        self._paint_disp: Optional[QImage] = None
        self._dab_cache_key: Tuple[Any, ...] = ()
        self._dab_cache_img: Optional[QImage] = None
        self._last_cursor_rect: Optional[QRect] = None
        self._scale = 1.0
        self._ox = 0.0
        self._oy = 0.0
        self._tool = self.TOOL_NAV
        self._brush_size = 48.0
        self._brush_soft = 45.0
        self._panning = False
        self._pan_start = QPoint()
        self._pan_h0 = 0.0
        self._pan_v0 = 0.0
        self._painting = False
        self._last_doc: Optional[QPointF] = None
        self._hover: Optional[QPointF] = None
        self._zoom_rect: Optional[QRect] = None
        self._zoom_start = QPoint()
        self._flares: List[Dict[str, Any]] = []
        self._selected_flare = -1
        self._dragging_flare = False
        self._scaling_flare = False
        self._scale_flare_start_dist = 1.0
        self._scale_flare_start_val = 100
        self._compare = False
        self._split_compare = False
        self._split_pos = 0.5
        self._dragging_split = False
        self._checker_tile: Optional[QPixmap] = None
        self._checker_theme_key = ""
        # ---- v4.2: retouch paint layer -------------------------------------
        self._paint: Optional[QImage] = None        # full-res ARGB32 stroke layer
        self._paint_color = QColor("#ffffff")
        self._paint_opacity = 100                   # stroke flow 10..100 %
        self._paint_erase = False                   # paint-eraser sub-mode
        self._stroke_snapshot: Optional[QImage] = None   # layer copy during a stroke
        self._stroke_tag = ""                       # which layer the stroke edits
        self._stroke_bbox: Optional[QRect] = None
        self._stroke_undo: List[Tuple[str, QRect, QImage]] = []
        # ---- v4.2: polygonal mask selection --------------------------------
        self._poly_pts: List[QPointF] = []
        self._poly_drawing = False
        self._poly_shape: Optional[QImage] = None   # rendered selection (full-res)
        self._poly_smooth = True
        self._poly_feather = 0.0                    # edge softness, doc px
        self._poly_expand = 0.0                     # outward offset, doc px
        # ---- v4.2: crop frame ----------------------------------------------
        self._crop_rect: Optional[QRectF] = None    # doc-pixel coordinates
        self._crop_aspect: Optional[Tuple[float, float]] = None  # None = free
        self._crop_aspect_key = "free"
        self._crop_drag = 0                         # 0 none, -2 move, -3 new, 1..8 handles
        self._crop_press: Optional[QPointF] = None  # view coords at press
        self._crop_origin: Optional[QRectF] = None
        # ---- v4.2: tilt / straighten ----------------------------------------
        self._rot_angle = 0.0
        # effective (mask + polygon) cache
        self._eff_cache: Optional[QImage] = None
        self._eff_cov: Optional[float] = None
        self._paint_cov_val: Optional[float] = None
        # ---- v7.0: live split gap line preview & depth map studio overlays ----
        self._split_guide_visible = False
        self._split_guide_vertical = True
        self._split_guide_gap = 1
        self._depth_overlay: Optional[QImage] = None
        self._depth_overlay_opacity = 0.65
        self._depth_mask_preview: Optional[QImage] = None
        self._depth_probe_img: Optional[QImage] = None
        self._depth_probe_invert = False
        self._hover_depth_val: Optional[float] = None

    # ------------------------------------------------------------------ layers
    def set_document(self, img: Optional[QImage]) -> None:
        self._doc = img if (img is not None and not img.isNull()) else None
        if self._doc is not None:
            self._mask = QImage(self._doc.size(), QImage.Format.Format_ARGB32)
            self._mask.fill(Qt.GlobalColor.transparent)
            self._paint = QImage(self._doc.size(), QImage.Format.Format_ARGB32_Premultiplied)
            self._paint.fill(Qt.GlobalColor.transparent)
        else:
            self._mask = None
            self._paint = None
        self._display = None
        self._reset_transient_state()
        self.fit_view()
        self.mask_changed.emit()

    def _reset_transient_state(self) -> None:
        """Fresh document: clear selection, crop, tilt and stroke history."""
        self._poly_pts = []
        self._poly_drawing = False
        self._poly_shape = None
        self._poly_feather = 0.0
        self._poly_expand = 0.0
        self._crop_rect = None
        self._crop_drag = 0
        self._rot_angle = 0.0
        self._stroke_snapshot = None
        self._stroke_bbox = None
        self._stroke_undo.clear()
        self._depth_mask_preview = None
        self._hover_depth_val = None
        self._invalidate_view_caches(keep_doc=False)
        self._invalidate_mask_disp()
        self.poly_state_changed.emit(False)
        self.crop_changed.emit()
        self.rot_changed.emit(0.0)

    def set_display(self, preview: Optional[QImage]) -> None:
        self._display = preview if (preview is not None and not preview.isNull()) else None
        self._disp_pm = None
        self.update()

    def set_split_guide(self, visible: bool, vertical: bool = True, gap_px: int = 1) -> None:
        """Toggle & configure the live pixel-accurate Split Gap Line preview."""
        vis = bool(visible)
        vert = bool(vertical)
        gap = max(0, int(gap_px))
        if (
            self._split_guide_visible != vis
            or self._split_guide_vertical != vert
            or self._split_guide_gap != gap
        ):
            self._split_guide_visible = vis
            self._split_guide_vertical = vert
            self._split_guide_gap = gap
            self.update()

    def is_split_guide_visible(self) -> bool:
        return self._split_guide_visible

    def set_depth_overlay(self, overlay: Optional[QImage], opacity: float = 0.65) -> None:
        self._depth_overlay = overlay if (overlay is not None and not overlay.isNull()) else None
        self._depth_overlay_opacity = max(0.05, min(1.0, float(opacity)))
        self.update()

    def set_depth_mask_preview(self, mask_img: Optional[QImage]) -> None:
        self._depth_mask_preview = mask_img if (mask_img is not None and not mask_img.isNull()) else None
        self.update()

    def set_depth_probe_source(self, depth_img: Optional[QImage], invert_polarity: bool = False) -> None:
        self._depth_probe_img = depth_img if (depth_img is not None and not depth_img.isNull()) else None
        self._depth_probe_invert = bool(invert_polarity)
        self._hover_depth_val = None
        self.update()

    def apply_depth_mask_into_mask(self, depth_mask: Optional[QImage], blend_mode: str = "replace") -> bool:
        """Commit a generated depth mask into the full-res active editor mask with
        full Ctrl+Z stroke undo support. blend_mode: replace | add | subtract | intersect."""
        if self._doc is None or self._mask is None or depth_mask is None or depth_mask.isNull():
            return False
        dm = depth_mask
        if dm.size() != self._mask.size():
            dm = dm.scaled(
                self._mask.size(),
                Qt.AspectRatioMode.IgnoreAspectRatio,
                Qt.TransformationMode.SmoothTransformation,
            )
        dm = dm.convertToFormat(QImage.Format.Format_ARGB32)
        self._push_stroke_undo("mask", self._mask.copy(), self._mask.rect())
        if blend_mode == "replace":
            self._mask = dm.copy()
        elif blend_mode == "add":
            p = QPainter(self._mask)
            p.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceOver)
            p.drawImage(0, 0, dm)
            p.end()
        elif blend_mode == "subtract":
            p = QPainter(self._mask)
            p.setCompositionMode(QPainter.CompositionMode.CompositionMode_DestinationOut)
            p.drawImage(0, 0, dm)
            p.end()
        elif blend_mode == "intersect":
            p = QPainter(self._mask)
            p.setCompositionMode(QPainter.CompositionMode.CompositionMode_DestinationIn)
            p.drawImage(0, 0, dm)
            p.end()
        self._depth_mask_preview = None
        self._invalidate_mask_disp()
        self.update()
        self.mask_changed.emit()
        return True

    def _invalidate_view_caches(self, keep_doc: bool = False) -> None:
        self._disp_pm = None
        if not keep_doc:
            self._doc_pm = None
        self._paint_disp = None
        self._mask_disp = None

    def _ensure_disp_caches(self) -> None:
        """Zero-lag display caching: downscales smoothly for fit/zoom-out views,
        and reuses native-resolution pixmaps when zoomed in (>= 100%) so zooming
        never allocates giant multi-megabyte upscaled bitmaps on low-end laptops."""
        if self._doc is None:
            return
        doc_w, doc_h = self._doc.width(), self._doc.height()
        dw = max(1, int(round(doc_w * self._scale)))
        dh = max(1, int(round(doc_h * self._scale)))
        # Cap cache dimensions at native document size (never upscale into RAM!)
        cw = min(doc_w, dw)
        ch = min(doc_h, dh)
        if self._doc_pm is None or self._doc_pm.width() != cw or self._doc_pm.height() != ch:
            if cw == doc_w and ch == doc_h:
                self._doc_pm = QPixmap.fromImage(self._doc)
            else:
                self._doc_pm = QPixmap.fromImage(
                    self._doc.scaled(cw, ch, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)
                )
        src_disp = self._display if self._display is not None else self._doc
        sw, sh = min(src_disp.width(), dw), min(src_disp.height(), dh)
        if self._disp_pm is None or self._disp_pm.width() != sw or self._disp_pm.height() != sh:
            if src_disp is self._doc and self._doc_pm is not None:
                self._disp_pm = self._doc_pm
            elif sw == src_disp.width() and sh == src_disp.height():
                self._disp_pm = QPixmap.fromImage(src_disp)
            else:
                self._disp_pm = QPixmap.fromImage(
                    src_disp.scaled(sw, sh, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)
                )
        if self._paint is not None:
            if cw >= doc_w and ch >= doc_h:
                self._paint_disp = None  # zoomed in: draw native _paint directly
            elif self._paint_disp is None or self._paint_disp.width() != cw or self._paint_disp.height() != ch:
                self._paint_disp = self._paint.scaled(
                    cw, ch, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation
                ).convertToFormat(QImage.Format.Format_ARGB32_Premultiplied)

    def _sync_paint_disp_dirty(self, doc_rect: QRect) -> None:
        if self._paint is None or self._doc is None:
            return
        if self._paint_disp is None:
            self._ensure_disp_caches()
            return
        r = doc_rect.intersected(self._paint.rect())
        if r.isEmpty():
            return
        sx = self._paint_disp.width() / max(1.0, float(self._doc.width()))
        sy = self._paint_disp.height() / max(1.0, float(self._doc.height()))
        vr = QRect(
            max(0, int(math.floor(r.left() * sx)) - 1),
            max(0, int(math.floor(r.top() * sy)) - 1),
            max(2, int(math.ceil(r.width() * sx)) + 3),
            max(2, int(math.ceil(r.height() * sy)) + 3),
        ).intersected(self._paint_disp.rect())
        if vr.isEmpty():
            return
        sub = self._paint.copy(r)
        p = QPainter(self._paint_disp)
        p.setCompositionMode(QPainter.CompositionMode.CompositionMode_Source)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        p.drawImage(vr, sub)
        p.end()

    def _sync_mask_disp_dirty(self, doc_rect: QRect) -> None:
        if self._mask is None or self._doc is None or not self._mask_visible:
            return
        if self._mask_disp is None:
            self._ensure_mask_disp()
            return
        src = self.effective_mask()
        if src is None:
            return
        r = doc_rect.intersected(src.rect())
        if r.isEmpty():
            return
        sx = self._mask_disp.width() / max(1.0, float(self._doc.width()))
        sy = self._mask_disp.height() / max(1.0, float(self._doc.height()))
        vr = QRect(
            max(0, int(math.floor(r.left() * sx)) - 1),
            max(0, int(math.floor(r.top() * sy)) - 1),
            max(2, int(math.ceil(r.width() * sx)) + 3),
            max(2, int(math.ceil(r.height() * sy)) + 3),
        ).intersected(self._mask_disp.rect())
        if vr.isEmpty():
            return
        sub = src.copy(r).scaled(vr.size(), Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.FastTransformation)
        factor = 255 if self._mask_disp_opaque else 115
        tint = QImage(vr.size(), QImage.Format.Format_ARGB32_Premultiplied)
        tint.fill(QColor(255, 24, 24, factor))
        pt = QPainter(tint)
        pt.setCompositionMode(QPainter.CompositionMode.CompositionMode_DestinationIn)
        pt.drawImage(0, 0, sub)
        pt.end()
        pm = QPainter(self._mask_disp)
        pm.setCompositionMode(QPainter.CompositionMode.CompositionMode_Source)
        pm.drawImage(vr.topLeft(), tint)
        pm.end()

    def _doc_rect_to_widget_dirty(self, doc_rect: QRect) -> QRect:
        tl = self._to_view(QPointF(doc_rect.left(), doc_rect.top()))
        br = self._to_view(QPointF(doc_rect.right() + 1, doc_rect.bottom() + 1))
        pad = 6
        return QRect(
            int(math.floor(tl.x())) - pad, int(math.floor(tl.y())) - pad,
            int(math.ceil(br.x() - tl.x())) + pad * 2, int(math.ceil(br.y() - tl.y())) + pad * 2,
        ).intersected(self.rect())

    def _get_cached_dab(self, radius: float, softness: float, color: QColor, alpha: float) -> QImage:
        key = (round(radius, 1), round(softness, 1), color.rgba(), round(alpha, 3))
        if self._dab_cache_img is None or self._dab_cache_key != key:
            self._dab_cache_img = build_brush_dab(radius, softness, color, alpha)
            self._dab_cache_key = key
        return self._dab_cache_img

    def document(self) -> Optional[QImage]:
        return self._doc

    def mask(self) -> Optional[QImage]:
        """Raw painted mask (brush strokes only)."""
        return self._mask

    def paint_layer(self) -> Optional[QImage]:
        return self._paint

    def effective_mask(self) -> Optional[QImage]:
        """The mask the pipeline should consume: painted strokes UNIONED with
        the polygon selection shape (when one exists)."""
        if self._mask is None:
            return None
        if self._poly_shape is None:
            return self._mask
        if self._eff_cache is None:
            eff = self._mask.convertToFormat(QImage.Format.Format_ARGB32)
            p = QPainter(eff)
            p.drawImage(0, 0, self._poly_shape)
            p.end()
            self._eff_cache = eff
        return self._eff_cache

    def mask_coverage_value(self) -> float:
        if self._mask is None:
            return 0.0
        if self._eff_cov is None:
            self._eff_cov = mask_coverage(self.effective_mask())
        return self._eff_cov

    def has_mask(self) -> bool:
        return self.mask_coverage_value() > 0.0005

    def has_paint(self) -> bool:
        return self._paint is not None and self._paint_cov > 0.0005

    @property
    def _paint_cov(self) -> float:
        # lazily computed and cached on the instance
        cov = getattr(self, "_paint_cov_val", None)
        if cov is None:
            cov = mask_coverage(self._paint) if self._paint is not None else 0.0
            self._paint_cov_val = cov
        return cov

    def clear_mask(self) -> None:
        if self._mask is not None:
            self._mask.fill(Qt.GlobalColor.transparent)
            self._drop_poly_shape()
            self._prune_stroke_undo("mask")
            self._invalidate_mask_disp()
            self.mask_changed.emit()
            self.update()

    def invert_mask(self) -> None:
        if self._mask is None:
            return
        # a visible polygon selection is committed first so the inversion
        # covers the full combined selection
        self.commit_poly()
        inv = QImage(self._mask.size(), QImage.Format.Format_ARGB32)
        inv.fill(QColor(255, 0, 0, 255))
        p = QPainter(inv)
        p.setCompositionMode(QPainter.CompositionMode.CompositionMode_DestinationOut)
        p.drawImage(0, 0, self._mask)
        p.end()
        self._mask = inv
        self._prune_stroke_undo("mask")
        self._invalidate_mask_disp()
        self.mask_changed.emit()
        self.update()

    def clear_paint(self) -> None:
        if self._paint is not None:
            self._paint.fill(Qt.GlobalColor.transparent)
            self._prune_stroke_undo("paint")
            self._paint_cov_val = None
            self._paint_disp = None
            self.paint_changed.emit()
            self.update()

    def set_mask_display_opaque(self, opaque: bool) -> None:
        if self._mask_disp_opaque != opaque:
            self._mask_disp_opaque = bool(opaque)
            self._invalidate_mask_disp()
            self.update()

    def set_mask_visible(self, visible: bool) -> None:
        visible = bool(visible)
        if self._mask_visible != visible:
            self._mask_visible = visible
            if visible:
                self._mask_disp = None
            self.update()

    def is_mask_visible(self) -> bool:
        return self._mask_visible

    def set_split_compare(self, on: bool) -> None:
        on = bool(on)
        if self._split_compare != on:
            self._split_compare = on
            self.update()

    def is_split_compare(self) -> bool:
        return self._split_compare

    # ------------------------------------------------------------------ tools
    def set_tool(self, tool: str) -> None:
        if tool not in self.ALL_TOOLS:
            return
        if tool != self._tool:
            # leaving ROTATE always drops the un-applied preview angle
            if self._tool == self.TOOL_ROTATE and abs(self._rot_angle) > 0.05:
                self._rot_angle = 0.0
                self.rot_changed.emit(0.0)
            if self._poly_drawing:
                self._poly_drawing = False
                self._poly_pts = []
                self._poly_hover = None
        self._tool = tool
        if tool in (self.TOOL_BRUSH, self.TOOL_ERASE, self.TOOL_PAINT):
            self.setCursor(Qt.CursorShape.BlankCursor)   # ring cursor is painted
        elif tool in (self.TOOL_POLY, self.TOOL_CROP):
            self.setCursor(Qt.CursorShape.CrossCursor)
        elif tool in (self.TOOL_FLARE, self.TOOL_DEPTH):
            self.setCursor(Qt.CursorShape.CrossCursor)
        else:
            self.setCursor(Qt.CursorShape.ArrowCursor)
        if tool == self.TOOL_CROP:
            self._ensure_crop_rect()
            self.crop_changed.emit()
        self.update()

    def set_brush(self, size: float, softness: float) -> None:
        self._brush_size = max(2.0, size)
        self._brush_soft = max(0.0, min(100.0, softness))
        self.update()

    def set_paint_brush(self, size: float, softness: float, opacity: int) -> None:
        self._brush_size = max(2.0, size)
        self._brush_soft = max(0.0, min(100.0, softness))
        self._paint_opacity = max(5, min(100, int(opacity)))
        self.update()

    def set_paint_color(self, color: QColor) -> None:
        self._paint_color = QColor(color)
        self.update()

    def paint_color(self) -> QColor:
        return QColor(self._paint_color)

    def set_paint_erase(self, erase: bool) -> None:
        self._paint_erase = bool(erase)
        self.update()

    def paint_erase(self) -> bool:
        return self._paint_erase

    # ------------------------------------------------------------- flare & compare
    def set_flares(self, flares: List[Dict[str, Any]], selected: int = -1) -> None:
        """Visual flare registry (normalized positions drawn as handles)."""
        self._flares = list(flares or [])
        self._selected_flare = max(-1, min(int(selected), len(self._flares) - 1))
        self.update()

    def set_selected_flare(self, index: int) -> None:
        self._selected_flare = int(index)
        self.update()

    def selected_flare(self) -> int:
        return self._selected_flare

    def set_compare(self, on: bool) -> None:
        """Hold-to-compare: show the untouched original instead of the grade."""
        if self._compare != bool(on):
            self._compare = bool(on)
            self.update()

    def _flare_handle_at(self, view_pos: QPointF) -> int:
        """Index of the flare handle under `view_pos` (screen-space radius)."""
        if self._doc is None:
            return -1
        dr = self._doc_rect()
        hit = self._FLARE_HIT_PX
        for i, f in enumerate(self._flares):
            hx = dr.left() + float(f.get("x", 0.5)) * dr.width()
            hy = dr.top() + float(f.get("y", 0.5)) * dr.height()
            if math.hypot(view_pos.x() - hx, view_pos.y() - hy) <= hit:
                return i
        return -1

    def _checker_brush(self) -> QBrush:
        """Professional alpha checkerboard tile in the active theme's deeps."""
        key = C.get("key", "")
        if self._checker_tile is None or self._checker_theme_key != key:
            c1 = QColor(C["deep"])
            c2 = QColor(C["field_bot"])
            if c1 == c2:
                c2 = QColor(C["sunken_bot"])
            tile = QPixmap(24, 24)
            tile.fill(c1)
            pt = QPainter(tile)
            pt.fillRect(0, 0, 12, 12, c2)
            pt.fillRect(12, 12, 12, 12, c2)
            pt.end()
            self._checker_tile = tile
            self._checker_theme_key = key
        return QBrush(self._checker_tile)

    # ------------------------------------------------------------------ zoom & pan
    def fit_view(self) -> None:
        if self._doc is None:
            self._scale = 1.0
            self._invalidate_view_caches(keep_doc=False)
            self.update()
            self.zoom_changed.emit(1.0, True)
            return
        vw, vh = max(1, self.width()), max(1, self.height())
        s = min((vw - 14) / self._doc.width(), (vh - 14) / self._doc.height())
        self._scale = max(0.02, min(4.0, s))
        self._center()
        self._invalidate_view_caches(keep_doc=False)
        self.update()
        self.zoom_changed.emit(self._scale, True)

    def zoom_1_1(self) -> None:
        self._scale = 1.0
        self._center()
        self._invalidate_view_caches(keep_doc=False)
        self.update()
        self.zoom_changed.emit(1.0, False)

    def zoom_by(self, factor: float, anchor: Optional[QPoint] = None) -> None:
        if self._doc is None:
            return
        old = self._scale
        new = max(0.02, min(16.0, old * factor))
        if abs(new - old) < 1e-4:
            return
        if anchor is None:
            anchor = QPoint(self.width() // 2, self.height() // 2)
        dx = (anchor.x() - self._ox) / old
        dy = (anchor.y() - self._oy) / old
        self._scale = new
        self._ox = anchor.x() - dx * new
        self._oy = anchor.y() - dy * new
        self._clamp_pan()
        self._invalidate_view_caches(keep_doc=False)
        self._invalidate_mask_disp()
        self.update()
        self.zoom_changed.emit(self._scale, False)

    def zoom_percent(self) -> int:
        return int(round(self._scale * 100))

    def _center(self) -> None:
        if self._doc is None:
            self._ox = self._oy = 0.0
            return
        dw = self._doc.width() * self._scale
        dh = self._doc.height() * self._scale
        self._ox = (self.width() - dw) / 2.0
        self._oy = (self.height() - dh) / 2.0

    def _clamp_pan(self) -> None:
        if self._doc is None:
            return
        dw = self._doc.width() * self._scale
        dh = self._doc.height() * self._scale
        vw, vh = self.width(), self.height()
        m = 60.0
        if dw <= vw:
            self._ox = (vw - dw) / 2.0
        else:
            self._ox = min(max(self._ox, vw - dw - m), m)
        if dh <= vh:
            self._oy = (vh - dh) / 2.0
        else:
            self._oy = min(max(self._oy, vh - dh - m), m)

    # ------------------------------------------------------------------ coordinates
    def _to_doc(self, pos: QPointF) -> QPointF:
        return QPointF((pos.x() - self._ox) / max(1e-6, self._scale),
                       (pos.y() - self._oy) / max(1e-6, self._scale))

    def _to_view(self, doc_pt: QPointF) -> QPointF:
        return QPointF(self._ox + doc_pt.x() * self._scale,
                       self._oy + doc_pt.y() * self._scale)

    def _doc_rect(self) -> QRectF:
        if self._doc is None:
            return QRectF()
        return QRectF(self._ox, self._oy,
                      self._doc.width() * self._scale, self._doc.height() * self._scale)

    # ------------------------------------------------------------------ mask overlay cache
    def _invalidate_mask_disp(self) -> None:
        self._mask_disp = None
        self._eff_cache = None
        self._eff_cov = None

    def _ensure_mask_disp(self) -> None:
        if self._mask_disp is not None or self._mask is None or self._doc is None or not self._mask_visible:
            return
        dw = max(1, int(round(self._doc.width() * self._scale)))
        dh = max(1, int(round(self._doc.height() * self._scale)))
        if dw > 4096 or dh > 4096:
            return
        src = self.effective_mask()
        if src is None:
            return
        small = src.scaled(dw, dh, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.FastTransformation)
        small = small.convertToFormat(QImage.Format.Format_ARGB32_Premultiplied)
        factor = 255 if self._mask_disp_opaque else 115
        overlay = QImage(small.size(), QImage.Format.Format_ARGB32_Premultiplied)
        overlay.fill(QColor(255, 24, 24, factor))
        p = QPainter(overlay)
        p.setCompositionMode(QPainter.CompositionMode.CompositionMode_DestinationIn)
        p.drawImage(0, 0, small)
        p.end()
        self._mask_disp = overlay

    # ------------------------------------------------------------------ stroke history
    def _prune_stroke_undo(self, tag: str) -> None:
        self._stroke_undo = [e for e in self._stroke_undo if e[0] != tag]

    def _push_stroke_undo(self, tag: str, snapshot: QImage, bbox: QRect) -> None:
        """Remember a region of `snapshot` (pre-stroke) so Ctrl+Z can revert
        exactly this stroke later."""
        if snapshot is None or bbox.isEmpty():
            return
        r = bbox.intersected(snapshot.rect())
        if r.isEmpty():
            return
        self._stroke_undo.append((tag, r, snapshot.copy(r)))

        def _bytes(e: Tuple[str, QRect, Any]) -> int:
            img = e[2]
            if isinstance(img, QImage):
                try:
                    return int(img.sizeInBytes())
                except Exception:
                    return int(img.width() * img.height() * 4)
            return 0  # poly-state entries carry a parameter tuple

        while len(self._stroke_undo) > self._STROKE_UNDO_MAX:
            self._stroke_undo.pop(0)
        total = sum(_bytes(e) for e in self._stroke_undo)
        while total > self._STROKE_UNDO_BUDGET and len(self._stroke_undo) > 1:
            dropped = self._stroke_undo.pop(0)
            total -= _bytes(dropped)

    def undo_last_stroke(self) -> bool:
        """Undo the newest paint/mask stroke or polygon op. True when handled;
        False lets the caller fall back to the document-level undo."""
        while self._stroke_undo:
            tag, rect, snap = self._stroke_undo.pop()
            if tag == "mask":
                layer = self._mask
            elif tag == "paint":
                layer = self._paint
            elif tag == "poly":
                st = snap
                self._poly_smooth, self._poly_feather, self._poly_expand = st
                self._render_poly_shape()
                self.mask_changed.emit()
                return True
            else:
                continue
            if layer is None or layer.isNull():
                continue
            p = QPainter(layer)
            p.setCompositionMode(QPainter.CompositionMode.CompositionMode_DestinationOut)
            p.fillRect(rect, QColor(0, 0, 0, 255))
            p.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceOver)
            p.drawImage(rect.topLeft(), snap)
            p.end()
            if tag == "paint":
                self._paint_cov_val = None
                self._paint_disp = None
                self.paint_changed.emit()
            else:
                self._invalidate_mask_disp()
                self.mask_changed.emit()
            self.update()
            return True
        return False

    # ------------------------------------------------------------------ painting strokes
    def _begin_stroke(self, tag: str) -> None:
        layer = self._mask if tag == "mask" else self._paint
        self._stroke_tag = tag
        self._stroke_snapshot = layer.copy() if layer is not None else None
        self._stroke_bbox = None

    def _finish_stroke(self) -> None:
        if self._stroke_snapshot is not None and self._stroke_bbox is not None:
            pad = self._brush_size + 8.0
            bbox = self._stroke_bbox.adjusted(int(-pad), int(-pad), int(pad), int(pad))
            self._push_stroke_undo(self._stroke_tag, self._stroke_snapshot, bbox)
        self._stroke_snapshot = None
        self._stroke_bbox = None
        self._stroke_tag = ""

    def _track_stroke_bbox(self, x: float, y: float) -> None:
        if self._stroke_bbox is None:
            self._stroke_bbox = QRect(int(x), int(y), 1, 1)
        else:
            self._stroke_bbox = self._stroke_bbox.united(QRect(int(x), int(y), 1, 1))

    def _stamp_line(self, a: QPointF, b: QPointF) -> QRect:
        if self._mask is None:
            return QRect()
        dist = math.hypot(b.x() - a.x(), b.y() - a.y())
        radius = max(1.0, self._brush_size * 0.5)
        step = max(1.2, self._brush_size * 0.28)
        n = max(1, int(dist / step))
        erase = self._tool == self.TOOL_ERASE
        dab = self._get_cached_dab(radius, self._brush_soft, QColor(255, 0, 0), 1.0)
        half = dab.width() * 0.5
        p = QPainter(self._mask)
        p.setCompositionMode(
            QPainter.CompositionMode.CompositionMode_DestinationOut if erase
            else QPainter.CompositionMode.CompositionMode_SourceOver
        )
        for i in range(n + 1):
            t = i / float(n)
            x = a.x() + (b.x() - a.x()) * t
            y = a.y() + (b.y() - a.y()) * t
            p.drawImage(QPointF(x - half, y - half), dab)
            self._track_stroke_bbox(x, y)
        p.end()
        self._eff_cache = None
        self._eff_cov = None
        pad = int(math.ceil(half)) + 2
        dirty = QRect(
            int(math.floor(min(a.x(), b.x()))) - pad, int(math.floor(min(a.y(), b.y()))) - pad,
            max(1, int(math.ceil(max(a.x(), b.x()) - min(a.x(), b.x()))) + pad * 2),
            max(1, int(math.ceil(max(a.y(), b.y()) - min(a.y(), b.y()))) + pad * 2),
        ).intersected(self._mask.rect())
        self._sync_mask_disp_dirty(dirty)
        return dirty

    def _stamp_paint_line(self, a: QPointF, b: QPointF) -> QRect:
        if self._paint is None:
            return QRect()
        dist = math.hypot(b.x() - a.x(), b.y() - a.y())
        step = max(1.2, self._brush_size * 0.24)
        n = max(1, int(dist / step))
        flow = self._paint_opacity / 100.0
        if self._paint_erase:
            radius = max(1.0, self._brush_size * 0.5 * 1.14)
            dab = self._get_cached_dab(radius, self._brush_soft * 0.45, QColor(255, 255, 255), 1.0)
            comp = QPainter.CompositionMode.CompositionMode_DestinationOut
        else:
            radius = max(1.0, self._brush_size * 0.5)
            dab = self._get_cached_dab(radius, self._brush_soft, self._paint_color, max(0.03, flow * 0.55))
            comp = QPainter.CompositionMode.CompositionMode_SourceOver
        half = dab.width() * 0.5
        p = QPainter(self._paint)
        p.setCompositionMode(comp)
        for i in range(n + 1):
            t = i / float(n)
            x = a.x() + (b.x() - a.x()) * t
            y = a.y() + (b.y() - a.y()) * t
            p.drawImage(QPointF(x - half, y - half), dab)
            self._track_stroke_bbox(x, y)
        p.end()
        self._paint_cov_val = None
        pad = int(math.ceil(half)) + 2
        dirty = QRect(
            int(math.floor(min(a.x(), b.x()))) - pad, int(math.floor(min(a.y(), b.y()))) - pad,
            max(1, int(math.ceil(max(a.x(), b.x()) - min(a.x(), b.x()))) + pad * 2),
            max(1, int(math.ceil(max(a.y(), b.y()) - min(a.y(), b.y()))) + pad * 2),
        ).intersected(self._paint.rect())
        self._sync_paint_disp_dirty(dirty)
        return dirty

    def _pick_color_at(self, view_pos: QPointF) -> None:
        """Alt+Click eyedropper: sample the pixel the user actually sees
        (graded preview when active) and adopt it as the paint color."""
        if self._doc is None:
            return
        shown = self._display if self._display is not None else self._doc
        doc_pt = self._to_doc(view_pos)
        sx = int(round(doc_pt.x() * shown.width() / max(1, self._doc.width())))
        sy = int(round(doc_pt.y() * shown.height() / max(1, self._doc.height())))
        sx = max(0, min(shown.width() - 1, sx))
        sy = max(0, min(shown.height() - 1, sy))
        col = QColor.fromRgb(shown.pixel(sx, sy))
        self._paint_color = col
        self.color_picked.emit(col)
        self.update()

    # ------------------------------------------------------------------ polygon selection
    def has_poly(self) -> bool:
        return self._poly_shape is not None

    def poly_drawing(self) -> bool:
        return self._poly_drawing

    def poly_params(self) -> Tuple[bool, float, float]:
        return (self._poly_smooth, self._poly_feather, self._poly_expand)

    def set_poly_smooth(self, smooth: bool) -> None:
        if self._poly_shape is None:
            self._poly_smooth = bool(smooth)
            return
        self._push_poly_state_undo()
        self._poly_smooth = bool(smooth)
        self._render_poly_shape()

    def poly_expand_by(self, delta: float) -> None:
        if self._poly_shape is None:
            return
        self._push_poly_state_undo()
        self._poly_expand = max(-400.0, min(400.0, self._poly_expand + delta))
        self._render_poly_shape()

    def poly_feather_set(self, value: float) -> None:
        if self._poly_shape is None:
            self._poly_feather = max(0.0, min(120.0, float(value)))
            return
        self._push_poly_state_undo()
        self._poly_feather = max(0.0, min(120.0, float(value)))
        self._render_poly_shape()

    def _push_poly_state_undo(self) -> None:
        state = (self._poly_smooth, self._poly_feather, self._poly_expand)
        self._stroke_undo.append(("poly", QRect(0, 0, 1, 1), state))
        while len(self._stroke_undo) > self._STROKE_UNDO_MAX + 4:
            self._stroke_undo.pop(0)

    def _render_poly_shape(self) -> None:
        """Rasterize the current polygon (with smoothing / offset / feather)
        into the full-res selection shape shown as the red overlay."""
        self._poly_shape = None
        if self._doc is not None and len(self._poly_pts) >= 3:
            pts = offset_polygon_points(self._poly_pts, self._poly_expand)
            path = smooth_polygon_path(pts) if self._poly_smooth else polygon_path(pts)
            shape = QImage(self._doc.size(), QImage.Format.Format_ARGB32)
            shape.fill(Qt.GlobalColor.transparent)
            p = QPainter(shape)
            p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(255, 255, 255, 255))
            p.drawPath(path)
            p.end()
            if self._poly_feather > 0.5:
                shape = blur_alpha_qimage(shape, self._poly_feather)
            self._poly_shape = shape
        self._invalidate_mask_disp()
        self.poly_state_changed.emit(self._poly_shape is not None)
        self.update()

    def close_poly(self) -> bool:
        """Finish the in-progress polygon (A / Enter / double-click / clicking
        the first point). Non-glitch guards: needs 3+ points, duplicate points
        are ignored at add time."""
        if not self._poly_drawing or len(self._poly_pts) < 3 or self._doc is None:
            return False
        self._poly_drawing = False
        self._push_poly_state_undo()
        self._render_poly_shape()
        return True

    def cancel_poly(self) -> None:
        """Esc while drawing: forget the in-progress points."""
        if self._poly_drawing:
            self._poly_drawing = False
            self._poly_pts = []
            self._poly_hover = None
            self.update()

    def discard_poly(self) -> bool:
        """Drop the finished selection shape (keeps the painted mask)."""
        if self._poly_shape is None:
            return False
        self._drop_poly_shape()
        self.update()
        return True

    def _drop_poly_shape(self) -> None:
        self._poly_shape = None
        self._poly_pts = []
        self._poly_drawing = False
        self._invalidate_mask_disp()
        self.poly_state_changed.emit(False)
        self.mask_changed.emit()

    def commit_poly(self) -> bool:
        """Union the finished selection into the painted mask (so the mask
        brush / eraser can keep working alongside it)."""
        if self._poly_shape is None or self._mask is None:
            return False
        br = self._poly_shape.rect()
        if not br.isEmpty():
            snapshot = self._mask.copy(br)
            self._push_stroke_undo("mask", snapshot, br)
            p = QPainter(self._mask)
            p.drawImage(0, 0, self._poly_shape)
            p.end()
        self._poly_shape = None
        self._poly_pts = []
        self._invalidate_mask_disp()
        self.mask_changed.emit()
        self.update()
        return True

    # ------------------------------------------------------------------ crop
    def set_crop_aspect(self, key: str) -> None:
        a = ASPECT_BY_KEY.get(key)
        if a is None:
            self._crop_aspect = None
            self._crop_aspect_key = "free"
        else:
            self._crop_aspect = (float(a["w"]), float(a["h"]))
            self._crop_aspect_key = key
        if self._crop_rect is not None and self._crop_aspect is not None:
            self._crop_rect = self._aspect_fit_rect(self._crop_rect, self._crop_aspect)
        self.crop_changed.emit()
        self.update()

    def crop_aspect_key(self) -> str:
        return self._crop_aspect_key

    def clear_crop(self) -> None:
        """Drop the crop frame without cropping (Esc / CANCEL)."""
        self._crop_rect = None
        self._crop_drag = 0
        self.crop_changed.emit()
        self.update()

    def _ensure_crop_rect(self) -> None:
        if self._doc is None:
            self._crop_rect = None
            return
        if self._crop_rect is not None:
            return
        w, h = float(self._doc.width()), float(self._doc.height())
        r = QRectF(w * 0.09, h * 0.09, w * 0.82, h * 0.82)
        if self._crop_aspect is not None:
            r = self._aspect_fit_rect(r, self._crop_aspect)
        self._crop_rect = r

    @staticmethod
    def _aspect_fit_rect(rect: QRectF, aspect: Tuple[float, float]) -> QRectF:
        """Largest centered rect inside `rect` matching w:h."""
        aw, ah = aspect
        if aw <= 0 or ah <= 0:
            return QRectF(rect)
        scale = min(rect.width() / aw, rect.height() / ah)
        w = aw * scale
        h = ah * scale
        cx, cy = rect.center().x(), rect.center().y()
        return QRectF(cx - w / 2.0, cy - h / 2.0, w, h)

    def crop_doc_rect(self) -> Optional[QRect]:
        if self._doc is None or self._crop_rect is None:
            return None
        r = self._crop_rect.intersected(QRectF(self._doc.rect()))
        qr = QRect(int(round(r.left())), int(round(r.top())),
                   int(round(r.width())), int(round(r.height())))
        if qr.width() < 8 or qr.height() < 8:
            return None
        return qr

    def apply_crop(self, rect: Optional[QRect] = None) -> bool:
        """Crop the working document + mask + paint layer in memory. Nothing
        is written to disk — the result stays on the stage for further work."""
        if self._doc is None:
            return False
        if rect is None:
            rect = self.crop_doc_rect()
        if rect is None or rect.width() < 8 or rect.height() < 8:
            return False
        # a pending lasso selection is unioned into the mask first so it stays
        # aligned with the cropped content
        self.commit_poly()
        self._doc = self._doc.copy(rect)
        if self._mask is not None:
            self._mask = self._mask.copy(rect)
        if self._paint is not None:
            self._paint = self._paint.copy(rect)
            self._paint_cov_val = None
        self._stroke_undo.clear()
        self._stroke_snapshot = None
        self._stroke_bbox = None
        self._poly_shape = None
        self._poly_pts = []
        self._poly_drawing = False
        self._crop_rect = None
        self._crop_drag = 0
        self._invalidate_mask_disp()
        self.fit_view()
        self.mask_changed.emit()
        self.poly_state_changed.emit(False)
        self.crop_changed.emit()
        return True

    def _crop_handle_at(self, view_pos: QPointF) -> int:
        """1..8 = corner/edge handles (TL,TR,BR,BL,T,R,B,L), -2 = inside move,
        0 = outside (draw new)."""
        if self._doc is None or self._crop_rect is None:
            return 0
        r = self._crop_rect
        tl = self._to_view(r.topLeft())
        br = self._to_view(r.bottomRight())
        vr = QRectF(tl, br)
        hit = self._CROP_HIT_PX
        corners = [
            vr.topLeft(), vr.topRight(), vr.bottomRight(), vr.bottomLeft(),
        ]
        for i, cpt in enumerate(corners):
            if math.hypot(view_pos.x() - cpt.x(), view_pos.y() - cpt.y()) <= hit:
                return i + 1
        edges = [
            QPointF(vr.center().x(), vr.top()),
            QPointF(vr.right(), vr.center().y()),
            QPointF(vr.center().x(), vr.bottom()),
            QPointF(vr.left(), vr.center().y()),
        ]
        for i, ept in enumerate(edges):
            if math.hypot(view_pos.x() - ept.x(), view_pos.y() - ept.y()) <= hit:
                return i + 5
        if vr.contains(view_pos):
            return -2
        return 0

    def _crop_update_drag(self, view_pos: QPointF) -> None:
        """Live crop-frame geometry. Handles 1..4 are corners (TL,TR,BR,BL),
        5..8 are edges (T,R,B,L), -2 = move the whole frame, -3 = draw a new
        frame. Aspect lock mirrors the generation aspect set."""
        if self._doc is None or self._crop_rect is None or self._crop_press is None:
            return
        dw = float(self._doc.width())
        dh = float(self._doc.height())
        cur = self._to_doc(view_pos)
        cur.setX(max(0.0, min(dw, cur.x())))
        cur.setY(max(0.0, min(dh, cur.y())))
        ratio = None
        if self._crop_aspect is not None:
            ratio = self._crop_aspect[0] / max(1e-6, self._crop_aspect[1])
        r = QRectF(self._crop_rect)
        mode = self._crop_drag
        mn = self._CROP_MIN

        if mode == -2 and self._crop_origin is not None:
            press_doc = self._to_doc(self._crop_press)
            dx = cur.x() - press_doc.x()
            dy = cur.y() - press_doc.y()
            o = QRectF(self._crop_origin)
            nx = min(max(o.left() + dx, 0.0), dw - o.width())
            ny = min(max(o.top() + dy, 0.0), dh - o.height())
            r = QRectF(nx, ny, o.width(), o.height())
        elif mode == -3:
            press_doc = self._to_doc(self._crop_press)
            press_doc.setX(max(0.0, min(dw, press_doc.x())))
            press_doc.setY(max(0.0, min(dh, press_doc.y())))
            w = abs(cur.x() - press_doc.x())
            h = abs(cur.y() - press_doc.y())
            if ratio is not None:
                w = max(w, h * ratio)
                h = w / ratio
            w = max(mn, min(w, dw))
            h = max(mn, min(h, dh))
            if ratio is not None and h * ratio <= dw:
                w = h * ratio
            x = press_doc.x() if cur.x() >= press_doc.x() else press_doc.x() - w
            y = press_doc.y() if cur.y() >= press_doc.y() else press_doc.y() - h
            r = QRectF(max(0.0, min(dw - w, x)), max(0.0, min(dh - h, y)), w, h)
        elif 1 <= mode <= 4:
            anchors = {
                1: QPointF(r.right(), r.bottom()),   # TL handle -> BR anchor
                2: QPointF(r.left(), r.bottom()),    # TR handle -> BL anchor
                3: QPointF(r.left(), r.top()),       # BR handle -> TL anchor
                4: QPointF(r.right(), r.top()),      # BL handle -> TR anchor
            }
            a = anchors[mode]
            avail_w = (dw - a.x()) if cur.x() >= a.x() else a.x()
            avail_h = (dh - a.y()) if cur.y() >= a.y() else a.y()
            w = max(0.0, abs(cur.x() - a.x()))
            h = max(0.0, abs(cur.y() - a.y()))
            if ratio is not None:
                w = max(w, h * ratio, mn)
                h = w / ratio
                if h > avail_h:
                    h = avail_h
                    w = h * ratio
            w = max(mn, min(w, avail_w))
            h = max(mn, min(h, avail_h))
            x = a.x() if cur.x() >= a.x() else a.x() - w
            y = a.y() if cur.y() >= a.y() else a.y() - h
            r = QRectF(x, y, w, h)
        else:  # edge handles 5..8
            if mode in (5, 7):  # top / bottom
                anchor_y = r.bottom() if mode == 5 else r.top()
                h = max(mn, min(abs(cur.y() - anchor_y), anchor_y if mode == 5 else dh - anchor_y))
                y = anchor_y - h if mode == 5 else anchor_y
                w = r.width()
                x = r.left()
                if ratio is not None:
                    w = min(dw, h * ratio)
                    cx = r.center().x()
                    x = max(0.0, min(dw - w, cx - w / 2.0))
            else:  # left / right
                anchor_x = r.right() if mode == 8 else r.left()
                w = max(mn, min(abs(cur.x() - anchor_x), anchor_x if mode == 8 else dw - anchor_x))
                x = anchor_x - w if mode == 8 else anchor_x
                h = r.height()
                y = r.top()
                if ratio is not None:
                    h = min(dh, w / ratio)
                    cy = r.center().y()
                    y = max(0.0, min(dh - h, cy - h / 2.0))
            r = QRectF(x, y, w, h)

        r = r.intersected(QRectF(0.0, 0.0, dw, dh))
        if r.width() >= mn and r.height() >= mn:
            self._crop_rect = r
            self.crop_changed.emit()
            self.update()

    # ------------------------------------------------------------------ rotate
    def set_rot_angle(self, deg: float) -> None:
        deg = max(-180.0, min(180.0, float(deg)))
        if abs(deg - self._rot_angle) < 0.001:
            return
        self._rot_angle = deg
        self.rot_changed.emit(deg)
        self.update()

    def rot_angle(self) -> float:
        return self._rot_angle

    def apply_rotation(self) -> bool:
        """Bake the pending tilt: rotate doc, mask and paint layer around the
        center keeping the canvas borders; corners become transparent."""
        if self._doc is None or abs(self._rot_angle) < 0.01:
            return False
        # a pending lasso selection is unioned into the mask first so it rotates
        # together with the content
        self.commit_poly()
        deg = self._rot_angle
        self._doc = rotate_qimage_about_center(self._doc, deg)
        if self._mask is not None:
            self._mask = rotate_qimage_about_center(self._mask, deg)
        if self._paint is not None:
            self._paint = rotate_qimage_about_center(self._paint, deg)
            self._paint_cov_val = None
        self._stroke_undo.clear()
        self._stroke_snapshot = None
        self._stroke_bbox = None
        self._rot_angle = 0.0
        self._invalidate_view_caches(keep_doc=False)
        self._invalidate_mask_disp()
        self.rot_changed.emit(0.0)
        self.mask_changed.emit()
        self.update()
        return True

    # ------------------------------------------------------------------ Qt events
    def _flare_scale_ring_radius(self, f: Dict[str, Any]) -> float:
        sc = max(30, min(250, int(f.get("scale", 100))))
        return 18.0 + (sc / 100.0) * 20.0

    def _flare_scale_grip_at(self, view_pos: QPointF) -> int:
        if self._doc is None or not (0 <= self._selected_flare < len(self._flares)):
            return -1
        f = self._flares[self._selected_flare]
        dr = self._doc_rect()
        hx = dr.left() + float(f.get("x", 0.5)) * dr.width()
        hy = dr.top() + float(f.get("y", 0.5)) * dr.height()
        ring_r = self._flare_scale_ring_radius(f)
        if math.hypot(view_pos.x() - (hx + ring_r), view_pos.y() - hy) <= 12.0:
            return self._selected_flare
        return -1

    def _cursor_dirty_rect(self, pos: Optional[QPointF]) -> QRect:
        if pos is None:
            return QRect()
        r = int(math.ceil((self._brush_size * 0.5) * self._scale)) + 24
        return QRect(int(pos.x()) - r, int(pos.y()) - r, r * 2, r * 2).intersected(self.rect())

    def wheelEvent(self, event) -> None:  # noqa: N802
        delta = event.angleDelta().y()
        if delta:
            if (
                (event.modifiers() & Qt.KeyboardModifier.ShiftModifier)
                and self._tool == self.TOOL_FLARE
                and 0 <= self._selected_flare < len(self._flares)
            ):
                cur = int(self._flares[self._selected_flare].get("scale", 100))
                nxt = max(30, min(250, cur + (10 if delta > 0 else -10)))
                if nxt != cur:
                    self.flare_scaled.emit(self._selected_flare, nxt)
                event.accept()
                return
            self.zoom_by(1.22 if delta > 0 else 1.0 / 1.22, event.position().toPoint())
        event.accept()

    def mousePressEvent(self, event) -> None:  # noqa: N802
        # v7.0: Ctrl + Right Mouse Click anywhere on the editor canvas restores Fit View
        if (
            event.button() == Qt.MouseButton.RightButton
            and (event.modifiers() & Qt.KeyboardModifier.ControlModifier)
        ):
            if self._doc is not None:
                self.fit_view()
                self.fit_restored.emit()
            event.accept()
            return
        if event.button() == Qt.MouseButton.LeftButton:
            if event.modifiers() & Qt.KeyboardModifier.ControlModifier:
                self._zoom_start = event.position().toPoint()
                self._zoom_rect = QRect(self._zoom_start, self._zoom_start)
                event.accept()
                return
            if self._doc is None:
                return
            pos = event.position()
            if self._split_compare and not self._compare:
                dr = self._doc_rect()
                sx = dr.left() + self._split_pos * dr.width()
                if abs(pos.x() - sx) <= 10.0 and dr.top() <= pos.y() <= dr.bottom():
                    self._dragging_split = True
                    self.setCursor(Qt.CursorShape.SplitHCursor)
                    event.accept()
                    return
            if (event.modifiers() & Qt.KeyboardModifier.AltModifier
                    and self._tool in (self.TOOL_PAINT, self.TOOL_BRUSH, self.TOOL_ERASE)):
                self._pick_color_at(pos)
                event.accept()
                return
            if self._tool == self.TOOL_DEPTH:
                if self._depth_probe_img is not None:
                    doc_pt = self._to_doc(pos)
                    nx = max(0.0, min(1.0, doc_pt.x() / max(1.0, float(self._doc.width()))))
                    ny = max(0.0, min(1.0, doc_pt.y() / max(1.0, float(self._doc.height()))))
                    val = sample_depth_at(self._depth_probe_img, nx, ny, self._depth_probe_invert)
                    if val is not None:
                        self._hover_depth_val = val
                        self.depth_sampled.emit(val)
                        self.update()
                event.accept()
                return
            if self._tool == self.TOOL_FLARE:
                s_hit = self._flare_scale_grip_at(pos)
                if s_hit >= 0:
                    f = self._flares[s_hit]
                    if not f.get("locked", False):
                        dr = self._doc_rect()
                        hx = dr.left() + float(f.get("x", 0.5)) * dr.width()
                        hy = dr.top() + float(f.get("y", 0.5)) * dr.height()
                        self._scaling_flare = True
                        self._scale_flare_start_dist = max(8.0, math.hypot(pos.x() - hx, pos.y() - hy))
                        self._scale_flare_start_val = int(f.get("scale", 100))
                    event.accept()
                    return
                hit = self._flare_handle_at(pos)
                if hit >= 0:
                    self._selected_flare = hit
                    self._dragging_flare = not bool(self._flares[hit].get("locked", False))
                    self.flare_selected.emit(hit)
                else:
                    doc = self._to_doc(pos)
                    fx = max(-0.2, min(1.2, doc.x() / max(1, self._doc.width())))
                    fy = max(-0.2, min(1.2, doc.y() / max(1, self._doc.height())))
                    self.flare_placed.emit(fx, fy)
                event.accept()
                return
            if self._tool == self.TOOL_POLY:
                doc_pt = self._to_doc(pos)
                if self._poly_drawing:
                    if len(self._poly_pts) >= 3:
                        first_v = self._to_view(self._poly_pts[0])
                        if math.hypot(pos.x() - first_v.x(), pos.y() - first_v.y()) <= self._POLY_CLOSE_PX:
                            self.close_poly()
                            event.accept()
                            return
                    last = self._poly_pts[-1]
                    if math.hypot(doc_pt.x() - last.x(), doc_pt.y() - last.y()) * self._scale < 1.5:
                        event.accept()
                        return
                    self._poly_pts.append(doc_pt)
                else:
                    if self._poly_shape is not None:
                        self.commit_poly()
                    self._poly_drawing = True
                    self._poly_pts = [doc_pt]
                self.update()
                event.accept()
                return
            if self._tool == self.TOOL_CROP:
                self._ensure_crop_rect()
                self._crop_press = QPointF(pos)
                self._crop_origin = QRectF(self._crop_rect)
                self._crop_drag = self._crop_handle_at(pos)
                if self._crop_drag == 0:
                    doc_pt = self._to_doc(pos)
                    self._crop_rect = QRectF(doc_pt, doc_pt)
                    self._crop_drag = -3
                self.update()
                event.accept()
                return
            if self._tool in (self.TOOL_BRUSH, self.TOOL_ERASE):
                self._begin_stroke("mask")
                self._painting = True
                self._last_doc = self._to_doc(pos)
                dirty = self._stamp_line(self._last_doc, self._last_doc)
                wd = self._doc_rect_to_widget_dirty(dirty).united(self._cursor_dirty_rect(pos))
                self.update(wd if not wd.isEmpty() else self.rect())
                event.accept()
                return
            if self._tool == self.TOOL_PAINT:
                self._begin_stroke("paint")
                self._painting = True
                self._last_doc = self._to_doc(pos)
                dirty = self._stamp_paint_line(self._last_doc, self._last_doc)
                wd = self._doc_rect_to_widget_dirty(dirty).united(self._cursor_dirty_rect(pos))
                self.update(wd if not wd.isEmpty() else self.rect())
                event.accept()
                return
            self._panning = True
            self._pan_start = pos.toPoint()
            self._pan_h0, self._pan_v0 = self._ox, self._oy
            self.setCursor(Qt.CursorShape.ClosedHandCursor)
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event) -> None:  # noqa: N802
        pos = event.position()
        prev_cur = self._last_cursor_rect
        self._hover = QPointF(pos)
        if self._zoom_rect is not None:
            self._zoom_rect = QRect(self._zoom_start, pos.toPoint()).normalized()
            self.update()
            event.accept()
            return
        if self._dragging_split and self._doc is not None:
            dr = self._doc_rect()
            self._split_pos = max(0.02, min(0.98, (pos.x() - dr.left()) / max(1.0, dr.width())))
            self.update()
            event.accept()
            return
        if self._scaling_flare and self._doc is not None and 0 <= self._selected_flare < len(self._flares):
            f = self._flares[self._selected_flare]
            dr = self._doc_rect()
            hx = dr.left() + float(f.get("x", 0.5)) * dr.width()
            hy = dr.top() + float(f.get("y", 0.5)) * dr.height()
            dist = max(8.0, math.hypot(pos.x() - hx, pos.y() - hy))
            new_scale = max(30, min(250, int(round(self._scale_flare_start_val * (dist / max(8.0, self._scale_flare_start_dist))))))
            self.flare_scaled.emit(self._selected_flare, new_scale)
            event.accept()
            return
        if self._dragging_flare and self._doc is not None and 0 <= self._selected_flare < len(self._flares):
            doc = self._to_doc(pos)
            fx = max(-0.25, min(1.25, doc.x() / max(1, self._doc.width())))
            fy = max(-0.25, min(1.25, doc.y() / max(1, self._doc.height())))
            self.flare_moved.emit(self._selected_flare, fx, fy)
            event.accept()
            return
        if self._tool == self.TOOL_POLY and self._poly_drawing:
            self._poly_hover = self._to_doc(pos)
            self.update()
            event.accept()
            return
        if self._tool == self.TOOL_CROP and self._crop_drag != 0 and self._crop_rect is not None:
            self._crop_update_drag(pos)
            event.accept()
            return
        if self._painting and self._last_doc is not None:
            doc = self._to_doc(pos)
            dirty = self._stamp_paint_line(self._last_doc, doc) if self._tool == self.TOOL_PAINT else self._stamp_line(self._last_doc, doc)
            self._last_doc = doc
            cur_rect = self._cursor_dirty_rect(pos)
            self._last_cursor_rect = cur_rect
            wd = self._doc_rect_to_widget_dirty(dirty).united(cur_rect)
            if prev_cur is not None and not prev_cur.isEmpty():
                wd = wd.united(prev_cur)
            self.update(wd if not wd.isEmpty() else self.rect())
            event.accept()
            return
        if self._panning:
            d = pos.toPoint() - self._pan_start
            self._ox = self._pan_h0 + d.x()
            self._oy = self._pan_v0 + d.y()
            self._clamp_pan()
            self.update()
            event.accept()
            return
        if self._split_compare and self._doc is not None and not self._compare:
            dr = self._doc_rect()
            sx = dr.left() + self._split_pos * dr.width()
            if abs(pos.x() - sx) <= 10.0 and dr.top() <= pos.y() <= dr.bottom():
                self.setCursor(Qt.CursorShape.SplitHCursor)
                super().mouseMoveEvent(event)
                return
        if self._tool == self.TOOL_FLARE and self._flare_scale_grip_at(pos) >= 0:
            self.setCursor(Qt.CursorShape.SizeHorCursor)
        elif self._tool == self.TOOL_FLARE and self._flare_handle_at(pos) >= 0:
            self.setCursor(Qt.CursorShape.PointingHandCursor)
        elif self._tool == self.TOOL_FLARE:
            self.setCursor(Qt.CursorShape.CrossCursor)
        elif self._tool == self.TOOL_CROP and self._crop_rect is not None:
            h = self._crop_handle_at(pos)
            self.setCursor({
                1: Qt.CursorShape.SizeFDiagCursor, 3: Qt.CursorShape.SizeFDiagCursor,
                2: Qt.CursorShape.SizeBDiagCursor, 4: Qt.CursorShape.SizeBDiagCursor,
                5: Qt.CursorShape.SizeVerCursor, 7: Qt.CursorShape.SizeVerCursor,
                6: Qt.CursorShape.SizeHorCursor, 8: Qt.CursorShape.SizeHorCursor,
                -2: Qt.CursorShape.SizeAllCursor,
            }.get(h, Qt.CursorShape.CrossCursor))
        if self._tool == self.TOOL_DEPTH and self._doc is not None and self._depth_probe_img is not None:
            dr = self._doc_rect()
            if dr.contains(pos):
                doc_pt = self._to_doc(pos)
                nx = max(0.0, min(1.0, doc_pt.x() / max(1.0, float(self._doc.width()))))
                ny = max(0.0, min(1.0, doc_pt.y() / max(1.0, float(self._doc.height()))))
                self._hover_depth_val = sample_depth_at(self._depth_probe_img, nx, ny, self._depth_probe_invert)
            else:
                self._hover_depth_val = None
            self.update()
        if self._tool in (self.TOOL_BRUSH, self.TOOL_ERASE, self.TOOL_PAINT):
            cur_rect = self._cursor_dirty_rect(pos)
            upd = cur_rect.united(prev_cur) if (prev_cur is not None and not prev_cur.isEmpty()) else cur_rect
            self._last_cursor_rect = cur_rect
            if not upd.isEmpty():
                self.update(upd)
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event) -> None:  # noqa: N802
        if event.button() == Qt.MouseButton.LeftButton:
            if self._zoom_rect is not None:
                r = QRect(self._zoom_rect)
                self._zoom_rect = None
                if r.width() >= 14 and r.height() >= 14 and self._doc is not None:
                    self._zoom_to_rect(r)
                self.update()
                event.accept()
                return
            if self._dragging_split:
                self._dragging_split = False
                self.set_tool(self._tool)
                event.accept()
                return
            if self._scaling_flare:
                self._scaling_flare = False
                event.accept()
                return
            if self._painting:
                was_paint = (self._tool == self.TOOL_PAINT)
                self._painting = False
                self._last_doc = None
                self._finish_stroke()
                if was_paint:
                    self.paint_changed.emit()
                else:
                    self.mask_changed.emit()
                event.accept()
                return
            if self._dragging_flare:
                self._dragging_flare = False
                event.accept()
                return
            if self._tool == self.TOOL_CROP and self._crop_drag != 0:
                self._crop_drag = 0
                self._crop_press = None
                self._crop_origin = None
                self.crop_changed.emit()
                event.accept()
                return
            if self._panning:
                self._panning = False
                self.set_tool(self._tool)
                event.accept()
                return
        super().mouseReleaseEvent(event)

    def mouseDoubleClickEvent(self, event) -> None:  # noqa: N802
        if (event.button() == Qt.MouseButton.LeftButton
                and self._tool == self.TOOL_POLY and self._poly_drawing):
            self.close_poly()
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def keyPressEvent(self, event) -> None:  # noqa: N802
        key = event.key()
        if self._poly_drawing and key in (Qt.Key.Key_A, Qt.Key.Key_Return, Qt.Key.Key_Enter):
            if not self.close_poly():
                self._flash_poly_hint()
            event.accept()
            return
        if key == Qt.Key.Key_Escape:
            if self._poly_drawing:
                self.cancel_poly()
                event.accept()
                return
            if self._poly_shape is not None:
                self.discard_poly()
                event.accept()
                return
            if self._tool == self.TOOL_CROP and self._crop_rect is not None:
                self._crop_rect = None
                self.crop_changed.emit()
                self.update()
                event.accept()
                return
        super().keyPressEvent(event)

    def _flash_poly_hint(self) -> None:
        # too few points: nudge the user with a repaint (badge handled in paint)
        self.update()

    def leaveEvent(self, event) -> None:  # noqa: N802
        self._hover = None
        self._poly_hover = None
        self.update()
        super().leaveEvent(event)

    def _zoom_to_rect(self, r: QRect) -> None:
        vw, vh = max(1, self.width()), max(1, self.height())
        factor = min(vw / float(r.width()), vh / float(r.height())) * 0.97
        old = self._scale
        new = max(0.02, min(16.0, old * factor))
        cx_doc = (r.center().x() - self._ox) / max(1e-6, old)
        cy_doc = (r.center().y() - self._oy) / max(1e-6, old)
        self._scale = new
        self._ox = vw / 2.0 - cx_doc * new
        self._oy = vh / 2.0 - cy_doc * new
        self._clamp_pan()
        self._invalidate_view_caches(keep_doc=False)
        self._invalidate_mask_disp()
        self.zoom_changed.emit(new, False)

    def resizeEvent(self, event) -> None:  # noqa: N802
        super().resizeEvent(event)
        self._invalidate_view_caches(keep_doc=False)
        self._invalidate_mask_disp()
        self.update()

    def dragEnterEvent(self, event) -> None:  # noqa: N802
        if event.mimeData().hasUrls():
            for u in event.mimeData().urls():
                if u.isLocalFile() and u.toLocalFile().lower().endswith((".png", ".webp", ".jpg", ".jpeg")):
                    event.acceptProposedAction()
                    return
        super().dragEnterEvent(event)

    def dropEvent(self, event) -> None:  # noqa: N802
        if event.mimeData().hasUrls():
            for u in event.mimeData().urls():
                if u.isLocalFile() and u.toLocalFile().lower().endswith((".png", ".webp", ".jpg", ".jpeg")):
                    self.image_dropped_in.emit(u.toLocalFile())
                    event.acceptProposedAction()
                    return
        super().dropEvent(event)

    # ------------------------------------------------------------------ paint
    def _rot_active(self) -> float:
        """Live tilt preview angle (only while the TILT tool owns the stage)."""
        if self._tool == self.TOOL_ROTATE and abs(self._rot_angle) >= 0.05:
            return self._rot_angle
        return 0.0

    def paintEvent(self, event) -> None:  # noqa: N802
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        paint_theme_backdrop(p, self.rect())
        if self._doc is None:
            wm = VECTOR_ASSETS.pixmap("viewer_watermark", 132, 132)
            wx = (self.width() - 132) // 2
            wy = (self.height() - 132) // 2 - 30
            p.drawPixmap(wx, wy, wm)
            p.setFont(_font(10.0, True, 1.6))
            p.setPen(QColor(C["kicker"]))
            p.drawText(QRect(12, wy + 140, self.width() - 24, 22), Qt.AlignmentFlag.AlignCenter,
                       "IMAGE EDITOR — full-size stage")
            p.setFont(_font(8.5))
            p.setPen(QColor(C["muted"]))
            p.drawText(QRect(12, wy + 164, self.width() - 24, 20), Qt.AlignmentFlag.AlignCenter,
                       "Open an image from the viewer, the gallery, OPEN\u2026 — or drop one right here")
            p.end()
            return
        rot = self._rot_active()
        dr = self._doc_rect()
        # professional alpha checkerboard behind the document + soft drop shadow
        p.fillRect(dr.adjusted(-8, -8, 8, 10), self._checker_brush())
        for i, alpha in ((5, 34), (3, 52), (1, 66)):
            sp = QPen(QColor(0, 0, 0, alpha))
            sp.setWidthF(2.0 * (i + 1))
            p.setPen(sp)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawRect(dr.adjusted(-(i + 1) * 2.0, -(i + 1) * 2.0, (i + 1) * 2.0, (i + 1) * 2.0))
        self._ensure_disp_caches()
        shown = self._doc if (self._compare or self._display is None) else self._display

        def _draw_base_stage(painter: QPainter, use_original: bool) -> None:
            pm = self._doc_pm if use_original else self._disp_pm
            if pm is not None and not pm.isNull():
                painter.drawPixmap(dr, pm, QRectF(0, 0, pm.width(), pm.height()))
            else:
                painter.drawImage(dr, self._doc if use_original else shown)

        def _draw_paint_layer(painter: QPainter) -> None:
            if self._paint is None or self._compare:
                return
            if self._paint_disp is not None and not self._paint_disp.isNull():
                painter.drawImage(dr, self._paint_disp)
            else:
                painter.drawImage(dr, self._paint)

        def _draw_mask_overlay(painter: QPainter) -> None:
            if self._compare:
                return
            if self._depth_overlay is not None and not self._depth_overlay.isNull():
                painter.save()
                painter.setOpacity(self._depth_overlay_opacity)
                painter.drawImage(dr, self._depth_overlay)
                painter.restore()
            if self._mask is not None and self._mask_visible:
                self._ensure_mask_disp()
                if self._mask_disp is not None and not self._mask_disp.isNull():
                    painter.drawImage(dr, self._mask_disp)
            if self._depth_mask_preview is not None and not self._depth_mask_preview.isNull():
                painter.save()
                painter.setOpacity(0.58 if self._mask_disp_opaque else 0.42)
                painter.drawImage(dr, self._depth_mask_preview)
                painter.restore()

        if rot:
            p.save()
            p.setClipRect(dr)
            t = QTransform()
            t.translate(dr.center().x(), dr.center().y())
            t.rotate(rot)
            t.translate(-dr.center().x(), -dr.center().y())
            p.setTransform(t, True)
            _draw_base_stage(p, self._compare)
            _draw_paint_layer(p)
            _draw_mask_overlay(p)
            p.restore()
        elif self._split_compare and not self._compare:
            split_x = dr.left() + self._split_pos * dr.width()
            p.save()
            p.setClipRect(QRectF(dr.left(), dr.top(), max(0.0, split_x - dr.left()), dr.height()))
            _draw_base_stage(p, True)
            p.restore()
            p.save()
            p.setClipRect(QRectF(split_x, dr.top(), max(0.0, dr.right() - split_x), dr.height()))
            _draw_base_stage(p, False)
            _draw_paint_layer(p)
            _draw_mask_overlay(p)
            p.restore()
            p.setPen(QPen(QColor(C["acc_spec"]), 1.8))
            p.drawLine(QPointF(split_x, dr.top()), QPointF(split_x, dr.bottom()))
            mid_y = dr.center().y()
            pill = QRectF(split_x - 10.0, mid_y - 16.0, 20.0, 32.0)
            p.setPen(QPen(QColor(C["acc_spec"]), 1.2))
            p.setBrush(QColor(C["deep"]))
            p.drawRoundedRect(pill, 6.0, 6.0)
            p.setPen(QColor(C["acc_spec"]))
            p.setFont(_font(8.0, True))
            p.drawText(pill, Qt.AlignmentFlag.AlignCenter, "◂▸")
            p.setFont(_font(7.6, True, 1.0))
            for bx, lbl in ((dr.left() + 8.0, "ORIGINAL"), (dr.right() - 74.0, "GRADED")):
                br_tag = QRectF(bx, dr.top() + 8.0, 66.0, 18.0)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor(0, 0, 0, 168))
                p.drawRoundedRect(br_tag, 4.0, 4.0)
                p.setPen(QColor(C["acc_spec"]))
                p.drawText(br_tag, Qt.AlignmentFlag.AlignCenter, lbl)
        else:
            _draw_base_stage(p, self._compare)
            _draw_paint_layer(p)
            _draw_mask_overlay(p)

        pen = QPen(QColor(C["line_hi"]), 1.0)
        p.setPen(pen)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRect(dr.adjusted(0.5, 0.5, -0.5, -0.5))

        if not self._mask_visible and self.has_mask() and not self._compare and not rot:
            txt = "Mask hidden (active · Press M to show)"
            p.setFont(_font(7.8, True, 0.8))
            mw = QFontMetrics(p.font()).horizontalAdvance(txt) + 18
            mb = QRectF(12.0, 12.0, mw, 21.0)
            p.setPen(QPen(QColor(C["acc_mid"]), 1.0))
            p.setBrush(QColor(0, 0, 0, 178))
            p.drawRoundedRect(mb, 4.0, 4.0)
            p.setPen(QColor(C["acc_spec"]))
            p.drawText(mb, Qt.AlignmentFlag.AlignCenter, txt)

        if rot:
            tick = QColor(C["acc_hi"])
            p.setPen(QPen(tick, 1.6))
            tick_len = 14.0
            for cx, cy, dx, dy in (
                (dr.left(), dr.top(), 1, 1), (dr.right(), dr.top(), -1, 1),
                (dr.left(), dr.bottom(), 1, -1), (dr.right(), dr.bottom(), -1, -1),
            ):
                p.drawLine(QPointF(cx, cy), QPointF(cx + dx * tick_len, cy))
                p.drawLine(QPointF(cx, cy), QPointF(cx, cy + dy * tick_len))
            p.setFont(_font(8.0, True, 1.2))
            rot_txt = f"Tilt {rot:+.1f}° · Preview"
            bw = QFontMetrics(p.font()).horizontalAdvance(rot_txt) + 18
            badge = QRectF(12.0, 12.0, bw, 22.0)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(0, 0, 0, 172))
            p.drawRoundedRect(badge, 3, 3)
            p.setPen(QColor(C["acc_spec"]))
            p.drawText(badge, Qt.AlignmentFlag.AlignCenter, rot_txt)

        if self._flares and self._tool == self.TOOL_FLARE and not self._compare and not rot:
            for i, f in enumerate(self._flares):
                hx = dr.left() + float(f.get("x", 0.5)) * dr.width()
                hy = dr.top() + float(f.get("y", 0.5)) * dr.height()
                sel = (i == self._selected_flare)
                vis = bool(f.get("visible", True))
                locked = bool(f.get("locked", False))
                col = QColor(C["acc_spec"]) if sel else QColor(C["acc_hi"])
                col.setAlpha((235 if sel else 155) if vis else 80)
                hp = QPen(col, 1.6 if sel else 1.1)
                if not vis:
                    hp.setStyle(Qt.PenStyle.DotLine)
                p.setPen(hp)
                p.setBrush(Qt.BrushStyle.NoBrush)
                r = 11.0 if sel else 7.5
                p.drawEllipse(QPointF(hx, hy), r, r)
                # Horizontal anamorphic axis alignment ticks (strictly 0° horizontal)
                p.drawLine(QPointF(hx - r - 10.0, hy), QPointF(hx - r + 1.5, hy))
                p.drawLine(QPointF(hx + r - 1.5, hy), QPointF(hx + r + 10.0, hy))
                p.drawLine(QPointF(hx, hy - r - 3.5), QPointF(hx, hy - r + 1.5))
                p.drawLine(QPointF(hx, hy + r - 1.5), QPointF(hx, hy + r + 3.5))
                if sel:
                    ring_r = self._flare_scale_ring_radius(f)
                    p.setPen(QPen(col, 1.0, Qt.PenStyle.DashLine))
                    p.drawEllipse(QPointF(hx, hy), ring_r, ring_r)
                    if not locked:
                        p.setPen(QPen(QColor(0, 0, 0, 190), 1.0))
                        p.setBrush(QColor(C["acc_spec"]))
                        p.drawEllipse(QPointF(hx + ring_r, hy), 4.8, 4.8)
                    sc_val = int(f.get("scale", 100))
                    tags = []
                    if locked:
                        tags.append("Locked")
                    if f.get("solo"):
                        tags.append("Solo")
                    if not vis:
                        tags.append("Hidden")
                    tag_s = f" ({', '.join(tags)})" if tags else ""
                    btxt = f"Flare {i + 1} · {sc_val}%{tag_s}"
                    p.setFont(_font(7.8, True, 0.2))
                    bw_f = QFontMetrics(p.font()).horizontalAdvance(btxt) + 12.0
                    badge = QRectF(hx + 12.0, hy + 10.0, bw_f, 17.0)
                    p.setPen(Qt.PenStyle.NoPen)
                    bg = QColor(C["acc_mid"]); bg.setAlpha(218)
                    p.setBrush(bg)
                    p.drawRoundedRect(badge, 4, 4)
                    p.setPen(QColor(C["acc_text"]))
                    p.drawText(badge, Qt.AlignmentFlag.AlignCenter, btxt)
        # live split gap line preview (pixel-width cut zone + exact half sizes)
        if self._split_guide_visible and not self._compare and not rot:
            self._paint_split_guide_overlay(p, dr)
        # crop frame overlay
        if self._tool == self.TOOL_CROP and self._crop_rect is not None:
            self._paint_crop_overlay(p, dr)
        # polygon in-progress overlay
        if self._poly_drawing and self._poly_pts:
            self._paint_poly_overlay(p, dr)
        # depth eyedropper hover crosshair + live depth value badge
        if self._tool == self.TOOL_DEPTH and self._hover is not None and not self._compare and not rot:
            self._paint_depth_probe_hud(p, dr)
        # zoom frame
        if self._zoom_rect is not None and self._zoom_rect.width() > 2:
            zp = QPen(QColor(C["acc_spec"]), 1.4, Qt.PenStyle.DashLine)
            p.setPen(zp)
            p.drawRect(QRectF(self._zoom_rect).adjusted(0.5, 0.5, -0.5, -0.5))
            fill = QColor(C["acc_spec"])
            fill.setAlpha(26)
            p.fillRect(QRectF(self._zoom_rect), fill)
        # brush cursor
        if (
            self._hover is not None
            and self._tool in (self.TOOL_BRUSH, self.TOOL_ERASE, self.TOOL_PAINT)
            and not self._zoom_rect
            and not self._compare
        ):
            r = (self._brush_size / 2.0) * self._scale
            if self._tool == self.TOOL_PAINT:
                col = QColor(self._paint_color)
                if self._paint_erase:
                    col = QColor(C["err"])
            else:
                col = QColor(C["acc_spec"]) if self._tool == self.TOOL_BRUSH else QColor(C["err"])
            cpen = QPen(col, 1.2)
            if self._tool == self.TOOL_PAINT and self._paint_erase:
                cpen.setStyle(Qt.PenStyle.DashLine)
            p.setPen(cpen)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawEllipse(self._hover, r, r)
            p.drawPoint(self._hover)
            if self._tool == self.TOOL_PAINT and not self._paint_erase:
                sw = QRectF(self._hover.x() + r + 5.0, self._hover.y() - 5.0, 10.0, 10.0)
                p.setPen(QPen(QColor(C["text_hi"]), 0.8))
                p.setBrush(QBrush(QColor(self._paint_color)))
                p.drawRect(sw)
        # compare badge (v7.0 fix: explicitly apply dark translucent brush)
        if self._compare and not rot:
            badge = QRectF(12.0, 12.0, 118.0, 22.0)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(0, 0, 0, 182))
            p.drawRoundedRect(badge, 3, 3)
            p.setPen(QColor(C["acc_spec"]))
            p.setFont(_font(8.0, True, 1.2))
            p.drawText(badge, Qt.AlignmentFlag.AlignCenter, "ORIGINAL")
        p.end()

    def _paint_split_guide_overlay(self, p: QPainter, dr: QRectF) -> None:
        """Render an exact pixel-accurate live preview of the image split cut
        and excluded center gap strip directly over the document."""
        if self._doc is None:
            return
        w, h = self._doc.width(), self._doc.height()
        vert = self._split_guide_vertical
        span = w if vert else h
        gap = max(0, min(int(self._split_guide_gap), max(0, span // 2 - 1)))
        first_span = max(1, (span - gap) // 2)
        second_span = max(1, span - gap - first_span)
        real_gap = span - first_span - second_span

        p.save()
        p.setClipRect(dr.adjusted(-2.0, -2.0, 2.0, 2.0))
        acc_hi = QColor(C["acc_hi"])
        acc_spec = QColor(C["acc_spec"])
        tint = QColor(C["acc_mid"])
        tint.setAlpha(68)
        hatch = QColor(C["acc_spec"])
        hatch.setAlpha(130)

        if vert:
            x0 = self._to_view(QPointF(float(first_span), 0.0)).x()
            x1 = self._to_view(QPointF(float(w - second_span), 0.0)).x()
            mid_x = 0.5 * (x0 + x1)
            band_w = max(1.5, x1 - x0)
            band = QRectF(mid_x - band_w * 0.5, dr.top(), band_w, dr.height())
            # Translucent hatched exclusion strip representing the exact gap
            if real_gap > 0:
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(tint)
                p.drawRect(band)
                p.setBrush(QBrush(hatch, Qt.BrushStyle.BDiagPattern))
                p.drawRect(band)
            # Dark shadow rails + luminous cut edge lines
            for edge_x in (x0, x1) if real_gap > 0 else (mid_x,):
                p.setPen(QPen(QColor(0, 0, 0, 195), 3.0))
                p.drawLine(QPointF(edge_x, dr.top()), QPointF(edge_x, dr.bottom()))
                p.setPen(QPen(acc_spec, 1.35))
                p.drawLine(QPointF(edge_x, dr.top()), QPointF(edge_x, dr.bottom()))
            if real_gap >= 4:
                p.setPen(QPen(acc_hi, 1.0, Qt.PenStyle.DashLine))
                p.drawLine(QPointF(mid_x, dr.top()), QPointF(mid_x, dr.bottom()))
            tag_a = f"L · {first_span}\u00d7{h}"
            tag_b = f"R · {second_span}\u00d7{h}"
            center_lbl = f"SPLIT L│R · GAP {real_gap} px"
            cx_pill = max(dr.left() + 8.0, min(dr.right() - 160.0, mid_x - 76.0))
            cy_pill = dr.top() + 8.0
            a_pos = QPointF(dr.left() + 8.0, dr.bottom() - 26.0)
            b_pos = QPointF(dr.right() - 102.0, dr.bottom() - 26.0)
        else:
            y0 = self._to_view(QPointF(0.0, float(first_span))).y()
            y1 = self._to_view(QPointF(0.0, float(h - second_span))).y()
            mid_y = 0.5 * (y0 + y1)
            band_h = max(1.5, y1 - y0)
            band = QRectF(dr.left(), mid_y - band_h * 0.5, dr.width(), band_h)
            if real_gap > 0:
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(tint)
                p.drawRect(band)
                p.setBrush(QBrush(hatch, Qt.BrushStyle.BDiagPattern))
                p.drawRect(band)
            for edge_y in (y0, y1) if real_gap > 0 else (mid_y,):
                p.setPen(QPen(QColor(0, 0, 0, 195), 3.0))
                p.drawLine(QPointF(dr.left(), edge_y), QPointF(dr.right(), edge_y))
                p.setPen(QPen(acc_spec, 1.35))
                p.drawLine(QPointF(dr.left(), edge_y), QPointF(dr.right(), edge_y))
            if real_gap >= 4:
                p.setPen(QPen(acc_hi, 1.0, Qt.PenStyle.DashLine))
                p.drawLine(QPointF(dr.left(), mid_y), QPointF(dr.right(), mid_y))
            tag_a = f"T · {w}\u00d7{first_span}"
            tag_b = f"B · {w}\u00d7{second_span}"
            center_lbl = f"SPLIT T\u2014B · GAP {real_gap} px"
            cx_pill = dr.left() + 8.0
            cy_pill = max(dr.top() + 8.0, min(dr.bottom() - 28.0, mid_y - 26.0))
            a_pos = QPointF(dr.right() - 104.0, dr.top() + 8.0)
            b_pos = QPointF(dr.right() - 104.0, dr.bottom() - 26.0)
        p.restore()

        # Floating crisp HUD pills (never clipped by image edges)
        p.setFont(_font(7.8, True, 0.7))
        fm = QFontMetrics(p.font())
        pw_c = fm.horizontalAdvance(center_lbl) + 16.0
        pr_c = QRectF(max(6.0, min(self.width() - pw_c - 6.0, cx_pill)), max(6.0, cy_pill), pw_c, 20.0)
        p.setPen(QPen(acc_spec, 1.1))
        p.setBrush(QColor(0, 0, 0, 196))
        p.drawRoundedRect(pr_c, 3.0, 3.0)
        p.setPen(acc_spec)
        p.drawText(pr_c, Qt.AlignmentFlag.AlignCenter, center_lbl)

        p.setFont(_font(7.3, True, 0.4))
        fm2 = QFontMetrics(p.font())
        for txt, pt in ((tag_a, a_pos), (tag_b, b_pos)):
            tw = fm2.horizontalAdvance(txt) + 12.0
            br = QRectF(max(6.0, min(self.width() - tw - 6.0, pt.x())), max(6.0, min(self.height() - 24.0, pt.y())), tw, 18.0)
            p.setPen(QPen(QColor(C["line_hi"]), 0.9))
            p.setBrush(QColor(0, 0, 0, 174))
            p.drawRoundedRect(br, 3.0, 3.0)
            p.setPen(QColor(C["text_hi"]))
            p.drawText(br, Qt.AlignmentFlag.AlignCenter, txt)

    def _paint_depth_probe_hud(self, p: QPainter, dr: QRectF) -> None:
        """Draw crisp precision depth-sampling reticle + live depth percentage pill."""
        if self._hover is None or not dr.contains(self._hover):
            return
        hx, hy = self._hover.x(), self._hover.y()
        acc = QColor(C["acc_spec"])
        p.setPen(QPen(QColor(0, 0, 0, 190), 2.4))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawEllipse(QPointF(hx, hy), 9.0, 9.0)
        p.setPen(QPen(acc, 1.3))
        p.drawEllipse(QPointF(hx, hy), 9.0, 9.0)
        p.drawLine(QPointF(hx - 14, hy), QPointF(hx - 5, hy))
        p.drawLine(QPointF(hx + 5, hy), QPointF(hx + 14, hy))
        p.drawLine(QPointF(hx, hy - 14), QPointF(hx, hy - 5))
        p.drawLine(QPointF(hx, hy + 5), QPointF(hx, hy + 14))
        if self._hover_depth_val is not None:
            v = self._hover_depth_val
            zone = "NEAR" if v >= 66.0 else ("MID" if v >= 33.0 else "FAR")
            txt = f"DEPTH {v:.0f}% · {zone} (Click to set focus)"
        else:
            txt = "No depth map loaded — Generate or Load in Depth tab"
        p.setFont(_font(7.6, True, 0.5))
        tw = QFontMetrics(p.font()).horizontalAdvance(txt) + 14.0
        bx = hx + 16.0 if hx + 16.0 + tw < self.width() - 6 else hx - tw - 14.0
        by = hy - 22.0 if hy > 30 else hy + 14.0
        br = QRectF(max(6.0, bx), max(6.0, by), tw, 19.0)
        p.setPen(QPen(acc, 1.0))
        p.setBrush(QColor(0, 0, 0, 196))
        p.drawRoundedRect(br, 3.0, 3.0)
        p.setPen(acc)
        p.drawText(br, Qt.AlignmentFlag.AlignCenter, txt)

    def _paint_crop_overlay(self, p: QPainter, dr: QRectF) -> None:
        r = self._crop_rect
        if r is None:
            return
        tl = self._to_view(r.topLeft())
        br = self._to_view(r.bottomRight())
        vr = QRectF(tl, br).normalized()
        # dim everything outside the crop
        dim = QColor(0, 0, 0, 132)
        stage = self.rect()
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QBrush(dim))
        p.drawRect(QRectF(stage.left(), stage.top(), stage.width(), max(0.0, vr.top() - stage.top())))
        p.drawRect(QRectF(stage.left(), vr.bottom(), stage.width(), max(0.0, stage.bottom() - vr.bottom())))
        p.drawRect(QRectF(stage.left(), vr.top(), max(0.0, vr.left() - stage.left()), vr.height()))
        p.drawRect(QRectF(vr.right(), vr.top(), max(0.0, stage.right() - vr.right()), vr.height()))
        # frame + rule-of-thirds grid
        p.setPen(QPen(QColor(C["acc_spec"]), 1.4))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRect(vr)
        p.setPen(QPen(QColor(255, 255, 255, 46), 0.8))
        for i in (1, 2):
            gx = vr.left() + vr.width() * i / 3.0
            gy = vr.top() + vr.height() * i / 3.0
            p.drawLine(QPointF(gx, vr.top()), QPointF(gx, vr.bottom()))
            p.drawLine(QPointF(vr.left(), gy), QPointF(vr.right(), gy))
        # 8 handles (crisp light squares with dark seats — visible on any pixel)
        hs = 4.6
        handle_pts = [
            vr.topLeft(), vr.topRight(), vr.bottomRight(), vr.bottomLeft(),
            QPointF(vr.center().x(), vr.top()), QPointF(vr.right(), vr.center().y()),
            QPointF(vr.center().x(), vr.bottom()), QPointF(vr.left(), vr.center().y()),
        ]
        for cpt in handle_pts:
            seat = QRectF(cpt.x() - hs - 1.0, cpt.y() - hs - 1.0, (hs + 1.0) * 2.0, (hs + 1.0) * 2.0)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(0, 0, 0, 150))
            p.drawRect(seat)
            p.setBrush(QColor(C["acc_spec"]))
            p.drawRect(QRectF(cpt.x() - hs, cpt.y() - hs, hs * 2.0, hs * 2.0))
        # aspect badge + dimensions
        ratio_txt = "FREE" if self._crop_aspect is None else self._crop_aspect_key
        label = f"{int(round(r.width()))} \u00d7 {int(round(r.height()))}  \u00b7  {ratio_txt}"
        p.setFont(_font(8.0, True, 0.8))
        fm = QFontMetrics(p.font())
        tw = fm.horizontalAdvance(label) + 16
        lb = QRectF(vr.left(), vr.top() - 24.0, tw, 19.0)
        if lb.top() < 2.0:
            lb.moveTop(vr.bottom() + 5.0)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(0, 0, 0, 176))
        p.drawRoundedRect(lb, 3, 3)
        p.setPen(QColor(C["acc_spec"]))
        p.drawText(lb, Qt.AlignmentFlag.AlignCenter, label)

    def _paint_poly_overlay(self, p: QPainter, dr: QRectF) -> None:
        pts = [self._to_view(q) for q in self._poly_pts]
        if not pts:
            return
        # closing preview: outline + rubber band to the cursor
        pen_col = QColor(C["acc_spec"])
        p.setPen(QPen(pen_col, 1.6, Qt.PenStyle.DashLine))
        p.setBrush(QColor(255, 80, 80, 36))
        poly = QPolygonF(pts)
        if self._poly_hover is not None and len(pts) >= 2:
            path = QPolygonF(pts + [self._to_view(self._poly_hover)])
            p.drawPolygon(path)
        else:
            p.drawPolygon(poly)
        # first point gets the "close here" halo
        fp = pts[0]
        near = False
        if self._hover is not None and len(pts) >= 3:
            near = math.hypot(self._hover.x() - fp.x(), self._hover.y() - fp.y()) <= self._POLY_CLOSE_PX
        halo = QColor(C["acc_spec"])
        halo.setAlpha(70 if near else 26)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QBrush(halo))
        p.drawEllipse(fp, 10.0 if near else 7.5, 10.0 if near else 7.5)
        for i, q in enumerate(pts):
            sq = QRectF(q.x() - 3.2, q.y() - 3.2, 6.4, 6.4)
            p.setPen(QPen(QColor(0, 0, 0, 170), 1.0))
            p.setBrush(QBrush(QColor(C["acc_spec"] if i == 0 else QColor(255, 255, 255, 235))))
            p.drawRect(sq)
        hint = f"{len(pts)} pts \u00b7 A / click first point = close \u00b7 Esc = cancel"
        p.setFont(_font(7.8, True, 0.6))
        fm = QFontMetrics(p.font())
        tw = fm.horizontalAdvance(hint) + 14
        hb = QRectF(12.0, 38.0, tw, 18.0)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(0, 0, 0, 170))
        p.drawRoundedRect(hb, 3, 3)
        p.setPen(QColor(C["acc_spec"]))
        p.drawText(hb, Qt.AlignmentFlag.AlignCenter, hint)
class MainWindow(QMainWindow):
    def __init__(self) -> None:
        super().__init__()
        ensure_dirs()
        SOUNDS._ensure_backend()  # players need a living QApplication
        self.settings = load_settings()
        self.llm_settings = load_llm_settings()
        self.lora_lib = load_lora_library(self.settings)
        self.api_key = load_api_key()  # personal key as stored in data/key.txt
        self.anon_mode = bool((self.settings.get("horde") or {}).get("anonymous", False))
        self.api = HordeAPI(HORDE_URL, self.effective_key(), CLIENT_AGENT)
        self.store = ImageStore(TEMP_DIR, OUTPUT_DIR)
        self.queue = QueueManager(self.api, self.store, self)

        self.templates: Dict[str, List[Dict[str, str]]] = {"anime": [], "krea": [], "moss": []}
        self.active_template: Optional[Dict[str, str]] = None
        self.tag_folders: List[str] = []
        self.tags_by_folder: Dict[str, List[Dict[str, str]]] = {}
        self.samplers: List[str] = list(SAMPLERS_BUILTIN)
        self.history: List[Dict[str, Any]] = load_history()
        self._tasks: List[TaskThread] = []
        self._fullscreen = False
        self._loading = True

        # Per-model negative prompts & span books (remembered separately per stack)
        raw_negs = self.settings.get("negatives") or {}
        self._negatives: Dict[str, str] = {
            "anime": str(raw_negs.get("anime", DEFAULT_NEGATIVES["anime"])),
            "krea": str(raw_negs.get("krea", DEFAULT_NEGATIVES["krea"])),
            "moss": str(raw_negs.get("moss", DEFAULT_NEGATIVES["moss"])),
        }
        self._neg_spans: Dict[str, List[Dict[str, Any]]] = {"anime": [], "krea": [], "moss": []}
        self._active_model_key = model_stack_key(str(self.settings.get("model") or DEFAULT_MODEL))

        # Per-model LLM system prompts (anime / krea / moss)
        raw_sys = self.llm_settings.get("system_prompts") or {}
        self._llm_sys_prompts: Dict[str, str] = {
            k: str(raw_sys.get(k) or v) for k, v in DEFAULT_LLM_SYSTEM_PROMPTS.items()
        }
        self._llm_tpl_key = str(self.llm_settings.get("active_template") or self._active_model_key)
        if self._llm_tpl_key not in DEFAULT_LLM_SYSTEM_PROMPTS:
            self._llm_tpl_key = "krea"

        # Vision (VLM) prompt extraction state — modular per-mode system prompts
        raw_vis = self.llm_settings.get("vision_prompts") or {}
        self._llm_vision_prompts: Dict[str, str] = {
            m: str(raw_vis.get(m) or build_default_vision_prompt(m)) for m in VISION_MODES
        }
        self._llm_vision_mode_key = str(self.llm_settings.get("vision_mode") or "natural")
        if self._llm_vision_mode_key not in VISION_MODES:
            self._llm_vision_mode_key = "natural"
        self._llm_vision_source: Optional[str] = None  # legacy single-source (kept for compat)
        self._llm_vision_images: List[str] = []        # v4: multi-image attachments
        self._llm_vision_task = "describe"             # "describe" | "motion"
        _mp = self.llm_settings.get("vision_motion_prompts") or {}
        self._llm_motion_prompts: Dict[str, str] = {
            m: str(_mp.get(m) or build_default_motion_prompt(m)) for m in VIDEO_MOTION_MODES
        }
        self._llm_motion_mode_key = str(self.llm_settings.get("vision_motion_mode") or "i2va")
        if self._llm_motion_mode_key not in VIDEO_MOTION_MODES:
            self._llm_motion_mode_key = "i2va"

        # Active LoRA folder filter + searches
        self._lora_folder_filter = str((self.settings.get("ui") or {}).get("lora_folder") or "ALL")
        self._lora_browse_key = self._active_model_key
        self._lora_search = ""
        self._tag_search = ""
        self._lora_detail_syncing = False

        # Wildcard roll cache
        self._wc_cache_key: Optional[str] = None
        self._wc_cache_val = ""

        # Image Editor + Depth Studio state (v7.0 — cached low-lag preview)
        self.edit_source_path: Optional[str] = None
        self.edit_base: Optional[QImage] = None
        self._edit_preview_base: Optional[QImage] = None
        self.edit_depth_path: Optional[str] = None
        self.edit_depth_base: Optional[QImage] = None
        self._edit_preview_depth: Optional[QImage] = None
        self.edit_undo_stack: List[QImage] = []
        self.edit_redo_stack: List[QImage] = []
        self._edit_depth_undo_stack: List[Optional[QImage]] = []
        self._edit_depth_redo_stack: List[Optional[QImage]] = []
        self.edit_adjust: Dict[str, float] = default_edit_adjustments()
        self.edit_depth_mask_params: Dict[str, Any] = default_depth_mask_params()
        self.edit_depth_fx: Dict[str, Any] = default_depth_fx()
        self.edit_depth_vis_mode: str = "off"
        self.edit_depth_vis_opacity: int = 65
        self.edit_depth_mask_live: bool = False
        self._edit_split_guide_pinned: bool = False
        self._edit_preview_timer = QTimer(self)
        self._edit_preview_timer.setSingleShot(True)
        self._edit_preview_timer.setInterval(85)
        self._edit_preview_timer.timeout.connect(self._edit_recompute_now)
        self._edit_skipped_effects: List[str] = []
        # v4.1 editor state: cinematic LUT grade + placed anamorphic flares
        self.edit_lut_key: str = ""
        self.edit_lut_intensity: int = 100
        self.edit_flares: List[Dict[str, Any]] = []
        self._edit_flare_sel: int = -1
        self._edit_stage_visible: bool = False

        # Alchemy aesthetic scoring workers
        self._aesthetic_workers: List[AestheticWorker] = []
        self._aesthetic_pending: List[str] = []

        # Browser VPN bridge & local SillyTavern server
        self.bridge: Optional[BrowserBridge] = None
        self.st_server: Optional[LocalStServer] = None
        self._st_waiters: Dict[int, Dict[str, Any]] = {}
        self._st_bridge = _StSubmitBridge(self)
        self._st_bridge.requested.connect(self._st_enqueue_request)
        self._st_state_cache: Dict[str, Any] = {}
        self._server_status_timer = QTimer(self)
        self._server_status_timer.setInterval(2000)
        self._server_status_timer.timeout.connect(self._update_server_status)
        self._server_status_timer.start()

        # Span books for colored tag-group & LoRA-trigger highlights
        self.prompt_book = SpanBook()
        self.neg_book = SpanBook()
        # Re-entrancy guards: on Qt >= 6.12 QSyntaxHighlighter.rehighlight()
        # re-emits textChanged even when no format changed, which would make
        # the textChanged -> rehighlight -> textChanged chain recurse
        # infinitely until CPython's C-stack guard aborts the app.
        self._prompt_hl_busy = False
        self._neg_hl_busy = False

        # Tile upscale state
        self.ups_source: Optional[str] = None
        self.ups_source_meta: Dict[str, Any] = {}
        self.ups_groups: Dict[int, Dict[str, Any]] = {}
        self.ups_active_gid: Optional[int] = None
        self._ups_next_gid = 1
        self._ups_pending_tpl_name = ""
        self._ups_refresh_timer = QTimer(self)
        self._ups_refresh_timer.setSingleShot(True)
        self._ups_refresh_timer.setInterval(150)
        self._ups_refresh_timer.timeout.connect(self._ups_refresh_now)

        # Debounced persistence timers
        self._save_timer = QTimer(self)
        self._save_timer.setSingleShot(True)
        self._save_timer.setInterval(750)
        self._save_timer.timeout.connect(self.save_now)

        self._llm_save_timer = QTimer(self)
        self._llm_save_timer.setSingleShot(True)
        self._llm_save_timer.setInterval(650)
        self._llm_save_timer.timeout.connect(self.save_llm_now)

        # Slideshow timer
        self._slide_timer = QTimer(self)
        self._slide_timer.setInterval(3000)
        self._slide_timer.timeout.connect(self._slide_step)

        # Single reusable status-flash reset timer (prevents overlapping singleShot races)
        self._flash_timer = QTimer(self)
        self._flash_timer.setSingleShot(True)
        self._flash_timer.setInterval(2600)
        self._flash_timer.timeout.connect(self._update_summary)

        # Gentle periodic telemetry refresh (heartbeat + account every 3 min)
        self._telemetry_timer = QTimer(self)
        self._telemetry_timer.setInterval(180000)
        self._telemetry_timer.timeout.connect(self.startup_network)
        self._telemetry_timer.start()

        # Thread-safe in-memory logger bridge
        self._log_bridge = _LogBridge(self)
        self._log_bridge.logged.connect(self._on_log_record)
        STUDIO_LOG.subscribe(self._log_bridge.logged.emit)

        self.setWindowTitle(f"{APP_NAME}  {APP_VERSION}  \u2014  AI Horde Workstation")
        self.setWindowIcon(VECTOR_ASSETS.icon("app_emblem", 32))
        self.setMinimumSize(640, 460)

        self._build_ui()
        self.toast = ToastOverlay(self.centralWidget())
        self.prompt_hl = SpanHighlighter(self.prompt_book, self.prompt_edit.document())
        self.neg_hl = SpanHighlighter(self.neg_book, self.neg_edit.document())

        self._build_menu()
        self._wire_shortcuts()
        self._apply_settings()
        self.load_templates()
        self.load_tags()
        self._rebuild_lora_ui()
        self.refresh_gallery()
        self._loading = False
        self._sync_tab_ribbon()
        self._update_preview()
        self._update_summary()
        self._update_generate_subtext()
        self._refresh_log_console()

        STUDIO_LOG.info("SYS", f"{APP_NAME} v{APP_VERSION} initialized | data={DATA_DIR} | outputs={OUTPUT_DIR}")
        if self.store.orphans_cleaned:
            STUDIO_LOG.info("SYS", f"Cleaned {self.store.orphans_cleaned} orphan metadata sidecar(s)")
        QTimer.singleShot(350, self.startup_network)

    # ------------------------------------------------------------------ UI Build
    def _build_ui(self) -> None:
        # v3.1: the window-filling top telemetry strip and the bottom status rail
        # are GONE — every pixel now belongs to the working split. The few
        # features they carried live on: menu + theme switch (viewer caption
        # row), history (Prompt tab header), LoRA / Horde chips
        # (command deck summary row), kudos & transport (HORDE tab).
        central = QWidget()
        outer = QVBoxLayout(central)
        outer.setContentsMargins(0, 0, 0, 0)
        outer.setSpacing(0)

        body = QWidget()
        root = QHBoxLayout(body)
        root.setContentsMargins(2, 2, 2, 2)
        root.setSpacing(0)
        self.split = QSplitter(Qt.Orientation.Horizontal)
        self.split.setObjectName("RootSplitter")
        self.left = self._build_left()
        self.right = self._build_right()
        self.split.addWidget(self.left)
        self.split.addWidget(self.right)
        self.split.setStretchFactor(0, 0)
        self.split.setStretchFactor(1, 1)
        self.split.setCollapsible(0, False)
        self.split.setCollapsible(1, False)
        root.addWidget(self.split)
        self.split.splitterMoved.connect(lambda *_a: self._on_workspace_resized())
        outer.addWidget(body, 1)
        self.setCentralWidget(central)

    def _on_workspace_resized(self) -> None:
        self._sync_tab_rail_width()
        self._sync_edit_stage_density()
        self._sync_deck_and_viewer_density()

    def _sync_tab_rail_width(self) -> None:
        """Distribute all 9 icon tabs cleanly across the exact left-panel width
        with zero horizontal scrolling and auto-scaled crisp icons at any width."""
        if not hasattr(self, "tabs"):
            return
        bar = self.tabs.tabBar()
        n = max(1, self.tabs.count())
        w = max(0, self.tabs.width())
        if w <= 0:
            return
        scale = ui_scale()
        avail_per_tab = max(18, (w - 4) // n)
        px = tab_icon_px(scale, avail_per_tab)
        rail_h = tab_rail_height(scale, px)
        if isinstance(bar, _AutoFitIconTabBar):
            bar.set_available_width(w)
            bar.set_rail_height(rail_h)
        else:
            bar.setFixedHeight(rail_h)
        if px != int(getattr(self, "_tab_icon_px", 0)):
            self._tab_icon_px = px
            self.tabs.setIconSize(QSize(px, px))
            for idx, (icon_key, _name, _tip) in enumerate(self._tab_specs):
                self.tabs.setTabIcon(idx, VECTOR_ASSETS.icon(icon_key, px))
        bar.updateGeometry()
        bar.update()
        if hasattr(self, "edit_subtabs"):
            self.edit_subtabs.tabBar().updateGeometry()
            self.edit_subtabs.tabBar().update()

    def _sync_edit_stage_density(self) -> None:
        """Adapt Edit Stage tool & overlay buttons between compact icon-only
        (800x600 / narrow split) and icon+label (wide display) so nothing ever overflows."""
        if not hasattr(self, "edit_tool_btns") or not hasattr(self, "edit_stage"):
            return
        stage_w = self.edit_stage.width()
        compact = (stage_w > 0 and stage_w < 680)
        if getattr(self, "_edit_stage_compact", None) != compact:
            self._edit_stage_compact = compact
            labels = getattr(self, "_edit_tool_labels", {})
            for k, btn in self.edit_tool_btns.items():
                btn.setText("" if compact else labels.get(k, ""))
        ov_compact = (stage_w > 0 and stage_w < 580)
        if getattr(self, "_edit_overlay_compact", None) != ov_compact:
            self._edit_overlay_compact = ov_compact
            for attr, full_txt in (
                ("edit_mask_vis_btn", "Mask"),
                ("edit_stage_depth_btn", "Depth"),
                ("edit_stage_split_btn", "Split"),
                ("edit_split_cmp_btn", "Wipe"),
            ):
                b = getattr(self, attr, None)
                if b is not None:
                    b.setText("" if ov_compact else full_txt)
                    b.setToolButtonStyle(
                        Qt.ToolButtonStyle.ToolButtonIconOnly if ov_compact
                        else Qt.ToolButtonStyle.ToolButtonTextBesideIcon
                    )
        if hasattr(self, "edit_ctx_stack"):
            self.edit_ctx_stack.updateGeometry()

    def _sync_deck_and_viewer_density(self) -> None:
        """Keep left deck, right viewer utility rows, and edit context bar crisp
        and overflow-free on 800x600 displays, narrow dragged splits & HiDPI scale."""
        scale = ui_scale()
        if hasattr(self, "gen_btn"):
            compact_h = self.height() > 0 and self.height() <= 640
            self.gen_btn.apply_metrics(scale, compact=compact_h)
        if hasattr(self, "edit_ctx_stack"):
            self.edit_ctx_stack.setMaximumHeight(max(64, int(round(78 * scale))))
            self.edit_ctx_stack.updateGeometry()
        if hasattr(self, "lora_folder_wrap") and hasattr(self, "lora_folder_strip"):
            w_strip = max(180, self.lora_folder_strip.viewport().width() or 260)
            want_h = min(84, max(28, self.lora_folder_flow.heightForWidth(w_strip) + 4))
            if self.lora_folder_strip.height() != want_h:
                self.lora_folder_strip.setFixedHeight(want_h)
        if hasattr(self, "left") and hasattr(self, "chip_lora"):
            lw = self.left.width()
            narrow_l = (lw > 0 and lw < 290)
            if getattr(self, "_deck_narrow", None) != narrow_l:
                self._deck_narrow = narrow_l
                self._update_deck_badges()
        if hasattr(self, "right_tabs") and hasattr(self, "gallery_btn"):
            rw = self.right_tabs.width()
            narrow_r = (rw > 0 and rw < 420)
            if getattr(self, "_viewer_narrow", None) != narrow_r:
                self._viewer_narrow = narrow_r
                self.gallery_btn.setText("Strip" if not narrow_r else "\u25A6")
                if hasattr(self, "theme_combo"):
                    self.theme_combo.setMinimumWidth(64 if narrow_r else 96)
                if hasattr(self, "scale_minus_btn") and hasattr(self, "scale_plus_btn"):
                    show_pm = not narrow_r
                    self.scale_minus_btn.setVisible(show_pm)
                    self.scale_plus_btn.setVisible(show_pm)

    def resizeEvent(self, event) -> None:  # noqa: N802
        super().resizeEvent(event)
        self._on_workspace_resized()

    def _sync_theme_btn(self) -> None:
        """Sync the theme dropdown (and any legacy theme affordances) with the
        active theme. Kept name for compatibility."""
        combo = getattr(self, "theme_combo", None)
        if combo is not None:
            ix = combo.findData(theme_name())
            if ix >= 0 and combo.currentIndex() != ix:
                combo.blockSignals(True)
                combo.setCurrentIndex(ix)
                combo.blockSignals(False)

    def _on_theme_combo_changed(self, _ix: int) -> None:
        key = str(self.theme_combo.currentData() or "")
        if key == theme_name():
            return
        set_theme(key)
        self._apply_theme_chrome(ui_scale())
        self._refresh_log_console()
        self._schedule_save()
        self._flash_summary(f"Theme: {C['name']}")

    def _build_left(self) -> QWidget:
        w = QWidget()
        lay = QVBoxLayout(w)
        lay.setContentsMargins(0, 0, 3, 0)
        lay.setSpacing(4)

        self.tabs = QTabWidget()
        self.tabs.setObjectName("IconTabs")
        self._icon_tabbar = _AutoFitIconTabBar(self.tabs)
        self.tabs.setTabBar(self._icon_tabbar)
        self.tabs.setUsesScrollButtons(False)
        self._tabbar_style = _IconTabBarStyle(QStyleFactory.create("fusion"))
        self.tabs.tabBar().setStyle(self._tabbar_style)
        self._tab_icon_px = tab_icon_px(1.0)
        self.tabs.setIconSize(QSize(self._tab_icon_px, self._tab_icon_px))
        self._tab_specs: List[Tuple[str, str, str]] = [
            ("tab_prompt", "Prompt", "Prompt & Negative (Ctrl+1)"),
            ("tab_templates", "Templates", "Prompt Templates (Ctrl+2)"),
            ("tab_tags", "Tags", "Tag Groups & Wildcards (Ctrl+3)"),
            ("tab_lora", "LoRA", "LoRA Manager: per-model folders, compact list, live weights & trigger ghost text (Ctrl+4)"),
            ("tab_llm", "LLM", "LLM Prompt Forge, Vision & Motion (Ctrl+5)"),
            ("tab_queue", "Queue", "Queue & In-Memory Logs (Ctrl+6)"),
            ("tab_horde", "Horde", "Horde, Bridge VPN & SillyTavern (Ctrl+7)"),
            ("tab_upscale", "Upscale", "Tile Upscale Engine — square SDXL img2img tiles (Ctrl+8)"),
            ("tab_edit", "Edit", "Image Editor & Depth Studio — grading, LUTs, Depth masks, cinematic bokeh/haze/rim FX, flares, live split & retouch (Ctrl+9)"),
        ]
        tab_widgets = (
            self._build_prompt_tab(),
            self._build_templates_tab(),
            self._build_tags_tab(),
            self._build_lora_tab(),
            self._build_llm_tab(),
            self._build_queue_tab(),
            self._build_horde_tab(),
            self._build_upscale_tab(),
            self._build_edit_tab(),
        )
        for idx, (wgt, (icon_key, _name, tip)) in enumerate(zip(tab_widgets, self._tab_specs)):
            self.tabs.addTab(wgt, VECTOR_ASSETS.icon(icon_key, self._tab_icon_px), "")
            self.tabs.setTabToolTip(idx, tip)
        self.tabs.currentChanged.connect(self._on_left_tab_changed)
        # Sleek East-Asian Active Tab Context Ribbon directly beneath the 9-icon rail
        self.tab_ribbon = ElideLabel("PROMPT  \u00b7  Ctrl+1")
        self.tab_ribbon.setObjectName("TabRibbon")
        self.tab_ribbon.setMinimumHeight(20)
        self.tab_ribbon.setToolTip("Active module — switch tabs with Ctrl+1..9 or click the icon rail above")
        lay.addWidget(self.tab_ribbon, 0)
        lay.addWidget(self.tabs, 1)
        self.deck = self._build_deck()
        lay.addWidget(self.deck, 0)
        w.setMinimumWidth(212)
        return w

    def _scroll_tab(self) -> Tuple[QScrollArea, QVBoxLayout]:
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.Shape.NoFrame)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        inner = QWidget()
        inner.setObjectName("Transparent")
        lay = QVBoxLayout(inner)
        lay.setContentsMargins(5, 5, 6, 5)
        lay.setSpacing(4)
        scroll.setWidget(inner)
        return scroll, lay

