    # ---- Tab 2: Templates ---------------------------------------------------
    def _build_templates_tab(self) -> QWidget:
        w = QWidget()
        lay = QVBoxLayout(w)
        lay.setContentsMargins(7, 7, 7, 7)
        lay.setSpacing(5)
        hdr = SectionHeader("Prompt templates")
        hdr.add_right(make_button("EDITOR\u2026", self.open_template_editor, small=True, accent=True))
        lay.addWidget(hdr)
        seg = QHBoxLayout()
        seg.setSpacing(0)
        self.tpl_group = QButtonGroup(self)
        self.tpl_group.setExclusive(True)
        self.tpl_set_btns: Dict[str, QPushButton] = {}
        for key, label, obj in (
            ("anime", "ANIMA", "SegL"), ("krea", "KREA 2", "Seg"), ("moss", "MOSS-S", "SegR")
        ):
            b = QPushButton(label)
            b.setObjectName(obj)
            b.setCheckable(True)
            b.setMinimumWidth(0)
            b.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Fixed)
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.setToolTip(
                "Preset library \u2014 ANIMA (anime tags) / KREA 2 (photography) / "
                "MOSS-S (scene captions & JSON layouts)"
            )
            self.tpl_group.addButton(b)
            self.tpl_set_btns[key] = b
            seg.addWidget(b, 1)
        self.tpl_group.buttonClicked.connect(lambda _b: self._on_tpl_set_clicked())
        lay.addLayout(seg)
        self.tpl_list = QListWidget()
        self.tpl_list.setAlternatingRowColors(True)
        self.tpl_list.currentItemChanged.connect(lambda cur, _p: self._show_template_preview(cur))
        self.tpl_list.itemDoubleClicked.connect(lambda _it: self.apply_selected_template())
        lay.addWidget(self.tpl_list, 1)
        self.tpl_preview = QPlainTextEdit()
        self.tpl_preview.setObjectName("SmallEdit")
        self.tpl_preview.setReadOnly(True)
        self.tpl_preview.setMinimumHeight(60)
        self.tpl_preview.setMaximumHeight(105)
        lay.addWidget(self.tpl_preview)
        row = QHBoxLayout()
        row.setSpacing(4)
        row.addWidget(make_button("APPLY", self.apply_selected_template, accent=True, compress=True), 1)
        row.addWidget(make_button("DETACH", self.clear_template, compress=True), 1)
        lay.addLayout(row)
        row2 = QHBoxLayout()
        row2.setSpacing(4)
        row2.addWidget(make_button("SAVE\u2026", self.save_prompt_as_template, small=True, compress=True), 1)
        row2.addWidget(make_button("RELOAD", self.load_templates, small=True, compress=True), 1)
        row2.addWidget(make_button("FILE", lambda: open_path(TEMPLATE_FILES[self._template_set()]), small=True, compress=True), 1)
        lay.addLayout(row2)
        return w

