        # Group 4: Depth Relighting, Optical Lens CA & 3D Flare Occlusion
        _add_dfx_group("Depth Relighting & 3D Optics", (
            ("fg_pop", "FG Pop", -50, 100, 0, "", "Foreground subject clarity, contrast & gentle studio key lift"),
            ("bg_dim", "BG Dim/Lift", -100, 50, 0, "", "Independently darken or lift the distant background"),
            ("bg_cool", "BG Temp", -100, 100, 0, "", "Shift background cool (-blue aerial) or warm (+gold)"),
            ("bg_desat", "BG Desat", 0, 100, 0, "%", "Recede background saturation so foreground subjects pop"),
            ("depth_ca", "Lens CA", 0, 100, 0, "%", "Optical chromatic fringing strictly in out-of-focus planes"),
            ("depth_vignette", "Depth Vig", 0, 100, 0, "%", "Studio vignette that deepens far corners while sparing foreground"),
            ("flare_occ", "Flare Occl", 0, 100, 0, "%", "Hide placed lens flares behind foreground depth planes"),
            ("flare_occ_plane", "Occ Plane", 0, 100, 58, "%", "Foreground depth threshold that occludes lens flares"),
        ))

        dl.addWidget(self.edit_depth_controls_wrap)
        dl.addStretch(1)

