        self.edit_split_vert.setChecked(True)
        self.edit_split_vert.setToolTip("Split into left and right halves")
        self.edit_split_horz = QPushButton("Horizontal —")
        self.edit_split_horz.setObjectName("SegR")
        self.edit_split_horz.setCheckable(True)
        self.edit_split_horz.setToolTip("Split into top and bottom halves")
        for b in (self.edit_split_vert, self.edit_split_horz):
            b.setCursor(Qt.CursorShape.PointingHandCursor)
