        sbtn1.setSpacing(4)
        self.edit_split_copy_a = make_button("Copy Left", self.edit_split_copy_first, small=True)
        self.edit_split_copy_b = make_button("Copy Right", self.edit_split_copy_second, small=True)
        sbtn1.addWidget(self.edit_split_copy_a, 1)
        sbtn1.addWidget(self.edit_split_copy_b, 1)
