        for key in THEME_ORDER:
            self.theme_combo.addItem(VECTOR_ASSETS.icon_for_theme("theme_badge", key, 14), str(THEMES[key]["name"]), key)
        self.theme_combo.setToolTip(
            "UI Theme  (Ctrl+Shift+T)\n" + "\n".join(f"\u2022 {THEMES[k]['name']} \u2014 {THEMES[k]['hint']}" for k in THEME_ORDER)
        )
        self.theme_combo.currentIndexChanged.connect(self._on_theme_combo_changed)
        self._sync_theme_btn()

        self.menu_btn = QToolButton()
        self.menu_btn.setObjectName("Small")
        self.menu_btn.setText("\u2630")
        self.menu_btn.setToolTip("Application Menu  (F10)")
        self.menu_btn.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        self.menu_btn.setFixedSize(26, 22)
        self.menu_btn.setCursor(Qt.CursorShape.PointingHandCursor)

        top_util.addWidget(self.panel_btn, 0)
