        self.viewer = ImageViewer()
        self.viewer.toggled_fit.connect(self._on_viewer_fit)
        self.viewer.zoom_changed.connect(self._on_viewer_zoom)
        self.viewer.image_dropped.connect(self._on_external_image_dropped)
        self.viewer.menu_requested.connect(self._viewer_context_menu)
        # v10.1: Ctrl+C inside the viewer copies the open image's pixel content
        # (WidgetWithChildren scope keeps normal text-copy shortcuts untouched).
        sc_viewer_copy = QShortcut(QKeySequence("Ctrl+C"), self.viewer)
        sc_viewer_copy.setContext(Qt.ShortcutContext.WidgetWithChildrenShortcut)
        sc_viewer_copy.activated.connect(lambda: self.copy_image_to_clipboard())
        lay.addWidget(self.viewer, 1)

        # ---- Compact Viewport Zoom & Filmstrip Bar (fits effortlessly down to 240px!) ----
        view_row = QHBoxLayout()
        view_row.setSpacing(3)
        self.zoom_out_btn = QToolButton()
        self.zoom_out_btn.setObjectName("Small")
        self.zoom_out_btn.setText("\u2212")
        self.zoom_out_btn.setFixedWidth(24)
        self.zoom_out_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.zoom_out_btn.setToolTip("Zoom out image")
        self.zoom_out_btn.clicked.connect(lambda: self.viewer.zoom_by(1.0 / 1.25))
        self.zoom_label = QLabel("Fit")
        self.zoom_label.setObjectName("InfoBar")
        self.zoom_label.setMinimumWidth(42)
        self.zoom_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
