        self.slide_btn = QToolButton()
        self.slide_btn.setObjectName("Small")
        self.slide_btn.setText("\u25B6")
        self.slide_btn.setFixedWidth(26)
        self.slide_btn.setCheckable(True)
        self.slide_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.slide_btn.setToolTip("Slideshow (3s interval)")
        self.slide_btn.toggled.connect(self._on_slideshow_toggled)
        self.gallery_btn = QToolButton()
        self.gallery_btn.setObjectName("Small")
        self.gallery_btn.setText("Strip")
