        self.gallery_btn.setChecked(True)
        self.gallery_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.gallery_btn.setToolTip("Show / hide recent filmstrip  (Ctrl+G)")
        self.gallery_btn.toggled.connect(self._toggle_gallery)
        # v10.1: clipboard copy of the open image — themed vector icon button
        self.copy_img_btn = QToolButton()
        self.copy_img_btn.setObjectName("Small")
        self.copy_img_btn.setIcon(VECTOR_ASSETS.icon("copy", 14))
        self.copy_img_btn.setIconSize(QSize(14, 14))
        self.copy_img_btn.setFixedWidth(28)
        self.copy_img_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        self.copy_img_btn.setToolTip("Copy image to clipboard  (Ctrl+C)")
        self.copy_img_btn.clicked.connect(lambda: self.copy_image_to_clipboard())
        view_row.addWidget(self.zoom_out_btn)
        view_row.addWidget(self.zoom_label)
        view_row.addWidget(self.zoom_in_btn)
        view_row.addWidget(self.fit_btn)
        view_row.addWidget(self.copy_img_btn)
        view_row.addStretch(1)
        view_row.addWidget(self.slide_btn)
        view_row.addWidget(self.gallery_btn)
        lay.addLayout(view_row)

        # v7.0: 2 compact balanced action rows (zero overflow even at 800x600!)
        act1 = QHBoxLayout()
        act1.setSpacing(3)
        self.save_btn = make_button("Save", self.save_current, accent=True,
                                    tip="Save current render into outputs/  (Ctrl+S)")
        self.save_btn.setObjectName("ActAccent")
        self.save_btn.setMinimumWidth(0)
        self.save_btn.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Fixed)
        act1.addWidget(self.save_btn, 3)
        for text, slot, tip in (
            ("Editor", self.edit_from_viewer, "Open current render in the full-size Image Editor & Depth Studio"),
            ("Upscale", self.ups_take_from_gallery, "Send current image to Tile Upscale tab"),
            ("Depth", lambda: self.request_depth_map(self._current_image()), "Generate Depth Anything V2 map via AI Horde Alchemy"),
            ("VLM", lambda: self._send_image_to_vlm(self._current_image()), "Send this image to the Vision Prompt Extractor (LLM tab)"),
        ):
            b = make_button(text, slot, tip=tip)
            b.setObjectName("Act")
            b.setMinimumWidth(0)
            b.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Fixed)
            act1.addWidget(b, 2)
        lay.addLayout(act1)

        act2 = QHBoxLayout()
        act2.setSpacing(3)
        for text, slot, tip in (
            ("Prompt", lambda: self.use_from_image("prompt"), "Load prompt + negative into editor"),
            ("Seed", lambda: self.use_from_image("seed"), "Load seed into editor"),
            ("All", lambda: self.use_from_image("all"), "Load prompt, negative, seed, model, size & LoRAs"),
            ("Info", self.show_current_info, "Inspect complete metadata & parameters"),
            ("Delete", self.delete_current, "Delete render from disk"),
        ):
            b = make_button(text, slot, tip=tip)
            b.setObjectName("Act")
            b.setMinimumWidth(0)
            b.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Fixed)
            act2.addWidget(b, 1)
        lay.addLayout(act2)

        self.gallery = RecentStripGallery()
