        self.edit_11_btn.clicked.connect(self.edit_canvas.zoom_1_1)
        for w in (self.edit_zoom_out_btn, self.edit_zoom_lbl, self.edit_zoom_in_btn,
                  self.edit_fit_btn, self.edit_11_btn):
            t_view.addWidget(w)

