        self.edit_mask_vis_btn.toggled.connect(self._on_edit_mask_visible_toggled)
        t_view.addWidget(self.edit_mask_vis_btn)

        self.edit_stage_depth_btn = QToolButton()
        self.edit_stage_depth_btn.setObjectName("Small")
        self.edit_stage_depth_btn.setCheckable(True)
        self.edit_stage_depth_btn.setText("Depth")
