        # live eliding document badge (compresses cleanly down to 40px on 800x600)
        self.edit_stage_doc_lbl = ElideLabel("")
        self.edit_stage_doc_lbl.setObjectName("InfoBar")
        self.edit_stage_doc_lbl.setMinimumHeight(20)
        self.edit_stage_doc_lbl.setMinimumWidth(48)
        self.edit_stage_doc_lbl.setMaximumWidth(200)
        self.edit_stage_doc_lbl.setToolTip("Document currently loaded on the edit stage")
        t_view.addWidget(self.edit_stage_doc_lbl)
        sl.addWidget(self._edit_view_wrap)

        # ---- Context bar: zero-overflow wrapping FlowLayout per tool (800x600!) ---
        self.edit_ctx_stack = _CompactStackedWidget()
        self.edit_ctx_stack.setMaximumHeight(68)

        def _flow_page() -> Tuple[QWidget, FlowLayout]:
            pg = QWidget()
            pg.setObjectName("Transparent")
            fl_lay = FlowLayout(pg, margin=0, spacing=4)
            return pg, fl_lay

        def _add_flow_sliders(
            fl_lay: FlowLayout,
            items: Sequence[Tuple[str, str, int, int, int, str]],
        ) -> Tuple[Dict[str, QSlider], Dict[str, QLabel]]:
            sliders: Dict[str, QSlider] = {}
            labels: Dict[str, QLabel] = {}
            for key, title, lo, hi, val, tip in items:
                grp = QWidget()
                grp.setObjectName("Transparent")
                gl_s = QHBoxLayout(grp)
                gl_s.setContentsMargins(0, 0, 2, 0)
                gl_s.setSpacing(3)
                gl_s.addWidget(make_label(title, "Kicker"))
                s = QSlider(Qt.Orientation.Horizontal)
                s.setRange(lo, hi)
                s.setValue(val)
                s.setFixedWidth(74)
                s.setCursor(Qt.CursorShape.PointingHandCursor)
                s.setToolTip(tip)
                vlab = make_label(str(val), "Value")
                vlab.setMinimumWidth(28)
                gl_s.addWidget(s)
                gl_s.addWidget(vlab)
                fl_lay.addWidget(grp)
                sliders[key] = s
                labels[key] = vlab
            return sliders, labels

        # -- page 0: NAV ------------------------------------------------------
        page_nav = QWidget()
        page_nav.setObjectName("Transparent")
        nl = QHBoxLayout(page_nav)
        nl.setContentsMargins(0, 1, 0, 1)
        nl.setSpacing(6)
        nav_hint = ElideLabel("Drag = pan · Wheel = zoom · Ctrl+Drag = frame zoom · Ctrl+Right-Click = restore Fit")
        nav_hint.setObjectName("Caption")
        nl.addWidget(nav_hint, 1)
        self.edit_ctx_stack.addWidget(page_nav)

        # -- page 1: MASK BRUSH / ERASER --------------------------------------
        page_mask, ml = _flow_page()
        m_sl, m_lab = _add_flow_sliders(ml, [
            ("size", "Size", 4, 400, 48, "Mask brush diameter in image pixels ([ and ] adjust)"),
            ("soft", "Soft", 0, 100, 45, "Mask brush edge softness (0 = hard round, 100 = very soft)"),
        ])
        self.edit_brush_size = m_sl["size"]
        self.edit_brush_soft = m_sl["soft"]
        self._edit_brush_size_lab = m_lab["size"]
        self._edit_brush_soft_lab = m_lab["soft"]
        self.edit_brush_size.valueChanged.connect(self._on_edit_brush_changed)
        self.edit_brush_soft.valueChanged.connect(self._on_edit_brush_changed)
        self.edit_mask_opaque_btn = QToolButton()
        self.edit_mask_opaque_btn.setObjectName("Small")
        self.edit_mask_opaque_btn.setCheckable(True)
        self.edit_mask_opaque_btn.setChecked(True)
