        # -- page 3: POLYGON LASSO --------------------------------------------
        page_poly, gl = _flow_page()
        self.edit_poly_smooth_btn = QToolButton()
        self.edit_poly_smooth_btn.setObjectName("Small")
        self.edit_poly_smooth_btn.setCheckable(True)
