        fel = QHBoxLayout(fe_grp)
        fel.setContentsMargins(0, 0, 0, 0)
        fel.setSpacing(3)
        fel.addWidget(make_label("Feather", "Kicker"))
        self.edit_poly_feather_sl = QSlider(Qt.Orientation.Horizontal)
        self.edit_poly_feather_sl.setRange(0, 120)
        self.edit_poly_feather_sl.setValue(0)
        self.edit_poly_feather_sl.setFixedWidth(74)
        self.edit_poly_feather_sl.setCursor(Qt.CursorShape.PointingHandCursor)
        self.edit_poly_feather_sl.setToolTip("Feather (blur) the selection edges, 0 = razor sharp")
        self.edit_poly_feather_sl.valueChanged.connect(self._on_edit_poly_feather)
        fel.addWidget(self.edit_poly_feather_sl)
        self.edit_poly_feather_val = make_label("0 px", "Value")
        self.edit_poly_feather_val.setMinimumWidth(34)
        fel.addWidget(self.edit_poly_feather_val)
        gl.addWidget(fe_grp)
        self.edit_poly_commit_btn = make_button("Add to Mask", self.edit_poly_commit, small=True, accent=True,
                                                tip="Union the selection into the red mask")
        gl.addWidget(self.edit_poly_commit_btn)
        self.edit_poly_discard_btn = make_button("Discard", self.edit_poly_discard, small=True,
                                                 tip="Throw the selection away (Esc)")
        gl.addWidget(self.edit_poly_discard_btn)
        self.edit_ctx_stack.addWidget(page_poly)

        # -- page 4: CROP -----------------------------------------------------
        page_crop, cl = _flow_page()
        ca_grp = QWidget()
        ca_grp.setObjectName("Transparent")
        cal = QHBoxLayout(ca_grp)
        cal.setContentsMargins(0, 0, 0, 0)
        cal.setSpacing(3)
        cal.addWidget(make_label("Aspect", "Kicker"))
        self.edit_crop_aspect = QComboBox()
        self.edit_crop_aspect.setSizeAdjustPolicy(QComboBox.SizeAdjustPolicy.AdjustToMinimumContentsLengthWithIcon)
        self.edit_crop_aspect.setMinimumContentsLength(6)
        self.edit_crop_aspect.addItem("Free", "free")
        for a in ASPECTS:
            self.edit_crop_aspect.addItem(f"{a['key']}  ·  {a['w']}×{a['h']}", a["key"])
        self.edit_crop_aspect.setToolTip("Lock the crop frame to the same aspect set used for generation")
        self.edit_crop_aspect.setMinimumWidth(86)
        self.edit_crop_aspect.setMaximumWidth(156)
        self.edit_crop_aspect.currentIndexChanged.connect(self._on_edit_crop_aspect_changed)
        cal.addWidget(self.edit_crop_aspect)
