        self.edit_crop_dims = make_label("—", "Value")
        self.edit_crop_dims.setMinimumWidth(64)
        cl.addWidget(self.edit_crop_dims)
        self.edit_crop_apply_btn = make_button("Apply Crop", self._edit_apply_crop, small=True, accent=True,
                                               tip="Crop the working image in memory (nothing is saved yet)")
        cl.addWidget(self.edit_crop_apply_btn)
        self.edit_crop_cancel_btn = make_button("Cancel", self._edit_cancel_crop, small=True,
                                                tip="Drop the crop frame (Esc)")
        cl.addWidget(self.edit_crop_cancel_btn)
        self.edit_ctx_stack.addWidget(page_crop)

        # -- page 5: TILT / ROTATE --------------------------------------------
        page_rot, rl = _flow_page()
        rt_grp = QWidget()
        rt_grp.setObjectName("Transparent")
        rtl = QHBoxLayout(rt_grp)
        rtl.setContentsMargins(0, 0, 0, 0)
        rtl.setSpacing(4)
        rtl.addWidget(make_label("Tilt", "Kicker"))
        self.edit_rot_slider = QSlider(Qt.Orientation.Horizontal)
        self.edit_rot_slider.setRange(-1800, 1800)
        self.edit_rot_slider.setValue(0)
        self.edit_rot_slider.setMinimumWidth(110)
        self.edit_rot_slider.setMaximumWidth(260)
        self.edit_rot_slider.setCursor(Qt.CursorShape.PointingHandCursor)
        self.edit_rot_slider.setToolTip("Tilt angle ±180° — borders stay static, image rotates under them")
        self.edit_rot_slider.valueChanged.connect(self._on_edit_rot_slider)
        rtl.addWidget(self.edit_rot_slider)
        self.edit_rot_val = make_label("0.0°", "Value")
        self.edit_rot_val.setMinimumWidth(46)
        rtl.addWidget(self.edit_rot_val)
        rl.addWidget(rt_grp)
        self.edit_rot_apply_btn = make_button("Apply Tilt", self._edit_apply_rotate, small=True, accent=True,
                                              tip="Bake the rotation into the working image")
